INSERT INTO `know_bases` VALUES
(1,'lovsamling','Lovsamling','Samlet dansk lovstof til juridisk retrieval','da','active',NULL,'2026-03-30 22:55:32','2026-03-31 00:57:03');
INSERT INTO `know_chunks` VALUES
(1288,1608,0,'Loven gælder for leje, herunder fremleje, af hus eller rum, uanset om lejeren er en person eller en virksomhed m.v. (juridisk person).',NULL,NULL,34,134,NULL,'2026-03-30 23:41:15'),
(1289,1609,0,'Loven gælder, selv om lejen skal betales med andet end penge, herunder ved arbejde.',NULL,NULL,21,83,NULL,'2026-03-30 23:41:15'),
(1290,1610,0,'Bortset fra § 17 gælder loven dog ikke for aftaler om leje af bolig med fuld kost, for aftaler mellem et hotel og dets gæster og for lejeforhold om beboelseslejligheder og andre beboelsesrum, herunder sommerhuse, kolonihavehuse og andre fritidsboliger, som er udlejet til ferie- og fritidsmæssige formål.',NULL,NULL,76,304,NULL,'2026-03-30 23:41:15'),
(1291,1611,0,'Loven gælder endvidere for leje af ustøttede private plejeboliger, jf. dog § 1, stk. 4, i erhvervslejeloven. §§ 7 og 9, kapitel 3, § 53, stk. 2, §§ 105-107, 109, 113, 119-121, 123, § 127, stk. 3, § 135 og kapitel 24 gælder dog ikke for ustøttede private plejeboliger.',NULL,NULL,67,267,NULL,'2026-03-30 23:41:15'),
(1292,1612,0,'Ustøttede private plejeboliger, jf. stk. 4, er tidligere institutionspladser på plejehjem og i beskyttede boliger, der den 31. december 2002 var omfattet af § 140 i lov om social service, og som kommunalbestyrelsen har omdannet til ustøttede private plejeboliger.',NULL,NULL,66,263,NULL,'2026-03-30 23:41:15'),
(1293,1613,0,'Loven gælder ikke, i det omfang lejeforholdet er omfattet af særlige regler i anden lovgivning.',NULL,NULL,24,95,NULL,'2026-03-30 23:41:15'),
(1294,1614,0,'Loven gælder ikke, i det omfang lejeforholdet er et led i et ansættelsesforhold under staten eller under en institution, hvortil staten yder tilskud, når løn- og andre ansættelsesvilkår er godkendt af staten. Loven gælder heller ikke lejeforhold, der er et led i et ansættelsesforhold under en region eller en kommune eller under en selvejende institution, hvormed en region eller en kommune har indgået overenskomst om institutionens drift, når løn- og andre ansættelsesvilkår er godkendt af Kommunernes Lønningsnævn eller er aftalt med eller fastsat af Regionernes Lønnings- og Takstnævn.',NULL,NULL,148,590,NULL,'2026-03-30 23:41:15'),
(1295,1615,0,'Bortset fra § 196, stk. 4, gælder loven ikke for leje af boliger, der er omfattet af § 1 i lov om leje af almene boliger.',NULL,NULL,31,121,NULL,'2026-03-30 23:41:15'),
(1296,1616,0,'Loven gælder ikke for lejeforhold om lokaler, der udlejes til brug for drift af friplejeboliger, jf. § 11, stk. 1, i lov om friplejeboliger.',NULL,NULL,35,140,NULL,'2026-03-30 23:41:15'),
(1297,1617,0,'Loven gælder ikke for lejeforhold, som er omfattet af erhvervslejeloven.',NULL,NULL,18,72,NULL,'2026-03-30 23:41:15'),
(1298,1618,0,'Lovens regler om beboelseslejligheder finder også anvendelse, når en lejlighed er udlejet tillige med lokaliteter til andet end beboelse. Bortset fra § 129, stk. 4, gælder kapitel 3-5 og §§ 105-107 og 127-130 dog ikke for lokaler omfattet af § 1, stk. 2, i erhvervslejeloven.',NULL,NULL,69,275,NULL,'2026-03-30 23:41:15'),
(1299,1620,0,'Ved regulerede kommuner forstås kommuner, hvor de hidtidige regler om huslejeregulering i kapitel II-V i lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019 med senere ændringer, fandt anvendelse. Ved regulerede kommuner forstås endvidere kommuner, hvor kommunalbestyrelsen har besluttet, at kommunen skal være reguleret, jf. stk. 2.',NULL,NULL,96,382,NULL,'2026-03-30 23:41:15'),
(1300,1621,0,'Kommunalbestyrelsen kan under hensyn til boligforholdene bestemme, at kommunen skal være reguleret. I regulerede kommuner kan kommunalbestyrelsen beslutte, at kommunen ikke længere skal være reguleret.',NULL,NULL,51,201,NULL,'2026-03-30 23:41:15'),
(1301,1623,0,'De beslutninger, som kommunalbestyrelsen træffer efter § 4, stk. 2, skal bekendtgøres i Statstidende og i øvrigt på den måde, der er sædvanlig i kommunen. Er andet ikke udtrykkeligt fastsat i beslutningen, får den virkning fra og med datoen på det nummer af Statstidende, hvori den er bekendtgjort.',NULL,NULL,75,298,NULL,'2026-03-30 23:41:15'),
(1302,1625,0,'§ 9, kapitel 3, §§ 62, 105-107, 109 og 113, § 115, stk. 2, §§ 119-123, § 127, stk. 3, og § 135 gælder alene for lejeforhold i ejendomme, der er beliggende i regulerede kommuner, jf. dog stk. 2-4 og § 7, stk. 3. §§ 42-45, 49-51 og 53 gælder ikke for lejeforhold i ejendomme omfattet af 1. pkt.',NULL,NULL,73,292,NULL,'2026-03-30 23:41:15'),
(1303,1626,0,'Lejeforhold i ejendomme, der er beliggende i regulerede kommuner, hvor mere end 80 pct. af ejendommens bruttoetageareal den 1. januar 1980 anvendtes til andet end beboelse, er ikke omfattet af stk. 1. For disse lejeforhold gælder dog §§ 33-36.',NULL,NULL,61,243,NULL,'2026-03-30 23:41:15'),
(1304,1627,0,'Lejeforhold om enkeltværelser til beboelse i ejendomme, der er beliggende i regulerede kommuner, hvor værelserne er en del af udlejerens beboelseslejlighed eller er en del af et en- eller tofamilieshus, som udlejeren bebor, er ikke omfattet af stk. 1. For disse lejeforhold gælder dog §§ 33-36 og 40.',NULL,NULL,75,300,NULL,'2026-03-30 23:41:15'),
(1305,1628,0,'Lejeforhold i ejendomme, som ved lejemålets indgåelse ejes af en selvejende institution, hvor boligerne er opført efter den tidligere gældende lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996 med senere ændringer, den tidligere gældende lov om boligbyggeri, jf. lovbekendtgørelse nr. 722 af 1. august 1996 med senere ændringer, eller lov om almene boliger m.v., er ikke omfattet af stk. 1.',NULL,NULL,110,439,NULL,'2026-03-30 23:41:15'),
(1306,1630,0,'§ 32 gælder alene for lejeforhold i ejendomme, der er beliggende i regulerede kommuner, som den 1. januar 1995 omfattede seks eller færre beboelseslejligheder. I ejendomme, der er beliggende i regulerede kommuner, og som ejes af andelsboligforeninger, gælder § 32, såfremt der i ejendommen er seks eller færre beboelseslejligheder, der er udlejet af andelsboligforeningen.',NULL,NULL,93,372,NULL,'2026-03-30 23:41:15'),
(1307,1631,0,'I ejendomme, der er beliggende i regulerede kommuner og opført efter den 1. januar 1995, gælder § 32, hvis ejendommen omfattede seks eller færre beboelseslejligheder, da den blev taget i brug.',NULL,NULL,48,192,NULL,'2026-03-30 23:41:15'),
(1308,1632,0,'Lejeforhold i ejendomme omfattet af stk. 1 og 2 er ikke omfattet af § 6, stk. 1. Dog gælder for lejemål i disse ejendomme §§ 9 og 33-36, § 38, stk. 3, og § 40. For lejemål i disse ejendomme gælder dog endvidere §§ 105, 106 og 109, såfremt ejendommen på tidspunktet for varslingen af iværksættelsen af forbedringen omfatter fire eller flere beboelseslejligheder, medmindre ejendommen er beliggende i landzone og ejendommen samtidig er en landbrugs- eller skovbrugsejendom.',NULL,NULL,118,471,NULL,'2026-03-30 23:41:15'),
(1309,1634,0,'I denne lov forstås ved en ejendom følgende, jf. dog § 9:',NULL,NULL,15,57,NULL,'2026-03-30 23:41:15'),
(1310,1635,0,'Et matrikelnummer.',NULL,NULL,5,18,NULL,'2026-03-30 23:41:15'),
(1311,1636,0,'Flere matrikelnumre, der ifølge notering i matriklen skal holdes forenet.',NULL,NULL,19,73,NULL,'2026-03-30 23:41:15'),
(1312,1637,0,'En ejerlejlighed.',NULL,NULL,5,17,NULL,'2026-03-30 23:41:15'),
(1313,1638,0,'En bygning på lejet grund, som har eget ejendomsblad i tingbogen.',NULL,NULL,17,65,NULL,'2026-03-30 23:41:15'),
(1314,1639,0,'Flere ejendomme, der ejes af samme ejer, som er opført kontinuerligt som en samlet bebyggelse, og som har fælles friarealer eller nogen form for driftsfællesskab, anses som én ejendom. Det samme gælder, hvor flere ejendomme er samvurderet eller samnoteret i tingbogen. Ligeledes skal flere ejerlejligheder, der henhører under samme ejerforening, og som ejes af samme udlejer, anses som én ejendom. 1.-3. pkt. gælder ved anvendelse af følgende regler:',NULL,NULL,113,450,NULL,'2026-03-30 23:41:15'),
(1315,1640,0,'Kapitel 3 om omkostningsbestemt leje, § 7 om huslejeregulering for mindre ejendomme i regulerede kommuner, § 62 om ulovlig opkrævning af depositum og forudbetalt leje, §§ 105-107 og 109 om iværksættelse af arbejder og § 161 om lejerens bytteret.',NULL,NULL,62,245,NULL,'2026-03-30 23:41:15'),
(1316,1641,0,'§ 113, § 115, stk. 2, §§ 119-123 og § 60 i lov om boligforhold om ejendommens udvendige vedligeholdelse og vedligeholdelsesplan.',NULL,NULL,32,128,NULL,'2026-03-30 23:41:15'),
(1317,1642,0,'Kapitel 5 om fri leje og kapitel 14 om forbedringsarbejder, når ejendommen er omfattet af § 6, stk. 1.',NULL,NULL,26,102,NULL,'2026-03-30 23:41:15'),
(1318,1644,0,'Dette kapitel kan ikke fraviges ved aftale.',NULL,NULL,11,43,NULL,'2026-03-30 23:41:15'),
(1319,1647,0,'En lejeaftale og andre aftaler om det lejede skal udfærdiges skriftligt, når en af parterne kræver det.',NULL,NULL,26,103,NULL,'2026-03-30 23:41:15'),
(1320,1648,0,'En lejeaftale anses for indgået på lovens vilkår, i det omfang der ikke udtrykkeligt er fastsat andet i aftalen.',NULL,NULL,28,112,NULL,'2026-03-30 23:41:15'),
(1321,1649,0,'Er lejens størrelse ikke aftalt, anses den for at udgøre det beløb, der er rimeligt under hensyn til reglerne i kapitel 3 eller reglerne om det lejedes værdi, jf. § 42, stk. 2 og 3, eller § 43.',NULL,NULL,49,193,NULL,'2026-03-30 23:41:15'),
(1322,1650,0,'Ønsker udlejeren at opkræve en leje, hvor afkastet beregnes efter § 25, stk. 2, skal det fremgå af lejeaftalen, hvornår den aftalte leje senest er fastsat efter § 23, og der skal i aftalen skønsmæssigt angives størrelsen af den leje, der maksimalt kan beregnes for lejemålet på tidspunktet for lejeaftalens indgåelse. Det skal tillige fremgå, om den aftalte leje er nedsat i henhold til § 23, stk. 2.',NULL,NULL,100,400,NULL,'2026-03-30 23:41:15'),
(1323,1651,0,'For lejeaftaler, som er omfattet af udlejerens beslutning om regulering efter nettoprisindeks, jf. § 26, og som indgås, efter at udlejeren har truffet beslutning om en sådan regulering, skal det fremgå af lejeaftalen, at lejen reguleres efter nettoprisindeks, og det skal endvidere fremgå af lejeaftalen, hvornår den i § 26 nævnte 2-årsperiode udløber.',NULL,NULL,88,352,NULL,'2026-03-30 23:41:15'),
(1324,1652,0,'Det skal udtrykkeligt oplyses i lejeaftalen, hvis et lejemål er ombygget efter følgende regler:',NULL,NULL,24,95,NULL,'2026-03-30 23:41:15'),
(1325,1653,0,'Den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, og hvor lejeforhøjelse er beregnet efter samme lov.',NULL,NULL,43,171,NULL,'2026-03-30 23:41:15'),
(1326,1654,0,'Kapitel 5 om aftalt boligforbedring i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003, og hvor lejeforhøjelse er beregnet efter samme lov.',NULL,NULL,45,180,NULL,'2026-03-30 23:41:15'),
(1327,1655,0,'Det tidligere gældende kapitel 6 a om aftalt grøn byfornyelse i lov om byfornyelse og udvikling af byer, jf. lovbekendtgørelse nr. 144 af 21. februar 2020, og hvor lejeforhøjelse er beregnet efter § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019.',NULL,NULL,74,293,NULL,'2026-03-30 23:41:15'),
(1328,1656,0,'Ydes der efter de nævnte love i stk. 1 tilskud til nedsættelse af lejeforhøjelsen for lejemålet, skal det udtrykkeligt oplyses i lejeaftalen, med hvilket beløb tilskud ydes for de enkelte betalingsterminer i hele tilskudsperioden.',NULL,NULL,58,230,NULL,'2026-03-30 23:41:15'),
(1329,1657,0,'Har udlejeren helt eller delvis undladt at give de i stk. 1 og 2 omtalte oplysninger, kan der ikke opkræves lejeforhøjelse efter de særlige regler i den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, i kapitel 5 i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, eller i § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019. Er lejeforhøjelse opkrævet, uanset at oplysningerne ikke er givet, kan lejeren kræve lejeforhøjelsen tilbagebetalt. § 15, stk. 3, 2. og 3. pkt., finder tilsvarende anvendelse.',NULL,NULL,169,675,NULL,'2026-03-30 23:41:15'),
(1330,1659,0,'Udlejeren eller lejeren kan med et varsel på 1 måned til den første dag i en måned, der ikke er en helligdag, forlange, at meddelelser ikke afgives som digitale dokumenter. Er lejeren eller udlejeren fritaget for Digital Post, jf. § 5 i lov om Digital Post fra offentlige afsendere, kan meddelelser dog ikke afgives som digitale dokumenter.',NULL,NULL,85,340,NULL,'2026-03-30 23:41:15'),
(1331,1660,0,'Meddelelser efter § 176 og § 182, stk. 2, kan ikke afgives som digitale dokumenter.',NULL,NULL,21,83,NULL,'2026-03-30 23:41:15'),
(1332,1662,0,'Ved indgåelse af lejeaftale om beboelseslejligheder eller enkelte værelser til beboelse må blanketter kun anvendes, hvis de er autoriseret ved aftale mellem landsomfattende sammenslutninger af henholdsvis grundejerforeninger og lejerforeninger eller af indenrigs- og boligministeren.',NULL,NULL,71,283,NULL,'2026-03-30 23:41:15'),
(1333,1663,0,'Ved en blanket forstås en skriftlig lejeaftale, der indeholder lejevilkår, som egner sig til benyttelse over for flere lejere og fremtræder på en sådan måde, at lejeren må opfatte dem som standardiserede.',NULL,NULL,51,204,NULL,'2026-03-30 23:41:15'),
(1334,1664,0,'Anvendes en blanket, der ikke er autoriseret, er bestemmelser, der pålægger lejeren større forpligtelser eller giver lejeren mindre rettigheder end angivet i loven, ugyldige.',NULL,NULL,44,174,NULL,'2026-03-30 23:41:15'),
(1335,1665,0,'Indenrigs- og boligministeren fastsætter efter forhandling med landsomfattende sammenslutninger af henholdsvis grundejerforeninger og lejerforeninger nærmere regler om udarbejdelse af autoriserede standardblanketter for lejeaftaler.',NULL,NULL,58,232,NULL,'2026-03-30 23:41:15'),
(1336,1667,0,'Ved udlejning til beboelse eller ved formidling eller bytning af sådanne lejeforhold er det ikke tilladt at modtage eller kræve vederlag fra lejeren eller at betinge sig, at lejeren indgår anden retshandel, som ikke er et led i lejeaftalen.',NULL,NULL,60,240,NULL,'2026-03-30 23:41:15'),
(1337,1668,0,'Bestemmelsen i stk. 1 omfatter ikke vederlag for afståelse af en forretning eller vederlag for at formidle afståelsen.',NULL,NULL,30,118,NULL,'2026-03-30 23:41:15'),
(1338,1669,0,'Beløb, der er betalt i strid med stk. 1, kan kræves tilbagebetalt. Beløbet forrentes fra forfaldsdagen med en årlig rente, der svarer til den rente, der er fastsat efter § 5, stk. 1 og 2, i renteloven. Når særlige forhold begrunder det, kan boligretten bestemme, at der skal betales en højere eller en lavere rente.',NULL,NULL,79,315,NULL,'2026-03-30 23:41:15'),
(1339,1670,0,'Overtrædelse af stk. 1 straffes med bøde eller fængsel indtil 4 måneder, medmindre højere straf er forskyldt efter anden lovgivning.',NULL,NULL,33,132,NULL,'2026-03-30 23:41:15'),
(1340,1671,0,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:15'),
(1341,1672,0,'Det er ikke tilladt for udlejere at tilbyde lejere betaling eller anden form for ydelse med det formål at få lejeren til at bringe lejeforholdet til ophør.',NULL,NULL,39,155,NULL,'2026-03-30 23:41:15'),
(1342,1673,0,'Lejeren kan kræve lejeforhold, som bringes til ophør som følge af betaling, som er ydet i strid med stk. 1, retableret på uændrede vilkår. Retablerede lejeforhold anses for indgået på tidspunktet for indgåelsen af det ophørte lejeforhold.',NULL,NULL,60,238,NULL,'2026-03-30 23:41:15'),
(1343,1674,0,'Betalinger ydet i strid med stk. 1 kan ikke kræves tilbagebetalt.',NULL,NULL,17,65,NULL,'2026-03-30 23:41:15'),
(1344,1675,0,'Overtrædelse af stk. 1 straffes med bøde eller fængsel indtil 4 måneder, medmindre højere straf er forskyldt efter anden lovgivning.',NULL,NULL,33,132,NULL,'2026-03-30 23:41:15'),
(1345,1676,0,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:15'),
(1346,1678,0,'Lejerens rettigheder efter reglerne i denne lov er gyldige mod enhver uden tinglysning. Det samme gælder aftaler om forudbetaling af leje, indskud, depositum el.lign., når disse beløb tilsammen ikke overstiger ½ års leje.',NULL,NULL,56,221,NULL,'2026-03-30 23:41:15'),
(1347,1679,0,'Ved lejeforholdets ophør skal lejerens krav efter stk. 1 dog være gjort gældende ved sagsanlæg inden 1 år fra ophørstidspunktet, såfremt det skal kunne gøres gældende mod en anden ejer end den, som ejede ejendommen, da kravet forfaldt.',NULL,NULL,59,235,NULL,'2026-03-30 23:41:15'),
(1348,1680,0,'En lejer, der ved aftale har erhvervet videregående rettigheder, f.eks. aftalt uopsigelighed eller afståelsesret, kan kræve aftalen tinglyst efter tinglysningsloven.',NULL,NULL,42,165,NULL,'2026-03-30 23:41:15'),
(1349,1682,0,'Dette kapitel kan bortset fra § 17, stk. 3, ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,23,91,NULL,'2026-03-30 23:41:15'),
(1350,1685,0,'Ved lejeaftalens indgåelse må lejen ikke fastsættes til et beløb, som overstiger det beløb, der kan dække ejendommens nødvendige driftsudgifter, jf. § 24, og afkastet af ejendommens værdi, jf. § 25. For lejemål, som er forbedret, kan der til lejen efter 1. pkt. lægges en beregnet forbedringsforhøjelse, jf. dog stk. 2.',NULL,NULL,80,319,NULL,'2026-03-30 23:41:16'),
(1351,1686,0,'Ved lejeaftalens indgåelse må lejen for lejemål, som er gennemgribende forbedret, ikke fastsættes til et beløb, der overstiger det lejedes værdi efter § 42, stk. 2 og 3, jf. dog stk. 3-6, § 21, stk. 1, og § 161, stk. 3. Ved lejemål, som er forbedret gennemgribende, forstås lejemål, hvor forbedringer efter principperne i § 128 væsentligt har forøget det lejedes værdi, og hvor forbedringsudgiften enten overstiger 2.280 kr. pr. m² eller et samlet beløb på 260.738 kr. Forbedringerne skal være gennemført inden for en periode på 2 år og må ikke være omfattet af § 129, stk. 1, i den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer. Beløbene i 2. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1. Ved genudlejning er det de beløb, som var gældende ved forbedringernes gennemførelse, der finder anvendelse.',NULL,NULL,320,1280,NULL,'2026-03-30 23:41:16'),
(1352,1687,0,'Før et lejemål kan forbedres gennemgribende efter stk. 2, skal huslejenævnet ved besigtigelse konstatere, at lejemålet har en stand, som på tidspunktet for besigtigelsen muliggør en væsentlig forøgelse af det lejedes værdi. Huslejenævnet skal gennemføre besigtigelsen inden for 4 uger fra modtagelsen af anmodningen. Huslejenævnet skal fremsende afgørelse herom til udlejeren senest 2 uger efter besigtigelsen. Afgørelsen har gyldighed i 3 år.',NULL,NULL,111,443,NULL,'2026-03-30 23:41:16'),
(1353,1688,0,'Stk. 2 finder alene anvendelse, hvis der er gået mindst 5 år siden seneste kontrolskifte vedrørende lejemålet eller den ejendom, hvori lejemålet indgår. Et kontrolskifte foreligger i følgende situationer:',NULL,NULL,51,204,NULL,'2026-03-30 23:41:16'),
(1354,1689,0,'En eller flere fysiske eller juridiske personers erhvervelse ved aftale, gave eller fuldbyrdelse af pant eller anden sikkerhed eller på anden vis af mindst 50 pct. af ejerandelen til lejemålet eller den ejendom, hvori lejemålet indgår.',NULL,NULL,59,235,NULL,'2026-03-30 23:41:16'),
(1355,1690,0,'En direkte eller indirekte overgang eller overdragelse af den bestemmende indflydelse over den eller de juridiske personer, der ejer lejemålet eller den ejendom, hvori lejemålet indgår.',NULL,NULL,47,185,NULL,'2026-03-30 23:41:16'),
(1356,1691,0,'En ændring af mindst 50 pct. af det reelle ejerskab af den eller de juridiske personer, der ejer lejemålet eller den ejendom, hvori lejemålet indgår.',NULL,NULL,38,149,NULL,'2026-03-30 23:41:16'),
(1357,1692,0,'En direkte eller indirekte overgang eller overdragelse af retten til mindst 50 pct. af det økonomiske afkast fra lejemålet, den ejendom, hvori lejemålet indgår, eller de juridiske personer, der direkte eller indirekte ejer lejemålet eller den ejendom, hvori lejemålet indgår.',NULL,NULL,69,275,NULL,'2026-03-30 23:41:16'),
(1358,1693,0,'En direkte eller indirekte overgang eller overdragelse af retten til mindst 50 pct. af en værdistigning af lejemålet, den ejendom, hvori lejemålet indgår, eller de juridiske personer, der direkte eller indirekte ejer lejemålet eller den ejendom, hvori lejemålet indgår.',NULL,NULL,68,269,NULL,'2026-03-30 23:41:16'),
(1359,1694,0,'Indgåelse eller overdragelse af en eller flere aftaler om, at en eller flere parter har ret til at få gennemført en overdragelse eller overgang, som ville udgøre et kontrolskifte efter nr. 1-5, hvis den eller disse aftaler blev gennemført enten alene eller i forening med en allerede gennemført disposition.',NULL,NULL,77,307,NULL,'2026-03-30 23:41:16'),
(1360,1695,0,'Indgåelse eller overdragelse af en betinget aftale om udskudt direkte eller indirekte overdragelse af lejemålet eller den ejendom, hvori lejemålet indgår, hvis en gennemførelse af den betingede aftale vil indebære kontrolskifte efter nr. 1-6.',NULL,NULL,61,242,NULL,'2026-03-30 23:41:16'),
(1361,1696,0,'Foretagelse af en eller flere dispositioner, som ikke er omfattet af nr. 1-7, men hvorved der opnås en tilsvarende virkning.',NULL,NULL,31,124,NULL,'2026-03-30 23:41:16'),
(1362,1697,0,'Følgende situationer er ikke omfattet af stk. 4:',NULL,NULL,12,48,NULL,'2026-03-30 23:41:16'),
(1363,1698,0,'Udlejning og genudlejning af lejemål, der inden den 1. juli 2020 opfyldte betingelserne for at kunne udlejes efter § 5, stk. 2, i den tidligere gældende lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, eller både opfylder betingelserne for at kunne udlejes efter stk. 2 og er genudlejet efterfølgende, når den første genudlejning ikke er foretaget i en 5-årsperiode efter et kontrolskifte, jf. stk. 4, som endnu ikke er udløbet.',NULL,NULL,121,481,NULL,'2026-03-30 23:41:16'),
(1364,1699,0,'Kontrolskifte, der sker ved arv efter arveloven eller hensidden i uskiftet bo efter arvelovens § 26 eller i begge tilfælde tilsvarende udenlandske regler. Arveforskud omfattes uanset 1. pkt. af stk. 4.',NULL,NULL,51,201,NULL,'2026-03-30 23:41:16'),
(1365,1700,0,'Kontrolskifte, der sker ved gennemførelsen af en eller flere koncerninterne transaktioner.',NULL,NULL,23,90,NULL,'2026-03-30 23:41:16'),
(1366,1701,0,'Kontrolskifte, der sker ved omdannelsen af en andelsboligforenings, et boligaktieselskabs eller et boliganpartsselskabs ejendom til en udlejningsejendom og alle senere videresalg, når andelsboligforeningen, boligaktieselskabet eller boliganpartsselskabet er stiftet før den 1. juli 2020.',NULL,NULL,72,287,NULL,'2026-03-30 23:41:16'),
(1367,1702,0,'Kontrolskifte, der sker vedrørende boliger, der er beliggende i en ejendom, hvor ejeren eller en tidligere ejer inden for en periode på 2 år har foretaget og afholdt udgifter til energiforbedringer eksklusive vedligeholdelse, jf. § 128, vedrørende den del af ejendommen, der anvendes til beboelse, svarende til mindst 3.012 kr. pr. m2 bruttoetageareal for denne del af ejendommen. Forbedringerne efter 1. pkt. må ikke være omfattet af lov om byfornyelse og udvikling af byer bortset fra det tidligere gældende kapitel 6 a, jf. lovbekendtgørelse nr. 144 af 21. februar 2020. Investeringskravet i 1. pkt. skal være opfyldt på tidspunktet for udlejning efter stk. 2. Beløb, som anvendes til opfyldelse af 1. pkt., kan ikke indgå ved opgørelsen af beløbskravet efter stk. 2. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,216,861,NULL,'2026-03-30 23:41:16'),
(1368,1703,0,'Kontrolskifte, der sker vedrørende boliger, der er beliggende i en ejendom, hvor ejeren eller en tidligere ejer har udført energiforbedringer i et omfang, som indebærer, at ejendommen har opnået en indplacering på energimærkningsskalaen, der ligger tre niveauer over den indplacering, som var gældende fra den 1. juli 2020. § 9 finder ikke anvendelse.',NULL,NULL,88,351,NULL,'2026-03-30 23:41:16'),
(1369,1704,0,'Stk. 2 finder alene anvendelse for lejemål i ejendomme, der på udlejningstidspunktet har opnået en indplacering på niveau A-C på energimærkningsskalaen efter lov om fremme af energibesparelser i bygninger, og for lejemål i ejendomme, hvor ejeren har udført energiforbedringer i et omfang, som indebærer, at ejendommen har opnået en indplacering på energimærkningsskalaen, der ligger to niveauer over den indplacering, som var gældende den 1. juli 2020. Kravet i 1. pkt. skal være opfyldt på tidspunktet for udlejning efter stk. 2. Uanset 1. pkt. finder stk. 2 anvendelse på lejemål i ejendomme, der er fredet efter lov om bygningsfredning og bevaring af bygninger og bymiljøer.',NULL,NULL,170,677,NULL,'2026-03-30 23:41:16'),
(1370,1705,0,'Ved tvister om lejefastsættelse efter § 19, stk. 2, skal udlejeren fremlægge dokumentation for forbedringsudgiften og for, at forbedringerne er gennemført inden for en periode på 2 år. Kan sådan dokumentation ikke fremlægges, kan § 19, stk. 2, alene finde anvendelse, såfremt det utvivlsomt må anses for godtgjort, at forbedringer er udført i tilstrækkeligt omfang og inden for en periode på 2 år. Ved indbringelse for boligretten påhviler det udlejeren at godtgøre, at den aftalte leje ikke overstiger det lejedes værdi.',NULL,NULL,131,521,NULL,'2026-03-30 23:41:16'),
(1371,1706,0,'Ved sammenligningen, jf. § 42, stk. 2 og 3, ses der bort fra følgende:',NULL,NULL,18,70,NULL,'2026-03-30 23:41:16'),
(1372,1707,0,'Lejemål, der er forbedret efter § 129, stk. 1, og § 137.',NULL,NULL,14,56,NULL,'2026-03-30 23:41:16'),
(1373,1708,0,'Lejemål omfattet af kapitel 5.',NULL,NULL,8,30,NULL,'2026-03-30 23:41:16'),
(1374,1709,0,'Lejemål omfattet af den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',NULL,NULL,130,520,NULL,'2026-03-30 23:41:16'),
(1375,1710,0,'Ved vurderingen af lejen og det lejedes værdi ses der bort fra følgende:',NULL,NULL,18,72,NULL,'2026-03-30 23:41:16'),
(1376,1711,0,'Lejeforhøjelse til afsættelse efter § 120 og forbedringer, der er gennemført for beløb, der er afsat efter denne bestemmelse.',NULL,NULL,32,125,NULL,'2026-03-30 23:41:16'),
(1377,1712,0,'Lejeforhøjelse efter § 129, stk. 1 og 2, og § 137 og § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og forbedringer efter § 129, stk. 1, og §§ 137 og 146 og det tidligere gældende kapitel 6 a i lov om byfornyelse og udvikling af byer, jf. lovbekendtgørelse nr. 144 af 21. februar 2020.',NULL,NULL,84,335,NULL,'2026-03-30 23:41:16'),
(1378,1713,0,'Lejeforhøjelser og forbedringer efter den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',NULL,NULL,135,538,NULL,'2026-03-30 23:41:16'),
(1379,1714,0,'Vil udlejeren indgå en lejeaftale i henhold til § 19, stk. 2, og er det den første udlejning af det pågældende lejemål efter § 19, stk. 2, skal udlejeren, når lejeforholdet er opsagt eller ophævet, og inden en ny lejeaftale indgås, orientere beboerrepræsentanterne eller lejerne om dette og om indholdet af denne bestemmelse. I modsat fald er vilkåret om lejefastsættelse efter § 19, stk. 2, ugyldigt. Beboerrepræsentanterne eller lejeren kan da, inden 14 dage efter at orienteringen er givet, indbringe en sag om manglende vedligeholdelse for huslejenævnet, jf. § 114. Beboerrepræsentanterne eller lejeren skal angive vedligeholdelsesmanglerne, der alene kan vedrøre mangler uden for de enkelte lejemål. Afgiver huslejenævnet påbud om udbedring af vedligeholdelsesmangler, jf. § 114, stk. 2, kan der ikke opkræves husleje efter § 19, stk. 2, før de konstaterede vedligeholdelsesmangler er udbedret.',NULL,NULL,225,899,NULL,'2026-03-30 23:41:16'),
(1380,1715,0,'Det påhviler udlejeren at opretholde den gennemgribende forbedring af lejemålet. Såfremt der opstår tvist herom, kan lejeren indbringe spørgsmålet for huslejenævnet, dog tidligst 5 år efter at en sådan sag senest har været forelagt huslejenævnet af denne lejer. Anses udlejeren for ikke at have opfyldt sin pligt til at opretholde den gennemgribende forbedring, skal lejen for fremtiden beregnes efter § 19, stk. 1.',NULL,NULL,104,415,NULL,'2026-03-30 23:41:16'),
(1381,1716,0,'Ved lejeaftalens indgåelse kan der ikke aftales en leje eller lejevilkår, der efter en samlet bedømmelse er mere byrdefulde for lejeren end de vilkår, der gælder for andre lejere i ejendommen.',NULL,NULL,48,192,NULL,'2026-03-30 23:41:16'),
(1382,1717,0,'Reglen i stk. 1 er dog ikke til hinder for, at der i lejemål, som er forbedret, uden at der samtidig er gennemført en til forbedringen svarende lejeforhøjelse, ved genudlejning kan aftales en leje efter reglerne i §§ 19-21.',NULL,NULL,56,223,NULL,'2026-03-30 23:41:16'),
(1383,1718,0,'Hvis lejen ikke kan dække ejendommens nødvendige driftsudgifter, jf. § 24, og afkast af ejendommens værdi, jf. § 25, kan udlejeren forlange lejeforhøjelse til udligning af forskellen.',NULL,NULL,46,183,NULL,'2026-03-30 23:41:16'),
(1384,1719,0,'Lejeforhøjelse kan ikke kræves, hvis lejen efter lejeforhøjelsen vil overstige det lejedes værdi efter § 42, stk. 2 og 3. Ved vurderingen af lejen og det lejedes værdi finder § 20, stk. 3, tilsvarende anvendelse. 1. pkt. gælder ikke for ejendomme, hvis opførelse er finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån, og ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af den tidligere gældende lov om realrenteafgift, såfremt beregning af afkast sker efter § 25, stk. 4.',NULL,NULL,147,585,NULL,'2026-03-30 23:41:16'),
(1385,1720,0,'Lejeforhøjelse efter stk. 1 har, medmindre parterne træffer anden aftale, virkning fra den 1. i den måned, der indtræder 3 måneder efter kravets fremsættelse.',NULL,NULL,40,158,NULL,'2026-03-30 23:41:16'),
(1386,1721,0,'Vil et krav om lejeforhøjelse efter stk. 1 eller efter § 46, hvor afkastet er beregnet efter § 25, stk. 2, medføre en lejeforhøjelse, der sammen med lejeforhøjelser, jf. stk. 1-3, inden for de sidste 3 år overstiger 96 kr. pr. m2 bruttoetageareal, skal udlejeren senest samtidig med varslingen om lejeforhøjelse underrette lejeren om, at denne kan forlange at få tilbudt en anden passende bolig. § 106, stk. 2-4, finder tilsvarende anvendelse. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,134,534,NULL,'2026-03-30 23:41:16'),
(1387,1722,0,'Har udlejeren helt eller delvis undladt at give de i § 11, stk. 4, omtalte oplysninger i forbindelse med indgåelsen af en lejeaftale, kan den gældende leje alene forhøjes på grundlag af stigninger i ejendommens driftsudgifter siden lejeaftalens indgåelse. Er lejeforhøjelse opkrævet for et beløb, der ligger ud over det i 1. pkt. tilladte, kan lejeren kræve det for meget betalte beløb tilbagebetalt. § 40 finder tilsvarende anvendelse.',NULL,NULL,109,436,NULL,'2026-03-30 23:41:16'),
(1388,1724,0,'De nødvendige driftsudgifter omfatter udgifter til skatter, afgifter, renholdelse, administration og forsikring i det omfang, det er rimeligt under hensyn til ejendommens og det lejedes karakter. De nødvendige driftsudgifter omfatter endvidere de beløb, der afsættes til vedligeholdelse m.v. efter §§ 117, 119 og 120, jf. dog § 113, stk. 2.',NULL,NULL,85,340,NULL,'2026-03-30 23:41:16'),
(1389,1725,0,'Udgifter til konsulentbistand som omfattet af § 47, stk. 3, optages ikke på budgettet.',NULL,NULL,22,86,NULL,'2026-03-30 23:41:16'),
(1390,1726,0,'Beboerrepræsentanterne kan indhente tilbud på renholdelse, forsikringer og udfærdigelse af varme- og vandregnskaber og forelægge disse for udlejeren. Såfremt udlejeren afviser at antage et forelagt tilbud efter 1. pkt., kan beboerrepræsentanterne indbringe sagen for huslejenævnet, der kan pålægge udlejeren at antage et af beboerrepræsentanterne indhentet tilbud, såfremt huslejenævnet vurderer, at tilbuddet med hensyn til pris og kvalitet er bedre end det af udlejeren antagne.',NULL,NULL,120,480,NULL,'2026-03-30 23:41:16'),
(1391,1727,0,'Stk. 3 gælder ikke for ejendomme, der er opdelt i ejerlejligheder.',NULL,NULL,17,66,NULL,'2026-03-30 23:41:16'),
(1392,1728,0,'I fredede ejendomme, hvorpå der er tinglyst en særlig bevaringsdeklaration i henhold til lovgivningen om bygningsfredning, kan et beløb svarende til den ejendomsskat, der til enhver tid kunne have været opkrævet, optages som driftsudgift, uanset om ejendommen er fritaget for ejendomsbeskatning.',NULL,NULL,74,295,NULL,'2026-03-30 23:41:16'),
(1393,1730,0,'Til afkast af ejendommens værdi afsættes på budgettet et beløb, der ikke må overstige 7 pct. af den ejendomsværdi, der er fastsat pr. 1. april 1973 ved 15. almindelige vurdering af landets faste ejendomme.',NULL,NULL,52,205,NULL,'2026-03-30 23:41:16'),
(1394,1731,0,'I stedet for et afkast efter reglen i stk. 1 kan udlejeren i ejendomme, der tages i brug efter 1963, som afkast beregne et beløb, der ikke må overstige rimelige ydelser på sædvanlige langfristede prioritetslån, der er optaget til finansiering af ejendommens opførelse, med tillæg af en passende forrentning af den resterende del af den rimelige anskaffelsessum med fradrag af lejerindskud. Som passende forrentning anses:',NULL,NULL,106,421,NULL,'2026-03-30 23:41:16'),
(1395,1732,0,'8 pct. for ejendomme med ibrugtagelse i 1964.',NULL,NULL,12,45,NULL,'2026-03-30 23:41:16'),
(1396,1733,0,'10 pct. for ejendomme med ibrugtagelse i 1965-69.',NULL,NULL,13,49,NULL,'2026-03-30 23:41:16'),
(1397,1734,0,'12 pct. for ejendomme med ibrugtagelse i 1970-73.',NULL,NULL,13,49,NULL,'2026-03-30 23:41:16'),
(1398,1735,0,'14 pct. for ejendomme med ibrugtagelse efter 1973.',NULL,NULL,13,50,NULL,'2026-03-30 23:41:16'),
(1399,1736,0,'I stedet for afkast efter stk. 1 og 2 kan udlejeren for ejendomme finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån som afkast beregne den rente, udlejeren løbende betaler på indekslån optaget til finansiering af ejendommens opførelse, med tillæg af 4 pct. af den indekserede hovedstol. Udlejeren kan endvidere beregne en forrentning på 4 pct. af den resterende anskaffelsessum efter fradrag af lejerindskud. Det beløb, der er beregnet efter 2. pkt., reguleres med samme procentsats, hvormed hovedstolen på indekslånet reguleres.',NULL,NULL,149,594,NULL,'2026-03-30 23:41:16'),
(1400,1737,0,'For ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af lov om realrenteafgift, kan beregnes samme beløb i afkast som beregnet efter stk. 3 for en tilsvarende ejendom finansieret med størst muligt indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån.',NULL,NULL,87,345,NULL,'2026-03-30 23:41:16'),
(1401,1738,0,'Er der i perioden fra den 1. januar 1964 til den 1. april 1973 gennemført lejeforhøjelser for forbedringer, kan afkastet beregnes med indtil 7 pct. af ejendomsværdien ved den seneste almindelige vurdering forud for forbedringens gennemførelse med tillæg af et afkast af den rimelige forbedringsudgift beregnet efter reglerne i stk. 2, således at tidspunktet for forbedringens ibrugtagelse er afgørende for forrentningsprocentens størrelse.',NULL,NULL,110,439,NULL,'2026-03-30 23:41:16'),
(1402,1739,0,'Såfremt ejendommen er opdelt i ejerlejligheder efter 15. almindelige vurdering, beregnes afkastet på grundlag af en forholdsmæssig andel af ejendomsværdien ved 15. almindelige vurdering.',NULL,NULL,47,186,NULL,'2026-03-30 23:41:16'),
(1403,1740,0,'Til det beregnede afkast kan udlejeren lægge det beløb, som henlagdes eller kunne være henlagt pr. kvadratmeter bruttoetageareal ved udgangen af 2014, jf. § 9, stk. 7, i den tidligere gældende lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 962 af 14. august 2010. Beløbet i 1. pkt. reguleres efter reglerne i § 204, stk. 1.',NULL,NULL,88,352,NULL,'2026-03-30 23:41:16'),
(1404,1742,0,'Udlejeren kan i stedet for regulering efter § 23 beslutte, at lejen i perioder på 2 år ad gangen reguleres én gang årligt efter udviklingen i Danmarks Statistiks nettoprisindeks i en 12-månedersperiode sluttende i juni måned året før det finansår, reguleringen vedrører. Beløbet afrundes til nærmeste hele kronebeløb. Regulering efter nettoprisindeks kan kun ske for den del af lejen, som vedrører de i § 24, stk. 1, nævnte nødvendige driftsudgifter bortset fra skatter og afgifter. Regulering efter nettoprisindeks omfatter alle lejemål i ejendommen bortset fra de lejemål, hvor der er aftalt en regulering af lejen efter kapitel 5. Ved 2-årsperiodens udløb skal udlejeren beregne lejen efter § 23. Beregningen skal sammen med oplysning om, at beregningen kan indbringes for huslejenævnet, være kommet frem til lejerne inden 2-årsperiodens udløb. Hvis lejen ved 2-årsperiodens udløb overstiger den leje, som beregnes efter § 23, skal udlejeren med virkning fra tidspunktet for 2-årsperiodens udløb nedsætte lejen til den nu beregnede leje.',NULL,NULL,260,1040,NULL,'2026-03-30 23:41:16'),
(1405,1743,0,'Beslutning om regulering af lejen efter nettoprisindeks kan gennemføres alene ved udlejerens skriftlige meddelelse herom til lejerne og er bindende for udlejeren i en periode på 2 år fra det tidspunkt, hvor udlejeren har afsendt meddelelse herom til lejerne. Lejeregulering efter stk. 1 kan tidligst få virkning, 12 måneder efter at lejen er beregnet og fastsat efter § 23.',NULL,NULL,94,373,NULL,'2026-03-30 23:41:16'),
(1406,1744,0,'Krav om lejeforhøjelse som følge af regulering efter nettoprisindeks efter stk. 1 skal være skriftligt og indeholde en angivelse af lejeforhøjelsens størrelse og dens beregning. Lejeforhøjelsen har virkning fra den 1. i den måned, der indtræder 3 måneder efter kravets fremsættelse.',NULL,NULL,71,282,NULL,'2026-03-30 23:41:16'),
(1407,1745,0,'Har udlejeren reguleret lejen efter nettoprisindeks, kan lejeforhøjelse opgjort efter § 23 tidligst få virkning, 12 måneder efter at der senest er trådt en lejeforhøjelse som følge af regulering af lejen efter nettoprisindeks i kraft og efter udløbet af den i stk. 2 nævnte 2-årsperiode.',NULL,NULL,72,287,NULL,'2026-03-30 23:41:16'),
(1408,1747,0,'Lejeforhøjelsen fordeles på lejlighederne efter deres indbyrdes brugsværdi. Har lejligheder samme indbyrdes brugsværdi, skal lejeforhøjelsen forlods pålægges lejligheder, hvis leje er lavest. De beløb, der afsættes til vedligeholdelse efter §§ 117, 119 og 120, fordeles dog efter lejlighedernes bruttoetageareal. For ejendomme med lejligheder, hvor afsættelse sker med forskellige beløb pr. kvadratmeter bruttoetageareal, sker fordelingen efter de enkelte lejligheders faktiske beløb pr. kvadratmeter bruttoetageareal.',NULL,NULL,130,518,NULL,'2026-03-30 23:41:16'),
(1409,1748,0,'Ved bedømmelsen af lejlighedernes indbyrdes brugsværdi ses bort fra forbedringer, som er bekostet af lejeren.',NULL,NULL,28,109,NULL,'2026-03-30 23:41:16'),
(1410,1749,0,'Er lejen for en lejlighed forhøjet på grundlag af forbedring eller øget brugsværdi, der ikke modsvares af udgifter på budgettet, og er forhøjelsen sket efter den ejendomsvurdering, hvoraf afkastprocenten beregnes, ses der ved budgetteringen og ved bedømmelsen af lejlighedernes indbyrdes brugsværdi bort fra denne lejeforhøjelse.',NULL,NULL,83,329,NULL,'2026-03-30 23:41:16'),
(1411,1751,0,'For rum, der benyttes af udlejeren, eller som er udlejet uden at være omfattet af reglerne i dette kapitel, og for de i stk. 3 omhandlede enkeltværelser skal der på budgettet optages en lejeværdi, der svarer til de pågældende rums andel af ejendommens nødvendige driftsudgifter og afkast. Fordelingen sker efter bruttoetageareal.',NULL,NULL,83,329,NULL,'2026-03-30 23:41:16'),
(1412,1752,0,'For ejendomme, hvor der for beboelseslejligheder til vedligeholdelse efter §§ 117, 119 og 120 afsættes forskellige beløb pr. kvadratmeter bruttoetageareal for de enkelte beboelseslejligheder, sker fordelingen af afsætningsbeløbene efter disse lejligheders faktiske beløb pr. kvadratmeter bruttoetageareal.',NULL,NULL,77,305,NULL,'2026-03-30 23:41:16'),
(1413,1753,0,'Lejen for enkeltværelser til beboelse, som er omfattet af dette kapitel, jf. § 6, stk. 3, fastsættes efter bruttoetagearealet som en forholdsmæssig andel af den lejeværdi, der er optaget på lejebudgettet for de i stk. 1, 1. pkt., omhandlede lejemål.',NULL,NULL,63,249,NULL,'2026-03-30 23:41:16'),
(1414,1755,0,'I ejendomme uden beboerrepræsentation skal krav om lejeforhøjelse efter § 23 fremsættes samtidig over for de lejere, hvis leje ønskes forhøjet. Kravet skal være skriftligt. Det skal indeholde oplysning om det gældende budget og det nye budget, herunder driftsudgifter og -indtægter, om lejeforhøjelsens størrelse og dens beregning og om den fremtidige lejes størrelse. Kravet skal indeholde oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 2. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,129,514,NULL,'2026-03-30 23:41:16'),
(1415,1756,0,'Har mindst en fjerdedel af de lejere, hvis leje ønskes forhøjet, senest 6 uger efter at kravet om lejeforhøjelse er kommet frem, skriftligt fremsat indsigelse mod lejeforhøjelsen, skal udlejeren inden yderligere 6 uger forelægge sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om lejeforhøjelse.',NULL,NULL,80,317,NULL,'2026-03-30 23:41:16'),
(1416,1757,0,'I ejendomme med beboerrepræsentation skal krav om lejeforhøjelse efter § 23 fremsættes samtidig over for de lejere, hvis leje ønskes forhøjet. Kravet skal være skriftligt. Det skal indeholde oplysning om det gældende budget og det nye budget, herunder driftsudgifter og -indtægter, om lejeforhøjelsens størrelse og dens beregning og om den fremtidige lejes størrelse. Kravet skal tillige indeholde oplysning om, at skrivelsen er forelagt for beboerrepræsentanterne, og om deres eventuelle udtalelser. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,140,559,NULL,'2026-03-30 23:41:16'),
(1417,1758,0,'Senest 7 dage før kravet efter stk. 1 skal udlejeren varsle beboerrepræsentanterne om lejeforhøjelsen. Varslingen skal indeholde kopi af skrivelsen til lejerne, oplysning om det gældende budget og det nye budget og fornøden redegørelse for budgetposterne, herunder om ændringer i de enkelte beløbs størrelse. Modtager beboerrepræsentanterne ikke disse oplysninger, er varslingen efter stk. 1 ugyldig.',NULL,NULL,100,400,NULL,'2026-03-30 23:41:16'),
(1418,1759,0,'Beboerrepræsentanterne kan inden 3 uger efter modtagelsen af varslingen efter stk. 2 fremsætte skriftligt krav om, at udlejeren inden yderligere 3 uger til beboerrepræsentationen fremsender en skriftlig redegørelse om nærmere angivne supplerende oplysninger sammen med dokumentation for bestemte udgifter i budgettet. Beboerrepræsentanterne skal endvidere have oplysning om deres adgang til at gøre indsigelse, jf. stk. 4. Modtager beboerrepræsentanterne ikke disse oplysninger, er kravet om lejeforhøjelse ugyldigt.',NULL,NULL,129,516,NULL,'2026-03-30 23:41:16'),
(1419,1760,0,'Såfremt beboerrepræsentanterne, senest 6 uger efter at udlejerens varsling efter stk. 2 eller yderligere oplysninger efter stk. 3 er kommet frem, skriftligt har meddelt, at de ikke kan tiltræde lejeforhøjelsen, skal udlejeren inden yderligere 6 uger forelægge sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om lejeforhøjelse.',NULL,NULL,87,348,NULL,'2026-03-30 23:41:16'),
(1420,1761,0,'Såfremt udlejeren ikke rettidigt har modtaget meddelelse fra beboerrepræsentanterne som nævnt i stk. 4 eller beboerrepræsentanterne har tiltrådt lejeforhøjelsen, kan udlejeren oppebære den varslede lejeforhøjelse, når denne har meddelt lejerne dette med tilkendegivelse af, at den enkelte lejer kan indbringe spørgsmålet om lejeforhøjelsens rimelighed for huslejenævnet efter § 38.',NULL,NULL,96,381,NULL,'2026-03-30 23:41:16'),
(1421,1762,0,'Meddelelse efter stk. 5 kan gives i skrivelsen efter stk. 1, hvis den udsendes, efter at beboerrepræsentanterne har svaret eller deres svarfrist er udløbet.',NULL,NULL,39,156,NULL,'2026-03-30 23:41:16'),
(1422,1764,0,'Krav om lejeforhøjelse, der udelukkende skyldes afsættelse af de i §§ 117, 119 og 120 nævnte afsættelsesbeløb, kan uanset bestemmelserne i §§ 29 og 30 gennemføres alene ved udlejerens skriftlige meddelelse herom til lejerne.',NULL,NULL,56,224,NULL,'2026-03-30 23:41:16'),
(1423,1766,0,'Reglerne i kapitel 4 og 5 finder anvendelse for ejendomme omfattet af § 7. Lejen i disse ejendomme kan dog ikke væsentligt overstige den leje, der betales for tilsvarende lejeforhold med hensyn til beliggenhed, art, størrelse, kvalitet, udstyr og vedligeholdelsestilstand omfattet af § 6, stk. 1, og hvor lejen er reguleret efter § 23. Ved afgørelse efter 2. pkt. skal der for lejeforhold i ejendomme med lokaler, som anvendes til andet end beboelse, ske sammenligning med lejen for lejeforhold i tilsvarende ejendomme. Såfremt der ikke findes sammenlignelige lejemål, hvor lejen er reguleret efter § 23, eller såfremt lejens størrelse for sammenlignelige lejemål må anses for at være atypisk, kan huslejenævnet i henhold til § 83 i lov om boligforhold indhente oplysninger om ejendommens driftsudgifter m.v. og på grundlag af disse oplysninger ansætte den leje, som ville kunne opkræves, hvis lejen skulle beregnes efter § 23. 2.-4. pkt. gælder dog ikke for lejeforhold omfattet af § 54, stk. 1.',NULL,NULL,249,996,NULL,'2026-03-30 23:41:16'),
(1424,1768,0,'Reglerne i §§ 34-36 gælder for udlejning af de værelser, der er omfattet af § 6, stk. 3.',NULL,NULL,22,88,NULL,'2026-03-30 23:41:16'),
(1425,1769,0,'Finder lejeren, at lejen eller andre vilkår er urimelige, kan lejeren indbringe spørgsmålet for huslejenævnet, der kan ændre lejen efter § 45 og lejevilkårene.',NULL,NULL,40,159,NULL,'2026-03-30 23:41:16'),
(1426,1770,0,'Nedsættes lejen eller ændres lejevilkårene af huslejenævnet, kan dette bestemme, at lejeforholdet ikke kan opsiges uden nævnets godkendelse.',NULL,NULL,35,140,NULL,'2026-03-30 23:41:16'),
(1427,1771,0,'Skønnes en opsigelse fra udlejerens side foranlediget af eller at stå i forbindelse med forsøg på at opnå en urimelig leje eller andre urimelige lejevilkår, kan huslejenævnet underkende opsigelsens gyldighed og bestemme, at lejeforholdet kun kan opsiges med nævnets godkendelse. Det samme gælder, hvis en opsigelse som følge af andre særlige omstændigheder i forbindelse med dens afgivelse skønnes stridende mod sædvanlig god udlejningsskik, således at den må anses for urimelig.',NULL,NULL,120,479,NULL,'2026-03-30 23:41:16'),
(1428,1772,0,'Er en sag rejst for huslejenævnet, kan dette, når omstændighederne taler derfor, bestemme, at lejeforholdet ikke uden nævnets godkendelse kan opsiges, inden nævnets afgørelse i sagen er truffet.',NULL,NULL,49,194,NULL,'2026-03-30 23:41:16'),
(1429,1774,0,'Indbringes krav om lejeforhøjelse efter § 29, stk. 2, eller efter § 30, stk. 4, for huslejenævnet, kan nævnet tilsidesætte kravet helt eller delvis, dersom betingelserne for forhøjelsens gennemførelse ikke er til stede.',NULL,NULL,55,219,NULL,'2026-03-30 23:41:16'),
(1430,1775,0,'Nævnet kan dog, såfremt det konstateres, at kravet om lejeforhøjelse på grund af formelle mangler af mindre betydning er ugyldigt, jf. § 29, stk. 1, og § 30, stk. 1 og 3, i stedet for at tilsidesætte kravet på dette grundlag fastsætte en frist for udlejeren til at berigtige de konstaterede formelle mangler. Berigtiges manglerne inden den angivne frist, bevarer kravet om lejeforhøjelse sin gyldighed.',NULL,NULL,101,402,NULL,'2026-03-30 23:41:16'),
(1431,1776,0,'Indtil nævnets afgørelse foreligger, kan udlejeren oppebære den varslede lejeforhøjelse som en foreløbig lejeforhøjelse, der dog ikke må overstige 15 kr. pr. m² bruttoetageareal om året. Lejen skal reguleres i overensstemmelse med nævnets afgørelse. Regulering af depositum og forudbetalt leje kan ikke forlanges, før kravet om lejeforhøjelse er afgjort af nævnet.',NULL,NULL,91,364,NULL,'2026-03-30 23:41:16'),
(1432,1777,0,'På lejerens begæring skal huslejenævnet, medmindre nævnet har truffet afgørelse efter § 37, stk. 1, afgøre, om udlejeren har krævet højere leje eller betinget sig andre vilkår end tilladt efter bestemmelserne i dette kapitel.',NULL,NULL,57,225,NULL,'2026-03-30 23:41:16'),
(1433,1778,0,'§ 37, stk. 2, finder tilsvarende anvendelse.',NULL,NULL,11,44,NULL,'2026-03-30 23:41:16'),
(1434,1779,0,'I ejendomme med beboerrepræsentation afgør huslejenævnet på beboerrepræsentanternes begæring på vegne af samtlige lejere uenighed om acontobidrag til varme og lign., om acontobidrag til vand, om acontobidrag til køling efter kapitel 7, om udlejerens ret til at modsætte sig installation af vandmålere og kølingsmålere efter § 67, stk. 3, og § 68, stk. 2, om lejerens ret efter § 142, stk. 2, om, hvorvidt en aftale i henhold til § 138 er åbenbart urimelig, og om lejeforhøjelser varslet efter §§ 26 eller 31.',NULL,NULL,127,508,NULL,'2026-03-30 23:41:16'),
(1435,1781,0,'Med bøde eller fængsel indtil 4 måneder straffes den, som afkræver en lejer højere leje end tilladt efter reglerne i §§ 19-21. På samme måde straffes den udlejer, som aftaler leje og lejevilkår, der er mere byrdefulde for lejeren end tilladt efter bestemmelserne i §§ 19-22.',NULL,NULL,69,274,NULL,'2026-03-30 23:41:16'),
(1436,1782,0,'Med bøde straffes den, som opkræver højere leje end tilladt af huslejenævnet efter reglen i § 34, stk. 1, eller som i strid med § 35 opsiger lejeforholdet uden nævnets samtykke.',NULL,NULL,45,177,NULL,'2026-03-30 23:41:16'),
(1437,1783,0,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:16'),
(1438,1785,0,'Har udlejeren opkrævet højere leje, depositum, indskud el.lign. end tilladt, kan lejeren kræve det for meget betalte beløb tilbage, ligesom lejeren vil kunne kræve lejen nedsat med virkning for fremtiden. Ved lejeforholdets ophør skal lejerens krav være gjort gældende for huslejenævnet inden 1 år fra fraflytningstidspunktet.',NULL,NULL,82,326,NULL,'2026-03-30 23:41:16'),
(1439,1786,0,'Lejeren kan uanset stk. 1 ikke kræve tilbagebetaling af for meget betalt leje med den begrundelse, at lejen overstiger det lejedes værdi, medmindre krav om nedsættelse af lejen er fremsat for huslejenævnet inden 1 år efter det tidspunkt, lejen eller den forhøjede leje første gang skal betales.',NULL,NULL,74,294,NULL,'2026-03-30 23:41:16'),
(1440,1787,0,'Tilbagebetalingskrav forrentes fra betalingstidspunktet med en årlig rente, der svarer til den rente, der er fastsat efter § 5, stk. 1 og 2, i lov om renter ved forsinket betaling m.v. Hvor særlige forhold begrunder det, kan det bestemmes, at der skal betales en højere eller en lavere rente.',NULL,NULL,73,292,NULL,'2026-03-30 23:41:16'),
(1441,1789,0,'Dette kapitel kan ikke fraviges til skade for lejeren.',NULL,NULL,14,54,NULL,'2026-03-30 23:41:16'),
(1442,1790,0,'§ 54 finder dog anvendelse.',NULL,NULL,7,27,NULL,'2026-03-30 23:41:16'),
(1443,1793,0,'Er lejen væsentlig lavere end det lejedes værdi, kan udlejeren forlange lejen forhøjet til det beløb, der er rimeligt under hensyn hertil. Ved vurderingen af lejen og det lejedes værdi ses der bort fra:',NULL,NULL,51,202,NULL,'2026-03-30 23:41:16'),
(1444,1794,0,'Lejeforhøjelser efter § 129, stk. 1 og 2, og § 137 og § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, forbedringer efter § 129, stk. 1, og §§ 137 og 146 og forbedringer efter det tidligere gældende kapitel 6 a i lov om byfornyelse og udvikling af byer, jf. lovbekendtgørelse nr. 144 af 21. februar 2020.',NULL,NULL,88,352,NULL,'2026-03-30 23:41:16'),
(1445,1795,0,'Lejeforhøjelser efter § 63 b i tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010, og forbedringer, der er udført for beløb omfattet af § 63 a i tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010.',NULL,NULL,64,256,NULL,'2026-03-30 23:41:16'),
(1446,1796,0,'Lejeforhøjelser og forbedringer efter den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',NULL,NULL,135,538,NULL,'2026-03-30 23:41:16'),
(1447,1797,0,'Forbedringer, som lejeren har udført for egen regning med udlejerens tilladelse.',NULL,NULL,20,80,NULL,'2026-03-30 23:41:16'),
(1448,1798,0,'Ved afgørelse efter stk. 1, 1. pkt., skal der foretages en sammenligning med den leje, som er almindeligt gældende i kvarteret eller området for tilsvarende beboelseslejlighed eller enkeltværelse til beboelse med hensyn til beliggenhed, art, størrelse, kvalitet, udstyr og vedligeholdelsestilstand.',NULL,NULL,75,298,NULL,'2026-03-30 23:41:16'),
(1449,1799,0,'Ved sammenligningen af lejemål, jf. stk. 2, tillægges det vægt, når lejen i sammenligningslejemål har været genstand for særskilt prøvelse.',NULL,NULL,35,139,NULL,'2026-03-30 23:41:16'),
(1450,1800,0,'Ved sammenligningen, jf. stk. 2, ses der bort fra:',NULL,NULL,13,50,NULL,'2026-03-30 23:41:16'),
(1451,1801,0,'Lejemål, der er forbedret efter § 129, stk. 1, og § 137.',NULL,NULL,14,56,NULL,'2026-03-30 23:41:16'),
(1452,1802,0,'Lejemål omfattet af §§ 49-51 og kapitel 5.',NULL,NULL,11,42,NULL,'2026-03-30 23:41:16'),
(1453,1803,0,'Lejemål omfattet af den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',NULL,NULL,130,520,NULL,'2026-03-30 23:41:16'),
(1454,1804,0,'Krav om lejeforhøjelse kan tidligst få virkning 2 år efter lejeforholdets begyndelse, eller 2 år efter at der sidst er trådt en lejeforhøjelse i kraft, som følge af at lejen var væsentlig lavere end det lejedes værdi.',NULL,NULL,55,217,NULL,'2026-03-30 23:41:16'),
(1455,1806,0,'Lejen for ustøttede private plejeboliger, jf. § 1, stk. 5, skal til enhver tid være fastsat, således at den svarer til det lejedes værdi, som fastsættes ved en sammenligning med støttede ældre- eller plejeboliger i kommunen efter reglerne i § 42, stk. 2 og 4. Ved fastsættelse af lejen ses der bort fra forbedringer, som lejeren har udført for egen regning med udlejerens tilladelse.',NULL,NULL,96,383,NULL,'2026-03-30 23:41:16'),
(1456,1807,0,'Krav om lejeforhøjelse, jf. stk. 1, kan varsles én gang årligt.',NULL,NULL,16,63,NULL,'2026-03-30 23:41:16'),
(1457,1808,0,'Overstiger lejen det lejedes værdi efter stk. 1, kan lejeren forlange lejen nedsat hertil.',NULL,NULL,23,90,NULL,'2026-03-30 23:41:16'),
(1458,1809,0,'Nedsættes lejen efter stk. 3, kan lejeren kræve det for meget betalte beløb tilbagebetalt.',NULL,NULL,23,90,NULL,'2026-03-30 23:41:16'),
(1459,1810,0,'§ 45, stk. 4 og 5, finder tilsvarende anvendelse for ustøttede private plejeboliger.',NULL,NULL,21,84,NULL,'2026-03-30 23:41:16'),
(1460,1812,0,'Lejeforhøjelse efter §§ 42 eller 43 kan gennemføres med 3 måneders varsel.',NULL,NULL,19,74,NULL,'2026-03-30 23:41:16'),
(1461,1813,0,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde en angivelse af lejeforhøjelsens størrelse. Kravet skal tillige indeholde oplysning om grunden til lejeforhøjelsen og om lejerens adgang til at gøre indsigelse, jf. stk. 3. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,74,296,NULL,'2026-03-30 23:41:16'),
(1462,1814,0,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren skriftligt fremsætte indsigelse, senest 6 uger efter at kravet om lejeforhøjelse er kommet frem. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',NULL,NULL,79,315,NULL,'2026-03-30 23:41:16'),
(1463,1815,0,'Indtil huslejenævnets afgørelse foreligger, kan udlejeren oppebære den varslede lejeforhøjelse som en foreløbig lejeforhøjelse, der dog ikke må overstige 15 kr. pr. m² bruttoetageareal om året. Lejen skal reguleres i overensstemmelse med nævnets afgørelse. Regulering af depositum og forudbetalt leje kan ikke forlanges, før kravet om lejeforhøjelse er afgjort af nævnet. Tilbagebetaling til lejeren af for meget betalt leje forrentes fra betalingstidspunktet efter bestemmelsen i § 15, stk. 3.',NULL,NULL,124,494,NULL,'2026-03-30 23:41:16'),
(1464,1816,0,'Lejeforhøjelse kan kræves uanset aftalt uopsigelighed, når udlejeren har forbeholdt sig at kunne regulere lejen.',NULL,NULL,28,112,NULL,'2026-03-30 23:41:16'),
(1465,1818,0,'Er lejen væsentlig højere end det lejedes værdi, kan lejeren forlange lejen nedsat til et beløb, der er rimeligt under hensyn hertil. Ved vurdering af lejen og det lejedes værdi finder reglen i § 42, stk. 1, tilsvarende anvendelse.',NULL,NULL,58,231,NULL,'2026-03-30 23:41:16'),
(1466,1819,0,'Ved afgørelse efter stk. 1 skal der tages hensyn til de i § 42, stk. 2-4, nævnte omstændigheder.',NULL,NULL,24,96,NULL,'2026-03-30 23:41:16'),
(1467,1820,0,'Nedsættes lejen efter stk. 1, kan lejeren kræve det for meget betalte beløb tilbagebetalt.',NULL,NULL,23,90,NULL,'2026-03-30 23:41:16'),
(1468,1821,0,'Sag om nedsættelse af lejen skal indbringes inden 1 år efter det tidspunkt, lejen eller den forhøjede leje første gang skal betales.',NULL,NULL,33,132,NULL,'2026-03-30 23:41:16'),
(1469,1822,0,'I ejendomme med beboerrepræsentation kan beboerrepræsentanterne kræve nedsættelse af lejen. Nedsættes lejen, anvendes tilbagebetalingsbeløbet forlods til dækning af beboerrepræsentanternes udgifter ved sagen.',NULL,NULL,52,208,NULL,'2026-03-30 23:41:16'),
(1470,1824,0,'Forøges de ejendomsskatter, der påhviler ejendommen, kan udlejeren forlange udgiften udlignet gennem en lejeforhøjelse for de beboelseslejligheder og beboelsesrum, som skatten vedrører. Lejeforhøjelse kan kræves uanset aftalt uopsigelighed.',NULL,NULL,60,240,NULL,'2026-03-30 23:41:16'),
(1471,1825,0,'Lejeforhøjelsen fordeles i forhold til den gældende leje eller, hvor der ikke er fastsat nogen leje, lejeværdi. For lejeforhold i ejendomme, hvor reglerne i §§ 19-31 gælder, fordeles forhøjelsen dog efter reglerne i §§ 27 og 28.',NULL,NULL,57,228,NULL,'2026-03-30 23:41:16'),
(1472,1826,0,'Lejeforhøjelsen kan gennemføres med 3 måneders varsel. Lejeforhøjelsen kan dog kræves med virkning fra det tidspunkt, udgiften er pålagt ejendommen, hvis kravet om lejeforhøjelse fremsættes senest 5 måneder efter dette tidspunkt.',NULL,NULL,58,229,NULL,'2026-03-30 23:41:16'),
(1473,1827,0,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde en beregning af, hvorledes ændringen af lejen fremkommer, og oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 5. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,63,249,NULL,'2026-03-30 23:41:16'),
(1474,1828,0,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren, senest 6 uger efter at kravet er kommet frem, fremsætte skriftlig indsigelse, der angiver, på hvilke punkter kravet ikke kan godkendes. I ejendomme med beboerrepræsentation kan beboerrepræsentanterne på samtlige lejeres vegne gøre indsigelse mod kravet om lejeforhøjelse, jf. 1. pkt. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',NULL,NULL,126,503,NULL,'2026-03-30 23:41:16'),
(1475,1829,0,'Reglerne i § 46 gælder også, hvis der pålægges ejendommen nye eller forøgede afgifter til vand, el, renovation, wc, skorstensfejning el.lign. efter takster, der er fastsat eller godkendt af det offentlige.',NULL,NULL,52,205,NULL,'2026-03-30 23:41:16'),
(1476,1830,0,'Reglerne i § 46 gælder også, hvis der pålægges ejendommen nye vej- eller kloakbidrag eller lignende bidrag til det offentlige. Er bidrag pålagt ejendommen som en engangsydelse, kan udlejeren, når ydelsen er betalt, opkræve bidraget hos lejerne gennem en lejeforhøjelse, der i løbet af 10 år har dækket udlejerens udlæg med tillæg af sædvanlige finansieringsudgifter. Lejeforhøjelsen bortfalder ved periodens udløb.',NULL,NULL,104,414,NULL,'2026-03-30 23:41:16'),
(1477,1831,0,'Reglerne i § 46 gælder også udgifter til dækning af konsulentbistand i henhold til § 4 b, stk. 1, 2. pkt., i den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer. Udlejeren kan, når udgiften er betalt, udligne denne gennem en lejeforhøjelse, der i løbet af 12 måneder har dækket udlejerens udlæg med sædvanlige finansieringsudgifter. Lejeforhøjelsen kan dog alene opkræves med lige store beløb hos de lejere, som har antaget konsulentbistand, jf. 1. pkt., og lejeforhøjelsen bortfalder ved periodens udløb.',NULL,NULL,143,572,NULL,'2026-03-30 23:41:16'),
(1478,1833,0,'Bortfalder eller nedsættes de i §§ 46 og 47 nævnte skatter, afgifter, udgifter og bidrag, skal udlejeren med virkning fra nedsættelsestidspunktet foretage en tilsvarende lejenedsættelse for de beboelseslejligheder og beboelsesrum, i hvis leje udgiften har været indregnet. Udlejeren skal dog ikke foretage lejenedsættelse, hvis bortfald eller nedsættelse af skatter, afgifter, udgifter og bidrag samtidig udlignes eller overstiges af nye forøgede skatter, afgifter, udgifter eller bidrag. I fredede ejendomme, hvorpå der er tinglyst en særlig bevaringsdeklaration i henhold til lovgivningen om bygningsfredning, kan et beløb svarende til den ejendomsskat, der til enhver tid kunne have været opkrævet, dog opkræves som en del af lejen, uanset om en ejendom er fritaget for ejendomsbeskatning.',NULL,NULL,198,792,NULL,'2026-03-30 23:41:16'),
(1479,1834,0,'Udlejeren skal give lejeren skriftlig meddelelse om nedsættelsen af lejen, senest 6 uger efter at meddelelsen om nedsættelsen af skatter, afgifter, udgifter eller bidrag er kommet frem.',NULL,NULL,47,185,NULL,'2026-03-30 23:41:16'),
(1480,1836,0,'For ejendomme, hvis opførelse er finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån, kan lejen fastsættes, således at den samlede lejeindtægt kan dække ejendommens nødvendige driftsudgifter på tidspunktet for ejendommens opførelse med tillæg af afkastet af ejendommens værdi.',NULL,NULL,85,339,NULL,'2026-03-30 23:41:16'),
(1481,1837,0,'Som afkast kan beregnes den rente, udlejeren løbende betaler på indekslån optaget til finansiering af ejendommens opførelse med tillæg af 4 pct. af den indekserede hovedstol. Udlejeren kan endvidere beregne en forrentning på 4 pct. af den resterende anskaffelsessum efter fradrag af lejerindskud.',NULL,NULL,74,296,NULL,'2026-03-30 23:41:16'),
(1482,1838,0,'Driftsudgifterne efter stk. 1 og forrentningen efter stk. 2, 2. pkt., reguleres med samme procentsats, hvormed hovedstolen på indekslånet reguleres. Regulering kan dog ikke ske af driftsudgifter omfattet af §§ 46-48.',NULL,NULL,54,216,NULL,'2026-03-30 23:41:16'),
(1483,1839,0,'Lejen fordeles på beboelseslejlighederne efter deres indbyrdes værdi. Ved bedømmelsen af beboelseslejlighedernes indbyrdes værdi ses der bort fra forbedringer, som lejeren har betalt.',NULL,NULL,46,183,NULL,'2026-03-30 23:41:16'),
(1484,1840,0,'Lejeforhøjelse efter stk. 2 og 3 kan gennemføres med 3 måneders varsel.',NULL,NULL,18,71,NULL,'2026-03-30 23:41:16'),
(1485,1841,0,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde en beregning af, hvorledes ændringen af lejen fremkommer, og oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 7. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,63,249,NULL,'2026-03-30 23:41:16'),
(1486,1842,0,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren, senest 6 uger efter at kravet er kommet frem, fremsætte skriftlig indsigelse, der angiver, på hvilke punkter kravet ikke kan godkendes. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',NULL,NULL,89,355,NULL,'2026-03-30 23:41:16'),
(1487,1844,0,'For ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af lov om realrenteafgift, kan lejen uanset ejendommens finansiering fastsættes til samme beløb, som lovligt kan opkræves efter § 49 for en tilsvarende ejendom finansieret med størst muligt indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån.',NULL,NULL,98,391,NULL,'2026-03-30 23:41:16'),
(1488,1846,0,'§§ 42-45 finder ikke anvendelse for lejemål i ejendomme, hvis opførelse er finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån. Det samme gælder for lejemål i ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af lov om realrenteafgift, såfremt lejefastsættelsen sker efter § 50.',NULL,NULL,98,389,NULL,'2026-03-30 23:41:16'),
(1489,1848,0,'Uenighed om lejeregulering og lejefastsættelse efter reglerne i dette kapitel afgøres af huslejenævnet.',NULL,NULL,26,103,NULL,'2026-03-30 23:41:16'),
(1490,1850,0,'§§ 42-48 kan ikke ved aftale fraviges til skade for lejeren, jf. dog kapitel 5 om fri leje.',NULL,NULL,23,91,NULL,'2026-03-30 23:41:16'),
(1491,1851,0,'Det kan dog aftales, at lejen én gang årligt reguleres efter udviklingen i Danmarks Statistiks nettoprisindeks. Lejeforhøjelse kan gennemføres alene ved udlejerens skriftlige meddelelse herom til lejeren.',NULL,NULL,51,204,NULL,'2026-03-30 23:41:16'),
(1492,1852,0,'De øvrige bestemmelser i dette kapitel kan ikke fraviges.',NULL,NULL,15,57,NULL,'2026-03-30 23:41:16'),
(1493,1855,0,'Lejen kan fastsættes frit efter parternes aftale i følgende lejeforhold:',NULL,NULL,18,72,NULL,'2026-03-30 23:41:16'),
(1494,1856,0,'Lejeforhold om beboelseslejligheder i ejendomme, der er taget i brug efter den 31. december 1991.',NULL,NULL,25,97,NULL,'2026-03-30 23:41:16'),
(1495,1857,0,'Lejeforhold om beboelseslejligheder, der den 31. december 1991 eller inden denne dato lovligt udelukkende benyttedes til eller lovligt var indrettet udelukkende til erhvervsformål, jf. reglerne i kapitel VII i den tidligere gældende lov om midlertidig regulering af boligforholdene.',NULL,NULL,71,282,NULL,'2026-03-30 23:41:16'),
(1496,1858,0,'Lejeforhold om nyindrettede beboelseslejligheder eller nyindrettede enkeltværelser i en tagetage, som den 1. september 2002 ikke var benyttet til eller registreret som beboelse. Det samme gælder lejligheder og enkeltværelser i nypåbyggede etager, hvortil der er givet byggetilladelse efter den 1. juli 2004. I forbindelse med indretning af boliger i tagetagen kan udlejeren med 6 ugers varsel råde over loftsrum, hvis der anvises lejeren andre rum, der er anvendelige til det aftalte formål.',NULL,NULL,123,491,NULL,'2026-03-30 23:41:16'),
(1497,1859,0,'For lejeforhold omfattet af stk. 1, nr. 2 og 3, er det en betingelse for, at lejen kan fastsættes frit, at det fremgår af lejeaftalen, at lejemålet er omfattet af disse bestemmelser.',NULL,NULL,46,182,NULL,'2026-03-30 23:41:16'),
(1498,1860,0,'Lejeforhøjelse for lejeforhold, hvor lejen fastsættes frit efter parternes aftale, jf. stk. 1, kan kræves på grundlag af aftale om regulering af lejen efter nettoprisindeks og kan gennemføres alene ved udlejerens skriftlige meddelelse herom til lejeren.',NULL,NULL,64,253,NULL,'2026-03-30 23:41:16'),
(1499,1862,0,'Uenighed om lejeaftaler indgået i henhold til § 54 og om, hvorvidt en aftale indgået i medfør af § 54 er rimelig, jf. aftalelovens § 36, afgøres af huslejenævnet. Huslejenævnet afgør endvidere uenighed om udlejerens ret til at råde over arealer i tagetager efter § 54, stk. 1, nr. 3.',NULL,NULL,71,283,NULL,'2026-03-30 23:41:16'),
(1500,1864,0,'Dette kapitel kan ikke fraviges til skade for lejeren.',NULL,NULL,14,54,NULL,'2026-03-30 23:41:16'),
(1501,1867,0,'Udlejeren skal anvise et betalingssted her i landet i form af en konto i et pengeinstitut, jf. dog 2. pkt. Er der ikke anvist et betalingssted, skal lejen betales på udlejerens bopæl her i landet. Indbetaling til et pengeinstitut anses for betaling på det anviste betalingssted.',NULL,NULL,70,278,NULL,'2026-03-30 23:41:16'),
(1502,1869,0,'Lejen kan kræves betalt månedsvis forud.',NULL,NULL,10,40,NULL,'2026-03-30 23:41:16'),
(1503,1870,0,'Er lejen beregnet for en kortere periode end 1 måned, kan den kræves betalt forud for den periode, den vedrører.',NULL,NULL,28,112,NULL,'2026-03-30 23:41:16'),
(1504,1871,0,'Leje for beboelseslejligheder og enkeltværelser til beboelse kan ikke kræves betalt for mere end 3 måneder ad gangen. Leje for ustøttede private plejeboliger kan ikke kræves betalt for mere end 1 måned ad gangen.',NULL,NULL,53,212,NULL,'2026-03-30 23:41:16'),
(1505,1872,0,'Rettidig betaling af husleje sker senest på forfaldsdagen. Forfalder lejen til betaling på en helligdag, en lørdag eller grundlovsdag, udskydes forfaldsdagen til den efterfølgende hverdag.',NULL,NULL,47,188,NULL,'2026-03-30 23:41:16'),
(1506,1873,0,'I tilfælde af opsigelse eller ved det tidsbestemte lejeforholds udløb er lejeren kun pligtig at betale leje for tiden indtil lejeforholdets ophør.',NULL,NULL,37,146,NULL,'2026-03-30 23:41:16'),
(1507,1875,0,'Udlejeren kan i lejeforhold om beboelseslejligheder og enkeltværelser til beboelse ved lejemålets indgåelse som depositum kræve et beløb svarende til højst 3 måneders leje. Beløbet henstår til sikkerhed for lejerens forpligtelser ved fraflytning.',NULL,NULL,62,246,NULL,'2026-03-30 23:41:16'),
(1508,1876,0,'I fremlejeforhold kan lejeren ved lejeaftalens indgåelse såvel som i lejeperioden i stedet for depositum vælge at stille sikkerhed i form af bankgaranti eller indestående på en særskilt deponeringskonto.',NULL,NULL,51,203,NULL,'2026-03-30 23:41:16'),
(1509,1877,0,'Udlejeren kan ved lejemålets indgåelse desuden kræve lejen forudbetalt for et tidsrum op til 3 måneder, når den forudbetalte leje samtidig ikke overstiger den leje, som skal betales i perioden, fra lejemålet opsiges af lejeren, indtil lejeforholdet ophører. Ved forudbetalt leje forstås i denne forbindelse det beløb, der umiddelbart inden de aftalte betalingsterminer henstår som indbetalt hos udlejeren. Er lejeaftalen opsagt eller ophævet, kan lejeren modregne det beløb, der er forudbetalt efter 1. pkt. i den sidste del af lejeperioden.',NULL,NULL,136,541,NULL,'2026-03-30 23:41:16'),
(1510,1878,0,'Depositum er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1. Hvis lejeren har valgt i stedet for depositum at stille sikkerhed i form af bankgaranti eller indestående på en deponeringskonto, finder reglerne for pligtig pengeydelse tilsvarende anvendelse, jf. § 182, stk. 1, nr. 1.',NULL,NULL,74,295,NULL,'2026-03-30 23:41:16'),
(1511,1879,0,'Huslejenævnet kan tillade, at stk. 1-3 fraviges, såfremt der stilles behørig sikkerhed for lejerens tilbagebetalingskrav, jf. § 17, stk. 1, 2. pkt.',NULL,NULL,37,147,NULL,'2026-03-30 23:41:16'),
(1512,1881,0,'Gennemføres lejeforhøjelse, kan depositum og forudbetalt leje kræves reguleret. Reguleringen kan for de nævnte beløb opkræves med lige store månedlige beløb over samme antal måneder, som det pågældende beløb svarede til i forhold til lejen ved lejemålets indgåelse. 1. pkt. finder tilsvarende anvendelse, hvis lejeren har valgt i stedet for depositum at stille sikkerhed i form af bankgaranti eller indestående på en deponeringskonto. Nedsættes lejen, skal udlejeren med virkning fra nedsættelsestidspunktet foretage en tilsvarende tilbagebetaling af depositum og forudbetalt leje til lejeren.',NULL,NULL,149,593,NULL,'2026-03-30 23:41:16'),
(1513,1882,0,'Regulering af depositum og forudbetalt leje efter stk. 1 er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1. Har lejeren valgt i stedet for depositum at stille sikkerhed i form af bankgaranti eller indestående på en deponeringskonto, finder reglerne for pligtig pengeydelse tilsvarende anvendelse, jf. § 182, stk. 1, nr. 1.',NULL,NULL,85,337,NULL,'2026-03-30 23:41:16'),
(1514,1884,0,'Udlejeren kan ikke i lejeforhold om ustøttede private plejeboliger kræve lejen forudbetalt efter § 59, stk. 3 og 4.',NULL,NULL,29,115,NULL,'2026-03-30 23:41:16'),
(1515,1886,0,'Med bøde eller fængsel indtil 4 måneder straffes den udlejer, som i ejendomme med lejefastsættelse efter §§ 19-31 forlanger depositum og forudbetalt leje i strid med § 59, stk. 1 og 3.',NULL,NULL,46,184,NULL,'2026-03-30 23:41:16'),
(1516,1887,0,'Medmindre højere straf er forskyldt efter anden lovgivning, straffes med bøde den lejer, der har foretaget fremleje, og som ikke inden 6 uger fra fremlejeforholdets ophør eller endelig huslejenævnsafgørelse, hvis sag herom er indbragt for huslejenævnet, har foretaget endelig afregning og tilbagebetaling af overskydende depositum og forudbetalt leje.',NULL,NULL,88,351,NULL,'2026-03-30 23:41:16'),
(1517,1888,0,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:16'),
(1518,1890,0,'Uenighed om depositum, forudbetalt leje og sikkerhedsstillelse efter §§ 59-61 afgøres af huslejenævnet. Huslejenævnet kan herunder tillade, at § 59, stk. 1-3, fraviges, jf. § 59, stk. 5.',NULL,NULL,47,186,NULL,'2026-03-30 23:41:16'),
(1519,1892,0,'§ 57, § 58, stk. 3-5, og §§ 59-61 kan ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,22,85,NULL,'2026-03-30 23:41:16'),
(1520,1895,0,'Leverer udlejeren varme og opvarmning af vand, kan udlejeren kræve sine udgifter til lejerens forbrug og andel i andre udgifter som nævnt i § 72, stk. 4 og 5, refunderet. De nævnte udgifter kan ikke indeholdes i lejen, jf. dog stk. 2.',NULL,NULL,59,234,NULL,'2026-03-30 23:41:16'),
(1521,1896,0,'Udgifter til leverancer efter stk. 1 kan indeholdes i lejen, medmindre pligt til måling af forbrug følger af anden lovgivning, ved følgende lejeaftaler:',NULL,NULL,38,152,NULL,'2026-03-30 23:41:16'),
(1522,1897,0,'Lejeaftaler om enkelte værelser til beboelse.',NULL,NULL,12,45,NULL,'2026-03-30 23:41:16'),
(1523,1898,0,'Lejeaftaler om lejligheder, der er forbeholdt uddannelsessøgende eller andre unge i ejendomme tilhørende selvejende institutioner, fonde el.lign., hvis vedtægter er godkendt af det offentlige.',NULL,NULL,48,192,NULL,'2026-03-30 23:41:16'),
(1524,1899,0,'Fordeling af udgiften imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. I ejendomme, som helt eller delvis er undtaget fra krav om individuel måling af varme i medfør af byggeloven, fordeles udgifterne efter udlejerens bestemmelse efter bruttoetagearealet eller efter rumfang.',NULL,NULL,76,303,NULL,'2026-03-30 23:41:16'),
(1525,1900,0,'I ejendomme, som helt eller delvis er undtaget fra krav om individuel måling af opvarmning af vand i medfør af byggeloven, fordeles udgifterne efter antallet og arten af varmtvandshaner og antallet af værelser.',NULL,NULL,53,210,NULL,'2026-03-30 23:41:16'),
(1526,1902,0,'Leverer udlejeren køling, kan udlejeren kræve sine udgifter til lejerens forbrug og andel i andre udgifter som nævnt i § 72, stk. 4, refunderet. Fordeling af udgiften imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. Er ejendommen helt eller delvis undtaget fra krav om individuel måling af køling i medfør af byggeloven, indeholdes udgifterne hertil i lejen.',NULL,NULL,97,386,NULL,'2026-03-30 23:41:16'),
(1527,1903,0,'Leverer udlejeren køling, og er udgiften hertil indeholdt i lejen, kan beboerrepræsentanterne eller et flertal af lejerne forlange, at fordelingen af udgiften fremover skal ske på grundlag af egnede forbrugsmålere. Udlejeren kan forlange, at fordelingen af udgiften i 1. pkt. fremtidig skal ske på grundlag af egnede forbrugsmålere, hvis installation af forbrugsmålere til måling af forbruget af køling er påbudt i henhold til lov. Beslutninger efter 1. og 2. pkt. er bindende for alle lejere uanset tidligere aftaler.',NULL,NULL,130,518,NULL,'2026-03-30 23:41:16'),
(1528,1904,0,'Udlejeren kan modsætte sig gennemførelse af en beslutning efter stk. 2, 1. pkt., hvis udlejeren kan godtgøre, at gennemførelsen ikke kan anses for at være rimelig og hensigtsmæssig.',NULL,NULL,46,181,NULL,'2026-03-30 23:41:16'),
(1529,1905,0,'Udgifter som følge af ændret fordeling betragtes som forbedring.',NULL,NULL,16,64,NULL,'2026-03-30 23:41:16'),
(1530,1906,0,'Beslutninger efter stk. 2 kan gennemføres med 6 ugers varsel til en regnskabsperiodes begyndelse.',NULL,NULL,25,97,NULL,'2026-03-30 23:41:16'),
(1531,1908,0,'Leverer udlejeren koldt vand, kan udlejeren kræve sine udgifter til lejerens forbrug refunderet. Fordeling af udgifterne imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. Er ejendommen helt eller delvis undtaget fra krav om individuel måling af koldt vand i medfør af byggeloven, indeholdes udgifterne hertil i lejen.',NULL,NULL,86,344,NULL,'2026-03-30 23:41:16'),
(1532,1909,0,'§ 67, stk. 2-5, finder tilsvarende anvendelse. Beslutninger efter § 67, stk. 2, vedrørende vand kan gennemføres med 6 ugers varsel og inden for en periode, der må anses for rimelig i forhold til omfanget af den samlede forbedring.',NULL,NULL,58,230,NULL,'2026-03-30 23:41:16'),
(1533,1911,0,'Leverer udlejeren gas til opvarmning og el, kan udlejeren kræve sine udgifter til lejerens forbrug refunderet. Fordeling af udgiften imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. Er ejendommen helt eller delvis undtaget fra krav om individuel måling af el eller gas i medfør af byggeloven, kan fordeling af udgiften ske efter areal eller rumfang. Fordeling af udgiften til el til andet end opvarmning kan dog kun ske ved godkendte individuelle elektricitetsmålere.',NULL,NULL,124,495,NULL,'2026-03-30 23:41:16'),
(1534,1912,0,'Måles forbruget af el og gas i den enkelte boligenhed ved fordelingsmålere, skal fordelingen imellem lejerne ske på grundlag af det målte forbrug. Udlejeren, beboerrepræsentanterne eller et flertal af lejerne kan forlange, at lejerne fremover betaler forbrug på grundlag af afregningsmålere direkte til forsyningsvirksomheden. Ændringen kan gennemføres med 6 ugers varsel. For leverancer af el til opvarmning kan ændringen gennemføres med 6 ugers varsel til et varmeregnskabsårs begyndelse.',NULL,NULL,123,490,NULL,'2026-03-30 23:41:16'),
(1535,1914,0,'Udlejeren kan med 6 ugers varsel til en betalingstermin forlange, at lejeren skal betale acontobidrag til dækning af lejerens andel i ejendommens udgifter vedrørende varme, opvarmning af vand, køling, vand, el og gas, når udgifterne hertil ikke er indeholdt i lejen, jf. dog § 79, stk. 2. Udlejeren kan med samme varsel forlange forhøjelse af løbende acontobidrag.',NULL,NULL,91,364,NULL,'2026-03-30 23:41:16'),
(1536,1915,0,'Bidragene betales med lige store beløb i forbindelse med de almindelige lejebetalinger.',NULL,NULL,22,87,NULL,'2026-03-30 23:41:16'),
(1537,1916,0,'De samlede bidrag for 1 år for henholdsvis varme, opvarmning af vand, køling, vand, el og gas må højst opkræves med den udgift, som forventes at blive pålignet for regnskabsperioden for den pågældende leverance. Ved forhøjelse af det løbende acontobidrag kan det månedlige bidrag højst forøges til 1/12 af den samlede udgift, som forventes at blive pålignet for regnskabsperioden for den pågældende leverance.',NULL,NULL,103,409,NULL,'2026-03-30 23:41:16'),
(1538,1918,0,'Udgifterne i §§ 65-69 opgøres i særskilte forbrugsregnskaber for følgende:',NULL,NULL,19,74,NULL,'2026-03-30 23:41:16'),
(1539,1919,0,'Varme og opvarmning af vand.',NULL,NULL,7,28,NULL,'2026-03-30 23:41:16'),
(1540,1920,0,'Køling.',NULL,NULL,2,7,NULL,'2026-03-30 23:41:16'),
(1541,1921,0,'Vand.',NULL,NULL,2,5,NULL,'2026-03-30 23:41:16'),
(1542,1922,0,'El.',NULL,NULL,1,3,NULL,'2026-03-30 23:41:16'),
(1543,1923,0,'Gas.',NULL,NULL,1,4,NULL,'2026-03-30 23:41:16'),
(1544,1924,0,'Rabatydelser og lign. skal godskrives regnskabet.',NULL,NULL,13,49,NULL,'2026-03-30 23:41:16'),
(1545,1925,0,'Lejerens bidrag efter §§ 65-69 er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1.',NULL,NULL,24,96,NULL,'2026-03-30 23:41:16'),
(1546,1926,0,'I regnskabet for varme og opvarmning af vand og i kølingsregnskabet kan udlejeren kun medtage udgiften til energiforbruget i regnskabsperioden. Sker leverancen fra et kollektivt forsyningsanlæg eller fra et naturgasanlæg, skal udlejeren dog medtage den samlede udgift. Udgifter til kontrol, eftersyn og vedligeholdelse af henholdsvis varmeanlæg og kølingsanlæg, der er pålagt udlejeren i henhold til lov om fremme af energibesparelser i bygninger, skal medtages i regnskabet.',NULL,NULL,119,475,NULL,'2026-03-30 23:41:16'),
(1547,1927,0,'Udgifterne til energimærkning medtages i regnskabet for varme og opvarmning af vand som en forholdsmæssig del med lige store beløb i hvert af årene i den periode, energimærkningen er gyldig. Endvidere kan medtages en passende forrentning af udgiften til energimærkning, der ikke er dækket ved lejernes betaling efter 1. pkt. Udlejeren har pligt til at orientere lejerne om, at der er udarbejdet energimærkning i henhold til lov om fremme af energibesparelser i bygninger og på en lejers forlangende give denne eller dennes befuldmægtigede adgang til at gennemgå dette materiale og eventuelle bilag hertil.',NULL,NULL,152,605,NULL,'2026-03-30 23:41:16'),
(1548,1928,0,'I vandregnskabet kan udlejeren medtage samtlige udgifter vedrørende forsyning med vand, herunder vand- og vandafledningsafgift, i regnskabsperioden.',NULL,NULL,37,148,NULL,'2026-03-30 23:41:16'),
(1549,1929,0,'Skal en udgift, der hidtil har været indeholdt i lejen, fremover indgå i et forbrugsregnskab, jf. stk. 1, nedsættes lejen samtidig med et beløb, der svarer til det, der var indeholdt i lejen.',NULL,NULL,48,191,NULL,'2026-03-30 23:41:16'),
(1550,1930,0,'Forbrugsregnskabet skal indeholde oplysning om lejerens andel af de samlede udgifter og om lejerens adgang til at gøre indsigelse, jf. § 77. Regnskabet skal endvidere indeholde oplysning om tidspunktet for udlejerens modtagelse af endelig afregning af leverancen fra et kollektivt forsyningsanlæg eller et naturgasanlæg, hvis regnskabet kommer frem til lejeren efter udløbet af fristen i § 75, 1. pkt. Indeholder regnskabet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,116,464,NULL,'2026-03-30 23:41:16'),
(1551,1931,0,'Medmindre andet er aftalt, begynder regnskabsåret for de i § 72, stk. 1, nr. 1, 2, 4 og 5, anførte regnskaber den 1. juni, jf. dog stk. 2-4.',NULL,NULL,35,140,NULL,'2026-03-30 23:41:16'),
(1552,1932,0,'Udlejeren kan med 6 ugers varsel bestemme, at regnskabet fremover skal begynde på en anden dato, jf. dog stk. 3 og 4. Regnskabsperioden ved overgangen til det nye regnskabsår må højst være 18 måneder.',NULL,NULL,50,200,NULL,'2026-03-30 23:41:16'),
(1553,1933,0,'For ejendomme, hvor leverancen af varme sker fra et kollektivt varmeforsyningsanlæg eller et naturgasanlæg, og for ejendomme, hvor leverancen af køling sker fra et kollektivt kølingsforsyningsanlæg, skal forbrugsregnskabet følge forsyningsanlæggets regnskabsår eller aflæsningsperiode.',NULL,NULL,72,285,NULL,'2026-03-30 23:41:16'),
(1554,1934,0,'For ejendomme, hvor leverancen af vand sker fra en kommune eller et vandværk, skal regnskabsåret fastsættes, således at det svarer til det, som udlejeren afregner efter i forhold til kommunen eller vandværket. Udlejeren kan dog beslutte, at vandregnskabsåret skal følge varmeregnskabsåret, jf. stk. 1 og 3.',NULL,NULL,77,306,NULL,'2026-03-30 23:41:16'),
(1555,1935,0,'Forbrugsregnskabet, jf. § 72, stk. 1, skal være kommet frem til lejerne senest 4 måneder efter regnskabsårets udløb. Indeholder regnskabet udgifter vedrørende leverancer fra et kollektivt forsyningsanlæg eller et naturgasanlæg, jf. § 72, stk. 1, nr. 1-5, skal regnskabet være kommet frem til lejerne, senest 3 måneder efter at udlejeren har modtaget endelig afregning fra forsyningsanlægget, hvis dette tidspunkt er senere end fristen efter 1. pkt.',NULL,NULL,112,448,NULL,'2026-03-30 23:41:16'),
(1556,1936,0,'Når et forbrugsregnskab er udsendt, skal udlejeren på lejerens forlangende give lejeren eller dennes befuldmægtigede adgang til at gennemgå bilagene til regnskabet på ejendommen eller andetsteds i vedkommende byområde.',NULL,NULL,55,218,NULL,'2026-03-30 23:41:16'),
(1557,1937,0,'Lejeren kan skriftligt gøre indsigelse mod de enkelte forbrugsregnskaber, senest 6 uger efter at regnskabet er kommet frem til lejeren. I ejendomme med beboerrepræsentation kan beboerrepræsentanterne på samtlige lejeres vegne gøre indsigelse mod de enkelte regnskaber, jf. 1. pkt. Indsigelsen skal indeholde oplysning om, på hvilke punkter regnskabet ikke kan godkendes. Udlejeren skal indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde sit krav om efterbetaling i henhold til regnskabet.',NULL,NULL,137,547,NULL,'2026-03-30 23:41:16'),
(1558,1938,0,'Har lejeren i henhold til et forbrugsregnskab betalt for lidt i acontobidrag, kan udlejeren kræve tillægsbetaling ved den første lejebetaling, der skal finde sted, når der er forløbet 1 måned, efter at forbrugsregnskabet er kommet frem til lejeren. Overstiger tillægsbetalingen 3 måneders leje, er lejeren dog berettiget til at betale i tre lige store månedlige rater, således at første rate forfalder til det fastsatte tidspunkt for tillægsbetalingen. Fraflytter lejeren, skal tillægsbetaling senest betales på fraflytningsdagen.',NULL,NULL,133,530,NULL,'2026-03-30 23:41:16'),
(1559,1939,0,'Har lejeren i henhold til et forbrugsregnskab betalt for meget i acontobidrag, skal det for meget betalte beløb tilbagebetales lejeren eller fradrages i første lejebetaling, efter at forbrugsregnskabet er kommet frem til lejeren.',NULL,NULL,58,229,NULL,'2026-03-30 23:41:16'),
(1560,1940,0,'Er forbrugsregnskabet ikke kommet frem til lejeren ved udløbet af den i § 75 nævnte frist, mister udlejeren sin ret til at kræve tillægsbetaling af lejeren.',NULL,NULL,39,156,NULL,'2026-03-30 23:41:16'),
(1561,1941,0,'Er forbrugsregnskabet ikke kommet frem til lejeren inden 2 måneder efter den i § 75 nævnte frist, kan lejeren undlade at indbetale acontobidrag, indtil regnskabet er kommet frem til lejeren og lejeren har modtaget et eventuelt for meget betalt bidrag for den afsluttede regnskabsperiode.',NULL,NULL,72,287,NULL,'2026-03-30 23:41:16'),
(1562,1942,0,'Har udlejeren som følge af en undskyldelig fejl ikke medtaget en udgiftspost på forbrugsregnskabet, kan udlejeren til det følgende forbrugsregnskab overføre den del af posten, som ikke overstiger 10 pct. af de samlede udgifter i det først afsluttede regnskab. Udlejeren skal orientere lejerne om størrelsen af det overførte beløb.',NULL,NULL,83,330,NULL,'2026-03-30 23:41:16'),
(1563,1943,0,'I tilfælde af fejlagtig udgiftsfordeling mellem lejerne skal udlejeren snarest rette fejlen ved skriftlig meddelelse til de berørte lejere. Med hensyn til tillægsbetaling og tilbagebetaling som følge af rettelsen finder § 78 og § 79, stk. 1, tilsvarende anvendelse.',NULL,NULL,67,265,NULL,'2026-03-30 23:41:16'),
(1564,1945,0,'Indenrigs- og boligministeren kan fastsætte regler om, hvordan udgifter til kontrol, eftersyn og vedligeholdelse af tekniske anlæg til varme og opvarmning af vand samt køling, som er pålagt udlejeren i henhold til lov om fremme af energibesparelser i bygninger, fordeles mellem ejendommens lejligheder og lokaler.',NULL,NULL,79,313,NULL,'2026-03-30 23:41:16'),
(1565,1946,0,'Indenrigs- og boligministeren kan fastsætte regler om, at engangsydelser eller udgifter, der ikke betales hvert år, skal fordeles over flere regnskabsår, og at udlejeren kan medtage en passende forrentning af den del af udgiften, der ikke er dækket ved lejernes løbende betaling.',NULL,NULL,70,279,NULL,'2026-03-30 23:41:16'),
(1566,1948,0,'Uenighed om lejerens betaling for varme, opvarmning af vand, køling, vand, el og gas, herunder uenighed om acontobidrag, og hvor udlejeren modsætter sig at opsætte målere i henhold til § 67, stk. 2, § 68, stk. 2, og § 70, 2. pkt., afgøres af huslejenævnet.',NULL,NULL,64,256,NULL,'2026-03-30 23:41:16'),
(1567,1950,0,'§§ 65-69, § 72, stk. 3-5, og § 74, stk. 3, kan ikke fraviges.',NULL,NULL,16,61,NULL,'2026-03-30 23:41:16'),
(1568,1951,0,'De øvrige bestemmelser i dette kapitel kan ikke fraviges til skade for lejeren.',NULL,NULL,20,79,NULL,'2026-03-30 23:41:16'),
(1569,1954,0,'Leverer udlejeren fælles programforsyning, kan udlejeren forlange de nødvendige og rimelige udgifter til etablering og forbedring, jf. stk. 2, og drift heraf refunderet, herunder udgifter til administration. Det samme gælder forsyning med adgang til elektroniske kommunikationstjenester. Udgifterne fordeles ligeligt på de lejemål i ejendommen, hvor lejeren ifølge aftale med udlejeren er forpligtet til at bidrage til den fælles programforsyning eller til den fælles forsyning med adgang til elektroniske kommunikationstjenester, jf. dog § 85. Udgifterne kan ikke indeholdes i lejen.',NULL,NULL,146,584,NULL,'2026-03-30 23:41:16'),
(1570,1955,0,'Har udlejeren efter aftale med lejeren etableret eller forbedret ejendommens programforsyning eller forsyning med adgang til elektroniske kommunikationstjenester, kan udlejeren forlange, at lejeren godtgør udlejeren de etablerings- og forbedringsudgifter, der med rimelighed er afholdt. Uden aftale kan udlejeren dog forlange godtgørelse for udgifter, der med rimelighed er afholdt til forbedringer, det påhviler udlejeren at udføre efter anden lovgivning. Udlejeren kan forlange en passende forrentning og afskrivning af udgifterne. Udgifter til vedligeholdelse af fællesantenneanlæg eller fælles forsyning med adgang til elektroniske kommunikationstjenester kan ikke fradrages på ejendommens konti for udvendig vedligeholdelse, jf. §§ 119 og 120. Der kan ikke beregnes lejeforhøjelse efter §§ 128 og 129 for etablering og forbedring af fællesantenner.',NULL,NULL,214,853,NULL,'2026-03-30 23:41:16'),
(1571,1956,0,'Lejerens bidrag til udgifter efter stk. 1 er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:16'),
(1572,1958,0,'For lejemål, hvor lejeren under iagttagelse af reglerne i § 6 a i lov om radio- og fjernsynsvirksomhed m.v. og de i medfør af § 6 a, stk. 6, i lov om radio- og fjernsynsvirksomhed m.v. udstedte regler har fravalgt tilslutning til og betaling for fælles programforsyning, eller hvor lejeren har individuelt valg af elektroniske kommunikationstjenester, skal den enkelte lejer kun betale for de programmer eller de elektroniske kommunikationstjenester, som lejeren har adgang til.',NULL,NULL,120,478,NULL,'2026-03-30 23:41:16'),
(1573,1959,0,'Har lejeren fravalgt tilslutning til og betaling for programforsyning i et fællesantenneanlæg, som ejes af andre end udlejeren, kan lejeren ikke pålægges at betale til etablering, forbedring og drift af anlægget bortset fra rimelige udgifter til administration. Ejes fællesantenneanlægget af andre end udlejeren, og benyttes anlægget også til fremføring af andre elektroniske kommunikationstjenester, kan alle husstande uanset fravalg af fælles programforsyning pålægges at betale til etablering, forbedring og drift, herunder administration af anlægget.',NULL,NULL,139,554,NULL,'2026-03-30 23:41:16'),
(1574,1961,0,'Leverer udlejeren fælles programforsyning eller fælles forsyning med adgang til elektroniske kommunikationstjenester m.v. i ejendommen, kan udlejeren uanset modstående aftale med 6 måneders varsel meddele lejeren, at udlejeren bringer leveringen af fælles programforsyning eller fælles forsyning med adgang til elektroniske kommunikationstjenester m.v. i ejendommen til ophør.',NULL,NULL,94,376,NULL,'2026-03-30 23:41:16'),
(1575,1962,0,'Har udlejeren gjort sig skyldig i grov tilsidesættelse af sine forpligtelser vedrørende administration af den fælles programforsyning eller den fælles forsyning med adgang til elektroniske kommunikationstjenester m.v., kan lejeren med virkning for fremtiden frigøre sig fra forpligtelsen til at modtage den fælles programforsyning eller den fælles adgang til elektroniske kommunikationstjenester, som udlejeren foranstalter fordelt i ejendommen.',NULL,NULL,112,445,NULL,'2026-03-30 23:41:16'),
(1576,1964,0,'Huslejenævnet afgør uenighed imellem lejeren og udlejeren vedrørende §§ 84-86.',NULL,NULL,20,78,NULL,'2026-03-30 23:41:16'),
(1577,1965,0,'Efter lejerens anmodning skal huslejenævnet afgøre, om udlejeren har opkrævet større beløb end tilladt efter §§ 84 og 85. Har udlejeren efter nævnets afgørelse opkrævet større beløb end tilladt, kan lejeren forlange det for meget betalte beløb tilbage. § 15, stk. 3, 2. og 3. pkt., finder tilsvarende anvendelse.',NULL,NULL,78,312,NULL,'2026-03-30 23:41:16'),
(1578,1967,0,'§§ 84 og 85 kan ikke fraviges til skade for lejeren. §§ 86 og 87 kan ikke fraviges.',NULL,NULL,21,83,NULL,'2026-03-30 23:41:16'),
(1579,1970,0,'Udlejeren skal stille det lejede til lejerens rådighed i god og forsvarlig stand fra tidspunktet for lejeforholdets begyndelse. På overtagelsestidspunktet skal det lejede være rengjort, ruderne skal være hele, og alle udvendige døre skal være forsynet med brugelige låse med tilhørende nøgler.',NULL,NULL,74,293,NULL,'2026-03-30 23:41:16'),
(1580,1972,0,'Udlejeren, der udlejer mere end én beboelseslejlighed, skal syne beboelseslejligheden i forbindelse med indflytningen og udarbejde en indflytningsrapport. Den indflyttende lejer skal indkaldes til synet.',NULL,NULL,51,203,NULL,'2026-03-30 23:41:16'),
(1581,1973,0,'Indflytningsrapporten, jf. stk. 1, skal udleveres til lejeren ved synet, eventuelt i et digitalt dokument, jf. dog § 13, stk. 1. Er lejeren ikke til stede ved synet, eller vil lejeren ikke kvittere for modtagelsen af rapporten, skal rapporten sendes til lejeren senest 2 uger efter synet.',NULL,NULL,72,288,NULL,'2026-03-30 23:41:16'),
(1582,1974,0,'Ved overtrædelse af stk. 1 og 2 bortfalder udlejerens krav på istandsættelse efter § 187, stk. 1, medmindre kravet skyldes skader, som lejeren er ansvarlig for.',NULL,NULL,40,160,NULL,'2026-03-30 23:41:16'),
(1583,1976,0,'Er det lejede mangelfuldt ved lejeforholdets begyndelse, skal lejeren for ikke at miste retten til at påberåbe sig manglen, jf. §§ 95-97, senest 2 uger efter lejeforholdets begyndelse meddele udlejeren, at lejeren vil gøre den gældende. Dette gælder dog ikke, hvis manglen ikke kan erkendes ved anvendelse af sædvanlig agtpågivenhed eller udlejeren har handlet svigagtigt.',NULL,NULL,93,372,NULL,'2026-03-30 23:41:16'),
(1584,1978,0,'Uenighed om, hvorvidt det lejede er mangelfuldt ved lejeforholdets begyndelse, afgøres af huslejenævnet.',NULL,NULL,26,104,NULL,'2026-03-30 23:41:16'),
(1585,1979,0,'Huslejenævnet kan pålægge udlejeren at udbedre manglen.',NULL,NULL,14,55,NULL,'2026-03-30 23:41:16'),
(1586,1981,0,'§§ 90-92 kan ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,15,60,NULL,'2026-03-30 23:41:16'),
(1587,1984,0,'Er det lejede ikke fuldført på det tidspunkt, hvor lejeren efter aftalen skal overtage lejemålet, eller er den tidligere lejer ikke fraflyttet på overtagelsestidspunktet, eller foreligger der en anden hindring for lejerens overtagelse af det lejede til den aftalte tid, uden at dette skyldes lejerens forhold, kan lejeren kræve et forholdsmæssigt afslag i lejen.',NULL,NULL,91,362,NULL,'2026-03-30 23:41:16'),
(1588,1985,0,'Lejeren kan hæve lejeaftalen ved væsentlig forsinkelse i de tilfælde, som er omtalt i stk. 1, medmindre forsinkelsen af udlejeren måtte forudsættes ikke at være af væsentlig betydning for lejeren. Retten til at hæve lejeaftalen er betinget af, at lejeren, efter at forsinkelsen er indtrådt, har fremsat påkrav over for udlejeren, og at lejerens overtagelse ikke kan ske inden rimelig tid derefter. Er det lejede ikke fuldført ved lejeaftalens indgåelse, og er overtagelsestidspunktet ikke aftalt, kan lejeren til enhver tid inden overtagelsen hæve aftalen. Lejeaftalen kan dog altid hæves ved enhver forsinkelse, hvis lejeren udtrykkeligt har betinget sig overtagelse af lokalerne til et bestemt tidspunkt.',NULL,NULL,177,706,NULL,'2026-03-30 23:41:16'),
(1589,1986,0,'Uanset om lejeren hæver lejeaftalen, kan lejeren i de tilfælde, hvor den tidligere lejer ikke er fraflyttet, kræve erstatning, medmindre udlejeren godtgør, at forsinkelsen ikke skyldes noget forhold, som udlejeren er ansvarlig for.',NULL,NULL,58,231,NULL,'2026-03-30 23:41:16'),
(1590,1988,0,'Er det lejede ikke ved overtagelsen og under lejeforholdets bestående i den stand, som lejeren efter retsforholdet mellem lejeren og udlejeren kan kræve, og afhjælper udlejeren ikke straks manglen efter påkrav derom, kan lejeren selv afhjælpe den for udlejerens regning. Vedrører manglen det lejedes forsyning med lys, gas, varme, kulde el.lign., kan lejeren ved fogedens bistand skaffe sig adgang til ejendommens installationer for at afhjælpe manglen. 1. og 2. pkt. finder tilsvarende anvendelse, hvis udlejeren uberettiget har afbrudt det lejedes forsyning med lys, gas, varme, kulde el.lign. Hvis manglen vedrører det lejedes forsyning med varme, opvarmning af brugsvand, el eller vand, kan lejeren rette henvendelse til kommunen med henblik på at få genoptaget forsyningen efter reglerne i kapitel 3 om kommunal sikring af forsyning med vand, varme og el i lov om boligforhold.',NULL,NULL,221,882,NULL,'2026-03-30 23:41:16'),
(1591,1989,0,'Lejeren kan kræve et forholdsmæssigt afslag i lejen, så længe en mangel forringer det lejedes værdi for lejeren.',NULL,NULL,28,112,NULL,'2026-03-30 23:41:16'),
(1592,1990,0,'Er det lejede mangelfuldt som nævnt i § 95, og afhjælper udlejeren ikke straks manglen, eller kan den ikke afhjælpes inden for en rimelig tid, kan lejeren hæve lejeaftalen, hvis manglen må anses for væsentlig eller udlejeren har handlet svigagtigt.',NULL,NULL,62,248,NULL,'2026-03-30 23:41:16'),
(1593,1991,0,'Er manglen afhjulpet, inden lejeren har hævet lejeaftalen, kan lejeren ikke senere påberåbe sig manglen som grund for ophævelse.',NULL,NULL,32,128,NULL,'2026-03-30 23:41:16'),
(1594,1992,0,'Lejeren kan kræve erstatning, hvis det lejede ved aftalens indgåelse savnede egenskaber, som må anses for tilsikrede, eller udlejeren har handlet svigagtigt. Det samme gælder, hvis det lejede senere lider skade som følge af udlejerens forsømmelse eller der i øvrigt opstår hindringer eller ulemper for lejerens brugsret som følge af forhold, som udlejeren er ansvarlig for.',NULL,NULL,94,373,NULL,'2026-03-30 23:41:16'),
(1595,1993,0,'Bliver det lejede ødelagt ved brand eller anden ulykke, bortfalder aftalen.',NULL,NULL,19,75,NULL,'2026-03-30 23:41:16'),
(1596,1995,0,'Er brugen af det lejede helt eller delvis i strid med lovgivning, andre offentlige forskrifter eller servitutter eller andre lignende rettigheder over ejendommen, som var gældende ved lejeaftalens indgåelse, kan lejeren kræve et forholdsmæssigt afslag i lejen og erstatning. Lejeren kan endvidere hæve lejeaftalen, såfremt brugen indskrænkes væsentligt eller udlejeren har handlet svigagtigt.',NULL,NULL,98,392,NULL,'2026-03-30 23:41:16'),
(1597,1996,0,'Stk. 1 gælder ikke, hvis lejeren vidste, at brugen var retsstridig, og heller ikke, hvis lejerens ukendskab skyldes grov uagtsomhed. Endvidere finder stk. 1 ikke anvendelse, hvis det retsstridige forhold ikke har medført nogen indskrænkninger i lejerens brugsret og udlejeren efter opfordring straks bringer forholdet i orden.',NULL,NULL,82,326,NULL,'2026-03-30 23:41:16'),
(1598,1997,0,'Er det lejede mangelfuldt efter stk. 1, skal lejeren for ikke at miste retten til at påberåbe sig manglen senest 2 uger efter lejeforholdets begyndelse meddele udlejeren, at lejeren vil gøre den gældende. Dette gælder dog ikke, hvis manglen ikke kan erkendes ved anvendelse af sædvanlig agtpågivenhed eller udlejeren har handlet svigagtigt.',NULL,NULL,85,340,NULL,'2026-03-30 23:41:16'),
(1599,1998,0,'Bringes et lejeforhold bortset fra de i § 99 nævnte tilfælde til ophør i utide på grund af andre rettigheder over ejendommen, kan lejeren kræve erstatning af udlejeren.',NULL,NULL,42,168,NULL,'2026-03-30 23:41:16'),
(1600,1999,0,'Bringes lejeforholdet til ophør i utide, fordi det offentlige af sundhedsmæssige eller andre grunde nedlægger forbud mod lejerens brug, er lejeren kun pligtig at betale leje indtil den dag, forbuddet træder i kraft. Hvis forbuddet kun begrænser brugen på mindre væsentlig måde, kan lejeren dog kun kræve et forholdsmæssigt afslag i lejen.',NULL,NULL,85,338,NULL,'2026-03-30 23:41:16'),
(1601,2001,0,'§§ 94-100 kan ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,16,61,NULL,'2026-03-30 23:41:16'),
(1602,2004,0,'Udlejeren eller dennes stedfortræder har ret til at få eller skaffe sig adgang til det lejede, når forholdene kræver det.',NULL,NULL,31,121,NULL,'2026-03-30 23:41:16'),
(1603,2005,0,'Udlejeren kan med 6 ugers varsel iværksætte arbejder i det lejede, når udførelsen ikke er til væsentlig ulempe for lejeren.',NULL,NULL,31,123,NULL,'2026-03-30 23:41:16'),
(1604,2006,0,'Inden iværksættelse af andre arbejder har lejeren krav på 3 måneders varsel.',NULL,NULL,19,76,NULL,'2026-03-30 23:41:16'),
(1605,2007,0,'Udlejeren kan dog altid uden varsel foretage uopsættelige reparationer i det lejede.',NULL,NULL,21,84,NULL,'2026-03-30 23:41:16'),
(1606,2009,0,'Ethvert arbejde, der iværksættes af udlejeren, skal udføres uden afbrydelse og med den størst mulige hensyntagen til lejeren. Udlejeren skal straks foretage efterreparationer.',NULL,NULL,44,175,NULL,'2026-03-30 23:41:16'),
(1607,2010,0,'Inden udlejeren i ejendomme omfattet af § 6, stk. 1, og § 7, stk. 3, 3. pkt., iværksætter en forbedring, der vil medføre en lejeforhøjelse, der sammen med forbedringsforhøjelser gennemført i de sidste 3 år vil udgøre mere end 100 kr. pr. m² bruttoetageareal pr. år, skal udlejeren fremsætte skriftligt varsel herom over for de lejere, hvis lejeforhold ønskes forbedret. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,115,460,NULL,'2026-03-30 23:41:16'),
(1608,2011,0,'I ejendomme med beboerrepræsentation skal udlejeren fremsætte tilsvarende varsel efter stk. 1 over for beboerrepræsentanterne.',NULL,NULL,32,126,NULL,'2026-03-30 23:41:16'),
(1609,2012,0,'Varsling i henhold til stk. 1 og 2 skal indeholde en beskrivelse af arbejdet med overslag over udgifterne og den forventede størrelse af den lejeforhøjelse, der er en følge af forbedringens gennemførelse. Varslingen skal endvidere indeholde oplysning om beboerrepræsentationens eller i ejendomme uden beboerrepræsentation lejernes adgang til at gøre indsigelse, jf. stk. 4. I ejendomme med beboerrepræsentation skal lejerne tillige have oplysning om, at kravet samtidig er forelagt for beboerrepræsentanterne. Indeholder varslingen ikke disse oplysninger, er den ugyldig.',NULL,NULL,143,571,NULL,'2026-03-30 23:41:16'),
(1610,2013,0,'Har beboerrepræsentationen, eller i ejendomme uden beboerrepræsentation mindst en fjerdedel af lejerne, senest 6 uger efter at varslingsskrivelsen er kommet frem til dem, skriftligt fremsat indsigelse mod iværksættelsen af en forbedring som nævnt i stk. 1, skal udlejeren inden yderligere 6 uger indbringe sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om forbedringen.',NULL,NULL,98,392,NULL,'2026-03-30 23:41:16'),
(1611,2014,0,'Vil en forbedring medføre en lejeforhøjelse, der sammen med lejeforhøjelser for forbedringer gennemført i de sidste 3 år vil udgøre mere end 199 kr. pr. m² bruttoetageareal pr. år, skal udlejeren i ejendomme omfattet af § 6, stk. 1, og § 7, stk. 3, 3. pkt., senest 3 måneder før forbedringens iværksættelse underrette lejeren om, at denne kan kræve at få tilbudt anden passende bolig inden udløbet af den i stk. 2 nævnte frist. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,130,518,NULL,'2026-03-30 23:41:16'),
(1612,2015,0,'Fremsætter lejeren senest 6 uger efter varslingen efter stk. 1 krav om at få tilbudt anden passende bolig, skal udlejeren inden forbedringens iværksættelse tilbyde lejeren en bolig af passende størrelse, beliggenhed, kvalitet og udstyr og til en leje, der efter fradrag af eventuel boligstøtte ikke afviger væsentligt fra den hidtidige leje. Lejligheden har en passende størrelse, når den har samme værelsesantal som lejerens hidtidige lejlighed eller den har et værelse mere end antallet af husstandsmedlemmer.',NULL,NULL,128,511,NULL,'2026-03-30 23:41:16'),
(1613,2016,0,'Såfremt lejeren gør indsigelse, fordi denne finder, at udlejerens tilbud om anden bolig ikke opfylder betingelserne i stk. 2, skal udlejeren indbringe spørgsmålet for huslejenævnet.',NULL,NULL,46,181,NULL,'2026-03-30 23:41:16'),
(1614,2017,0,'Over for en lejer, der ikke har fået underretning efter stk. 1 om sin ret til at kræve anden bolig, kan lejeforhøjelse som følge af forbedringen ikke gennemføres ud over den i stk. 1 angivne grænse. Tilsvarende gælder, hvis udlejeren ikke overholder forpligtelserne efter stk. 2 og 3.',NULL,NULL,71,284,NULL,'2026-03-30 23:41:16'),
(1615,2018,0,'Når forbedringen alene omfatter foranstaltninger, der er påbudt i henhold til lov, arbejder, der er gennemført i medfør af § 146, eller foranstaltninger, der er omfattet af den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 658 af 11. august 1993, af kapitel 5 i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003, eller af den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, finder reglerne i §§ 105 og 106 ikke anvendelse.',NULL,NULL,142,568,NULL,'2026-03-30 23:41:16'),
(1616,2020,0,'Huslejenævnet træffer afgørelse i tvister efter dette kapitel.',NULL,NULL,16,62,NULL,'2026-03-30 23:41:16'),
(1617,2021,0,'Udfører udlejeren ikke et påbegyndt forbedringsarbejde med den fornødne hurtighed, jf. § 104, kan huslejenævnet fastsætte en tidsfrist for arbejdets fuldførelse.',NULL,NULL,41,161,NULL,'2026-03-30 23:41:16'),
(1618,2022,0,'Indbringes sag om iværksættelse af forbedringer efter § 105, kan huslejenævnet modsætte sig iværksættelsen, hvis forbedringen må anses for uhensigtsmæssig under hensyn til ejendommens alder, beliggenhed og beskaffenhed. Det samme gælder, hvis forbedringen ikke skønnes at medføre en passende forøgelse af brugsværdien under hensyn til ejendommens og de pågældende rums karakter, tilstand, indretning og udstyr. Det kan herved tages i betragtning, om ændringer, som foranstaltningerne vil medføre i de enkelte udlejede rum, skønnes rimelige i forhold til disses hidtidige hensigtsmæssige anvendelse.',NULL,NULL,150,598,NULL,'2026-03-30 23:41:16'),
(1619,2023,0,'Såfremt udlejeren iværksætter en forbedring, som nævnet har modsat sig, kan udlejeren ikke kræve lejeforhøjelse for forbedringen.',NULL,NULL,33,129,NULL,'2026-03-30 23:41:16'),
(1620,2024,0,'Indbringelse efter §§ 89 eller 90 i lov om boligforhold af en afgørelse, hvorved nævnet har tiltrådt iværksættelse af en forbedring, har opsættende virkning.',NULL,NULL,40,157,NULL,'2026-03-30 23:41:16'),
(1621,2026,0,'Dette kapitel kan ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,17,65,NULL,'2026-03-30 23:41:16'),
(1622,2029,0,'Ved vedligeholdelse forstås de reparationer og udskiftninger, som udføres med henblik på at bevare og opretholde lejemålets og ejendommens stand, efterhånden som der sker forringelse ved slid og ælde.',NULL,NULL,50,200,NULL,'2026-03-30 23:41:16'),
(1623,2030,0,'Ved indvendig vedligeholdelse forstås vedligeholdelse af lejligheden med hvidtning, maling, tapetsering og behandling af gulve.',NULL,NULL,32,127,NULL,'2026-03-30 23:41:16'),
(1624,2031,0,'Ved udvendig vedligeholdelse forstås vedligeholdelse af alle dele af ejendommen og det lejede, som ikke er omfattet af den indvendige vedligeholdelse.',NULL,NULL,38,150,NULL,'2026-03-30 23:41:16'),
(1625,2033,0,'Vedligeholdelse, herunder såvel indvendig som udvendig vedligeholdelse, jf. stk. 2, som følge af forringelse ved slid og ælde skal foretages, så ofte det er påkrævet under hensyn til ejendommens og det lejedes karakter, jf. dog § 117.',NULL,NULL,59,234,NULL,'2026-03-30 23:41:16'),
(1626,2034,0,'Udlejeren skal holde ejendommen og det lejede forsvarligt ved lige, herunder vedligeholde alle indretninger til afløb og til forsyning med el, gas, vand, varme og kulde, og sørge for renholdelse og sædvanlig belysning af ejendommen og adgangsvejene til det lejede, ligesom udlejeren skal renholde fortov, gård og andre fælles indretninger.',NULL,NULL,85,339,NULL,'2026-03-30 23:41:16'),
(1627,2035,0,'Lejeren skal i lejeperioden foretage vedligeholdelse og fornøden fornyelse af låse og nøgler.',NULL,NULL,24,93,NULL,'2026-03-30 23:41:16'),
(1628,2037,0,'Udlejeren skal hvert år inden den 1. juli udarbejde en plan for ejendommens vedligeholdelse i den kommende 10-årsperiode. Planen skal omfatte større vedligeholdelsesarbejder på ejendommen. I ejendomme med beboerrepræsentation skal udlejeren indkalde beboerrepræsentationen til møde med henblik på udarbejdelse og revision af vedligeholdelsesplanen.',NULL,NULL,87,348,NULL,'2026-03-30 23:41:16'),
(1629,2038,0,'Udlejeren mister retten til at opkræve beløb efter §§ 119 og 120, hvis udlejeren ikke har udarbejdet en vedligeholdelsesplan for ejendommen i overensstemmelse med stk. 1 og lejerne har indbragt sag herom for huslejenævnet. Udlejeren kan ikke opkræve de nævnte beløb fra lejernes indbringelse af sag for huslejenævnet, indtil en vedligeholdelsesplan er udarbejdet og udleveret til lejerne.',NULL,NULL,97,388,NULL,'2026-03-30 23:41:16'),
(1630,2039,0,'Stk. 1 gælder ikke for ejendomme omfattet af § 3 b i lov om andelsboligforeninger og andre boligfællesskaber.',NULL,NULL,28,109,NULL,'2026-03-30 23:41:16'),
(1631,2040,0,'Indenrigs- og boligministeren fastsætter nærmere regler om udarbejdelse af vedligeholdelsesplaner.',NULL,NULL,25,98,NULL,'2026-03-30 23:41:16'),
(1632,2042,0,'Huslejenævnet træffer afgørelse i tvister om opfyldelse af henholdsvis lejerens og udlejerens pligt til renholdelse og vedligeholdelse, jf. § 112. Huslejenævnet træffer endvidere afgørelse i tvister om udarbejdelse og gennemførelse af vedligeholdelsesplaner, jf. § 113.',NULL,NULL,68,269,NULL,'2026-03-30 23:41:16'),
(1633,2043,0,'Huslejenævnet kan på lejerens begæring pålægge udlejeren at lade bestemte arbejder udføre og kan fastsætte nærmere retningslinjer herom. Huslejenævnet skal fastsætte en tidsfrist for det enkelte arbejdes fuldførelse. Huslejenævnet kan samtidig bestemme, at lejen skal nedsættes med et beløb, der svarer til forringelsen af det lejedes værdi, hvis udlejeren ikke overholder den frist, der er fastsat efter 2. pkt. Lejenedsættelsen gælder, indtil arbejderne er udført eller huslejenævnet beslutter, at ejendommen skal administreres på ejerens vegne, jf. kapitel 5 i lov om boligforhold. Grundejernes Investeringsfond kan træffe beslutning om at iværksætte arbejderne på udlejerens vegne, jf. § 70, stk. 1, i lov om boligforhold.',NULL,NULL,182,726,NULL,'2026-03-30 23:41:16'),
(1634,2044,0,'Huslejenævnet kan give påbud efter stk. 2, uanset om udgifterne kan afholdes af indestående på konti efter §§ 119 og 120.',NULL,NULL,31,121,NULL,'2026-03-30 23:41:16'),
(1635,2046,0,'§§ 111, 113 og 114 kan ikke fraviges ved aftale. § 112 kan ikke ved aftale fraviges til skade for lejeren bortset fra aftale om, at lejeren overtager pligten til vedligeholdelse. Det kan ikke aftales, at lejeren ved fraflytning skal istandsætte andet end de dele af det lejede, som er omfattet af lejerens vedligeholdelsespligt.',NULL,NULL,82,328,NULL,'2026-03-30 23:41:16'),
(1636,2047,0,'§ 112, stk. 2, kan ikke fraviges til skade for lejeren, for så vidt angår udvendig vedligeholdelse, i ejendomme omfattet af § 6, stk. 1. Det kan dog aftales, at lejeren skal vedligeholde den have, som indgår i det lejede.',NULL,NULL,56,221,NULL,'2026-03-30 23:41:16'),
(1637,2050,0,'Når en lejlighed er udlejet helt eller delvis til beboelse, anses udlejerens pligt til indvendig vedligeholdelse for opfyldt, når udlejeren til dette formål løbende har afholdt de beløb, der skal anvendes hertil efter reglerne i §§ 117 og 118. Omfatter en lejeaftale såvel lokaler, der er udlejet til beboelse, som lokaler, der udelukkende er udlejet til andet end beboelse, og er lokalerne beliggende i hver sin fysiske enhed, finder 1. pkt. kun anvendelse, for så vidt angår den del af det lejede, der er udlejet til beboelse.',NULL,NULL,132,528,NULL,'2026-03-30 23:41:16'),
(1638,2051,0,'Udlejeren skal i hvert regnskabsår afsætte 46 kr. pr. m² bruttoareal på en vedligeholdelseskonto for lejligheden til opfyldelse af den indvendige vedligeholdelsespligt. Beløbene afsættes med 1/12 månedsvis. Det i 1. pkt. nævnte beløb er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,77,306,NULL,'2026-03-30 23:41:16'),
(1639,2052,0,'Har lejeren ved aftale delvis overtaget pligten til indvendig vedligeholdelse, nedsættes det beløb, der afsættes på vedligeholdelseskontoen, forholdsmæssigt.',NULL,NULL,40,157,NULL,'2026-03-30 23:41:17'),
(1640,2053,0,'Når udlejeren har afholdt udgift til indvendig vedligeholdelse og til anden vedligeholdelse efter § 118, stk. 2, kan udlejeren fradrage udgiften på vedligeholdelseskontoen. Udlejeren skal samtidig give lejeren en skriftlig opgørelse over de afholdte udgifter og oplysning om, hvilket beløb der herefter er til rådighed. Lejeren kan kræve dokumentation for de afholdte vedligeholdelsesudgifter.',NULL,NULL,99,393,NULL,'2026-03-30 23:41:17'),
(1641,2054,0,'Inden 3 måneder efter hvert regnskabsårs afslutning skal udlejeren give lejeren skriftlig meddelelse om, hvilket beløb der ved regnskabsårets afslutning var til rådighed til lejlighedens vedligeholdelse. En negativ saldo skal ansættes til nul.',NULL,NULL,61,243,NULL,'2026-03-30 23:41:17'),
(1642,2055,0,'Undlader udlejeren at efterkomme en anmodning fra huslejenævnet om inden et fastsat tidspunkt at fremlægge regnskaber med bilag for de sidste 5 år, kan lejeren kræve lagt til grund, at der på kontoen mindst henstår et beløb svarende til periodens hensættelse uden fradrag for afholdte udgifter til vedligeholdelse.',NULL,NULL,79,314,NULL,'2026-03-30 23:41:17'),
(1643,2056,0,'Ved genudlejning skal vedligeholdelseskontoen videreføres, og udlejeren skal oplyse den nye lejer om, hvilket beløb der ved lejeforholdets begyndelse er til rådighed til vedligeholdelse.',NULL,NULL,47,186,NULL,'2026-03-30 23:41:17'),
(1644,2057,0,'Ved ejerskifte overtager den nye udlejer vedligeholdelsespligten og viderefører vedligeholdelseskontoen.',NULL,NULL,26,104,NULL,'2026-03-30 23:41:17'),
(1645,2058,0,'Lejeren kan kræve, at udlejeren foretager indvendig vedligeholdelse, når det er nødvendigt, og udgiften kan afholdes af det beløb, der er til rådighed på vedligeholdelseskontoen.',NULL,NULL,45,178,NULL,'2026-03-30 23:41:17'),
(1646,2059,0,'Lejeren kan endvidere kræve, at det beløb, hvormed saldoen på vedligeholdelseskontoen overstiger et beløb svarende til de seneste 3 års samlede hensættelser, anvendes til andre rimelige og hensigtsmæssige vedligeholdelsesarbejder i lejligheden. Det er dog en betingelse, at lejligheden fremtræder i velvedligeholdt stand, for så vidt angår indvendig vedligeholdelse.',NULL,NULL,92,366,NULL,'2026-03-30 23:41:17'),
(1647,2060,0,'Er lejeaftalen opsagt af en af parterne, kan lejeren ikke fremsætte krav efter stk. 1 og 2.',NULL,NULL,23,91,NULL,'2026-03-30 23:41:17'),
(1648,2062,0,'Udlejeren skal som et led i opfyldelsen af sin pligt til at vedligeholde ejendommen afsætte det beløb, der blev afsat eller skulle være afsat efter den tidligere gældende § 18 i lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 962 af 11. august 2010, pr. 31. december 2014. Beløbet efter 1. pkt. reguleres én gang årligt, jf. § 204, stk. 2.',NULL,NULL,92,367,NULL,'2026-03-30 23:41:17'),
(1649,2063,0,'Har ejendommen lejligheder og lokaler, der ikke er omfattet af reglerne om udvendige vedligeholdelseskonti i dette kapitel, skal der for sådanne lokaler afsættes samme beløb pr. kvadratmeter på vedligeholdelseskontoen, som afsættes af lejen for beboelseslejligheder. For private andelsboligforeninger skal der kun afsættes beløb på vedligeholdelseskontoen for lejligheder og lokaler, der er udlejet af andelsboligforeningen.',NULL,NULL,106,424,NULL,'2026-03-30 23:41:17'),
(1650,2064,0,'Udlejeren af en ejendom, der ikke er omfattet af § 120, skal udarbejde et særskilt årsregnskab for vedligeholdelsesudgifterne fordelt på de enkelte arbejder eller kategorier af arbejder. En positiv eller negativ saldo overføres til det følgende regnskabsår. Udlejeren skal indsende årsregnskabet til Grundejernes Investeringsfond.',NULL,NULL,83,330,NULL,'2026-03-30 23:41:17'),
(1651,2065,0,'I ejendomme taget i brug før 1970, som har mere end to beboelseslejligheder, skal udlejeren ud over de beløb, der er nævnt i § 119, årligt afsætte det beløb, der blev afsat eller skulle være afsat efter den tidligere gældende § 18 b i lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 962 af 11. august 2010, pr. 31. december 2014. Beløbet efter 1. pkt. reguleres én gang årligt, jf. § 204, stk. 2. Beløbet indsættes på en konto for ejendommen i Grundejernes Investeringsfond, jf. § 60 i lov om boligforhold.',NULL,NULL,134,534,NULL,'2026-03-30 23:41:17'),
(1652,2066,0,'Stk. 1 finder tilsvarende anvendelse, hvor afsættelse sker efter § 211.',NULL,NULL,18,71,NULL,'2026-03-30 23:41:17'),
(1653,2067,0,'Det indbetalte beløb kan ikke gøres til genstand for kreditorforfølgning og kan kun udbetales efter reglerne i § 122 og § 63 i lov om boligforhold.',NULL,NULL,37,147,NULL,'2026-03-30 23:41:17'),
(1654,2068,0,'Bestemmelsen i stk. 1 finder ikke anvendelse på ejendomme, som af vurderingsmyndighederne er vurderet som landbrugs- eller skovejendom, jf. ejendomsvurderingslovens § 3, stk. 1, nr. 2 og 3.',NULL,NULL,48,189,NULL,'2026-03-30 23:41:17'),
(1655,2070,0,'På kontoen efter §§ 119 og 120 kan fradrages beløb, der er anvendt til opfyldelsen af udlejerens pligt til udvendig vedligeholdelse, jf. § 111, stk. 3. Endvidere kan der med tilslutning fra beboerrepræsentanterne eller et flertal af lejerne fradrages beløb, der er anvendt til forbedring.',NULL,NULL,72,288,NULL,'2026-03-30 23:41:17'),
(1656,2071,0,'Dækkes en udgift ved optagelse af lån, er udlejeren berettiget til i stedet for at fradrage udgiften at fradrage de årlige prioritetsydelser på kontoen, efterhånden som disse betales.',NULL,NULL,46,183,NULL,'2026-03-30 23:41:17'),
(1657,2072,0,'Beløb indbetalt på en konto efter § 120 kan udbetales, når udlejeren dokumenterer, at et tilsvarende beløb er anvendt til ejendommens udvendige vedligeholdelse, til forbedring eller til ydelser på lån til de nævnte formål, jf. § 121, stk. 2, jf. dog stk. 4. Der bortses fra den del af udgiften, hvortil tilskud er ydet efter anden lovgivning.',NULL,NULL,86,342,NULL,'2026-03-30 23:41:17'),
(1658,2073,0,'Senest samtidig med at udlejeren kræver beløb udbetalt efter stk. 1, skal beboerrepræsentanterne eller lejerne have underretning om, hvilke udgifter der er afholdt, og hvilket beløb der kræves udbetalt.',NULL,NULL,51,202,NULL,'2026-03-30 23:41:17'),
(1659,2074,0,'Beløb indsat på en konto efter § 120 kan udbetales, medmindre beboerrepræsentanterne eller et flertal af lejerne protesterer mod udbetalingen inden 6 uger efter modtagelsen af underretningen efter stk. 2. Såfremt enighed ikke kan opnås mellem udlejeren og beboerrepræsentanterne eller et flertal af lejerne, skal udlejeren indbringe sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om udbetaling efter stk. 1.',NULL,NULL,108,430,NULL,'2026-03-30 23:41:17'),
(1660,2075,0,'Det er en betingelse for udbetaling efter stk. 1, at udlejeren dokumenterer, at indestående beløb på ejendommens konto efter § 119 er opbrugt.',NULL,NULL,36,142,NULL,'2026-03-30 23:41:17'),
(1661,2077,0,'Grundejernes Investeringsfond kan fritage ejeren af en ejendom for afsættelse efter § 120 for den del af ejendommen, der udelukkende anvendes til andet end beboelse.',NULL,NULL,42,165,NULL,'2026-03-30 23:41:17'),
(1662,2078,0,'Grundejernes Investeringsfonds afgørelse efter stk. 1 kan indbringes for huslejenævnet.',NULL,NULL,22,87,NULL,'2026-03-30 23:41:17'),
(1663,2079,0,'Indenrigs- og boligministeren kan fastsætte regler for, i hvilket omfang Grundejernes Investeringsfond kan fritage en ejer for afsættelse efter § 120.',NULL,NULL,38,150,NULL,'2026-03-30 23:41:17'),
(1664,2081,0,'Tvister om opfyldelse af udlejerens pligt til at føre en indvendig vedligeholdelseskonto og om beløb, der fradrages på kontiene for indvendig og udvendig vedligeholdelse, afgøres af huslejenævnet.',NULL,NULL,49,196,NULL,'2026-03-30 23:41:17'),
(1665,2082,0,'Huslejenævnet kan beslutte, at afsættelsesbeløbet efter § 120, stk. 1, skal nedsættes i en periode op til 5 år, såfremt beboerrepræsentanterne eller et flertal af lejerne forlanger det. Beløbet kan bl.a. nedsættes, hvis der på kontoen efter § 120, stk. 1, i forvejen henstår beløb svarende til de seneste 5 års hensættelser, eller hvis ejendommens vedligeholdelsesstand tilsiger, at der i perioden ikke er behov for et større beløb. Beløbet kan ikke nedsættes til et beløb, der er lavere end 15 kr. pr. m² bruttoetageareal.',NULL,NULL,131,523,NULL,'2026-03-30 23:41:17'),
(1666,2083,0,'Huslejenævnet indsender afgørelser, jf. stk. 2, til Grundejernes Investeringsfond, som lægger dem til grund ved beregningen af det bindingspligtige beløb efter § 120 for den enkelte ejendom.',NULL,NULL,48,190,NULL,'2026-03-30 23:41:17'),
(1667,2085,0,'§§ 116-118 kan ikke ved aftale fraviges til skade for lejeren. §§ 119-124 kan ikke fraviges.',NULL,NULL,23,92,NULL,'2026-03-30 23:41:17'),
(1668,2088,0,'Udlejeren har ret til at foretage ændringer, herunder forbedringer af ejendommen og i det lejede, når ændringerne ikke væsentligt og varigt ændrer det lejedes identitet.',NULL,NULL,43,169,NULL,'2026-03-30 23:41:17'),
(1669,2089,0,'Ved installation af varmeanlæg i ejendommen har udlejeren ret til med 6 ugers varsel at råde over de kælder- og loftsrum, der er nødvendige til anlæggets drift, når der anvises lejeren andre rum, der er anvendelige til det aftalte brug. Lejeren kan dog ikke kræve anvist andet rum, hvis den forudsatte anvendelse af rummet må anses for overflødiggjort af installationen.',NULL,NULL,93,370,NULL,'2026-03-30 23:41:17'),
(1670,2091,0,'Ved forbedringer forstås foranstaltninger eller installationer, der forøger det lejedes værdi, eller foranstaltninger, som er påbudt ved lov eller offentlige forskrifter, når disse ikke er omfattet af udlejerens vedligeholdelsespligt.',NULL,NULL,59,234,NULL,'2026-03-30 23:41:17'),
(1671,2092,0,'Inden udlejeren iværksætter forbedringer, skal udlejeren iagttage § 131 om inddragelse af beboerrepræsentationen.',NULL,NULL,29,113,NULL,'2026-03-30 23:41:17'),
(1672,2093,0,'Inden udlejeren iværksætter forbedringer i ejendomme omfattet af § 6, stk. 1, og § 7, stk. 3, 3. pkt., skal udlejeren iagttage §§ 105 og 106 om varsling af iværksættelse.',NULL,NULL,43,170,NULL,'2026-03-30 23:41:17'),
(1673,2094,0,'Har udlejeren forbedret det lejede, kan udlejeren forlange lejen forhøjet med et beløb, der modsvarer forøgelsen af det lejedes værdi.',NULL,NULL,34,134,NULL,'2026-03-30 23:41:17'),
(1674,2095,0,'Lejeforhøjelsen skal som udgangspunkt kunne give en passende forrentning af den udgift, der med rimelighed er afholdt til forbedringen, og dække afskrivning og sædvanlige udgifter til vedligeholdelse, administration, forsikring og lign.',NULL,NULL,59,236,NULL,'2026-03-30 23:41:17'),
(1675,2096,0,'For arbejder, der medfører energibesparelser for lejerne i ejendommen, kan udlejeren forlange en lejeforhøjelse på grundlag af de samlede udgifter, der med rimelighed er afholdt hertil, dog højst svarende til den besparelse, som arbejderne medfører for lejerne.',NULL,NULL,66,261,NULL,'2026-03-30 23:41:17'),
(1676,2097,0,'Har udlejeren gennemført arbejder efter reglen i § 146, kan udlejeren forlange en lejeforhøjelse, der giver en passende forrentning af den udgift, der med rimelighed er afholdt, og dækker afskrivning og sædvanlige udgifter til vedligeholdelse, administration, forsikring og lign.',NULL,NULL,70,279,NULL,'2026-03-30 23:41:17'),
(1677,2098,0,'Har udlejeren udført foranstaltninger efter den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, eller efter kapitel 5 i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003, kan udlejeren i stedet for lejeforhøjelse for forbedringerne efter § 128 kræve lejeforhøjelse beregnet og gennemført efter reglerne i den tidligere gældende lov om privat byfornyelse eller i kapitel 5 i den tidligere gældende lov om byfornyelse.',NULL,NULL,131,524,NULL,'2026-03-30 23:41:17'),
(1678,2099,0,'Har en ejendom centralvarme eller varmtvandsinstallation, og tilslutter udlejeren denne til et kollektivt varmeforsyningsanlæg, kan udlejeren forlange, at lejeren over 10 år godtgør udlejeren ejendommens udgifter ved omlægningen med fradrag af besparelsen.',NULL,NULL,64,256,NULL,'2026-03-30 23:41:17'),
(1679,2100,0,'Indenrigs- og boligministeren fastsætter nærmere regler til stk. 1 om krav til dokumentation, om betingelserne for at kræve lejeforhøjelse og om forhøjelsens beregning.',NULL,NULL,42,168,NULL,'2026-03-30 23:41:17'),
(1680,2102,0,'Lejeforhøjelse efter §§ 128 og 129 kan gennemføres med 3 måneders varsel. Lejeforhøjelsen kan dog tidligst få virkning fra det tidspunkt, hvor forbedringen er fuldført.',NULL,NULL,42,168,NULL,'2026-03-30 23:41:17'),
(1681,2103,0,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde oplysning om grunden til lejeforhøjelsen og en beregning af lejeforhøjelsen med oplysning om de afholdte udgifter samt oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 5. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',NULL,NULL,77,307,NULL,'2026-03-30 23:41:17'),
(1682,2104,0,'Udlejeren kan kræve en foreløbig lejeforhøjelse på grundlag af et overslag over udgifterne og forbeholde sig at fremsætte nyt krav, når byggeregnskabet er afsluttet. Lejen skal reguleres efter byggeregnskabet, når det foreligger.',NULL,NULL,58,229,NULL,'2026-03-30 23:41:17'),
(1683,2105,0,'Hvis byggeregnskabet ikke er aflagt inden 6 måneder fra det tidspunkt, hvor den foreløbige lejeforhøjelse trådte i kraft, kan huslejenævnet på begæring af en lejer fastsætte en frist, inden for hvilken byggeregnskabet skal aflægges. Er byggeregnskab ikke aflagt inden fristens udløb, bortfalder den foreløbige lejeforhøjelse, medmindre overskridelsen af fristen beror på forhold, som ikke kan lægges udlejeren til last.',NULL,NULL,105,419,NULL,'2026-03-30 23:41:17'),
(1684,2106,0,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren fremsætte skriftlig indsigelse, senest 6 uger efter at kravet er kommet frem til lejeren. I ejendomme med beboerrepræsentation kan beboerrepræsentanterne på samtlige lejeres vegne gøre indsigelse mod kravet om lejeforhøjelse, jf. 1. pkt. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',NULL,NULL,114,456,NULL,'2026-03-30 23:41:17'),
(1685,2107,0,'For ejendomme omfattet af § 6, stk. 1, finder §§ 38 og 40 også anvendelse for varslede forbedringsforhøjelser.',NULL,NULL,28,110,NULL,'2026-03-30 23:41:17'),
(1686,2108,0,'Er en sag indbragt for huslejenævnet, kan udlejeren, indtil nævnets afgørelse foreligger, oppebære den varslede lejeforhøjelse som en foreløbig lejeforhøjelse. Lejen skal reguleres i overensstemmelse med nævnets afgørelse. Huslejenævnet kan dog bestemme, at udlejeren kun kan oppebære et mindre beløb, indtil nævnet har truffet sin afgørelse.',NULL,NULL,86,342,NULL,'2026-03-30 23:41:17'),
(1687,2109,0,'Inden udlejeren i en ejendom med beboerrepræsentation varsler iværksættelse af arbejder, der vil medføre en lejeforhøjelse, som sammen med forbedringsforhøjelser gennemført i de sidste 3 år vil udgøre mere end 63 kr. pr. m² bruttoetageareal pr. år, skal udlejeren med rimeligt varsel skriftligt indkalde beboerrepræsentanterne til et møde med henblik på at orientere om og drøfte de påtænkte forbedringsarbejder, udbudsmateriale og overslag over forbedringsforhøjelsen. Mødet skal afholdes, inden iværksættelse varsles. Forud for mødet skal udlejeren fremsende skriftligt materiale vedrørende forbedringsarbejderne. Det i 1. pkt. nævnte beløb er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,179,715,NULL,'2026-03-30 23:41:17'),
(1688,2110,0,'Skal udlejeren ikke varsle iværksættelse af de arbejder, der vil medføre en lejeforhøjelse, men er de øvrige betingelser i stk. 1 opfyldt, skal møde efter stk. 1 afholdes senest 2 uger før forbedringsforhøjelsens varsling.',NULL,NULL,56,222,NULL,'2026-03-30 23:41:17'),
(1689,2111,0,'Hvis arbejderne udbydes i begrænset licitation uden forudgående prækvalifikation, skal udlejeren senest på det i stk. 1 nævnte møde opfordre beboerrepræsentanterne til at pege på mindst én bydende i licitationen. Udlejeren skal skriftligt og med rimeligt varsel indkalde beboerrepræsentanterne til deltagelse i licitationsforretningen.',NULL,NULL,84,335,NULL,'2026-03-30 23:41:17'),
(1690,2112,0,'Overholder udlejeren ikke forpligtelserne efter stk. 1-3, kan lejeforhøjelse ikke opkræves ud over beløbsgrænsen nævnt i stk. 1.',NULL,NULL,32,128,NULL,'2026-03-30 23:41:17'),
(1691,2114,0,'Inden der iværksættes forbedringer, herunder gennemgribende forbedringer efter § 19, stk. 2, og ombygningsarbejder vedrørende sammenlægning af lejligheder, kan huslejenævnet på udlejerens anmodning træffe afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves, hvis ombygningsarbejdet udføres i overensstemmelse med det projektmateriale vedrørende det påtænkte arbejde, som udlejeren skal forelægge huslejenævnet, jf. stk. 4.',NULL,NULL,110,438,NULL,'2026-03-30 23:41:17'),
(1692,2115,0,'Inden ejeren af en ejerbolig eller andelshaveren med brugsret til en bestemt beboelseslejlighed træffer beslutning om at udleje boligen, kan huslejenævnet tillige træffe afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves. Denne adgang gælder dog kun for ejere, der ikke ejer andre udlejede ejerboliger, og for andelshavere, der ikke har brugsret til andre udlejede andelsboliger.',NULL,NULL,99,396,NULL,'2026-03-30 23:41:17'),
(1693,2116,0,'Inden udlejeren iværksætter ombygningsarbejder efter bestemmelsen i § 2, stk. 1, nr. 1-4, i den tidligere gældende lov om privat byfornyelse, og hvis der er foretaget reservation af investeringsramme efter den tidligere gældende lov om privat byfornyelse, kan huslejenævnet på udlejerens anmodning træffe afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves. Huslejenævnet kan forlange dokumentation for, at der er reserveret investeringsramme efter den tidligere gældende lov om privat byfornyelse.',NULL,NULL,129,514,NULL,'2026-03-30 23:41:17'),
(1694,2117,0,'Samtidig med indbringelse for nævnet efter stk. 1 skal udlejeren fremsende projektmateriale indeholdende arbejdernes art, en angivelse af lejen eller lejeforhøjelsens forventede størrelse og de anslåede udgifter ved arbejdernes gennemførelse til huslejenævnet og de lejere, der berøres af forbedringsarbejdet.',NULL,NULL,78,309,NULL,'2026-03-30 23:41:17'),
(1695,2118,0,'Huslejenævnets afgørelse om forhåndsgodkendelse skal træffes, senest 2 måneder efter at huslejenævnet har modtaget bemærkninger efter § 83, stk. 3, i lov om boligforhold eller svar efter § 84, stk. 4, i lov om boligforhold, eller når fristen for svar efter bestemmelserne er udløbet.',NULL,NULL,71,283,NULL,'2026-03-30 23:41:17'),
(1696,2119,0,'Huslejenævnet kan kun ændre den ved forhåndsgodkendelsen fastsatte leje, hvis der er tale om ændrede forhold.',NULL,NULL,28,109,NULL,'2026-03-30 23:41:17'),
(1697,2120,0,'For de enkelte lejemål omfattet af § 2, stk. 1, nr. 1-4, i den tidligere gældende lov om privat byfornyelse, hvor huslejenævnet inden arbejdernes iværksættelse har truffet afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves, afgør nævnet på udlejerens anmodning, når ombygningen er udført, om ombygningsudgifterne står i rimeligt forhold til den opnåede kvalitet. Nævnet afgør ligeledes, om de udførte ombygningsarbejder er omfattet af den i medfør af § 2, stk. 3, i den tidligere gældende lov om privat byfornyelse fastsatte positivliste, og om den af udlejeren beregnede lejeforhøjelse er i overensstemmelse med bestemmelsen i § 5 a i den tidligere gældende lov om privat byfornyelse. Udlejerens anmodning til huslejenævnet skal vedlægges et ombygningsregnskab med oplysning om de afholdte og dokumenterede udgifter og lejestigninger fordelt på de enkelte lejemål attesteret af en registreret eller statsautoriseret revisor.',NULL,NULL,236,942,NULL,'2026-03-30 23:41:17'),
(1698,2122,0,'Huslejenævnet træffer afgørelse i tvister om lejeforhøjelse efter reglerne om forbedringer i §§ 128-131.',NULL,NULL,26,104,NULL,'2026-03-30 23:41:17'),
(1699,2124,0,'Med bøde eller fængsel indtil 4 måneder straffes den, som gennemfører forbedringer i en ejendom omfattet af § 6, stk. 1, i strid med reglerne i § 127, stk. 3, § 128, § 129, stk. 1-3, eller § 130 eller med kendskab til det lovstridige forhold finansierer sådanne forbedringer.',NULL,NULL,69,275,NULL,'2026-03-30 23:41:17'),
(1700,2125,0,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:17'),
(1701,2127,0,'Dette kapitel kan ikke fraviges til skade for lejeren, jf. dog stk. 2-4.',NULL,NULL,18,72,NULL,'2026-03-30 23:41:17'),
(1702,2128,0,'§ 126 og § 130, stk. 1, 1. pkt., kan fraviges ved aftale. § 129, stk. 4, kan ligeledes fraviges ved aftale, for så vidt angår perioden for godtgørelse.',NULL,NULL,38,151,NULL,'2026-03-30 23:41:17'),
(1703,2129,0,'§ 128 i ejendomme, som ikke er omfattet af § 6, stk. 1, kan fraviges ved aftale, for så vidt angår lejeforhøjelsens størrelse.',NULL,NULL,32,126,NULL,'2026-03-30 23:41:17'),
(1704,2130,0,'Kapitlets bestemmelser finder ikke anvendelse ved aftalte forbedringer i henhold til § 137. Varslingsreglerne i § 130 finder ikke anvendelse ved beboerrepræsentanternes tiltrædelse af forbedringer i henhold til § 138.',NULL,NULL,55,217,NULL,'2026-03-30 23:41:17'),
(1705,2133,0,'Udlejeren og lejeren af en beboelseslejlighed kan, efter at lejeaftale er indgået, indgå aftale om gennemførelse af forbedringsarbejder i lejligheden med en i aftalen nærmere fastsat lejeforhøjelse.',NULL,NULL,50,198,NULL,'2026-03-30 23:41:17'),
(1706,2134,0,'Lejeren kan forlange, at udlejeren, forinden aftale indgås, indhenter en forhåndsgodkendelse efter bestemmelserne i § 132, stk. 1. Lejeren kan endvidere anmode Udbetaling Danmark om en udtalelse vedrørende eventuelle boligstøttemæssige konsekvenser af en aftale om lejeforhøjelse efter stk. 1.',NULL,NULL,74,293,NULL,'2026-03-30 23:41:17'),
(1707,2135,0,'En aftale, jf. stk. 1, er kun gyldig, hvis følgende betingelser er opfyldt:',NULL,NULL,19,75,NULL,'2026-03-30 23:41:17'),
(1708,2136,0,'Aftalen skal være skriftlig.',NULL,NULL,7,28,NULL,'2026-03-30 23:41:17'),
(1709,2137,0,'Det skal udtrykkeligt fremgå af aftalen, at lejeforhøjelsen er aftalt efter nærværende bestemmelse.',NULL,NULL,25,99,NULL,'2026-03-30 23:41:17'),
(1710,2138,0,'Udlejeren skal, forinden aftale indgås, have orienteret lejeren om muligheden for at indhente forhåndsgodkendelse, jf. stk. 2, 1. pkt., og beregning vedrørende boligstøttemæssige konsekvenser, jf. stk. 2, 2. pkt.',NULL,NULL,53,212,NULL,'2026-03-30 23:41:17'),
(1711,2139,0,'Aftalen bortfalder, når det pågældende lejeforhold ophører.',NULL,NULL,15,59,NULL,'2026-03-30 23:41:17'),
(1712,2141,0,'Beboerrepræsentanterne kan på samtlige lejeres vegne tiltræde forbedringsarbejder, der sammen med forbedringsarbejder, som beboerrepræsentanterne inden for de sidste 3 år har tiltrådt efter denne bestemmelse, medfører lejeforhøjelser, som ikke overstiger 100 kr. pr. m² bruttoetageareal. Det i stk. 1 nævnte beløb er opgjort i 2021-niveau og reguleres én gang årligt, jf. reglerne i § 204, stk. 1.',NULL,NULL,100,397,NULL,'2026-03-30 23:41:17'),
(1713,2142,0,'Beboerrepræsentanterne skal, forinden de tiltræder forbedringsarbejderne, afholde beboermøde til drøftelse af de pågældende forbedringsarbejder, og der skal på beboermødet være flertal blandt de fremmødte beboere for forbedringsarbejdernes gennemførelse. Efter beboermødet skal beboerrepræsentanterne snarest skriftligt meddele samtlige beboere beslutningen og oplyse, at såfremt en fjerdedel af beboerne inden 2 uger efter meddelelsen forlanger det, skal beboerrepræsentanterne foranstalte urafstemning blandt ejendommens beboere, jf. bekendtgørelsen om beboerrepræsentation.',NULL,NULL,144,576,NULL,'2026-03-30 23:41:17'),
(1714,2144,0,'Huslejenævnet træffer afgørelse i tvister om, hvorvidt en aftale i henhold til § 138 om forbedringsarbejder er åbenbart urimelig.',NULL,NULL,33,129,NULL,'2026-03-30 23:41:17'),
(1715,2146,0,'Dette kapitel kan ikke fraviges til skade for lejeren.',NULL,NULL,14,54,NULL,'2026-03-30 23:41:17'),
(1716,2149,0,'Lejeren må ikke uden udlejerens samtykke foretage ændringer af det lejede eller anbringe andre indretninger eller genstande end de i §§ 142-145 nævnte.',NULL,NULL,38,151,NULL,'2026-03-30 23:41:17'),
(1717,2150,0,'Lejeren har ret til at foretage sædvanlige installationer i det lejede, medmindre udlejeren kan godtgøre, at ejendommens el- og afløbskapacitet ikke er tilstrækkelig til installationen. Lejeren skal give meddelelse til udlejeren, inden lejeren foretager installationen.',NULL,NULL,68,269,NULL,'2026-03-30 23:41:17'),
(1718,2151,0,'Lejeren af en beboelseslejlighed eller et værelse til helårsbeboelse har ret til at installere hjælpemidler m.v. i det lejede og efter udlejerens anvisning på ejendommens fællesarealer efter bestemmelserne i lov om social service, hvis kommunalbestyrelsen garanterer for betaling af retableringsudgifter ved lejerens fraflytning. Lejeren skal forudgående skriftligt anmelde de påtænkte installationer m.v. til udlejeren. Lejeren har ret til at lade installationerne udføre, hvis udlejeren ikke har gjort skriftlig begrundet indsigelse senest 6 uger efter lejerens anmeldelse af arbejderne. Udlejeren kan nægte lejeren at lade installationerne på fællesarealerne udføre, hvis de er til væsentlig ulempe for ejendommen eller de øvrige lejere.',NULL,NULL,185,740,NULL,'2026-03-30 23:41:17'),
(1719,2152,0,'Lejeren er erstatningsansvarlig for skade, der er forårsaget af de installationer, lejeren har foretaget. Udlejeren kan kræve, at lejeren ved forsikring eller på anden måde stiller fornøden sikkerhed for opfyldelsen af erstatningsansvaret.',NULL,NULL,60,239,NULL,'2026-03-30 23:41:17'),
(1720,2153,0,'Lejeren har efter udlejerens anvisning ret til at anbringe radio- og fjernsynsantenne på ejendommen til modtagelse af radio- og tv-programmer, jf. dog stk. 2. Lejeren har tilsvarende ret til at lade etablere kabelforbindelse til fremføring af radio- og tv-programmer eller adgang til elektroniske kommunikationstjenester i ejendommen, hvis der er mulighed for tilslutning til kabel-tv eller lignende fælles net i området. Ønsker flere lejere at etablere samme programforsyning eller forsyning med adgang til elektroniske kommunikationstjenester, kan disse beslutte, at opsætning af antenne eller forsyning med adgang til elektroniske kommunikationstjenester skal ske i form af et fællesanlæg.',NULL,NULL,173,692,NULL,'2026-03-30 23:41:17'),
(1721,2154,0,'Lejerens ret efter stk. 1 gælder ikke, hvis udlejeren godtgør, at anbringelsen vil være til ulempe for ejendommen eller dens lejere. Retten gælder endvidere ikke, hvis lejeren kan få adgang til et ønsket program enten gennem udlejerens fælles tv-forsyning eller gennem et af lejerne etableret fællesantenneanlæg.',NULL,NULL,78,312,NULL,'2026-03-30 23:41:17'),
(1722,2155,0,'Lejeren er erstatningsansvarlig for skade, der er forårsaget af antennen eller kabelforbindelsen. Udlejeren kan forlange, at lejeren indbetaler et rimeligt depositum til sikkerhed for krav mod lejeren, som opstår som følge af antennen, herunder udgifter til nedtagning af antennen og retablering ved lejerens fraflytning, jf. stk. 7.',NULL,NULL,84,333,NULL,'2026-03-30 23:41:17'),
(1723,2156,0,'Ønsker flere lejere at etablere en fællesantenne i ejendommen efter stk. 1, 3. pkt., kan udlejeren forlange, at de pågældende lejere stifter en antenneforening, som skal stå for etablering og drift af fællesantenneanlægget. Der skal vælges en bestyrelse for antenneforeningen. Det påhviler bestyrelsen at meddele udlejeren, hvem der sidder i bestyrelsen, således at udlejeren med frigørende virkning kan henvende sig til disse angående spørgsmål vedrørende antenneanlægget. Bestyrelsen skal samtidig sende et eksemplar af foreningens vedtægter til udlejeren. Antenneforeningen er erstatningsansvarlig for skade, der er forårsaget af fællesantenneanlægget. Vedtægterne skal indeholde bestemmelser om, at foreningen skal tegne en ansvarsforsikring og en kaskoforsikring vedrørende antenneanlægget, og at foreningen i tilfælde af ophør skal bære udgifterne til nedtagning af antenneanlægget og retablering. Udlejeren kan forlange, at foreningen indbetaler et rimeligt depositum til sikkerhed for udlejerens krav mod foreningen, herunder udgifter til nedtagning af antenneanlægget og retablering.',NULL,NULL,273,1092,NULL,'2026-03-30 23:41:17'),
(1724,2157,0,'Ved væsentlig tilsidesættelse af de pligter, som er angivet i stk. 4, kan udlejeren kræve fællesantenneanlægget nedtaget og retablering.',NULL,NULL,34,136,NULL,'2026-03-30 23:41:17'),
(1725,2158,0,'Stk. 4 og 5 gælder tilsvarende for lejernes etablering af fælles forsyning med adgang til elektroniske kommunikationstjenester.',NULL,NULL,32,127,NULL,'2026-03-30 23:41:17'),
(1726,2159,0,'Har lejeren opsat egen antenne efter stk. 1 eller været tilsluttet fællesantenneanlæg efter stk. 4, kan udlejeren kræve lejerens antenne nedtaget og retablering, når lejeren fraflytter lejemålet.',NULL,NULL,49,195,NULL,'2026-03-30 23:41:17'),
(1727,2160,0,'Lejeren har ret til at foretage skiltning på mure, døre og vinduer, der hører til det lejede, i det omfang det er sædvanligt efter arten af lejerens forretning og ejendommen. Lejeren har endvidere ret til at anbringe markiser, udhængsskabe, automater, varer og lign. i sædvanligt omfang.',NULL,NULL,72,287,NULL,'2026-03-30 23:41:17'),
(1728,2161,0,'Lejeren af en butik eller en beværtning skal holde forretningen åben og i forsvarlig drift i sædvanligt omfang. Det kan ikke uanset modstående aftale pålægges lejere af forretninger i butiksfællesskaber at holde åbent mandag til fredag efter kl. 20.00 og fra lørdag kl. 17.00 til mandag kl. 6.00.',NULL,NULL,74,296,NULL,'2026-03-30 23:41:17'),
(1729,2163,0,'Lejeren af en beboelseslejlighed har ret til at udføre nærmere fastsatte forbedringsarbejder m.v. i lejligheden og ved fraflytning få godtgørelse for de afholdte udgifter efter reglerne i stk. 4-8. Bestemmelsen i 1. pkt. gælder ikke for lejere i fremlejeforhold efter § 158 og lejere i tidsbegrænsede lejeforhold efter § 173.',NULL,NULL,82,325,NULL,'2026-03-30 23:41:17'),
(1730,2164,0,'Lejeren skal forudgående anmelde de påtænkte forbedringsarbejder m.v. til udlejeren. Nødvendig byggesagsbehandling forestås og betales af lejeren. § 142, stk. 3, finder tilsvarende anvendelse.',NULL,NULL,48,192,NULL,'2026-03-30 23:41:17'),
(1731,2165,0,'Forbedringer m.v. efter stk. 1 skal være rimelige og hensigtsmæssige. Udlejeren kan nægte lejeren at forbedre det lejede, når særlig vægtige grunde taler herfor, herunder når der er tale om uhensigtsmæssige arbejder, f.eks. særlig luksusprægede eller særlig energiforbrugende arbejder. Lejeren kan lade arbejderne udføre, såfremt udlejeren ikke har gjort indsigelse senest 6 uger efter lejerens anmeldelse af arbejderne efter stk. 2. Indsigelsen skal være skriftlig og angive, hvilke arbejder der gøres indsigelse mod, og begrundelsen herfor.',NULL,NULL,136,542,NULL,'2026-03-30 23:41:17'),
(1732,2166,0,'Godtgørelsen beregnes på grundlag af afholdte udgifter, som skal dokumenteres efter arbejdernes afslutning og påtegnes lejekontrakten. Udlejeren kan reducere beregningsgrundlaget for godtgørelse med værdien af eksisterende installationer og bygningsdele m.v., som er omfattet af forbedringsarbejderne. Udlejeren kan endvidere reducere beregningsgrundlaget for godtgørelse, hvis udgifterne skønnes at være uforholdsmæssigt høje.',NULL,NULL,107,427,NULL,'2026-03-30 23:41:17'),
(1733,2167,0,'Godtgørelsen udgør den del af de afholdte udgifter beregnet efter stk. 4, som efter fradrag af eventuel støtte efter anden lovgivning overstiger 16.015 kr. Godtgørelsen kan højst udgøre 126.684 kr. Godtgørelse på mindre end 3.204 kr. udbetales ikke. Som afholdte udgifter kan alene medregnes dokumenterede udgifter til virksomheder, der er registreret efter momsloven, og som driver bygge- og anlægsvirksomhed. De i 1.-3. pkt. nævnte beløb er opgjort i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',NULL,NULL,128,512,NULL,'2026-03-30 23:41:17'),
(1734,2168,0,'Der kan ydes godtgørelse for flere forbedringer m.v. i samme lejlighed, selv om arbejderne ikke udføres samtidig. Under hensyntagen til nedskrivningen efter stk. 7 kan den samlede godtgørelse til en lejer dog aldrig overstige beløbsgrænsen i stk. 5.',NULL,NULL,63,249,NULL,'2026-03-30 23:41:17'),
(1735,2169,0,'Den oprindelig beregnede godtgørelse nedskrives med 10 pct. for hvert år, forbedringen m.v. har været i brug, første gang dog først 2 år efter at forbedringen er taget i brug, medmindre anden nedskrivning aftales imellem lejeren og udlejeren under hensyn til arbejdernes karakter. Ibrugtagningsdatoen for forbedringen m.v. skal sammen med en eventuel særlig aftale om nedskrivning af godtgørelsen påtegnes lejekontrakten.',NULL,NULL,106,421,NULL,'2026-03-30 23:41:17'),
(1736,2170,0,'Godtgørelsen udbetales af udlejeren ved lejerens fraflytning, hvis udførelsen af arbejderne er tilendebragt, jf. § 188, stk. 3. Udlejeren kan foretage modregning i godtgørelsen for lejerens forpligtelser over for udlejeren.',NULL,NULL,56,223,NULL,'2026-03-30 23:41:17'),
(1737,2171,0,'I nedskrivningsperioden, jf. stk. 7, kan en ny lejer ved genudlejning enten vælge at betale den nedskrevne godtgørelse til udlejeren eller vælge at betale en lejeforhøjelse, der modsvarer forøgelsen af det lejedes værdi, jf. § 128. Ved genudlejningen efter nedskrivningsperiodens udløb, jf. stk. 7, kan udlejeren kræve en lejeforhøjelse, der modsvarer forøgelsen af det lejedes værdi, jf. § 128.',NULL,NULL,99,395,NULL,'2026-03-30 23:41:17'),
(1738,2172,0,'Flytter en lejer, der har betalt den nedskrevne godtgørelse til udlejeren efter stk. 9, i nedskrivningsperioden, har lejeren ret til godtgørelse svarende til den nedskrevne godtgørelse beregnet efter stk. 7 modregnet eventuelle forpligtelser over for udlejeren, jf. stk. 8.',NULL,NULL,69,273,NULL,'2026-03-30 23:41:17'),
(1739,2173,0,'Indenrigs- og boligministeren fastsætter nærmere regler om afgrænsningen af forbedringsarbejder m.v. efter § 145.',NULL,NULL,29,113,NULL,'2026-03-30 23:41:17'),
(1740,2175,0,'Leverer udlejeren varme og opvarmning af brugsvand, og overstiger udgifterne hertil ifølge det senest udsendte varmeregnskab for 1 år halvdelen af lejen for den pågældende periode, kan beboerrepræsentanterne eller et flertal af lejerne forlange, at der udføres alle eller en del af de arbejder vedrørende varme og opvarmning af brugsvand, der er angivet i en energiplan, jf. lov om fremme af energibesparelser i bygninger. Foreligger der ikke energimærkning med tilhørende energiplan, jf. lov om fremme af energibesparelser i bygninger, kan lejerne, såfremt forholdet er omfattet af 1. pkt., kræve, at udlejeren gennemfører en sådan energimærkning. Det er en betingelse, at beboerrepræsentanterne eller et flertal af lejerne samtidig giver tilslutning til en lejeforhøjelse til dækning af samtlige udgifter, der følger af arbejdernes gennemførelse, jf. § 129, stk. 2.',NULL,NULL,217,867,NULL,'2026-03-30 23:41:17'),
(1741,2177,0,'Tvister om lejerens rettigheder og forpligtelser efter dette kapitel afgøres af huslejenævnet.',NULL,NULL,24,94,NULL,'2026-03-30 23:41:17'),
(1742,2178,0,'På begæring af beboerrepræsentanterne eller et flertal af lejerne afgør huslejenævnet, om betingelserne er opfyldt for at kræve udførelse af arbejder omfattet af lovens § 146.',NULL,NULL,44,175,NULL,'2026-03-30 23:41:17'),
(1743,2179,0,'Nævnet kan pålægge udlejeren at udføre de i stk. 2 nævnte arbejder og fastsætte en tidsfrist for det enkelte arbejdes udførelse.',NULL,NULL,32,128,NULL,'2026-03-30 23:41:17'),
(1744,2181,0,'§§ 142 og 143, § 144 stk. 2, 2. pkt., og §§ 145 og 146 kan ikke fraviges til skade for lejeren.',NULL,NULL,24,95,NULL,'2026-03-30 23:41:17'),
(1745,2184,0,'Lejeren skal behandle det lejede forsvarligt.',NULL,NULL,12,45,NULL,'2026-03-30 23:41:17'),
(1746,2185,0,'Lejeren er erstatningsansvarlig for skade, som forvoldes ved uforsvarlig adfærd af lejeren selv, lejerens husstand eller andre, som lejeren har givet adgang til det lejede.',NULL,NULL,43,172,NULL,'2026-03-30 23:41:17'),
(1747,2186,0,'Skader, hvis udbedring er uopsættelig, skal lejeren straks anmelde til udlejeren. Andre skader skal lejeren anmelde uden ugrundet ophold.',NULL,NULL,35,137,NULL,'2026-03-30 23:41:17'),
(1748,2187,0,'Lejeren må ikke uden udlejerens samtykke bruge det lejede til andet formål end aftalt.',NULL,NULL,22,86,NULL,'2026-03-30 23:41:17'),
(1749,2188,0,'Lejeren må ikke uden udlejerens samtykke overlade brugen af det lejede eller nogen del deraf til andre end medlemmer af sin husstand, jf. dog §§ 157 og 158.',NULL,NULL,39,156,NULL,'2026-03-30 23:41:17'),
(1750,2190,0,'Dette kapitel kan ikke fraviges til skade for lejeren.',NULL,NULL,14,54,NULL,'2026-03-30 23:41:17'),
(1751,2193,0,'Udlejeren skal sørge for, at der hersker god orden i ejendommen og om fornødent ophæve lejeforhold i de i § 182, stk. 1, nr. 7-10 og 13, nævnte tilfælde. Bestemmelserne i § 95, stk. 2, og §§ 96 og 97 finder tilsvarende anvendelse på udlejerens overtrædelse af denne pligt.',NULL,NULL,68,272,NULL,'2026-03-30 23:41:17'),
(1752,2194,0,'Lejeren skal overholde de almindelige ordensregler, der gælder for ejendommen, og skal efterkomme andre rimelige påbud, der skal sikre god husorden og forsvarlig brug af det lejede, jf. § 153.',NULL,NULL,48,192,NULL,'2026-03-30 23:41:17'),
(1753,2195,0,'Lejeren skal sørge for, at de pligter, der påhviler lejeren efter stk. 2, også iagttages af de personer, for hvis handlinger lejeren er ansvarlig efter § 149, stk. 2.',NULL,NULL,42,166,NULL,'2026-03-30 23:41:17'),
(1754,2196,0,'En lejer kan pålægges retsfølger efter § 154, når lejeren i følgende tilfælde udøver adfærd, som er til gene for ejendommen, udlejeren, dennes ansatte eller lejere i ejendommen eller andre, der lovligt færdes i ejendommen:',NULL,NULL,56,222,NULL,'2026-03-30 23:41:17'),
(1755,2197,0,'Når lejeren udøver eller truer med fysisk vold mod de pågældende personer.',NULL,NULL,19,74,NULL,'2026-03-30 23:41:17'),
(1756,2198,0,'Når lejerens adfærd kan være til fare for ejendommen eller de pågældende personer, herunder på grund af anvendelse af våben eller opbevaring af farefremkaldende materialer i det lejede.',NULL,NULL,47,185,NULL,'2026-03-30 23:41:17'),
(1757,2199,0,'Når lejerens adfærd medfører gener for de pågældende personer som generel utryghed, forråelse af ejendommens miljø eller sundhedsmæssig risiko.',NULL,NULL,36,143,NULL,'2026-03-30 23:41:17'),
(1758,2200,0,'Når lejeren, uden at der er tale om fysisk vold, udøver chikane over for de pågældende personer.',NULL,NULL,24,96,NULL,'2026-03-30 23:41:17'),
(1759,2201,0,'Når lejeren udøver uacceptabel støj til væsentlig gene for de pågældende personer i form af uacceptabelt støjende menneskelig adfærd, stærk musikstøj eller stærk maskinstøj.',NULL,NULL,44,173,NULL,'2026-03-30 23:41:17'),
(1760,2202,0,'Når lejeren ødelægger ejendommen eller løsøre på ejendommen eller på fællesarealer.',NULL,NULL,21,83,NULL,'2026-03-30 23:41:17'),
(1761,2203,0,'Når lejeren vanrøgter det lejede.',NULL,NULL,9,33,NULL,'2026-03-30 23:41:17'),
(1762,2204,0,'Når lejerens husdyr er til væsentlig gene for de pågældende personer på grund af støj, lugt, uhumskhed eller fare- eller frygtfremkaldelse.',NULL,NULL,35,139,NULL,'2026-03-30 23:41:17'),
(1763,2205,0,'Når lejeren, uden at der er tale om de i nr. 5 nævnte tilfælde, udøver støjende adfærd til gene for de pågældende personer.',NULL,NULL,31,123,NULL,'2026-03-30 23:41:17'),
(1764,2206,0,'Når lejerens husdyrhold, uden at der er tale om de i nr. 8 nævnte tilfælde, er til gene for de pågældende personer.',NULL,NULL,29,115,NULL,'2026-03-30 23:41:17'),
(1765,2207,0,'Når lejeren i øvrigt udøver adfærd, som er til gene for ejendommen eller de pågældende personer.',NULL,NULL,24,96,NULL,'2026-03-30 23:41:17'),
(1766,2208,0,'En lejer kan desuden pålægges retsfølger efter § 154, når lejeren holder husdyr i strid med lejeaftale eller husorden, uanset om husdyrholdet er til gene for ejendommen eller de i stk. 1 nævnte personer.',NULL,NULL,51,203,NULL,'2026-03-30 23:41:17'),
(1767,2209,0,'Lejeren kan pålægges retsfølger, uanset om den i stk. 1 og 2 beskrevne adfærd udøves af lejeren selv, lejerens husstand eller andre, som lejeren har givet adgang til det lejede.',NULL,NULL,45,177,NULL,'2026-03-30 23:41:17'),
(1768,2211,0,'Har lejeren tilsidesat god skik og orden, jf. § 153, kan lejeren af huslejenævnet pålægges en af følgende retsfølger:',NULL,NULL,30,117,NULL,'2026-03-30 23:41:17'),
(1769,2212,0,'Lejeforholdet kan gøres betinget, således at der, hvis lejeren inden for 1 år efter afgørelsen overtræder nærmere fastsatte betingelser vedrørende adfærd i ejendommen, er grundlag for, at lejemålet kan opsiges eller ophæves efter reglerne i kapitel 20 og 21.',NULL,NULL,65,258,NULL,'2026-03-30 23:41:17'),
(1770,2213,0,'Lejeren kan meddeles en advarsel om, at fornyet overtrædelse af god skik og orden, jf. § 153, kan føre til, at lejeforholdet gøres betinget efter nr. 1, eller til, at lejemålet opsiges eller ophæves efter reglerne i kapitel 20 og 21.',NULL,NULL,59,233,NULL,'2026-03-30 23:41:17'),
(1771,2214,0,'Det er en betingelse for, at en lejer kan pålægges retsfølger for tilsidesættelse af god skik og orden efter stk. 1, at tilsidesættelsen sker trods udlejerens påmindelse.',NULL,NULL,43,170,NULL,'2026-03-30 23:41:17'),
(1772,2216,0,'Sag om pålæg af retsfølger efter § 154 indbringes for huslejenævnet af udlejeren. Er der fremsat krav om, at lejeren pålægges en advarsel, kan nævnet ikke pålægge lejeren en strengere retsfølge.',NULL,NULL,49,194,NULL,'2026-03-30 23:41:17'),
(1773,2218,0,'Dette kapitel kan ikke fraviges.',NULL,NULL,8,32,NULL,'2026-03-30 23:41:17'),
(1774,2221,0,'Lejeren af en beboelseslejlighed har ret til at fremleje op til halvdelen af lejlighedens beboelsesrum til beboelse. Det samlede antal personer, der bor i lejligheden, må ikke overstige antallet af beboelsesrum.',NULL,NULL,53,211,NULL,'2026-03-30 23:41:17'),
(1775,2222,0,'Udlejeren skal modsætte sig fremlejeforholdet, hvis lejligheden er omfattet af reglerne om beboermaksimum og vil blive beboet af flere end to personer pr. beboelsesrum, jf. § 14, stk. 1, i lov om boligforhold.',NULL,NULL,53,209,NULL,'2026-03-30 23:41:17'),
(1776,2223,0,'Fremlejeaftaler skal indgås skriftligt, og lejeren skal inden fremlejeperiodens begyndelse tilstille udlejeren kopi af fremlejeaftalen.',NULL,NULL,34,135,NULL,'2026-03-30 23:41:17'),
(1777,2224,0,'En lejlighed, der udelukkende er udlejet til beboelse, har lejeren ret til at fremleje i indtil 2 år, når lejerens fravær er midlertidigt og skyldes sygdom, forretningsrejse, studieophold, midlertidig forflyttelse el.lign.',NULL,NULL,56,222,NULL,'2026-03-30 23:41:17'),
(1778,2225,0,'Udlejeren kan modsætte sig fremlejeforholdet, når en af følgende betingelser er opfyldt:',NULL,NULL,22,88,NULL,'2026-03-30 23:41:17'),
(1779,2226,0,'Ejendommen omfatter færre end 13 beboelseslejligheder.',NULL,NULL,14,54,NULL,'2026-03-30 23:41:17'),
(1780,2227,0,'Det samlede antal personer i lejligheden vil overstige antallet af beboelsesrum.',NULL,NULL,20,80,NULL,'2026-03-30 23:41:17'),
(1781,2228,0,'Udlejeren har i øvrigt rimelig grund til at modsætte sig fremlejeforholdet.',NULL,NULL,19,75,NULL,'2026-03-30 23:41:17'),
(1782,2229,0,'§ 157, stk. 2 og 3, finder tilsvarende anvendelse.',NULL,NULL,13,50,NULL,'2026-03-30 23:41:17'),
(1783,2230,0,'Hvis det skønnes rimeligt af hensyn til efterspørgslen, kan udlejer ved fremleje af ældreboliger eller ustøttede private plejeboliger stille krav om, at den pågældende bolig skal bebos af personer, som opfylder betingelserne for at komme i betragtning til en bolig af den pågældende karakter.',NULL,NULL,73,292,NULL,'2026-03-30 23:41:17'),
(1784,2231,0,'Lejeren er erstatningsansvarlig for skade, som ved uforsvarlig adfærd forvoldes af personer, der i kraft af reglerne i § 157 og § 158 benytter det lejede.',NULL,NULL,39,154,NULL,'2026-03-30 23:41:17'),
(1785,2232,0,'Lejeren er over for udlejeren ansvarlig for, at de i stk. 1 nævnte personer overholder de regler, der skal sikre en god husorden og forsvarlig brug af det lejede.',NULL,NULL,41,162,NULL,'2026-03-30 23:41:17'),
(1786,2233,0,'Lejeren er endvidere erstatningsansvarlig efter § 142, stk. 3, for skade forårsaget af installationer, som de i stk. 1 nævnte personer har foretaget i det lejede.',NULL,NULL,41,162,NULL,'2026-03-30 23:41:17'),
(1787,2234,0,'Lejeren må ikke uden ægtefællens samtykke foretage fremleje, såfremt dette vil medføre, at det lejede ikke længere kan tjene til fælles bolig eller som grundlag for ægtefællernes eller den anden ægtefælles virksomhed. Er den anden ægtefælle umyndig, meddeler værgen samtykket.',NULL,NULL,69,276,NULL,'2026-03-30 23:41:17'),
(1788,2235,0,'Nægter den anden ægtefælle at give samtykke efter stk. 1, eller kan samtykke ikke indhentes inden for rimelig tid, kan fremleje efter anmodning fra den ægtefælle, der lejer boligen, eller fra den anden part i aftalen tillades, hvis der ikke er rimelig grund til at nægte at gennemføre aftalen. Tilladelse efter 1. pkt. gives af Familieretshuset.',NULL,NULL,87,345,NULL,'2026-03-30 23:41:17'),
(1789,2236,0,'Har en ægtefælle indgået en aftale, der er omfattet af stk. 1, uden samtykke fra den anden ægtefælle og uden tilladelse efter stk. 2, kan aftalen efter anmodning fra den anden ægtefælle omstødes ved dom. Dette gælder dog ikke, hvis den anden part i fremlejeaftalen godtgør, at parten ikke vidste eller burde have vidst, at ægtefællen ikke var berettiget til at indgå fremlejeaftalen.',NULL,NULL,96,383,NULL,'2026-03-30 23:41:17'),
(1790,2237,0,'Retssag om omstødelse efter stk. 3 skal anlægges, inden 3 måneder efter at den anden ægtefælle fik kendskab til aftalen, dog senest 1 år efter at aftalen blev gennemført.',NULL,NULL,43,170,NULL,'2026-03-30 23:41:17'),
(1791,2239,0,'Lejeren af en lejlighed, der udelukkende er udlejet til beboelse, har ret til at bytte med en lejer af en anden beboelseslejlighed, således at denne overtager lejligheden.',NULL,NULL,43,171,NULL,'2026-03-30 23:41:17'),
(1792,2240,0,'Udlejeren kan modsætte sig bytte, hvis en af følgende betingelser er opfyldt:',NULL,NULL,20,77,NULL,'2026-03-30 23:41:17'),
(1793,2241,0,'Udlejer har sin bopæl i ejendommen, og denne omfatter færre end syv lejligheder.',NULL,NULL,20,80,NULL,'2026-03-30 23:41:17'),
(1794,2242,0,'Den fraflyttede lejer har ikke beboet lejligheden i 3 år.',NULL,NULL,15,57,NULL,'2026-03-30 23:41:17'),
(1795,2243,0,'Lejligheden vil ved bytning blive beboet af flere end én person pr. beboelsesrum.',NULL,NULL,21,81,NULL,'2026-03-30 23:41:17'),
(1796,2244,0,'Udlejeren har i øvrigt rimelig grund til at modsætte sig det pågældende bytte.',NULL,NULL,20,78,NULL,'2026-03-30 23:41:17'),
(1797,2245,0,'Såfremt der er tale om et lejemål, som udlejeren agter at forbedre i forbindelse med byttet og herefter fastsætte lejen efter § 19, stk. 2, skal udlejeren straks meddele lejeren dette og senest 1 måned efter lejerens meddelelse om bytte anmode huslejenævnet om en forhåndsgodkendelse, jf. § 132, stk. 1. Udlejeren skal fremsende kopi af anmodningen om forhåndsgodkendelse og oplysning om størrelsen af den forventede husleje efter forbedringen til lejeren. Når huslejenævnets forhåndsgodkendelse foreligger, skal udlejeren straks give lejeren kopi heraf. Undlader udlejeren at give de i 1. og 3. pkt. nævnte oplysninger, kan lejen ikke fastsættes efter § 19, stk. 2, hvis genudlejning sker som led i det pågældende bytte. Ved forhåndsgodkendelsen ses bort fra § 21, stk. 1.',NULL,NULL,194,773,NULL,'2026-03-30 23:41:17'),
(1798,2246,0,'Lejeren skal, senest 14 dage efter at kopi af huslejenævnets forhåndsgodkendelse efter stk. 3 er kommet frem til lejeren, meddele udlejeren, at byttet ønskes gennemført. Sker det ikke, fortsætter lejeforholdet på uændrede vilkår. En indhentet forhåndsgodkendelse efter stk. 3 har gyldighed i indtil 2 år efter godkendelsens datering.',NULL,NULL,84,333,NULL,'2026-03-30 23:41:17'),
(1799,2247,0,'Udlejeren skal modsætte sig bytte, hvis lejligheden er omfattet af reglerne om beboermaksimum og efter bytning vil blive beboet af flere end to personer pr. beboelsesrum, jf. § 14, stk. 1, i lov om boligforhold.',NULL,NULL,53,211,NULL,'2026-03-30 23:41:17'),
(1800,2248,0,'Hvis det skønnes rimeligt af hensyn til efterspørgslen, kan udlejer ved bytte af ældreboliger eller ustøttede private plejeboliger stille krav om, at den pågældende bolig skal bebos af personer, som opfylder betingelserne for at komme i betragtning til en bolig af den pågældende karakter.',NULL,NULL,73,289,NULL,'2026-03-30 23:41:17'),
(1801,2249,0,'Den lejer, der ved bytning ønsker at overtage en lejlighed, der tilhører en kommune, en almen boligorganisation, et kollegieselskab eller en stiftelse, skal opfylde de særlige vilkår, der gælder for overtagelse af sådanne lejligheder. Med stiftelse ligestilles en pensionskasse el.lign., der kun genudlejer lejlighederne til sine medlemmer ved overgang til pension.',NULL,NULL,92,365,NULL,'2026-03-30 23:41:17'),
(1802,2250,0,'Det kan betinges, at den, der ved bytning opnår en lejlighed i en andelsboligforening, skal indtræde som medlem af foreningen.',NULL,NULL,32,126,NULL,'2026-03-30 23:41:17'),
(1803,2251,0,'Bytteretten gælder uanset vedtægtsmæssige begrænsninger i beboernes bytteadgang.',NULL,NULL,20,80,NULL,'2026-03-30 23:41:17'),
(1804,2253,0,'Dør lejeren, har ægtefællen ret til at fortsætte lejeforholdet.',NULL,NULL,16,63,NULL,'2026-03-30 23:41:17'),
(1805,2254,0,'Dør lejeren af en beboelseslejlighed uden at efterlade sig en ægtefælle, har en anden person, der i en periode på mindst 2 år umiddelbart forud for dødsfaldet har haft fælles husstand med lejeren, ret til at fortsætte lejeforholdet.',NULL,NULL,58,232,NULL,'2026-03-30 23:41:17'),
(1806,2255,0,'Dør en lejer af en lejlighed, der delvis er udlejet til andet end beboelse, og har lejeren drevet en erhvervsvirksomhed, hvis stedlige forbliven i ejendommen er af væsentlig betydning og værdi for virksomheden, uden at efterlade sig en ægtefælle, har enhver af lejerens livsarvinger eller svigerbørn ret til at overtage lejeforholdet, medmindre udlejeren har vægtige grunde til at modsætte sig det. Det er dog en betingelse, at den pågældende har fornødent kendskab til den branche, hvori forretningen hidtil har været drevet, og ønsker selv eller sammen med sin ægtefælle at føre forretningen videre. Indtræder den pågældende ikke som lejer, kan udlejeren ikke udleje til anden side på lempeligere vilkår, end udlejeren har foreslået den pågældende.',NULL,NULL,188,750,NULL,'2026-03-30 23:41:17'),
(1807,2256,0,'I øvrigt kan i tilfælde af lejerens død såvel udlejeren som dødsboet opsige lejeforholdet med sædvanligt varsel, selv om lejeforholdet måtte være indgået for en bestemt længere tid eller med længere opsigelsesfrist.',NULL,NULL,54,215,NULL,'2026-03-30 23:41:17'),
(1808,2257,0,'Er det lejede en plejebolig, jf. § 1, stk. 1, 2. pkt., i den tidligere lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996, eller § 5, stk. 2, i lov om almene boliger m.v., eller en ustøttet privat plejebolig, jf. § 1, stk. 5, og dør lejeren uden at efterlade sig ægtefælle eller andre, som lejeren har haft fælles husstand med som anført i stk. 2, kan opsigelsen uanset stk. 4 ske med 1 måneds varsel. Indbo m.v. efter den afdøde beboer kan opmagasineres under iagttagelse af § 8 i lov om skifte af dødsboer.',NULL,NULL,139,556,NULL,'2026-03-30 23:41:17'),
(1809,2258,0,'Hvis lejeren af en beboelseslejlighed på grund af alder eller sygdom flytter på plejehjem, i beskyttet bolig el.lign. eller i plejebolig efter § 1, stk. 1, 2. pkt., i den tidligere lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996, eller § 5, stk. 2, i lov om almene boliger m.v., i en ustøttet privat plejebolig, jf. § 1, stk. 5, eller i en friplejebolig, finder § 163, stk. 1 og 2, tilsvarende anvendelse.',NULL,NULL,114,456,NULL,'2026-03-30 23:41:17'),
(1810,2259,0,'I tilfælde af lejerens separation eller skilsmisse eller ved omstødelse af lejerens ægteskab afgøres det om nødvendigt ved separationen, skilsmissen eller omstødelsen, hvilken af ægtefællerne der har ret til at fortsætte lejeforholdet. Den ægtefælle, hvis erhvervsvirksomhed er knyttet til et forretningslokale, har fortrinsret til dette og den dertil hørende beboelse.',NULL,NULL,93,369,NULL,'2026-03-30 23:41:17'),
(1811,2260,0,'Såfremt parter, der i mindst 2 år har haft fælles husstand, ophæver samlivet, kan de aftale, hvem af parterne der skal have ret til at fortsætte lejeforholdet til en lejlighed, der har tjent som fælles bolig. Kan parterne ikke blive enige om en aftale, jf. 1. pkt., kan der, når særlige grunde, herunder navnlig hensynet til parternes mindreårige børn, taler derfor, ved dom træffes bestemmelse om, hvem af parterne der skal have ret til at fortsætte lejeforholdet. § 165, 2. pkt., finder tilsvarende anvendelse.',NULL,NULL,128,512,NULL,'2026-03-30 23:41:17'),
(1812,2261,0,'Har lejeren forladt sin ægtefælle, har denne ret til at fortsætte lejeforholdet efter reglen i § 163, stk. 1.',NULL,NULL,28,109,NULL,'2026-03-30 23:41:17'),
(1813,2263,0,'Lejeren kan ikke give afkald på de rettigheder, der tilkommer lejeren eller andre efter §§ 157, 158, 160, 161 og 163-167. § 162 kan ikke fraviges ved aftale.',NULL,NULL,40,157,NULL,'2026-03-30 23:41:17'),
(1814,2266,0,'Lejeren kan frit opsige lejeaftalen, medmindre andet er aftalt.',NULL,NULL,16,63,NULL,'2026-03-30 23:41:17'),
(1815,2267,0,'Lejeren må dog ikke uden sin ægtefælles samtykke opsige lejemål om familiens bolig eller om lokaler, hvortil ægtefællernes eller den anden ægtefælles virksomhed er knyttet. § 160, stk. 2-4, finder tilsvarende anvendelse.',NULL,NULL,55,220,NULL,'2026-03-30 23:41:17'),
(1816,2269,0,'Udlejeren kan opsige følgende lejeforhold om:',NULL,NULL,12,45,NULL,'2026-03-30 23:41:17'),
(1817,2270,0,'Enkelte værelser til beboelse, når værelset er en del af udlejerens beboelseslejlighed eller er en del af et en- eller tofamilieshus, som udlejeren bebor.',NULL,NULL,39,154,NULL,'2026-03-30 23:41:17'),
(1818,2271,0,'En beboelseslejlighed i et hus, hvori der på tidspunktet for aftalens indgåelse kun findes to beboelseslejligheder, hvoraf ejeren bebor den ene. Reglen gælder, selv om ejeren anvender et eller flere lokaler i huset til andet end beboelse, og selv om der i ejendommen er udlejet et eller flere enkeltværelser til beboelse.',NULL,NULL,81,321,NULL,'2026-03-30 23:41:17'),
(1819,2272,0,'En ejerbolig eller en andelsbolig, hvis ejeren eller andelshaveren selv agter at bebo lejligheden, idet reglen dog kun gælder for ejere af ejerboliger eller ejere af andele i andelsboligforeninger, der ejede den pågældende lejlighed eller andel på tidspunktet for lejeaftalens indgåelse, og som på tidspunktet for opsigelsen ikke ejer andre udlejede ejerboliger eller andelsboliger.',NULL,NULL,96,382,NULL,'2026-03-30 23:41:17'),
(1820,2273,0,'En beboelseslejlighed, hvortil er knyttet lokaler til restauration, butik, kiosk eller tilsvarende brug på banegårde og i teatre, foreningsbygninger, forlystelsesanlæg, skove og parker og lign., hvor forretningen må antages hovedsagelig at blive søgt af det publikum, der benytter de nævnte virksomheder, skove og parker, og hvor forretningen står i direkte tilknytning til disse.',NULL,NULL,95,380,NULL,'2026-03-30 23:41:17'),
(1821,2274,0,'Andre lejeforhold end de i § 170 nævnte kan udlejeren kun opsige i følgende tilfælde, jf. dog §§ 172 og 177:',NULL,NULL,27,108,NULL,'2026-03-30 23:41:17'),
(1822,2275,0,'Når udlejeren ønsker selv at benytte det lejede.',NULL,NULL,12,48,NULL,'2026-03-30 23:41:17'),
(1823,2276,0,'Når udlejeren dokumenterer, at ejendommen skal nedrives. Det samme gælder, når udlejeren dokumenterer, at ombygning af ejendommen medfører, at det lejede må fraflyttes, og ejendommen efter ombygningen er omfattet af lov om almene boliger m.v., eller ombygningen sker som følge af ekspropriation eller ombygning til fyldestgørelse af et formål, til hvis gennemførelse der kan foretages ekspropriation.',NULL,NULL,100,400,NULL,'2026-03-30 23:41:17'),
(1824,2277,0,'Når lejeren af en beboelseslejlighed siden lejeaftalens indgåelse har været antaget som funktionær ved ejendommens drift til arbejde, for hvis udførelse det er af væsentlig betydning, at funktionæren bor i ejendommen, og udlejeren godtgør, at arbejdet ikke har været udført på tilfredsstillende måde. Opsigelse kan kun ske, når lejligheden ved genudlejning skal benyttes af den efterfølgende funktionær.',NULL,NULL,101,403,NULL,'2026-03-30 23:41:17'),
(1825,2278,0,'Når lejeren af en beboelseslejlighed, som er lejet som arbejder- eller funktionærbolig af den virksomhed, hvori lejeren er ansat, udtræder eller er udtrådt af sit arbejdsforhold til virksomheden, og lejligheden skal benyttes af en anden ansat i virksomheden.',NULL,NULL,65,258,NULL,'2026-03-30 23:41:17'),
(1826,2279,0,'Når udlejeren to eller flere gange i henhold til § 86, stk. 8, i lov om boligforhold har fået meddelelse om lejerens manglende efterlevelse af endelige huslejenævnsafgørelser.',NULL,NULL,44,175,NULL,'2026-03-30 23:41:17'),
(1827,2280,0,'Når lejeren har tilsidesat god skik og orden, jf. § 153, stk. 1, nr. 1-8 eller 11, jf. § 154, stk. 2, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',NULL,NULL,44,173,NULL,'2026-03-30 23:41:17'),
(1828,2281,0,'Når lejeren har tilsidesat betingelserne i et betinget lejeforhold, jf. § 154, stk. 1, nr. 1, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',NULL,NULL,42,165,NULL,'2026-03-30 23:41:17'),
(1829,2282,0,'Når vægtige grunde i øvrigt gør det særlig magtpåliggende for udlejeren at blive løst fra lejeforholdet.',NULL,NULL,26,104,NULL,'2026-03-30 23:41:17'),
(1830,2283,0,'Vedrører lejeforholdet en plejebolig efter § 1, stk. 1, 2. pkt., i den tidligere gældende lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996, eller § 5, stk. 2, i lov om almene boliger m.v. eller en ustøttet privat plejebolig, jf. § 1, stk. 5, anvist af kommunen eller amtskommunen, kan opsigelse efter stk. 1 kun ske, når lejeren samtidig anvises en anden og passende bolig.',NULL,NULL,106,423,NULL,'2026-03-30 23:41:17'),
(1831,2285,0,'Hvad angår opsigelsesretten efter § 171, stk. 1, nr. 1, gælder følgende begrænsninger:',NULL,NULL,22,86,NULL,'2026-03-30 23:41:17'),
(1832,2286,0,'Vedrører lejeforholdet en beboelseslejlighed, er det en betingelse, at udlejeren selv agter at bebo lejligheden.',NULL,NULL,28,112,NULL,'2026-03-30 23:41:17'),
(1833,2287,0,'Opsigelsen skal være rimelig ud fra en vurdering af begge parters forhold. Ved afgørelsen skal der bl.a. tages hensyn til, hvor længe udlejeren har ejet ejendommen, og, ved opsigelse af en lejer af en beboelseslejlighed, lejerens muligheder for at finde anden passende bolig.',NULL,NULL,69,275,NULL,'2026-03-30 23:41:17'),
(1834,2288,0,'Lejeforhold om lokaler, der er udlejet til erhvervsformål, kan udlejeren ikke opsige med henblik på at drive erhverv i samme branche som lejerens.',NULL,NULL,37,146,NULL,'2026-03-30 23:41:17'),
(1835,2289,0,'Er det lejede en ejerlejlighed, omfattes lejeforholdet kun af opsigelsesretten, hvis lejemålet er indgået efter ejendommens opdeling i ejerlejligheder. Er lejeaftalen indgået den 1. januar 1980 eller senere, er det herudover et krav, at lejeren ved lejeforholdets begyndelse var gjort bekendt med, at det lejede er en ejerlejlighed, og at opsigelse kan ske efter § 171, stk. 1, nr. 1. Er lejeaftalen indgået den 1. juli 1986 eller senere, er det tillige et krav, at udlejeren tidligere har beboet lejligheden.',NULL,NULL,128,509,NULL,'2026-03-30 23:41:17'),
(1836,2290,0,'En lejer kan ikke opsiges, så længe lejeren er beboerrepræsentant.',NULL,NULL,17,66,NULL,'2026-03-30 23:41:17'),
(1837,2291,0,'Bebor udlejeren ved opsigelsens afgivelse en lejlighed i ejendommen, skal udlejeren samtidig med opsigelsen tilbyde lejeren at overtage denne lejlighed.',NULL,NULL,38,152,NULL,'2026-03-30 23:41:17'),
(1838,2292,0,'Såfremt ejendommen ejes af flere personer i fællesskab, kan ejerne kun opsige lejeren af én beboelseslejlighed.',NULL,NULL,28,111,NULL,'2026-03-30 23:41:17'),
(1839,2294,0,'Er lejeaftalen tidsbestemt, ophører lejeforholdet uden opsigelse ved den aftalte lejetids udløb. Den tidsbestemte lejeaftale kan ikke ved opsigelse bringes til ophør i lejeperioden, medmindre dette er aftalt eller den anden part i lejeforholdet misligholder aftalen.',NULL,NULL,67,266,NULL,'2026-03-30 23:41:17'),
(1840,2295,0,'Benytter lejeren med udlejerens vidende det lejede i mere end 1 måned efter den aftalte lejetids udløb, uden at udlejeren har opfordret lejeren til at flytte, fortsætter lejeforholdet uden tidsbegrænsning.',NULL,NULL,52,205,NULL,'2026-03-30 23:41:17'),
(1841,2296,0,'Boligretten kan tilsidesætte tidsbegrænsningen, hvis den ikke må anses for tilstrækkeligt begrundet i udlejerens forhold.',NULL,NULL,31,121,NULL,'2026-03-30 23:41:17'),
(1842,2298,0,'Opsiges en lejer af en beboelseslejlighed efter § 171, stk. 1, nr. 1, 2, 3 eller 8, skal udlejeren uden unødigt ophold tilbyde lejeren at leje en anden lejlighed i ejendommen, hvis der bliver en lejlighed ledig til overtagelse senest 3 måneder efter den flyttedag, hvortil lejeren er opsagt, og lejligheden skal udlejes.',NULL,NULL,80,320,NULL,'2026-03-30 23:41:17'),
(1843,2299,0,'Opsiges en lejer efter § 171, stk. 1, nr. 2, skal udlejeren samtidig med opsigelsen tilbyde lejeren at leje en lejlighed eller lokaler af samme art som det opsagte, hvis der efter genopførelsen eller ombygningen sker udleje af lejligheder eller lokaler.',NULL,NULL,64,253,NULL,'2026-03-30 23:41:17'),
(1844,2300,0,'Opsiges en lejer af en beboelseslejlighed efter § 171, stk. 1, nr. 2, som følge af at en ejendom ombygges til almene ældreboliger eller almene ungdomsboliger efter lov om almene boliger m.v., finder stk. 1 og 2 alene anvendelse, hvis lejeren tilhører den personkreds, som er berettiget efter den nævnte lov.',NULL,NULL,77,307,NULL,'2026-03-30 23:41:17'),
(1845,2301,0,'Hvis en lejer af en beboelseslejlighed, jf. stk. 3, ikke tilhører den personkreds, som er berettiget efter den i stk. 3 nævnte lov, skal udlejeren samtidig med opsigelsen tilbyde lejeren at leje en passende bolig. En bolig anses for passende, når denne opfylder betingelserne i § 44, stk. 2, 2. og 3. pkt., i lov om boligforhold.',NULL,NULL,83,329,NULL,'2026-03-30 23:41:17'),
(1846,2303,0,'Opsigelsesvarslet er 3 måneder til den første hverdag i en måned, der ikke er dagen før en helligdag. Dog er opsigelsesvarslet 1 måned for de i § 170, nr. 1, nævnte lejeforhold.',NULL,NULL,45,177,NULL,'2026-03-30 23:41:17'),
(1847,2304,0,'Ved opsigelse efter § 170, nr. 2 og 3, og § 171, stk. 1, nr. 1, har lejeren krav på et opsigelsesvarsel på mindst 1 år til den første hverdag i en måned, der ikke er dagen før en helligdag.',NULL,NULL,48,189,NULL,'2026-03-30 23:41:17'),
(1848,2305,0,'Fraflytter lejeren inden opsigelsesvarslets udløb, skal udlejeren bestræbe sig på at genudleje det lejede. Hvad udlejeren indvinder eller burde have indvundet ved genudlejning, skal fragå i udlejerens krav over for lejeren.',NULL,NULL,56,223,NULL,'2026-03-30 23:41:17'),
(1849,2307,0,'Udlejerens opsigelse efter § 170, nr. 2 og 3, og § 171 skal være skriftlig og indeholde oplysning om lejerens adgang til at gøre indsigelse efter stk. 2. Udlejerens opsigelse efter § 171 skal endvidere indeholde oplysning om opsigelsesgrunden. Er det lejede udlejet til andet end beboelse, skal opsigelsen tillige indeholde oplysning om lejerens rettigheder efter §§ 177-179. Indeholder opsigelsen ikke disse oplysninger, er den ugyldig.',NULL,NULL,110,437,NULL,'2026-03-30 23:41:17'),
(1850,2308,0,'Vil lejeren ikke godkende opsigelsen, skal lejeren, senest 6 uger efter at opsigelsen er kommet frem til denne, fremsætte skriftlig indsigelse. Udlejeren må da anlægge sag ved boligretten senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at opretholde opsigelsen.',NULL,NULL,69,276,NULL,'2026-03-30 23:41:17'),
(1851,2310,0,'En lejer, der driver en erhvervsvirksomhed, hvis stedlige forbliven i ejendommen er af væsentlig betydning og værdi for virksomheden, kan kun opsiges efter § 171, hvis opsigelsen er rimelig ud fra en vurdering af begge parters forhold.',NULL,NULL,59,235,NULL,'2026-03-30 23:41:17'),
(1852,2311,0,'Ved afgørelsen efter stk. 1 skal der bl.a. tages hensyn til længden af det tidsrum, hvori forretningen har været drevet i de lejede lokaler, værdien af kundekredsen, forretningens nettooverskud, vægtige indvendinger mod lejerens person eller forretningsførelse, lejerens behandling af de lejede lokaler og lejerens forbedringer af disse.',NULL,NULL,85,337,NULL,'2026-03-30 23:41:17'),
(1853,2312,0,'Opsiges en lejer, der driver en erhvervsvirksomhed, hvis stedlige forbliven i ejendommen er af væsentlig betydning og værdi for virksomheden, kan der gives lejeren erstatning for opsigelsen.',NULL,NULL,48,190,NULL,'2026-03-30 23:41:17'),
(1854,2313,0,'Ved fastsættelse af en eventuel erstatning efter stk. 1 skal boligretten ud over de i § 177, stk. 2, nævnte forhold navnlig tage hensyn til følgende:',NULL,NULL,38,149,NULL,'2026-03-30 23:41:17'),
(1855,2314,0,'Værdiforringelsen af lejerens inventar og lign. ved flytning.',NULL,NULL,16,61,NULL,'2026-03-30 23:41:17'),
(1856,2315,0,'Lejerens flytteudgifter.',NULL,NULL,6,24,NULL,'2026-03-30 23:41:17'),
(1857,2316,0,'Det forhold, at ejendommen skal nedrives eller ombygges, og at lejeren er gjort bekendt hermed ved lejeaftalens indgåelse.',NULL,NULL,31,122,NULL,'2026-03-30 23:41:17'),
(1858,2317,0,'Lejeren skal ikke fraflytte, før lejeren har modtaget den erstatning, der er tilkendt denne, eller udlejeren ved bankgaranti eller på anden måde har stillet betryggende sikkerhed for erstatningsbeløbets betaling.',NULL,NULL,53,212,NULL,'2026-03-30 23:41:17'),
(1859,2318,0,'Vil lejeren godkende opsigelsen, men kræve erstatning efter § 178, skal lejeren meddele udlejeren dette, senest 6 uger efter at opsigelsen er kommet frem til lejeren.',NULL,NULL,42,166,NULL,'2026-03-30 23:41:17'),
(1860,2319,0,'Lejeren må endvidere anlægge sag ved boligretten senest 6 uger efter udløbet af den i stk. 1 nævnte frist.',NULL,NULL,27,106,NULL,'2026-03-30 23:41:17'),
(1861,2320,0,'Boligretten kan fastsætte, at hele erstatningen eller en del af denne skal tilbagebetales til udlejeren, hvis lejeren på ny åbner forretning i samme branche inden for en af retten fastsat tidsfrist på højst 3 år og inden for en af retten fastsat afstand fra det tidligere forretningslokale.',NULL,NULL,73,290,NULL,'2026-03-30 23:41:17'),
(1862,2321,0,'Lejeren må ikke åbne forretning i samme branche inden for den af retten fastsatte afstand i tid og sted, før lejeren har tilbagebetalt erstatning i overensstemmelse med reglerne i stk. 1.',NULL,NULL,47,187,NULL,'2026-03-30 23:41:17'),
(1863,2323,0,'§§ 171-179 kan, for så vidt angår opsigelse fra udlejerens side, ikke ved aftale fraviges til skade for lejeren, så længe udlejeren ikke har opsagt lejeren.',NULL,NULL,39,156,NULL,'2026-03-30 23:41:17'),
(1864,2324,0,'Lejeren kan ikke give afkald på sin ægtefælles ret efter § 169, stk. 2.',NULL,NULL,18,71,NULL,'2026-03-30 23:41:17'),
(1865,2327,0,'Udlejeren kan hæve lejeaftalen i følgende tilfælde, jf. dog § 183:',NULL,NULL,17,66,NULL,'2026-03-30 23:41:17'),
(1866,2328,0,'Når leje eller anden pligtig pengeydelse ikke er betalt rettidigt, jf. stk. 2.',NULL,NULL,20,78,NULL,'2026-03-30 23:41:17'),
(1867,2329,0,'Når det lejede benyttes til andet end aftalt og lejeren ikke trods udlejerens indsigelse er ophørt hermed.',NULL,NULL,27,106,NULL,'2026-03-30 23:41:17'),
(1868,2330,0,'Når lejeren modsætter sig, at udlejeren eller andre får adgang til det lejede, hvor de har ret hertil efter § 54, stk. 1, nr. 3, § 102, § 126, stk. 2, og § 186.',NULL,NULL,40,160,NULL,'2026-03-30 23:41:17'),
(1869,2331,0,'Når lejeren fraflytter det lejede i utide uden aftale med udlejeren.',NULL,NULL,17,68,NULL,'2026-03-30 23:41:17'),
(1870,2332,0,'Når lejeren vanrøgter det lejede og ikke uden ophold efter udlejerens indsigelse bringer det lejede i stand.',NULL,NULL,27,108,NULL,'2026-03-30 23:41:17'),
(1871,2333,0,'Når lejeren helt eller delvis overlader brugen af det lejede til en anden i tilfælde, hvor lejeren ikke er berettiget hertil og trods udlejerens indsigelse ikke bringer forholdet til ophør.',NULL,NULL,48,189,NULL,'2026-03-30 23:41:17'),
(1872,2334,0,'Når lejeren har tilsidesat god skik og orden, jf. § 153, stk. 1, nr. 1-8 eller 11, jf. § 154, stk. 2, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',NULL,NULL,44,173,NULL,'2026-03-30 23:41:17'),
(1873,2335,0,'Når lejeren har tilsidesat betingelserne i et betinget lejeforhold, jf. § 154, stk. 1, nr. 1, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',NULL,NULL,42,165,NULL,'2026-03-30 23:41:17'),
(1874,2336,0,'Når nogen er straffet i medfør af § 4 i lov om forbud mod besøgende i bestemte lokaler for at have modtaget besøgende i eller ved det lejede i strid med et forbud nedlagt i medfør af loven, eller når lejeren er straffet i medfør af § 8, stk. 1, i lov om forbud mod anvendelse af bestemte ejendomme som samlingssted for en gruppe for at have anvendt det lejede som samlingssted i strid med et forbud nedlagt i medfør af loven.',NULL,NULL,107,425,NULL,'2026-03-30 23:41:17'),
(1875,2337,0,'Når lejeren eller medlemmer af lejerens husstand er idømt en ubetinget fængselsstraf eller anden strafferetlig retsfølge af frihedsberøvende karakter for overtrædelse af §§ 119, 119 b, 134 a, 180, 181, 192 a, 216, 237 eller 244-246, § 252, stk. 1, §§ 260, 266, 276 a, 281 eller 288 eller § 291, stk. 2, i straffeloven eller i medfør af § 3 i lov om euforiserende stoffer for at have besiddet euforiserende stoffer med henblik på videreoverdragelse, og når overtrædelsen er begået inden for 1 km fra den ejendom, hvor lejemålet er beliggende.',NULL,NULL,136,541,NULL,'2026-03-30 23:41:17'),
(1876,2338,0,'Når lejeren af en butik eller beværtning trods udlejerens indsigelse ikke opfylder pligten til at holde forretningen åben og i forsvarlig drift.',NULL,NULL,36,144,NULL,'2026-03-30 23:41:17'),
(1877,2339,0,'Når en lejer, der helt eller delvis skal betale lejen ved at udføre arbejde, groft forsømmer sine pligter ved arbejdets udførelse og arbejdsforholdet som følge heraf bringes til ophør.',NULL,NULL,46,184,NULL,'2026-03-30 23:41:17'),
(1878,2340,0,'Når lejeren i øvrigt misligholder sine forpligtelser på en sådan måde, at lejerens fjernelse er påkrævet.',NULL,NULL,27,105,NULL,'2026-03-30 23:41:17'),
(1879,2341,0,'Udlejeren kan kun hæve lejeaftalen som følge af for sen betaling, hvis lejeren ikke har berigtiget restancen, senest 14 dage efter at skriftligt påkrav herom er kommet frem til lejeren. Udlejerens påkrav kan tidligst afgives efter 3. hverdag efter sidste rettidige betalingsdag og skal udtrykkeligt angive, at lejeforholdet kan ophæves, hvis lejerestancen ikke betales inden fristens udløb. Er den i 2. pkt. nævnte hverdag en lørdag eller grundlovsdag, kan påkrav tidligst afgives den følgende hverdag. Udløber den i 2. pkt. nævnte frist på en helligdag, en lørdag eller grundlovsdag, udskydes udløbet af fristen til den efterfølgende hverdag. Som gebyr for påkravet kan udlejeren kræve 287 kr. Det i 5. pkt. nævnte beløb er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1. Gebyret er pligtig pengeydelse i lejeforholdet.',NULL,NULL,211,842,NULL,'2026-03-30 23:41:17'),
(1880,2342,0,'Vedrører lejeaftalen en plejebolig efter § 1, stk. 1, 2. pkt., i den tidligere gældende lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996 med senere ændringer, eller § 5, stk. 2, i lov om almene boliger m.v. eller en ustøttet privat plejebolig, jf. § 1, stk. 5, anvist af kommunen eller amtskommunen, kan aftalen kun hæves efter stk. 1, når lejeren samtidig anvises en anden og passende bolig.',NULL,NULL,111,442,NULL,'2026-03-30 23:41:17'),
(1881,2344,0,'Skønnes det forhold, der lægges lejeren til last, at være af uvæsentlig betydning, kan udlejeren ikke hæve lejeaftalen.',NULL,NULL,30,119,NULL,'2026-03-30 23:41:17'),
(1882,2345,0,'Udlejeren kan ikke påberåbe sig de i § 182, nr. 1-6, nævnte forhold, hvis de er rettet, inden udlejeren hæver lejeaftalen.',NULL,NULL,31,122,NULL,'2026-03-30 23:41:17'),
(1883,2347,0,'Når udlejeren hæver lejeaftalen, skal lejeren straks fraflytte og betale leje m.v. for tiden, indtil lejeren kunne fraflytte med sædvanligt varsel. Lejeren skal endvidere erstatte udlejeren ethvert tab, derunder omkostningerne ved lejerens udsættelse af det lejede.',NULL,NULL,67,265,NULL,'2026-03-30 23:41:17'),
(1884,2348,0,'Udlejeren skal bestræbe sig for at genudleje det lejede. Hvad udlejeren indvinder eller burde have indvundet ved genudlejning i det i stk. 1 nævnte tidsrum, skal fragå i udlejerens krav over for lejeren.',NULL,NULL,51,203,NULL,'2026-03-30 23:41:17'),
(1885,2350,0,'Dette kapitel kan ikke fraviges, således at udlejeren skal kunne ophæve aftalen af andre grunde end de i § 182, jf. § 183, nævnte, eller at disse skal have videregående følger for lejeren end fastsat i § 184.',NULL,NULL,52,208,NULL,'2026-03-30 23:41:17'),
(1886,2352,0,'Er der afgivet opsigelse, eller skal det lejede af anden grund fraflyttes, skal lejeren give adgang til at bese det lejede. Lejeren fastsætter tiden herfor. Den skal være mindst 2 timer hveranden hverdag på et tidspunkt, der er bekvemt for en besigtigelse. Denne kan kun finde sted med deltagelse af udlejeren eller dennes stedfortræder, når lejeren ikke er repræsenteret.',NULL,NULL,93,372,NULL,'2026-03-30 23:41:17'),
(1887,2353,0,'Lejeren skal senest 8 dage før fraflytning opgive den adresse, som meddelelser, herunder krav efter § 187, kan sendes til.',NULL,NULL,31,122,NULL,'2026-03-30 23:41:17'),
(1888,2354,0,'Det lejede skal være fraflyttet senest kl. 12.00 på fraflytningsdagen. Lejeren skal aflevere det lejede i samme stand som ved overleveringen med undtagelse af den forringelse, som skyldes slid og ælde, og som ikke er omfattet af lejerens vedligeholdelsespligt, og mangler, som det påhviler udlejeren at udbedre. Det kan ikke pålægges lejeren at bringe det lejede i bedre stand end den, hvori lejeren overtog det lejede.',NULL,NULL,105,419,NULL,'2026-03-30 23:41:18'),
(1889,2355,0,'Udlejeren kan ikke gøre krav i medfør af stk. 1 gældende, når der er forløbet mere end 2 uger fra flyttesynet, jf. stk. 3, eller fra fraflytningsdagen for lejemål, der ikke er omfattet af pligten i stk. 3. Udgifter til istandsættelse, der ikke er medtaget i fraflytningsrapporten, jf. stk. 4, er lejeren uvedkommende. 1. og 2. pkt. gælder dog ikke, hvis manglen ikke kan erkendes ved anvendelse af sædvanlig agtpågivenhed eller lejeren har handlet svigagtigt.',NULL,NULL,115,459,NULL,'2026-03-30 23:41:18'),
(1890,2356,0,'Udlejere, der udlejer mere end én beboelseslejlighed, skal syne beboelseslejligheden, senest 2 uger efter at udlejeren er blevet bekendt med, at fraflytning har fundet sted. Den fraflyttende lejer skal indkaldes skriftligt til synet med mindst 1 uges varsel. Udlejeren og lejeren kan dog aftale et kortere varsel, når lejeforholdet er ophævet eller opsagt.',NULL,NULL,89,356,NULL,'2026-03-30 23:41:18'),
(1891,2357,0,'Udlejeren skal i forbindelse med synet, jf. stk. 3, udarbejde en fraflytningsrapport. Rapporten skal udleveres til lejeren ved synet eller sendes til lejeren senest 2 uger efter synet, såfremt lejeren ikke er til stede ved synet eller ikke vil kvittere for modtagelsen af rapporten.',NULL,NULL,71,282,NULL,'2026-03-30 23:41:18'),
(1892,2358,0,'Ved overtrædelse af stk. 3 og 4 bortfalder udlejerens krav på istandsættelse efter stk. 1.',NULL,NULL,23,90,NULL,'2026-03-30 23:41:18'),
(1893,2359,0,'Forbedringer, som lejeren har foretaget, må kun fjernes, når lejeren bringer det lejede i den stand, hvori lejeren overtog det.',NULL,NULL,32,127,NULL,'2026-03-30 23:41:18'),
(1894,2360,0,'Har lejeren med udlejerens samtykke efter § 141 foretaget ændringer af det lejede, kan udlejeren kun kræve retablering, når udlejeren har taget forbehold herfor, da udlejeren meddelte samtykket.',NULL,NULL,49,194,NULL,'2026-03-30 23:41:18'),
(1895,2361,0,'Har lejeren iværksat forbedringsarbejder m.v. mod godtgørelse ved fraflytning, jf. § 145, stk. 1, og § 63 i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010, og er disse ikke tilendebragt, kan udlejeren enten kræve arbejderne færdiggjort eller eventuelt kræve retablering.',NULL,NULL,77,308,NULL,'2026-03-30 23:41:18'),
(1896,2363,0,'§ 187, stk. 1, 3. pkt., stk. 2, 1. pkt., hvor der i henhold til § 187, stk. 3, er pligt til at afholde flyttesyn, og stk. 3-5, kan ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,45,178,NULL,'2026-03-30 23:41:18'),
(1897,2365,0,'Huslejenævnet træffer afgørelser i tvister om reglerne i §§ 187-189.',NULL,NULL,17,68,NULL,'2026-03-30 23:41:18'),
(1898,2367,0,'Formålet med ordningen med beboerrepræsentation er at give lejerne mulighed for at vælge repræsentanter, som kan varetage lejernes interesser i forholdet til udlejeren og være forhandlingspart over for udlejeren. Som et led heri er det et væsentligt formål med ordningen, at den medvirker til at sikre det bedst mulige grundlag for samarbejdet imellem lejerne og udlejeren i den enkelte ejendom. Med henblik på at sikre et godt og konstruktivt samarbejde om forhold af fælles interesse i ejendommen skal udlejeren og beboerrepræsentanterne derfor bestræbe sig på at sikre et højt gensidigt informationsniveau om dispositioner vedrørende ejendommen. Udlejeren bør for at fremme samarbejdet inddrage beboerrepræsentanterne i alle spørgsmål, der er af væsentlig betydning for lejerne i ejendommen.',NULL,NULL,199,794,NULL,'2026-03-30 23:41:18'),
(1899,2368,0,'Beboerrepræsentanterne kan følgende:',NULL,NULL,9,36,NULL,'2026-03-30 23:41:18'),
(1900,2369,0,'Få oplysning om, hvem der ejer ejendommen, og hvem der administrerer den.',NULL,NULL,19,73,NULL,'2026-03-30 23:41:18'),
(1901,2370,0,'Drøfte ethvert spørgsmål af betydning for ejendommens drift med udlejeren.',NULL,NULL,19,74,NULL,'2026-03-30 23:41:18'),
(1902,2371,0,'Blive holdt orienteret, når der foretages genudlejning af lejligheder i ejendommen.',NULL,NULL,21,83,NULL,'2026-03-30 23:41:18'),
(1903,2372,0,'Blive holdt orienteret om udlejerens ansættelse og afskedigelse af ejendomsfunktionærer.',NULL,NULL,22,88,NULL,'2026-03-30 23:41:18'),
(1904,2373,0,'I ejendomme med mindst seks beboelseslejligheder har lejerne ret til at vælge beboerrepræsentanter.',NULL,NULL,25,99,NULL,'2026-03-30 23:41:18'),
(1905,2374,0,'Ved oprettelsen af en beboerrepræsentation i en ejendom skal mindst 50 pct. af de på et beboermøde fremmødte lejere vælge beboerrepræsentanter. Er der ikke 50 pct. af lejerne til stede på beboermødet, skal en beslutning om at oprette en beboerrepræsentation bekræftes ved en efterfølgende urafstemning blandt samtlige lejere. Der skal vælges tre beboerrepræsentanter. I ejendomme med mindre end 13 lejligheder nedsættes antallet til en.',NULL,NULL,109,436,NULL,'2026-03-30 23:41:18'),
(1906,2375,0,'I ejendomme med mindre end seks og mere end to udlejede beboelseslejligheder har et flertal af lejerne samme beføjelser som beboerrepræsentationen i andre ejendomme. Der skal vælges en talsmand til at repræsentere lejerne over for udlejerne. Talsmanden skal handle i overensstemmelse med lejerflertallets beslutninger.',NULL,NULL,80,318,NULL,'2026-03-30 23:41:18'),
(1907,2376,0,'Er der oprettet en beboerrepræsentation i en ejendom, fortsætter den, indtil den besluttes ophævet, jf. dog stk. 5 og 6. En beslutning om at ophæve beboerrepræsentationen skal drøftes efter reglerne i stk. 2.',NULL,NULL,52,208,NULL,'2026-03-30 23:41:18'),
(1908,2377,0,'Såfremt det ikke med sikkerhed kan konstateres, hvorvidt der stadig er en beboerrepræsentation i ejendommen, herunder om de valgte beboerrepræsentanter stadig bebor ejendommen, kan udlejeren anmode samtlige beboelseslejere om inden en vis frist skriftligt at oplyse, hvem der er beboerrepræsentanter. Svarfristen skal være mindst 6 uger, dog således at der ved beregning af fristen ses bort fra juli måned. Hvis udlejeren ved svarfristens udløb ikke har modtaget den udbedte oplysning, anses beboerrepræsentationen for bortfaldet.',NULL,NULL,133,530,NULL,'2026-03-30 23:41:18'),
(1909,2378,0,'Beboerrepræsentationen bortfalder, såfremt der ikke har været afholdt beboermøde med valg af beboerrepræsentanter i 2 år.',NULL,NULL,31,121,NULL,'2026-03-30 23:41:18'),
(1910,2379,0,'Er flere ejendomme, der ejes af samme ejer, opført kontinuerligt som en samlet bebyggelse, og har disse ejendomme fælles friarealer eller nogen form for driftsfællesskab, kan der oprettes en beboerrepræsentation, når ejendommene i alt har mindst seks beboelseslejligheder. Det samme gælder, hvor flere ejendomme er samvurderet eller samnoteret i tingbogen. I sådanne ejendomme skal beboerrepræsentationen omfatte samtlige ejendomme.',NULL,NULL,108,432,NULL,'2026-03-30 23:41:18'),
(1911,2380,0,'I en ejendom, der er opdelt i ejerlejligheder, gælder reglerne om beboerrepræsentation for lejere, hvis udlejeren ejer mindst seks beboelseslejligheder i ejerforeningen.',NULL,NULL,43,169,NULL,'2026-03-30 23:41:18'),
(1912,2381,0,'I en ejendom, der ejes af en andelsboligforening, gælder reglerne om beboerrepræsentation, hvis mindst seks beboelseslejligheder ikke bebos af andelshavere.',NULL,NULL,39,156,NULL,'2026-03-30 23:41:18'),
(1913,2382,0,'Indenrigs- og boligministeren fastsætter nærmere regler om afholdelse af beboermøde og valg af beboerrepræsentanter og om afholdelse af udgifter i forbindelse med beboerrepræsentation.',NULL,NULL,46,184,NULL,'2026-03-30 23:41:18'),
(1914,2383,0,'Er der valgt beboerrepræsentanter, kan et beboermøde vedtage en husorden. Den skal være gældende, medmindre udlejeren har vægtige grunde til at modsætte sig dette.',NULL,NULL,41,163,NULL,'2026-03-30 23:41:18'),
(1915,2384,0,'I ejendomme, der er opdelt i ejerlejligheder, og i ejendomme, der ejes af andelsboligforeninger, skal samtlige beboere indkaldes til det beboermøde, der træffer afgørelse om husordenen. For hver beboelseslejlighed kan afgives én stemme.',NULL,NULL,59,236,NULL,'2026-03-30 23:41:18'),
(1916,2385,0,'Udlejeren skal inden for 2 uger fra den endelige afgørelse meddele det til beboerrepræsentationen, når der træffes afgørelser om boliglejeforhold, som giver en lejer helt eller delvist medhold og ikke angår husordenssager i den eller de ejendomme, som beboerrepræsentationen vedrører. I ejendomme, hvor der ikke findes en beboerrepræsentation, skal udlejeren inden for 2 uger fra den endelige afgørelse meddele det til samtlige lejere, når der træffes afgørelser om lejeforhold, som giver en lejer helt eller delvist medhold og ikke angår husordenssager i ejendommen.',NULL,NULL,142,567,NULL,'2026-03-30 23:41:18'),
(1917,2386,0,'Meddelelsen skal gives skriftligt og indeholde oplysning om tvistens emne og afgørelsens resultat. Meddelelsen skal tillige indeholde kopi af den trufne afgørelse. Indeholder meddelelsen ikke disse oplysninger, er den ugyldig. De oplysninger, der er nævnt i 1. pkt., kan gives digitalt, herunder ved at gøre oplysningerne tilgængelige på en digital platform, når udlejeren har givet lejeren meddelelse herom.',NULL,NULL,102,408,NULL,'2026-03-30 23:41:18'),
(1918,2387,0,'Overtrædelse af stk. 1 straffes med bøde eller fængsel indtil 4 måneder, medmindre højere straf er forskyldt efter anden lovgivning.',NULL,NULL,33,132,NULL,'2026-03-30 23:41:18'),
(1919,2388,0,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',NULL,NULL,27,107,NULL,'2026-03-30 23:41:18'),
(1920,2390,0,'Dette kapitel kan ikke ved aftale fraviges til skade for lejeren. § 194 kan ikke fraviges.',NULL,NULL,23,90,NULL,'2026-03-30 23:41:18'),
(1921,2393,0,'I ejendomme, der helt eller delvis anvendes til beboelse, skal udlejeren tilbyde lejerne ejendommen til overtagelse på andelsbasis, inden ejendommen overdrages til anden side.',NULL,NULL,44,175,NULL,'2026-03-30 23:41:18'),
(1922,2394,0,'Reglerne om tilbudspligt finder anvendelse på ejendomme, der udelukkende anvendes til beboelse, og som indeholder mindst seks beboelseslejligheder. Reglerne finder endvidere anvendelse på andre ejendomme med mindst 13 beboelseslejligheder.',NULL,NULL,60,239,NULL,'2026-03-30 23:41:18'),
(1923,2395,0,'Reglerne om tilbudspligt finder ikke anvendelse på ejendomme, der er opdelt i ejerlejligheder. Dette gælder dog ikke den ejerlejlighed, som efter § 16, stk. 3, i lov om ejerlejligheder indeholder boligerne i den oprindelige ejendom, og den ejerlejlighed, som efter § 20, stk. 1, 3. pkt., i lov om ejerlejligheder indeholder boligerne og eventuelle lokaler til andet end beboelse i den oprindelige ejendom.',NULL,NULL,102,405,NULL,'2026-03-30 23:41:18'),
(1924,2396,0,'Reglerne om tilbudspligt anvendes ved overdragelse af ejendomme omfattet af lov om leje af almene boliger, hvis ejendommen efter overdragelsen ikke er omfattet af samme lov. Dette gælder dog ikke for ejendomme, som er beliggende i et udsat boligområde, jf. § 61 a, stk. 1, i lov om almene boliger m.v., eller et boligområde, som ikke opfylder betingelserne i § 61 a, stk. 1, i lov om almene boliger m.v., men er omfattet af en fælles udviklingsplan eller en kommunal udviklingsplan, jf. § 168 a, stk. 1, eller § 168 b, stk. 1, i lov om almene boliger m.v.',NULL,NULL,139,555,NULL,'2026-03-30 23:41:18'),
(1925,2397,0,'Tilbudspligten efter stk. 1 og 2 opretholdes, selv om ejeren foretager udstykning, matrikulering eller arealoverførsel efter lov om udstykning og anden registrering i matriklen.',NULL,NULL,45,177,NULL,'2026-03-30 23:41:18'),
(1926,2399,0,'Tilbudspligten respekterer private forkøbsrettigheder og køberettigheder, der er tinglyst før den 3. maj 1979, men går i øvrigt forud for andre rettigheder over ejendommen, uanset hvornår de er stiftet.',NULL,NULL,51,202,NULL,'2026-03-30 23:41:18'),
(1927,2401,0,'Tilbudspligten gælder, når ejendommen eller en del heraf overdrages ved salg, gave, fusion, spaltning eller mageskifte. Tilbudspligten gælder endvidere ved overdragelse af aktier og anparter i aktie- og anpartsselskaber, som ejer ejendomme, når erhververen herved opnår majoriteten af stemmerne i selskabet.',NULL,NULL,77,307,NULL,'2026-03-30 23:41:18'),
(1928,2402,0,'Tilbudspligten kommer dog ikke til anvendelse i følgende tilfælde:',NULL,NULL,17,66,NULL,'2026-03-30 23:41:18'),
(1929,2403,0,'Når erhververen er staten eller en kommune.',NULL,NULL,11,43,NULL,'2026-03-30 23:41:18'),
(1930,2404,0,'Når erhververen er den hidtidige ejers ægtefælle eller er beslægtet eller besvogret med ejeren i op- eller nedadstigende linje eller i dennes sidelinje så nær som søskende eller disses børn.',NULL,NULL,48,190,NULL,'2026-03-30 23:41:18'),
(1931,2405,0,'Når erhververen er en hidtidig medejer.',NULL,NULL,10,39,NULL,'2026-03-30 23:41:18'),
(1932,2406,0,'Når erhvervelsen sker ved arv, medmindre erhververen er en juridisk person.',NULL,NULL,19,75,NULL,'2026-03-30 23:41:18'),
(1933,2407,0,'Når ejendommen inden for de seneste 5 år har været ejet af en andelsboligforening, et boligaktieselskab eller et boliganpartsselskab.',NULL,NULL,34,133,NULL,'2026-03-30 23:41:18'),
(1934,2409,0,'Tilbudspligten opfyldes, ved at ejeren over for samtlige lejere af beboelseslejligheder fremsætter tilbud om, at en af beboerne dannet andelsboligforening kan erhverve ejendommen til samme købesum, kontante udbetaling og øvrige vilkår, som ejeren kan opnå ved salg til anden side. Vilkårene skal være af et sådant indhold, at de kan opfyldes af en andelsboligforening. Acceptfristen skal være mindst 10 uger, dog således at der ved beregning af fristen ses bort fra juli måned.',NULL,NULL,120,477,NULL,'2026-03-30 23:41:18'),
(1935,2410,0,'I tilfælde af påtænkt salg skal tilbuddet ledsages af dokumentation for, at ejeren ved salget kan opnå de tilbudte vilkår. I tilfælde af påtænkt overdragelse ved gave, fusion, spaltning eller mageskifte eller af påtænkt arveudlæg skal der til afgørelse af, om købesummen og de øvrige tilbudte vilkår svarer til ejendommens værdi i handel og vandel som udlejningsejendom, optages syn og skøn efter reglerne herom i retsplejelovens § 343.',NULL,NULL,109,436,NULL,'2026-03-30 23:41:18'),
(1936,2411,0,'Ved overdragelse af aktier og anparter, hvor tilbudspligten efter § 198, stk. 1, 2. pkt., gælder, skal der ligeledes optages syn og skøn, jf. stk. 2. Dette gælder dog ikke ved overdragelse af aktier og anparter i selskaber, som ikke ejer andre aktiver end den tilbudspligtige ejendom.',NULL,NULL,71,284,NULL,'2026-03-30 23:41:18'),
(1937,2412,0,'Senest samtidig med tilbuddet skal ejeren give sædvanlige oplysninger om ejendommen, herunder ejendommens driftsudgifter, lejeforhold og saldi på de forskellige konti, som ejeren skal føre i henhold til denne lov. Den i stk. 1 nævnte acceptfrist løber fra det tidspunkt, hvor lejerne har modtaget oplysningerne. De oplysninger, der er nævnt i 1. pkt., kan gives digitalt, herunder ved at gøre oplysningerne tilgængelige på en digital platform, når udlejeren har givet lejeren meddelelse herom.',NULL,NULL,124,493,NULL,'2026-03-30 23:41:18'),
(1938,2413,0,'Ejeren kan afvise andelsboligforeningens accept, hvis foreningen ikke på anfordring dokumenterer, at den kan betale den krævede kontante udbetaling.',NULL,NULL,37,148,NULL,'2026-03-30 23:41:18'),
(1939,2414,0,'Bliver ejerens tilbud ikke accepteret, kan ejendommen videreoverdrages til andre ved salg på de tilbudte vilkår eller ved gave, mageskifte eller arveudlæg, hvis skøde anmeldes til tinglysning senest 1 år efter tilbuddet til lejerne.',NULL,NULL,58,232,NULL,'2026-03-30 23:41:18'),
(1940,2416,0,'Justitsministeren fastsætter regler om tinglysning af dokumenter om overdragelse af en ejendom, hvorpå der er tilbudspligt.',NULL,NULL,31,123,NULL,'2026-03-30 23:41:18'),
(1941,2418,0,'§§ 196-200 kan ikke ved aftale fraviges til skade for lejeren.',NULL,NULL,16,62,NULL,'2026-03-30 23:41:18'),
(1942,2421,0,'Tvister om lejeforhold, der er omfattet af denne lov, kan i 1. instans indbringes for byretten, hvis spørgsmålet ikke efter denne lov kan indbringes for huslejenævnet eller i Københavns Kommune ankenævnet. Retten benævnes boligretten.',NULL,NULL,59,234,NULL,'2026-03-30 23:41:18'),
(1943,2422,0,'Parterne kan dog, når der er opstået en tvist, aftale, at tvisten kan indbringes for boligretten, uden at huslejenævnet og i Københavns Kommune ankenævnet har behandlet sagen.',NULL,NULL,44,175,NULL,'2026-03-30 23:41:18'),
(1944,2423,0,'Stk. 1 og 2 begrænser ikke fogedrettens adgang til at gennemføre en umiddelbar fogedforretning, jf. retsplejelovens kapitel 55, om udsættelse af et lejemål, der er ophævet som følge af lejerens tilsidesættelse af god skik og orden.',NULL,NULL,58,231,NULL,'2026-03-30 23:41:18'),
(1945,2425,0,'Dette kapitel kan ikke fraviges.',NULL,NULL,8,32,NULL,'2026-03-30 23:41:18'),
(1946,2427,0,'De i § 19, stk. 2 og 5, § 23, stk. 4, § 105, stk. 1, § 106, stk. 1, § 117, stk. 1, § 131, stk. 1, § 138, § 145, stk. 5, og § 182, stk. 2, nævnte beløb er opgjort i 2021-niveau og reguleres én gang årligt efter udviklingen i Danmarks Statistiks nettoprisindeks i en 12-månedersperiode sluttende i juni måned året før det finansår, reguleringen vedrører. Beløbene afrundes til nærmeste hele kronebeløb.',NULL,NULL,100,400,NULL,'2026-03-30 23:41:18'),
(1947,2428,0,'De i § 119, stk. 1, og § 120, stk. 1 og 2, nævnte beløb reguleres én gang årligt efter udviklingen i Danmarks Statistiks nettoprisindeks i en 12-månedersperiode sluttende i juni måned året før det finansår, reguleringen vedrører. Beløbene afrundes til nærmeste hele kronebeløb.',NULL,NULL,70,277,NULL,'2026-03-30 23:41:18'),
(1948,2430,0,'Indenrigs- og boligministeren kan bemyndige en under ministeriet oprettet styrelse til at udøve de beføjelser, der i denne lov er tillagt ministeren.',NULL,NULL,38,149,NULL,'2026-03-30 23:41:18'),
(1949,2431,0,'Indenrigs- og boligministeren kan fastsætte regler om adgangen til at påklage afgørelser, der er truffet i henhold til bemyndigelse efter stk. 1, herunder at afgørelsen ikke skal kunne indbringes for ministeren.',NULL,NULL,53,211,NULL,'2026-03-30 23:41:18'),
(1950,2433,0,'Indenrigs- og boligministeren fastsætter nærmere regler om beregning af boligers og erhvervslokalers bruttoetageareal i henhold til denne lov.',NULL,NULL,36,142,NULL,'2026-03-30 23:41:18'),
(1951,2435,0,'Loven træder i kraft den 1. juli 2022.',NULL,NULL,10,38,NULL,'2026-03-30 23:41:18'),
(1952,2436,0,'Lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, ophæves.',NULL,NULL,19,73,NULL,'2026-03-30 23:41:18'),
(1953,2437,0,'Lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, ophæves.',NULL,NULL,28,110,NULL,'2026-03-30 23:41:18'),
(1954,2438,0,'Reglerne i § 3, stk. 2, i lov nr. 609 af 21. december 1983, § 4, stk. 6, i lov nr. 419 af 1. juni 1994, § 2, stk. 2, i lov nr. 461 af 12. juni 1996, § 11, stk. 3, 5, 7 og 8, i lov nr. 406 af 31. maj 2000, § 5, stk. 3, i lov nr. 1090 af 17. december 2002, § 6, stk. 2, i lov nr. 1219 af 27. december 2003, § 9, stk. 2, i lov nr. 1235 af 27. december 2003, § 7, stk. 3, i lov nr. 488 af 9. juni 2004, § 3, stk. 2, i lov nr. 632 af 11. juni 2010, § 4, stk. 3, i lov nr. 517 af 5. juni 2012, § 6, stk. 3 og 4, i lov nr. 439 af 6. maj 2014, § 5, stk. 3, 6 og 10, i lov nr. 310 af 30. marts 2015, § 4, stk. 2, i lov nr. 643 af 8. juni 2016, § 7, stk. 8, i lov nr. 550 af 30. maj 2017, § 3, stk. 2, i lov nr. 1561 af 19. december 2017, § 58, stk. 6, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, § 3, stk. 2 og 3, i lov nr. 817 af 9. juni 2020, § 3, stk. 2 og 3, i lov nr. 818 af 9. juni 2020 og § 3, stk. 2, i lov nr. 819 af 9. juni 2020 finder fortsat anvendelse.',NULL,NULL,251,1002,NULL,'2026-03-30 23:41:18'),
(1955,2439,0,'Regler fastsat i medfør af lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, forbliver i kraft, indtil de ophæves eller afløses af forskrifter udstedt i medfør af denne lov eller lov om boligforhold.',NULL,NULL,80,319,NULL,'2026-03-30 23:41:18'),
(1956,2440,0,'Reglerne i kapitel 23 og §§ 131, 138 og 161 finder ikke anvendelse i ejendomme, der inden den 1. marts 1975 er erhvervet af en kommune eller et godkendt saneringsselskab, og som er omfattet af en godkendt saneringsplan.',NULL,NULL,55,219,NULL,'2026-03-30 23:41:18'),
(1957,2441,0,'Ved vurderingen af, om lejemålet opfylder beløbskravene i § 19, stk. 2, 2. pkt., medregnes ligeledes ikke forbedringer foretaget efter § 58, stk. 3, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019.',NULL,NULL,60,238,NULL,'2026-03-30 23:41:18'),
(1958,2442,0,'Ved sammenligningen efter §§ 20 og 42 ses der tillige bort fra lejemål, som er forbedret efter § 58, stk. 3, og § 62 b i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019.',NULL,NULL,52,208,NULL,'2026-03-30 23:41:18'),
(1959,2443,0,'Ved vurderingen af lejen og det lejedes værdi efter §§ 20 og 42 ses der tillige bort fra lejeforhøjelse efter § 58, stk. 3 og 4, og § 62 b i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og forbedringer efter § 46 a, stk. 3, § 58, stk. 3, og § 62 b i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019. Der ses tillige bort fra lejeforhøjelser til afsættelse efter § 18 b i den tidligere gældende lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, og forbedringer gennemført for beløb, der er afsat efter denne bestemmelse.',NULL,NULL,163,652,NULL,'2026-03-30 23:41:18'),
(1960,2444,0,'Udlejeren kan ud over de i § 171 nævnte tilfælde opsige lejeren, når denne tilsidesætter betingelserne i et betinget lejeforhold i henhold til § 79 b, stk. 1, nr. 1, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',NULL,NULL,82,327,NULL,'2026-03-30 23:41:18'),
(1961,2445,0,'Har lejeren med udlejerens samtykke efter § 28 i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, foretaget ændringer af det lejede, kan udlejeren uanset § 188, stk. 2, kun kræve retablering, når udlejeren har taget forbehold herfor, da udlejeren meddelte samtykket.',NULL,NULL,77,305,NULL,'2026-03-30 23:41:18'),
(1962,2446,0,'Har lejeren iværksat forbedringsarbejder m.v. mod godtgørelse ved fraflytning, jf. § 62 a, stk. 1, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og er disse ikke tilendebragt, kan udlejeren enten kræve arbejderne færdiggjort eller eventuelt kræve retablering.',NULL,NULL,76,303,NULL,'2026-03-30 23:41:18'),
(1963,2447,0,'Såfremt den andel af lejen, der efter tidligere gældende regler afsættes til vedligeholdelse og opretning, er større end de beløb, der er fastsat i §§ 117 og 119, opretholdes den højere afsættelse, indtil de lejeforhøjelser, der måtte gennemføres i medfør af §§ 23 og 127-130, overstiger de hidtidige hensættelsesbeløb.',NULL,NULL,80,319,NULL,'2026-03-30 23:41:18'),
(1964,2448,0,'Såfremt den andel af lejen, der efter tidligere gældende regler afsættes til vedligeholdelse og opretning, er mindre end de beløb, der er fastsat i §§ 117 og 119, bibeholdes den lavere afsættelse, indtil der gennemføres lejeforhøjelse i medfør af §§ 23 og 127-130.',NULL,NULL,66,264,NULL,'2026-03-30 23:41:18'),
(1965,2449,0,'For ejendomme, der pr. 1. juli 2015 ikke længere er omfattet af reglerne i kapitel X A i lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010 med senere ændringer, udbetales det på kontoen efter § 63 a i samme lov indestående beløb efter reglerne i kapitel X A i samme lov. Der kan ikke varsles forbedringsforhøjelse for ejendomme omfattet af 1. pkt., før indestående beløb på kontoen efter § 63 a i lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010 med senere ændringer, er udbetalt. Huslejenævnet træffer afgørelse om tilsidesættelse af forbedringsforhøjelse opkrævet i strid med 2. pkt. For konti med negativ saldo fortsætter udlejeren med at opkræve og afsætte beløb efter §§ 63 a og 63 b i lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010 med senere ændringer, indtil kontoen er udlignet. Når saldoen på kontoen er udbetalt eller udlignet, skal lejen nedsættes tilsvarende. Huslejenævnet træffer afgørelse om nedsættelse af lejen efter 4. pkt.',NULL,NULL,246,982,NULL,'2026-03-30 23:41:18'),
(1966,2450,0,'Loven gælder ikke for Færøerne og Grønland.',NULL,NULL,11,43,NULL,'2026-03-30 23:41:18');
