INSERT INTO `know_units` VALUES
(1606,1,NULL,0,'chapter','Kapitel 1','Anvendelsesområde m.v.',NULL,1,0,'001',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1607,1,1606,1606,'paragraph_group',NULL,'Anvendelsesområde',NULL,1,1,'001.001',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1608,1,1607,1607,'paragraph','§ 1.',NULL,'Loven gælder for leje, herunder fremleje, af hus eller rum, uanset om lejeren er en person eller en virksomhed m.v. (juridisk person).',1,2,'001.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id839ed4f3-fa47-4410-a180-432429002f13\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1609,1,1608,1608,'subsection','Stk. 2.',NULL,'Loven gælder, selv om lejen skal betales med andet end penge, herunder ved arbejde.',1,3,'001.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1610,1,1608,1608,'subsection','Stk. 3.',NULL,'Bortset fra § 17 gælder loven dog ikke for aftaler om leje af bolig med fuld kost, for aftaler mellem et hotel og dets gæster og for lejeforhold om beboelseslejligheder og andre beboelsesrum, herunder sommerhuse, kolonihavehuse og andre fritidsboliger, som er udlejet til ferie- og fritidsmæssige formål.',2,3,'001.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1611,1,1608,1608,'subsection','Stk. 4.',NULL,'Loven gælder endvidere for leje af ustøttede private plejeboliger, jf. dog § 1, stk. 4, i erhvervslejeloven. §§ 7 og 9, kapitel 3, § 53, stk. 2, §§ 105-107, 109, 113, 119-121, 123, § 127, stk. 3, § 135 og kapitel 24 gælder dog ikke for ustøttede private plejeboliger.',3,3,'001.001.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1612,1,1608,1608,'subsection','Stk. 5.',NULL,'Ustøttede private plejeboliger, jf. stk. 4, er tidligere institutionspladser på plejehjem og i beskyttede boliger, der den 31. december 2002 var omfattet af § 140 i lov om social service, og som kommunalbestyrelsen har omdannet til ustøttede private plejeboliger.',4,3,'001.001.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1613,1,1607,1607,'paragraph','§ 2.',NULL,'Loven gælder ikke, i det omfang lejeforholdet er omfattet af særlige regler i anden lovgivning.',2,2,'001.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idf7a70440-99df-44c5-97ad-9590eb4489ab\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1614,1,1613,1613,'subsection','Stk. 2.',NULL,'Loven gælder ikke, i det omfang lejeforholdet er et led i et ansættelsesforhold under staten eller under en institution, hvortil staten yder tilskud, når løn- og andre ansættelsesvilkår er godkendt af staten. Loven gælder heller ikke lejeforhold, der er et led i et ansættelsesforhold under en region eller en kommune eller under en selvejende institution, hvormed en region eller en kommune har indgået overenskomst om institutionens drift, når løn- og andre ansættelsesvilkår er godkendt af Kommunernes Lønningsnævn eller er aftalt med eller fastsat af Regionernes Lønnings- og Takstnævn.',1,3,'001.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1615,1,1613,1613,'subsection','Stk. 3.',NULL,'Bortset fra § 196, stk. 4, gælder loven ikke for leje af boliger, der er omfattet af § 1 i lov om leje af almene boliger.',2,3,'001.001.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1616,1,1613,1613,'subsection','Stk. 4.',NULL,'Loven gælder ikke for lejeforhold om lokaler, der udlejes til brug for drift af friplejeboliger, jf. § 11, stk. 1, i lov om friplejeboliger.',3,3,'001.001.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1617,1,1613,1613,'subsection','Stk. 5.',NULL,'Loven gælder ikke for lejeforhold, som er omfattet af erhvervslejeloven.',4,3,'001.001.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1618,1,1607,1607,'paragraph','§ 3.',NULL,'Lovens regler om beboelseslejligheder finder også anvendelse, når en lejlighed er udlejet tillige med lokaliteter til andet end beboelse. Bortset fra § 129, stk. 4, gælder kapitel 3-5 og §§ 105-107 og 127-130 dog ikke for lokaler omfattet af § 1, stk. 2, i erhvervslejeloven.',3,2,'001.001.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id8115e8e1-9f11-420e-af2b-3aaaeb11e2bc\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1619,1,1606,1606,'paragraph_group',NULL,'Regulerede kommuner',NULL,2,1,'001.002',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1620,1,1619,1619,'paragraph','§ 4.',NULL,'Ved regulerede kommuner forstås kommuner, hvor de hidtidige regler om huslejeregulering i kapitel II-V i lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019 med senere ændringer, fandt anvendelse. Ved regulerede kommuner forstås endvidere kommuner, hvor kommunalbestyrelsen har besluttet, at kommunen skal være reguleret, jf. stk. 2.',1,2,'001.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idedf5bbac-73ad-4b5b-b4e6-807f7c3e8a3e\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1621,1,1620,1620,'subsection','Stk. 2.',NULL,'Kommunalbestyrelsen kan under hensyn til boligforholdene bestemme, at kommunen skal være reguleret. I regulerede kommuner kan kommunalbestyrelsen beslutte, at kommunen ikke længere skal være reguleret.',1,3,'001.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1622,1,1606,1606,'paragraph_group',NULL,'Bekendtgørelse af kommunalbestyrelsens beslutninger',NULL,3,1,'001.003',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1623,1,1622,1622,'paragraph','§ 5.',NULL,'De beslutninger, som kommunalbestyrelsen træffer efter § 4, stk. 2, skal bekendtgøres i Statstidende og i øvrigt på den måde, der er sædvanlig i kommunen. Er andet ikke udtrykkeligt fastsat i beslutningen, får den virkning fra og med datoen på det nummer af Statstidende, hvori den er bekendtgjort.',1,2,'001.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb85b9646-926b-44a4-8822-a20863877f98\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1624,1,1606,1606,'paragraph_group',NULL,'Huslejeregulering m.v. i regulerede kommuner',NULL,4,1,'001.004',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1625,1,1624,1624,'paragraph','§ 6.',NULL,'§ 9, kapitel 3, §§ 62, 105-107, 109 og 113, § 115, stk. 2, §§ 119-123, § 127, stk. 3, og § 135 gælder alene for lejeforhold i ejendomme, der er beliggende i regulerede kommuner, jf. dog stk. 2-4 og § 7, stk. 3. §§ 42-45, 49-51 og 53 gælder ikke for lejeforhold i ejendomme omfattet af 1. pkt.',1,2,'001.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb7f3fa82-845b-4b44-a4eb-002622d4727e\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1626,1,1625,1625,'subsection','Stk. 2.',NULL,'Lejeforhold i ejendomme, der er beliggende i regulerede kommuner, hvor mere end 80 pct. af ejendommens bruttoetageareal den 1. januar 1980 anvendtes til andet end beboelse, er ikke omfattet af stk. 1. For disse lejeforhold gælder dog §§ 33-36.',1,3,'001.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1627,1,1625,1625,'subsection','Stk. 3.',NULL,'Lejeforhold om enkeltværelser til beboelse i ejendomme, der er beliggende i regulerede kommuner, hvor værelserne er en del af udlejerens beboelseslejlighed eller er en del af et en- eller tofamilieshus, som udlejeren bebor, er ikke omfattet af stk. 1. For disse lejeforhold gælder dog §§ 33-36 og 40.',2,3,'001.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1628,1,1625,1625,'subsection','Stk. 4.',NULL,'Lejeforhold i ejendomme, som ved lejemålets indgåelse ejes af en selvejende institution, hvor boligerne er opført efter den tidligere gældende lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996 med senere ændringer, den tidligere gældende lov om boligbyggeri, jf. lovbekendtgørelse nr. 722 af 1. august 1996 med senere ændringer, eller lov om almene boliger m.v., er ikke omfattet af stk. 1.',3,3,'001.004.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1629,1,1606,1606,'paragraph_group',NULL,'Huslejeregulering for mindre ejendomme i regulerede kommuner',NULL,5,1,'001.005',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1630,1,1629,1629,'paragraph','§ 7.',NULL,'§ 32 gælder alene for lejeforhold i ejendomme, der er beliggende i regulerede kommuner, som den 1. januar 1995 omfattede seks eller færre beboelseslejligheder. I ejendomme, der er beliggende i regulerede kommuner, og som ejes af andelsboligforeninger, gælder § 32, såfremt der i ejendommen er seks eller færre beboelseslejligheder, der er udlejet af andelsboligforeningen.',1,2,'001.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id88eee2f6-64f9-4d86-a6e8-4a1e52c1237a\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1631,1,1630,1630,'subsection','Stk. 2.',NULL,'I ejendomme, der er beliggende i regulerede kommuner og opført efter den 1. januar 1995, gælder § 32, hvis ejendommen omfattede seks eller færre beboelseslejligheder, da den blev taget i brug.',1,3,'001.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1632,1,1630,1630,'subsection','Stk. 3.',NULL,'Lejeforhold i ejendomme omfattet af stk. 1 og 2 er ikke omfattet af § 6, stk. 1. Dog gælder for lejemål i disse ejendomme §§ 9 og 33-36, § 38, stk. 3, og § 40. For lejemål i disse ejendomme gælder dog endvidere §§ 105, 106 og 109, såfremt ejendommen på tidspunktet for varslingen af iværksættelsen af forbedringen omfatter fire eller flere beboelseslejligheder, medmindre ejendommen er beliggende i landzone og ejendommen samtidig er en landbrugs- eller skovbrugsejendom.',2,3,'001.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1633,1,1606,1606,'paragraph_group',NULL,'Ejendomsbegreber',NULL,6,1,'001.006',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1634,1,1633,1633,'paragraph','§ 8.',NULL,'I denne lov forstås ved en ejendom følgende, jf. dog § 9:',1,2,'001.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idec132e99-184e-4bda-9e14-64b2adb9b2de\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1635,1,1634,1634,'list_item','1)',NULL,'Et matrikelnummer.',1,3,'001.006.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1636,1,1634,1634,'list_item','2)',NULL,'Flere matrikelnumre, der ifølge notering i matriklen skal holdes forenet.',2,3,'001.006.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1637,1,1634,1634,'list_item','3)',NULL,'En ejerlejlighed.',3,3,'001.006.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1638,1,1634,1634,'list_item','4)',NULL,'En bygning på lejet grund, som har eget ejendomsblad i tingbogen.',4,3,'001.006.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1639,1,1633,1633,'paragraph','§ 9.',NULL,'Flere ejendomme, der ejes af samme ejer, som er opført kontinuerligt som en samlet bebyggelse, og som har fælles friarealer eller nogen form for driftsfællesskab, anses som én ejendom. Det samme gælder, hvor flere ejendomme er samvurderet eller samnoteret i tingbogen. Ligeledes skal flere ejerlejligheder, der henhører under samme ejerforening, og som ejes af samme udlejer, anses som én ejendom. 1.-3. pkt. gælder ved anvendelse af følgende regler:',2,2,'001.006.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id10c28721-ad04-4724-aee0-18d4108c6067\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1640,1,1639,1639,'list_item','1)',NULL,'Kapitel 3 om omkostningsbestemt leje, § 7 om huslejeregulering for mindre ejendomme i regulerede kommuner, § 62 om ulovlig opkrævning af depositum og forudbetalt leje, §§ 105-107 og 109 om iværksættelse af arbejder og § 161 om lejerens bytteret.',1,3,'001.006.002.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1641,1,1639,1639,'list_item','2)',NULL,'§ 113, § 115, stk. 2, §§ 119-123 og § 60 i lov om boligforhold om ejendommens udvendige vedligeholdelse og vedligeholdelsesplan.',2,3,'001.006.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1642,1,1639,1639,'list_item','3)',NULL,'Kapitel 5 om fri leje og kapitel 14 om forbedringsarbejder, når ejendommen er omfattet af § 6, stk. 1.',3,3,'001.006.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1643,1,1606,1606,'paragraph_group',NULL,'Fravigelighed',NULL,7,1,'001.007',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1644,1,1643,1643,'paragraph','§ 10.',NULL,'Dette kapitel kan ikke fraviges ved aftale.',1,2,'001.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id596bee31-7347-4b99-bf50-91257156d2a1\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1645,1,NULL,0,'chapter','Kapitel 2','Lejeaftalen',NULL,2,0,'002',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1646,1,1645,1645,'paragraph_group',NULL,'Lejeaftalens udformning og indhold',NULL,1,1,'002.001',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1647,1,1646,1646,'paragraph','§ 11.',NULL,'En lejeaftale og andre aftaler om det lejede skal udfærdiges skriftligt, når en af parterne kræver det.',1,2,'002.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd74370d4-8bff-4d37-b2bd-848a90264818\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1648,1,1647,1647,'subsection','Stk. 2.',NULL,'En lejeaftale anses for indgået på lovens vilkår, i det omfang der ikke udtrykkeligt er fastsat andet i aftalen.',1,3,'002.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1649,1,1647,1647,'subsection','Stk. 3.',NULL,'Er lejens størrelse ikke aftalt, anses den for at udgøre det beløb, der er rimeligt under hensyn til reglerne i kapitel 3 eller reglerne om det lejedes værdi, jf. § 42, stk. 2 og 3, eller § 43.',2,3,'002.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1650,1,1647,1647,'subsection','Stk. 4.',NULL,'Ønsker udlejeren at opkræve en leje, hvor afkastet beregnes efter § 25, stk. 2, skal det fremgå af lejeaftalen, hvornår den aftalte leje senest er fastsat efter § 23, og der skal i aftalen skønsmæssigt angives størrelsen af den leje, der maksimalt kan beregnes for lejemålet på tidspunktet for lejeaftalens indgåelse. Det skal tillige fremgå, om den aftalte leje er nedsat i henhold til § 23, stk. 2.',3,3,'002.001.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1651,1,1647,1647,'subsection','Stk. 5.',NULL,'For lejeaftaler, som er omfattet af udlejerens beslutning om regulering efter nettoprisindeks, jf. § 26, og som indgås, efter at udlejeren har truffet beslutning om en sådan regulering, skal det fremgå af lejeaftalen, at lejen reguleres efter nettoprisindeks, og det skal endvidere fremgå af lejeaftalen, hvornår den i § 26 nævnte 2-årsperiode udløber.',4,3,'002.001.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1652,1,1646,1646,'paragraph','§ 12.',NULL,'Det skal udtrykkeligt oplyses i lejeaftalen, hvis et lejemål er ombygget efter følgende regler:',2,2,'002.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"iddded99ae-ecfa-459c-9fe0-1ce1430a94d4\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1653,1,1652,1652,'list_item','1)',NULL,'Den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, og hvor lejeforhøjelse er beregnet efter samme lov.',1,3,'002.001.002.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1654,1,1652,1652,'list_item','2)',NULL,'Kapitel 5 om aftalt boligforbedring i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003, og hvor lejeforhøjelse er beregnet efter samme lov.',2,3,'002.001.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1655,1,1652,1652,'list_item','3)',NULL,'Det tidligere gældende kapitel 6 a om aftalt grøn byfornyelse i lov om byfornyelse og udvikling af byer, jf. lovbekendtgørelse nr. 144 af 21. februar 2020, og hvor lejeforhøjelse er beregnet efter § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019.',3,3,'002.001.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1656,1,1652,1652,'subsection','Stk. 2.',NULL,'Ydes der efter de nævnte love i stk. 1 tilskud til nedsættelse af lejeforhøjelsen for lejemålet, skal det udtrykkeligt oplyses i lejeaftalen, med hvilket beløb tilskud ydes for de enkelte betalingsterminer i hele tilskudsperioden.',4,3,'002.001.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1657,1,1652,1652,'subsection','Stk. 3.',NULL,'Har udlejeren helt eller delvis undladt at give de i stk. 1 og 2 omtalte oplysninger, kan der ikke opkræves lejeforhøjelse efter de særlige regler i den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, i kapitel 5 i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, eller i § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019. Er lejeforhøjelse opkrævet, uanset at oplysningerne ikke er givet, kan lejeren kræve lejeforhøjelsen tilbagebetalt. § 15, stk. 3, 2. og 3. pkt., finder tilsvarende anvendelse.',5,3,'002.001.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1658,1,1645,1645,'paragraph_group',NULL,'Digital kommunikation',NULL,2,1,'002.002',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1659,1,1658,1658,'paragraph','§ 13.',NULL,'Udlejeren eller lejeren kan med et varsel på 1 måned til den første dag i en måned, der ikke er en helligdag, forlange, at meddelelser ikke afgives som digitale dokumenter. Er lejeren eller udlejeren fritaget for Digital Post, jf. § 5 i lov om Digital Post fra offentlige afsendere, kan meddelelser dog ikke afgives som digitale dokumenter.',1,2,'002.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idcbd857a6-f281-4d34-886f-b65b65de9cab\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1660,1,1659,1659,'subsection','Stk. 2.',NULL,'Meddelelser efter § 176 og § 182, stk. 2, kan ikke afgives som digitale dokumenter.',1,3,'002.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1661,1,1645,1645,'paragraph_group',NULL,'Blanketter',NULL,3,1,'002.003',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1662,1,1661,1661,'paragraph','§ 14.',NULL,'Ved indgåelse af lejeaftale om beboelseslejligheder eller enkelte værelser til beboelse må blanketter kun anvendes, hvis de er autoriseret ved aftale mellem landsomfattende sammenslutninger af henholdsvis grundejerforeninger og lejerforeninger eller af indenrigs- og boligministeren.',1,2,'002.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id212dddd8-e6b6-4c2f-9ae9-f1d800e1bf17\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1663,1,1662,1662,'subsection','Stk. 2.',NULL,'Ved en blanket forstås en skriftlig lejeaftale, der indeholder lejevilkår, som egner sig til benyttelse over for flere lejere og fremtræder på en sådan måde, at lejeren må opfatte dem som standardiserede.',1,3,'002.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1664,1,1662,1662,'subsection','Stk. 3.',NULL,'Anvendes en blanket, der ikke er autoriseret, er bestemmelser, der pålægger lejeren større forpligtelser eller giver lejeren mindre rettigheder end angivet i loven, ugyldige.',2,3,'002.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1665,1,1662,1662,'subsection','Stk. 4.',NULL,'Indenrigs- og boligministeren fastsætter efter forhandling med landsomfattende sammenslutninger af henholdsvis grundejerforeninger og lejerforeninger nærmere regler om udarbejdelse af autoriserede standardblanketter for lejeaftaler.',3,3,'002.003.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1666,1,1645,1645,'paragraph_group',NULL,'Dusør',NULL,4,1,'002.004',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1667,1,1666,1666,'paragraph','§ 15.',NULL,'Ved udlejning til beboelse eller ved formidling eller bytning af sådanne lejeforhold er det ikke tilladt at modtage eller kræve vederlag fra lejeren eller at betinge sig, at lejeren indgår anden retshandel, som ikke er et led i lejeaftalen.',1,2,'002.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id48f6bd3d-ff92-42ec-9061-ff57b35b0cb2\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1668,1,1667,1667,'subsection','Stk. 2.',NULL,'Bestemmelsen i stk. 1 omfatter ikke vederlag for afståelse af en forretning eller vederlag for at formidle afståelsen.',1,3,'002.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1669,1,1667,1667,'subsection','Stk. 3.',NULL,'Beløb, der er betalt i strid med stk. 1, kan kræves tilbagebetalt. Beløbet forrentes fra forfaldsdagen med en årlig rente, der svarer til den rente, der er fastsat efter § 5, stk. 1 og 2, i renteloven. Når særlige forhold begrunder det, kan boligretten bestemme, at der skal betales en højere eller en lavere rente.',2,3,'002.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1670,1,1667,1667,'subsection','Stk. 4.',NULL,'Overtrædelse af stk. 1 straffes med bøde eller fængsel indtil 4 måneder, medmindre højere straf er forskyldt efter anden lovgivning.',3,3,'002.004.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1671,1,1667,1667,'subsection','Stk. 5.',NULL,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',4,3,'002.004.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1672,1,1666,1666,'paragraph','§ 16.',NULL,'Det er ikke tilladt for udlejere at tilbyde lejere betaling eller anden form for ydelse med det formål at få lejeren til at bringe lejeforholdet til ophør.',2,2,'002.004.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id2182755a-2dcc-4ae0-84de-4d5b33e581e6\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1673,1,1672,1672,'subsection','Stk. 2.',NULL,'Lejeren kan kræve lejeforhold, som bringes til ophør som følge af betaling, som er ydet i strid med stk. 1, retableret på uændrede vilkår. Retablerede lejeforhold anses for indgået på tidspunktet for indgåelsen af det ophørte lejeforhold.',1,3,'002.004.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1674,1,1672,1672,'subsection','Stk. 3.',NULL,'Betalinger ydet i strid med stk. 1 kan ikke kræves tilbagebetalt.',2,3,'002.004.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1675,1,1672,1672,'subsection','Stk. 4.',NULL,'Overtrædelse af stk. 1 straffes med bøde eller fængsel indtil 4 måneder, medmindre højere straf er forskyldt efter anden lovgivning.',3,3,'002.004.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1676,1,1672,1672,'subsection','Stk. 5.',NULL,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',4,3,'002.004.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1677,1,1645,1645,'paragraph_group',NULL,'Beskyttelse af lejerens rettigheder',NULL,5,1,'002.005',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1678,1,1677,1677,'paragraph','§ 17.',NULL,'Lejerens rettigheder efter reglerne i denne lov er gyldige mod enhver uden tinglysning. Det samme gælder aftaler om forudbetaling af leje, indskud, depositum el.lign., når disse beløb tilsammen ikke overstiger ½ års leje.',1,2,'002.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ide9ad4ced-901d-4ddb-a3eb-ac62a619dbfe\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1679,1,1678,1678,'subsection','Stk. 2.',NULL,'Ved lejeforholdets ophør skal lejerens krav efter stk. 1 dog være gjort gældende ved sagsanlæg inden 1 år fra ophørstidspunktet, såfremt det skal kunne gøres gældende mod en anden ejer end den, som ejede ejendommen, da kravet forfaldt.',1,3,'002.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1680,1,1678,1678,'subsection','Stk. 3.',NULL,'En lejer, der ved aftale har erhvervet videregående rettigheder, f.eks. aftalt uopsigelighed eller afståelsesret, kan kræve aftalen tinglyst efter tinglysningsloven.',2,3,'002.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1681,1,1645,1645,'paragraph_group',NULL,'Fravigelighed',NULL,6,1,'002.006',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1682,1,1681,1681,'paragraph','§ 18.',NULL,'Dette kapitel kan bortset fra § 17, stk. 3, ikke ved aftale fraviges til skade for lejeren.',1,2,'002.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id323056fd-41b2-4aae-871e-bd2987fbba90\"}','2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1683,1,NULL,0,'chapter','Kapitel 3','Omkostningsbestemt husleje m.v.',NULL,3,0,'003',NULL,'2026-03-30 23:41:15','2026-03-30 23:41:15'),
(1684,1,1683,1683,'paragraph_group',NULL,'Huslejefastsættelse ved lejeaftalens indgåelse',NULL,1,1,'003.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1685,1,1684,1684,'paragraph','§ 19.',NULL,'Ved lejeaftalens indgåelse må lejen ikke fastsættes til et beløb, som overstiger det beløb, der kan dække ejendommens nødvendige driftsudgifter, jf. § 24, og afkastet af ejendommens værdi, jf. § 25. For lejemål, som er forbedret, kan der til lejen efter 1. pkt. lægges en beregnet forbedringsforhøjelse, jf. dog stk. 2.',1,2,'003.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id682eec7e-a172-4bf5-b857-84616a4f4ce8\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1686,1,1685,1685,'subsection','Stk. 2.',NULL,'Ved lejeaftalens indgåelse må lejen for lejemål, som er gennemgribende forbedret, ikke fastsættes til et beløb, der overstiger det lejedes værdi efter § 42, stk. 2 og 3, jf. dog stk. 3-6, § 21, stk. 1, og § 161, stk. 3. Ved lejemål, som er forbedret gennemgribende, forstås lejemål, hvor forbedringer efter principperne i § 128 væsentligt har forøget det lejedes værdi, og hvor forbedringsudgiften enten overstiger 2.280 kr. pr. m² eller et samlet beløb på 260.738 kr. Forbedringerne skal være gennemført inden for en periode på 2 år og må ikke være omfattet af § 129, stk. 1, i den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer. Beløbene i 2. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1. Ved genudlejning er det de beløb, som var gældende ved forbedringernes gennemførelse, der finder anvendelse.',1,3,'003.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1687,1,1685,1685,'subsection','Stk. 3.',NULL,'Før et lejemål kan forbedres gennemgribende efter stk. 2, skal huslejenævnet ved besigtigelse konstatere, at lejemålet har en stand, som på tidspunktet for besigtigelsen muliggør en væsentlig forøgelse af det lejedes værdi. Huslejenævnet skal gennemføre besigtigelsen inden for 4 uger fra modtagelsen af anmodningen. Huslejenævnet skal fremsende afgørelse herom til udlejeren senest 2 uger efter besigtigelsen. Afgørelsen har gyldighed i 3 år.',2,3,'003.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1688,1,1685,1685,'subsection','Stk. 4.',NULL,'Stk. 2 finder alene anvendelse, hvis der er gået mindst 5 år siden seneste kontrolskifte vedrørende lejemålet eller den ejendom, hvori lejemålet indgår. Et kontrolskifte foreligger i følgende situationer:',3,3,'003.001.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1689,1,1685,1685,'list_item','1)',NULL,'En eller flere fysiske eller juridiske personers erhvervelse ved aftale, gave eller fuldbyrdelse af pant eller anden sikkerhed eller på anden vis af mindst 50 pct. af ejerandelen til lejemålet eller den ejendom, hvori lejemålet indgår.',4,3,'003.001.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1690,1,1685,1685,'list_item','2)',NULL,'En direkte eller indirekte overgang eller overdragelse af den bestemmende indflydelse over den eller de juridiske personer, der ejer lejemålet eller den ejendom, hvori lejemålet indgår.',5,3,'003.001.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1691,1,1685,1685,'list_item','3)',NULL,'En ændring af mindst 50 pct. af det reelle ejerskab af den eller de juridiske personer, der ejer lejemålet eller den ejendom, hvori lejemålet indgår.',6,3,'003.001.001.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1692,1,1685,1685,'list_item','4)',NULL,'En direkte eller indirekte overgang eller overdragelse af retten til mindst 50 pct. af det økonomiske afkast fra lejemålet, den ejendom, hvori lejemålet indgår, eller de juridiske personer, der direkte eller indirekte ejer lejemålet eller den ejendom, hvori lejemålet indgår.',7,3,'003.001.001.007','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1693,1,1685,1685,'list_item','5)',NULL,'En direkte eller indirekte overgang eller overdragelse af retten til mindst 50 pct. af en værdistigning af lejemålet, den ejendom, hvori lejemålet indgår, eller de juridiske personer, der direkte eller indirekte ejer lejemålet eller den ejendom, hvori lejemålet indgår.',8,3,'003.001.001.008','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1694,1,1685,1685,'list_item','6)',NULL,'Indgåelse eller overdragelse af en eller flere aftaler om, at en eller flere parter har ret til at få gennemført en overdragelse eller overgang, som ville udgøre et kontrolskifte efter nr. 1-5, hvis den eller disse aftaler blev gennemført enten alene eller i forening med en allerede gennemført disposition.',9,3,'003.001.001.009','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1695,1,1685,1685,'list_item','7)',NULL,'Indgåelse eller overdragelse af en betinget aftale om udskudt direkte eller indirekte overdragelse af lejemålet eller den ejendom, hvori lejemålet indgår, hvis en gennemførelse af den betingede aftale vil indebære kontrolskifte efter nr. 1-6.',10,3,'003.001.001.010','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1696,1,1685,1685,'list_item','8)',NULL,'Foretagelse af en eller flere dispositioner, som ikke er omfattet af nr. 1-7, men hvorved der opnås en tilsvarende virkning.',11,3,'003.001.001.011','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1697,1,1685,1685,'subsection','Stk. 5.',NULL,'Følgende situationer er ikke omfattet af stk. 4:',12,3,'003.001.001.012','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1698,1,1685,1685,'list_item','1)',NULL,'Udlejning og genudlejning af lejemål, der inden den 1. juli 2020 opfyldte betingelserne for at kunne udlejes efter § 5, stk. 2, i den tidligere gældende lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, eller både opfylder betingelserne for at kunne udlejes efter stk. 2 og er genudlejet efterfølgende, når den første genudlejning ikke er foretaget i en 5-årsperiode efter et kontrolskifte, jf. stk. 4, som endnu ikke er udløbet.',13,3,'003.001.001.013','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1699,1,1685,1685,'list_item','2)',NULL,'Kontrolskifte, der sker ved arv efter arveloven eller hensidden i uskiftet bo efter arvelovens § 26 eller i begge tilfælde tilsvarende udenlandske regler. Arveforskud omfattes uanset 1. pkt. af stk. 4.',14,3,'003.001.001.014','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1700,1,1685,1685,'list_item','3)',NULL,'Kontrolskifte, der sker ved gennemførelsen af en eller flere koncerninterne transaktioner.',15,3,'003.001.001.015','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1701,1,1685,1685,'list_item','4)',NULL,'Kontrolskifte, der sker ved omdannelsen af en andelsboligforenings, et boligaktieselskabs eller et boliganpartsselskabs ejendom til en udlejningsejendom og alle senere videresalg, når andelsboligforeningen, boligaktieselskabet eller boliganpartsselskabet er stiftet før den 1. juli 2020.',16,3,'003.001.001.016','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1702,1,1685,1685,'list_item','5)',NULL,'Kontrolskifte, der sker vedrørende boliger, der er beliggende i en ejendom, hvor ejeren eller en tidligere ejer inden for en periode på 2 år har foretaget og afholdt udgifter til energiforbedringer eksklusive vedligeholdelse, jf. § 128, vedrørende den del af ejendommen, der anvendes til beboelse, svarende til mindst 3.012 kr. pr. m2 bruttoetageareal for denne del af ejendommen. Forbedringerne efter 1. pkt. må ikke være omfattet af lov om byfornyelse og udvikling af byer bortset fra det tidligere gældende kapitel 6 a, jf. lovbekendtgørelse nr. 144 af 21. februar 2020. Investeringskravet i 1. pkt. skal være opfyldt på tidspunktet for udlejning efter stk. 2. Beløb, som anvendes til opfyldelse af 1. pkt., kan ikke indgå ved opgørelsen af beløbskravet efter stk. 2. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',17,3,'003.001.001.017','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1703,1,1685,1685,'list_item','6)',NULL,'Kontrolskifte, der sker vedrørende boliger, der er beliggende i en ejendom, hvor ejeren eller en tidligere ejer har udført energiforbedringer i et omfang, som indebærer, at ejendommen har opnået en indplacering på energimærkningsskalaen, der ligger tre niveauer over den indplacering, som var gældende fra den 1. juli 2020. § 9 finder ikke anvendelse.',18,3,'003.001.001.018','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1704,1,1685,1685,'subsection','Stk. 6.',NULL,'Stk. 2 finder alene anvendelse for lejemål i ejendomme, der på udlejningstidspunktet har opnået en indplacering på niveau A-C på energimærkningsskalaen efter lov om fremme af energibesparelser i bygninger, og for lejemål i ejendomme, hvor ejeren har udført energiforbedringer i et omfang, som indebærer, at ejendommen har opnået en indplacering på energimærkningsskalaen, der ligger to niveauer over den indplacering, som var gældende den 1. juli 2020. Kravet i 1. pkt. skal være opfyldt på tidspunktet for udlejning efter stk. 2. Uanset 1. pkt. finder stk. 2 anvendelse på lejemål i ejendomme, der er fredet efter lov om bygningsfredning og bevaring af bygninger og bymiljøer.',19,3,'003.001.001.019','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1705,1,1684,1684,'paragraph','§ 20.',NULL,'Ved tvister om lejefastsættelse efter § 19, stk. 2, skal udlejeren fremlægge dokumentation for forbedringsudgiften og for, at forbedringerne er gennemført inden for en periode på 2 år. Kan sådan dokumentation ikke fremlægges, kan § 19, stk. 2, alene finde anvendelse, såfremt det utvivlsomt må anses for godtgjort, at forbedringer er udført i tilstrækkeligt omfang og inden for en periode på 2 år. Ved indbringelse for boligretten påhviler det udlejeren at godtgøre, at den aftalte leje ikke overstiger det lejedes værdi.',2,2,'003.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idde06ba81-3316-453c-b161-0ee119104cd6\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1706,1,1705,1705,'subsection','Stk. 2.',NULL,'Ved sammenligningen, jf. § 42, stk. 2 og 3, ses der bort fra følgende:',1,3,'003.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1707,1,1705,1705,'list_item','1)',NULL,'Lejemål, der er forbedret efter § 129, stk. 1, og § 137.',2,3,'003.001.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1708,1,1705,1705,'list_item','2)',NULL,'Lejemål omfattet af kapitel 5.',3,3,'003.001.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1709,1,1705,1705,'list_item','3)',NULL,'Lejemål omfattet af den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',4,3,'003.001.002.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1710,1,1705,1705,'subsection','Stk. 3.',NULL,'Ved vurderingen af lejen og det lejedes værdi ses der bort fra følgende:',5,3,'003.001.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1711,1,1705,1705,'list_item','1)',NULL,'Lejeforhøjelse til afsættelse efter § 120 og forbedringer, der er gennemført for beløb, der er afsat efter denne bestemmelse.',6,3,'003.001.002.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1712,1,1705,1705,'list_item','2)',NULL,'Lejeforhøjelse efter § 129, stk. 1 og 2, og § 137 og § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og forbedringer efter § 129, stk. 1, og §§ 137 og 146 og det tidligere gældende kapitel 6 a i lov om byfornyelse og udvikling af byer, jf. lovbekendtgørelse nr. 144 af 21. februar 2020.',7,3,'003.001.002.007','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1713,1,1705,1705,'list_item','3)',NULL,'Lejeforhøjelser og forbedringer efter den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',8,3,'003.001.002.008','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1714,1,1684,1684,'paragraph','§ 21.',NULL,'Vil udlejeren indgå en lejeaftale i henhold til § 19, stk. 2, og er det den første udlejning af det pågældende lejemål efter § 19, stk. 2, skal udlejeren, når lejeforholdet er opsagt eller ophævet, og inden en ny lejeaftale indgås, orientere beboerrepræsentanterne eller lejerne om dette og om indholdet af denne bestemmelse. I modsat fald er vilkåret om lejefastsættelse efter § 19, stk. 2, ugyldigt. Beboerrepræsentanterne eller lejeren kan da, inden 14 dage efter at orienteringen er givet, indbringe en sag om manglende vedligeholdelse for huslejenævnet, jf. § 114. Beboerrepræsentanterne eller lejeren skal angive vedligeholdelsesmanglerne, der alene kan vedrøre mangler uden for de enkelte lejemål. Afgiver huslejenævnet påbud om udbedring af vedligeholdelsesmangler, jf. § 114, stk. 2, kan der ikke opkræves husleje efter § 19, stk. 2, før de konstaterede vedligeholdelsesmangler er udbedret.',3,2,'003.001.003','{\"source_class\":\"Paragraf\",\"source_id\":\"idfddfea08-49f2-40fc-9ce7-30b3961cf523\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1715,1,1714,1714,'subsection','Stk. 2.',NULL,'Det påhviler udlejeren at opretholde den gennemgribende forbedring af lejemålet. Såfremt der opstår tvist herom, kan lejeren indbringe spørgsmålet for huslejenævnet, dog tidligst 5 år efter at en sådan sag senest har været forelagt huslejenævnet af denne lejer. Anses udlejeren for ikke at have opfyldt sin pligt til at opretholde den gennemgribende forbedring, skal lejen for fremtiden beregnes efter § 19, stk. 1.',1,3,'003.001.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1716,1,1684,1684,'paragraph','§ 22.',NULL,'Ved lejeaftalens indgåelse kan der ikke aftales en leje eller lejevilkår, der efter en samlet bedømmelse er mere byrdefulde for lejeren end de vilkår, der gælder for andre lejere i ejendommen.',4,2,'003.001.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id6ac397b8-7d65-4dbb-8a39-f4385ece2412\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1717,1,1716,1716,'subsection','Stk. 2.',NULL,'Reglen i stk. 1 er dog ikke til hinder for, at der i lejemål, som er forbedret, uden at der samtidig er gennemført en til forbedringen svarende lejeforhøjelse, ved genudlejning kan aftales en leje efter reglerne i §§ 19-21.',1,3,'003.001.004.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1718,1,1684,1684,'paragraph','§ 23.',NULL,'Hvis lejen ikke kan dække ejendommens nødvendige driftsudgifter, jf. § 24, og afkast af ejendommens værdi, jf. § 25, kan udlejeren forlange lejeforhøjelse til udligning af forskellen.',5,2,'003.001.005','{\"source_class\":\"Paragraf\",\"source_id\":\"idf0b72a4a-06a9-4646-9bde-fa61e5706c28\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1719,1,1718,1718,'subsection','Stk. 2.',NULL,'Lejeforhøjelse kan ikke kræves, hvis lejen efter lejeforhøjelsen vil overstige det lejedes værdi efter § 42, stk. 2 og 3. Ved vurderingen af lejen og det lejedes værdi finder § 20, stk. 3, tilsvarende anvendelse. 1. pkt. gælder ikke for ejendomme, hvis opførelse er finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån, og ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af den tidligere gældende lov om realrenteafgift, såfremt beregning af afkast sker efter § 25, stk. 4.',1,3,'003.001.005.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1720,1,1718,1718,'subsection','Stk. 3.',NULL,'Lejeforhøjelse efter stk. 1 har, medmindre parterne træffer anden aftale, virkning fra den 1. i den måned, der indtræder 3 måneder efter kravets fremsættelse.',2,3,'003.001.005.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1721,1,1718,1718,'subsection','Stk. 4.',NULL,'Vil et krav om lejeforhøjelse efter stk. 1 eller efter § 46, hvor afkastet er beregnet efter § 25, stk. 2, medføre en lejeforhøjelse, der sammen med lejeforhøjelser, jf. stk. 1-3, inden for de sidste 3 år overstiger 96 kr. pr. m2 bruttoetageareal, skal udlejeren senest samtidig med varslingen om lejeforhøjelse underrette lejeren om, at denne kan forlange at få tilbudt en anden passende bolig. § 106, stk. 2-4, finder tilsvarende anvendelse. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',3,3,'003.001.005.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1722,1,1718,1718,'subsection','Stk. 5.',NULL,'Har udlejeren helt eller delvis undladt at give de i § 11, stk. 4, omtalte oplysninger i forbindelse med indgåelsen af en lejeaftale, kan den gældende leje alene forhøjes på grundlag af stigninger i ejendommens driftsudgifter siden lejeaftalens indgåelse. Er lejeforhøjelse opkrævet for et beløb, der ligger ud over det i 1. pkt. tilladte, kan lejeren kræve det for meget betalte beløb tilbagebetalt. § 40 finder tilsvarende anvendelse.',4,3,'003.001.005.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1723,1,1683,1683,'paragraph_group',NULL,'Driftsudgifter i det omkostningsbestemte huslejebudget',NULL,2,1,'003.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1724,1,1723,1723,'paragraph','§ 24.',NULL,'De nødvendige driftsudgifter omfatter udgifter til skatter, afgifter, renholdelse, administration og forsikring i det omfang, det er rimeligt under hensyn til ejendommens og det lejedes karakter. De nødvendige driftsudgifter omfatter endvidere de beløb, der afsættes til vedligeholdelse m.v. efter §§ 117, 119 og 120, jf. dog § 113, stk. 2.',1,2,'003.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd65a55d1-487c-47c9-9787-dd5b856d2ff7\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1725,1,1724,1724,'subsection','Stk. 2.',NULL,'Udgifter til konsulentbistand som omfattet af § 47, stk. 3, optages ikke på budgettet.',1,3,'003.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1726,1,1724,1724,'subsection','Stk. 3.',NULL,'Beboerrepræsentanterne kan indhente tilbud på renholdelse, forsikringer og udfærdigelse af varme- og vandregnskaber og forelægge disse for udlejeren. Såfremt udlejeren afviser at antage et forelagt tilbud efter 1. pkt., kan beboerrepræsentanterne indbringe sagen for huslejenævnet, der kan pålægge udlejeren at antage et af beboerrepræsentanterne indhentet tilbud, såfremt huslejenævnet vurderer, at tilbuddet med hensyn til pris og kvalitet er bedre end det af udlejeren antagne.',2,3,'003.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1727,1,1724,1724,'subsection','Stk. 4.',NULL,'Stk. 3 gælder ikke for ejendomme, der er opdelt i ejerlejligheder.',3,3,'003.002.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1728,1,1724,1724,'subsection','Stk. 5.',NULL,'I fredede ejendomme, hvorpå der er tinglyst en særlig bevaringsdeklaration i henhold til lovgivningen om bygningsfredning, kan et beløb svarende til den ejendomsskat, der til enhver tid kunne have været opkrævet, optages som driftsudgift, uanset om ejendommen er fritaget for ejendomsbeskatning.',4,3,'003.002.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1729,1,1683,1683,'paragraph_group',NULL,'Afkast i det omkostningsbestemte lejebudget',NULL,3,1,'003.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1730,1,1729,1729,'paragraph','§ 25.',NULL,'Til afkast af ejendommens værdi afsættes på budgettet et beløb, der ikke må overstige 7 pct. af den ejendomsværdi, der er fastsat pr. 1. april 1973 ved 15. almindelige vurdering af landets faste ejendomme.',1,2,'003.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id9664d155-1339-4729-b793-bbf9fec9b40b\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1731,1,1730,1730,'subsection','Stk. 2.',NULL,'I stedet for et afkast efter reglen i stk. 1 kan udlejeren i ejendomme, der tages i brug efter 1963, som afkast beregne et beløb, der ikke må overstige rimelige ydelser på sædvanlige langfristede prioritetslån, der er optaget til finansiering af ejendommens opførelse, med tillæg af en passende forrentning af den resterende del af den rimelige anskaffelsessum med fradrag af lejerindskud. Som passende forrentning anses:',1,3,'003.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1732,1,1730,1730,'list_item','1)',NULL,'8 pct. for ejendomme med ibrugtagelse i 1964.',2,3,'003.003.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1733,1,1730,1730,'list_item','2)',NULL,'10 pct. for ejendomme med ibrugtagelse i 1965-69.',3,3,'003.003.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1734,1,1730,1730,'list_item','3)',NULL,'12 pct. for ejendomme med ibrugtagelse i 1970-73.',4,3,'003.003.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1735,1,1730,1730,'list_item','4)',NULL,'14 pct. for ejendomme med ibrugtagelse efter 1973.',5,3,'003.003.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1736,1,1730,1730,'subsection','Stk. 3.',NULL,'I stedet for afkast efter stk. 1 og 2 kan udlejeren for ejendomme finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån som afkast beregne den rente, udlejeren løbende betaler på indekslån optaget til finansiering af ejendommens opførelse, med tillæg af 4 pct. af den indekserede hovedstol. Udlejeren kan endvidere beregne en forrentning på 4 pct. af den resterende anskaffelsessum efter fradrag af lejerindskud. Det beløb, der er beregnet efter 2. pkt., reguleres med samme procentsats, hvormed hovedstolen på indekslånet reguleres.',6,3,'003.003.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1737,1,1730,1730,'subsection','Stk. 4.',NULL,'For ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af lov om realrenteafgift, kan beregnes samme beløb i afkast som beregnet efter stk. 3 for en tilsvarende ejendom finansieret med størst muligt indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån.',7,3,'003.003.001.007','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1738,1,1730,1730,'subsection','Stk. 5.',NULL,'Er der i perioden fra den 1. januar 1964 til den 1. april 1973 gennemført lejeforhøjelser for forbedringer, kan afkastet beregnes med indtil 7 pct. af ejendomsværdien ved den seneste almindelige vurdering forud for forbedringens gennemførelse med tillæg af et afkast af den rimelige forbedringsudgift beregnet efter reglerne i stk. 2, således at tidspunktet for forbedringens ibrugtagelse er afgørende for forrentningsprocentens størrelse.',8,3,'003.003.001.008','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1739,1,1730,1730,'subsection','Stk. 6.',NULL,'Såfremt ejendommen er opdelt i ejerlejligheder efter 15. almindelige vurdering, beregnes afkastet på grundlag af en forholdsmæssig andel af ejendomsværdien ved 15. almindelige vurdering.',9,3,'003.003.001.009','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1740,1,1730,1730,'subsection','Stk. 7.',NULL,'Til det beregnede afkast kan udlejeren lægge det beløb, som henlagdes eller kunne være henlagt pr. kvadratmeter bruttoetageareal ved udgangen af 2014, jf. § 9, stk. 7, i den tidligere gældende lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 962 af 14. august 2010. Beløbet i 1. pkt. reguleres efter reglerne i § 204, stk. 1.',10,3,'003.003.001.010','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1741,1,1683,1683,'paragraph_group',NULL,'Lejeregulering efter nettoprisindeks',NULL,4,1,'003.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1742,1,1741,1741,'paragraph','§ 26.',NULL,'Udlejeren kan i stedet for regulering efter § 23 beslutte, at lejen i perioder på 2 år ad gangen reguleres én gang årligt efter udviklingen i Danmarks Statistiks nettoprisindeks i en 12-månedersperiode sluttende i juni måned året før det finansår, reguleringen vedrører. Beløbet afrundes til nærmeste hele kronebeløb. Regulering efter nettoprisindeks kan kun ske for den del af lejen, som vedrører de i § 24, stk. 1, nævnte nødvendige driftsudgifter bortset fra skatter og afgifter. Regulering efter nettoprisindeks omfatter alle lejemål i ejendommen bortset fra de lejemål, hvor der er aftalt en regulering af lejen efter kapitel 5. Ved 2-årsperiodens udløb skal udlejeren beregne lejen efter § 23. Beregningen skal sammen med oplysning om, at beregningen kan indbringes for huslejenævnet, være kommet frem til lejerne inden 2-årsperiodens udløb. Hvis lejen ved 2-årsperiodens udløb overstiger den leje, som beregnes efter § 23, skal udlejeren med virkning fra tidspunktet for 2-årsperiodens udløb nedsætte lejen til den nu beregnede leje.',1,2,'003.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ideee9ff39-d1ac-4d8e-a470-bde7d416daaf\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1743,1,1742,1742,'subsection','Stk. 2.',NULL,'Beslutning om regulering af lejen efter nettoprisindeks kan gennemføres alene ved udlejerens skriftlige meddelelse herom til lejerne og er bindende for udlejeren i en periode på 2 år fra det tidspunkt, hvor udlejeren har afsendt meddelelse herom til lejerne. Lejeregulering efter stk. 1 kan tidligst få virkning, 12 måneder efter at lejen er beregnet og fastsat efter § 23.',1,3,'003.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1744,1,1742,1742,'subsection','Stk. 3.',NULL,'Krav om lejeforhøjelse som følge af regulering efter nettoprisindeks efter stk. 1 skal være skriftligt og indeholde en angivelse af lejeforhøjelsens størrelse og dens beregning. Lejeforhøjelsen har virkning fra den 1. i den måned, der indtræder 3 måneder efter kravets fremsættelse.',2,3,'003.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1745,1,1742,1742,'subsection','Stk. 4.',NULL,'Har udlejeren reguleret lejen efter nettoprisindeks, kan lejeforhøjelse opgjort efter § 23 tidligst få virkning, 12 måneder efter at der senest er trådt en lejeforhøjelse som følge af regulering af lejen efter nettoprisindeks i kraft og efter udløbet af den i stk. 2 nævnte 2-årsperiode.',3,3,'003.004.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1746,1,1683,1683,'paragraph_group',NULL,'Fordeling af lejeforhøjelse på lejlighederne',NULL,5,1,'003.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1747,1,1746,1746,'paragraph','§ 27.',NULL,'Lejeforhøjelsen fordeles på lejlighederne efter deres indbyrdes brugsværdi. Har lejligheder samme indbyrdes brugsværdi, skal lejeforhøjelsen forlods pålægges lejligheder, hvis leje er lavest. De beløb, der afsættes til vedligeholdelse efter §§ 117, 119 og 120, fordeles dog efter lejlighedernes bruttoetageareal. For ejendomme med lejligheder, hvor afsættelse sker med forskellige beløb pr. kvadratmeter bruttoetageareal, sker fordelingen efter de enkelte lejligheders faktiske beløb pr. kvadratmeter bruttoetageareal.',1,2,'003.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idbff262e0-a516-45f9-9569-9d393ec9f19d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1748,1,1747,1747,'subsection','Stk. 2.',NULL,'Ved bedømmelsen af lejlighedernes indbyrdes brugsværdi ses bort fra forbedringer, som er bekostet af lejeren.',1,3,'003.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1749,1,1747,1747,'subsection','Stk. 3.',NULL,'Er lejen for en lejlighed forhøjet på grundlag af forbedring eller øget brugsværdi, der ikke modsvares af udgifter på budgettet, og er forhøjelsen sket efter den ejendomsvurdering, hvoraf afkastprocenten beregnes, ses der ved budgetteringen og ved bedømmelsen af lejlighedernes indbyrdes brugsværdi bort fra denne lejeforhøjelse.',2,3,'003.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1750,1,1683,1683,'paragraph_group',NULL,'Fordeling af budgetudgifter i blandede ejendomme',NULL,6,1,'003.006',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1751,1,1750,1750,'paragraph','§ 28.',NULL,'For rum, der benyttes af udlejeren, eller som er udlejet uden at være omfattet af reglerne i dette kapitel, og for de i stk. 3 omhandlede enkeltværelser skal der på budgettet optages en lejeværdi, der svarer til de pågældende rums andel af ejendommens nødvendige driftsudgifter og afkast. Fordelingen sker efter bruttoetageareal.',1,2,'003.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2e3e79b3-e4dd-481e-b9dd-36a559b75811\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1752,1,1751,1751,'subsection','Stk. 2.',NULL,'For ejendomme, hvor der for beboelseslejligheder til vedligeholdelse efter §§ 117, 119 og 120 afsættes forskellige beløb pr. kvadratmeter bruttoetageareal for de enkelte beboelseslejligheder, sker fordelingen af afsætningsbeløbene efter disse lejligheders faktiske beløb pr. kvadratmeter bruttoetageareal.',1,3,'003.006.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1753,1,1751,1751,'subsection','Stk. 3.',NULL,'Lejen for enkeltværelser til beboelse, som er omfattet af dette kapitel, jf. § 6, stk. 3, fastsættes efter bruttoetagearealet som en forholdsmæssig andel af den lejeværdi, der er optaget på lejebudgettet for de i stk. 1, 1. pkt., omhandlede lejemål.',2,3,'003.006.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1754,1,1683,1683,'paragraph_group',NULL,'Varsling af lejeforhøjelse',NULL,7,1,'003.007',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1755,1,1754,1754,'paragraph','§ 29.',NULL,'I ejendomme uden beboerrepræsentation skal krav om lejeforhøjelse efter § 23 fremsættes samtidig over for de lejere, hvis leje ønskes forhøjet. Kravet skal være skriftligt. Det skal indeholde oplysning om det gældende budget og det nye budget, herunder driftsudgifter og -indtægter, om lejeforhøjelsens størrelse og dens beregning og om den fremtidige lejes størrelse. Kravet skal indeholde oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 2. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',1,2,'003.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"iddac2b4ab-a74b-4685-ac56-f68ac08b4d1d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1756,1,1755,1755,'subsection','Stk. 2.',NULL,'Har mindst en fjerdedel af de lejere, hvis leje ønskes forhøjet, senest 6 uger efter at kravet om lejeforhøjelse er kommet frem, skriftligt fremsat indsigelse mod lejeforhøjelsen, skal udlejeren inden yderligere 6 uger forelægge sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om lejeforhøjelse.',1,3,'003.007.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1757,1,1754,1754,'paragraph','§ 30.',NULL,'I ejendomme med beboerrepræsentation skal krav om lejeforhøjelse efter § 23 fremsættes samtidig over for de lejere, hvis leje ønskes forhøjet. Kravet skal være skriftligt. Det skal indeholde oplysning om det gældende budget og det nye budget, herunder driftsudgifter og -indtægter, om lejeforhøjelsens størrelse og dens beregning og om den fremtidige lejes størrelse. Kravet skal tillige indeholde oplysning om, at skrivelsen er forelagt for beboerrepræsentanterne, og om deres eventuelle udtalelser. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',2,2,'003.007.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id5c7069fb-02a0-4ddb-97a9-6b1d2b778516\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1758,1,1757,1757,'subsection','Stk. 2.',NULL,'Senest 7 dage før kravet efter stk. 1 skal udlejeren varsle beboerrepræsentanterne om lejeforhøjelsen. Varslingen skal indeholde kopi af skrivelsen til lejerne, oplysning om det gældende budget og det nye budget og fornøden redegørelse for budgetposterne, herunder om ændringer i de enkelte beløbs størrelse. Modtager beboerrepræsentanterne ikke disse oplysninger, er varslingen efter stk. 1 ugyldig.',1,3,'003.007.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1759,1,1757,1757,'subsection','Stk. 3.',NULL,'Beboerrepræsentanterne kan inden 3 uger efter modtagelsen af varslingen efter stk. 2 fremsætte skriftligt krav om, at udlejeren inden yderligere 3 uger til beboerrepræsentationen fremsender en skriftlig redegørelse om nærmere angivne supplerende oplysninger sammen med dokumentation for bestemte udgifter i budgettet. Beboerrepræsentanterne skal endvidere have oplysning om deres adgang til at gøre indsigelse, jf. stk. 4. Modtager beboerrepræsentanterne ikke disse oplysninger, er kravet om lejeforhøjelse ugyldigt.',2,3,'003.007.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1760,1,1757,1757,'subsection','Stk. 4.',NULL,'Såfremt beboerrepræsentanterne, senest 6 uger efter at udlejerens varsling efter stk. 2 eller yderligere oplysninger efter stk. 3 er kommet frem, skriftligt har meddelt, at de ikke kan tiltræde lejeforhøjelsen, skal udlejeren inden yderligere 6 uger forelægge sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om lejeforhøjelse.',3,3,'003.007.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1761,1,1757,1757,'subsection','Stk. 5.',NULL,'Såfremt udlejeren ikke rettidigt har modtaget meddelelse fra beboerrepræsentanterne som nævnt i stk. 4 eller beboerrepræsentanterne har tiltrådt lejeforhøjelsen, kan udlejeren oppebære den varslede lejeforhøjelse, når denne har meddelt lejerne dette med tilkendegivelse af, at den enkelte lejer kan indbringe spørgsmålet om lejeforhøjelsens rimelighed for huslejenævnet efter § 38.',4,3,'003.007.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1762,1,1757,1757,'subsection','Stk. 6.',NULL,'Meddelelse efter stk. 5 kan gives i skrivelsen efter stk. 1, hvis den udsendes, efter at beboerrepræsentanterne har svaret eller deres svarfrist er udløbet.',5,3,'003.007.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1763,1,1683,1683,'paragraph_group',NULL,'Lejeforhøjelse ved forhøjet afsættelse til vedligeholdelse',NULL,8,1,'003.008',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1764,1,1763,1763,'paragraph','§ 31.',NULL,'Krav om lejeforhøjelse, der udelukkende skyldes afsættelse af de i §§ 117, 119 og 120 nævnte afsættelsesbeløb, kan uanset bestemmelserne i §§ 29 og 30 gennemføres alene ved udlejerens skriftlige meddelelse herom til lejerne.',1,2,'003.008.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id81fc6ed5-00c4-4d11-a35b-199b4b338785\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1765,1,1683,1683,'paragraph_group',NULL,'Huslejeregulering for mindre ejendomme',NULL,9,1,'003.009',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1766,1,1765,1765,'paragraph','§ 32.',NULL,'Reglerne i kapitel 4 og 5 finder anvendelse for ejendomme omfattet af § 7. Lejen i disse ejendomme kan dog ikke væsentligt overstige den leje, der betales for tilsvarende lejeforhold med hensyn til beliggenhed, art, størrelse, kvalitet, udstyr og vedligeholdelsestilstand omfattet af § 6, stk. 1, og hvor lejen er reguleret efter § 23. Ved afgørelse efter 2. pkt. skal der for lejeforhold i ejendomme med lokaler, som anvendes til andet end beboelse, ske sammenligning med lejen for lejeforhold i tilsvarende ejendomme. Såfremt der ikke findes sammenlignelige lejemål, hvor lejen er reguleret efter § 23, eller såfremt lejens størrelse for sammenlignelige lejemål må anses for at være atypisk, kan huslejenævnet i henhold til § 83 i lov om boligforhold indhente oplysninger om ejendommens driftsudgifter m.v. og på grundlag af disse oplysninger ansætte den leje, som ville kunne opkræves, hvis lejen skulle beregnes efter § 23. 2.-4. pkt. gælder dog ikke for lejeforhold omfattet af § 54, stk. 1.',1,2,'003.009.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idc55cd32a-be04-424d-b67e-9d6a802413e1\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1767,1,1683,1683,'paragraph_group',NULL,'Huslejeregulering og opsigelsesbeskyttelse for enkeltværelser',NULL,10,1,'003.010',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1768,1,1767,1767,'paragraph','§ 33.',NULL,'Reglerne i §§ 34-36 gælder for udlejning af de værelser, der er omfattet af § 6, stk. 3.',1,2,'003.010.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id5b91c150-8a72-41f9-a0f6-a22201384fe8\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1769,1,1767,1767,'paragraph','§ 34.',NULL,'Finder lejeren, at lejen eller andre vilkår er urimelige, kan lejeren indbringe spørgsmålet for huslejenævnet, der kan ændre lejen efter § 45 og lejevilkårene.',2,2,'003.010.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id3b644241-3732-49a4-9abd-d3780c9bb3a0\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1770,1,1769,1769,'subsection','Stk. 2.',NULL,'Nedsættes lejen eller ændres lejevilkårene af huslejenævnet, kan dette bestemme, at lejeforholdet ikke kan opsiges uden nævnets godkendelse.',1,3,'003.010.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1771,1,1767,1767,'paragraph','§ 35.',NULL,'Skønnes en opsigelse fra udlejerens side foranlediget af eller at stå i forbindelse med forsøg på at opnå en urimelig leje eller andre urimelige lejevilkår, kan huslejenævnet underkende opsigelsens gyldighed og bestemme, at lejeforholdet kun kan opsiges med nævnets godkendelse. Det samme gælder, hvis en opsigelse som følge af andre særlige omstændigheder i forbindelse med dens afgivelse skønnes stridende mod sædvanlig god udlejningsskik, således at den må anses for urimelig.',3,2,'003.010.003','{\"source_class\":\"Paragraf\",\"source_id\":\"idadf3dc58-bfdd-4acc-8eb1-aaddd70b15ee\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1772,1,1767,1767,'paragraph','§ 36.',NULL,'Er en sag rejst for huslejenævnet, kan dette, når omstændighederne taler derfor, bestemme, at lejeforholdet ikke uden nævnets godkendelse kan opsiges, inden nævnets afgørelse i sagen er truffet.',4,2,'003.010.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id54a2f6e9-6e0e-4647-aa06-bb2157cbb749\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1773,1,1683,1683,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,11,1,'003.011',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1774,1,1773,1773,'paragraph','§ 37.',NULL,'Indbringes krav om lejeforhøjelse efter § 29, stk. 2, eller efter § 30, stk. 4, for huslejenævnet, kan nævnet tilsidesætte kravet helt eller delvis, dersom betingelserne for forhøjelsens gennemførelse ikke er til stede.',1,2,'003.011.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf4c4f6ff-4988-4acc-8610-7631c44eb4a7\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1775,1,1774,1774,'subsection','Stk. 2.',NULL,'Nævnet kan dog, såfremt det konstateres, at kravet om lejeforhøjelse på grund af formelle mangler af mindre betydning er ugyldigt, jf. § 29, stk. 1, og § 30, stk. 1 og 3, i stedet for at tilsidesætte kravet på dette grundlag fastsætte en frist for udlejeren til at berigtige de konstaterede formelle mangler. Berigtiges manglerne inden den angivne frist, bevarer kravet om lejeforhøjelse sin gyldighed.',1,3,'003.011.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1776,1,1774,1774,'subsection','Stk. 3.',NULL,'Indtil nævnets afgørelse foreligger, kan udlejeren oppebære den varslede lejeforhøjelse som en foreløbig lejeforhøjelse, der dog ikke må overstige 15 kr. pr. m² bruttoetageareal om året. Lejen skal reguleres i overensstemmelse med nævnets afgørelse. Regulering af depositum og forudbetalt leje kan ikke forlanges, før kravet om lejeforhøjelse er afgjort af nævnet.',2,3,'003.011.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1777,1,1773,1773,'paragraph','§ 38.',NULL,'På lejerens begæring skal huslejenævnet, medmindre nævnet har truffet afgørelse efter § 37, stk. 1, afgøre, om udlejeren har krævet højere leje eller betinget sig andre vilkår end tilladt efter bestemmelserne i dette kapitel.',2,2,'003.011.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id76b9a030-1f74-4149-bb15-b86642bb7034\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1778,1,1777,1777,'subsection','Stk. 2.',NULL,'§ 37, stk. 2, finder tilsvarende anvendelse.',1,3,'003.011.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1779,1,1777,1777,'subsection','Stk. 3.',NULL,'I ejendomme med beboerrepræsentation afgør huslejenævnet på beboerrepræsentanternes begæring på vegne af samtlige lejere uenighed om acontobidrag til varme og lign., om acontobidrag til vand, om acontobidrag til køling efter kapitel 7, om udlejerens ret til at modsætte sig installation af vandmålere og kølingsmålere efter § 67, stk. 3, og § 68, stk. 2, om lejerens ret efter § 142, stk. 2, om, hvorvidt en aftale i henhold til § 138 er åbenbart urimelig, og om lejeforhøjelser varslet efter §§ 26 eller 31.',2,3,'003.011.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1780,1,1683,1683,'paragraph_group',NULL,'Straf',NULL,12,1,'003.012',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1781,1,1780,1780,'paragraph','§ 39.',NULL,'Med bøde eller fængsel indtil 4 måneder straffes den, som afkræver en lejer højere leje end tilladt efter reglerne i §§ 19-21. På samme måde straffes den udlejer, som aftaler leje og lejevilkår, der er mere byrdefulde for lejeren end tilladt efter bestemmelserne i §§ 19-22.',1,2,'003.012.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2ed47ff5-5f65-4433-89c4-1d2703b8a971\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1782,1,1781,1781,'subsection','Stk. 2.',NULL,'Med bøde straffes den, som opkræver højere leje end tilladt af huslejenævnet efter reglen i § 34, stk. 1, eller som i strid med § 35 opsiger lejeforholdet uden nævnets samtykke.',1,3,'003.012.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1783,1,1781,1781,'subsection','Stk. 3.',NULL,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',2,3,'003.012.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1784,1,1683,1683,'paragraph_group',NULL,'Tilbagebetaling af for meget betalt husleje m.v.',NULL,13,1,'003.013',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1785,1,1784,1784,'paragraph','§ 40.',NULL,'Har udlejeren opkrævet højere leje, depositum, indskud el.lign. end tilladt, kan lejeren kræve det for meget betalte beløb tilbage, ligesom lejeren vil kunne kræve lejen nedsat med virkning for fremtiden. Ved lejeforholdets ophør skal lejerens krav være gjort gældende for huslejenævnet inden 1 år fra fraflytningstidspunktet.',1,2,'003.013.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id913c70eb-dd8f-4664-b9da-60d840ae271d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1786,1,1785,1785,'subsection','Stk. 2.',NULL,'Lejeren kan uanset stk. 1 ikke kræve tilbagebetaling af for meget betalt leje med den begrundelse, at lejen overstiger det lejedes værdi, medmindre krav om nedsættelse af lejen er fremsat for huslejenævnet inden 1 år efter det tidspunkt, lejen eller den forhøjede leje første gang skal betales.',1,3,'003.013.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1787,1,1785,1785,'subsection','Stk. 3.',NULL,'Tilbagebetalingskrav forrentes fra betalingstidspunktet med en årlig rente, der svarer til den rente, der er fastsat efter § 5, stk. 1 og 2, i lov om renter ved forsinket betaling m.v. Hvor særlige forhold begrunder det, kan det bestemmes, at der skal betales en højere eller en lavere rente.',2,3,'003.013.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1788,1,1683,1683,'paragraph_group',NULL,'Fravigelighed',NULL,14,1,'003.014',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1789,1,1788,1788,'paragraph','§ 41.',NULL,'Dette kapitel kan ikke fraviges til skade for lejeren.',1,2,'003.014.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id5cf3a12b-dbda-41c4-9a1e-18d8bcd7f0dc\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1790,1,1789,1789,'subsection','Stk. 2.',NULL,'§ 54 finder dog anvendelse.',1,3,'003.014.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1791,1,NULL,0,'chapter','Kapitel 4','Lejefastsættelse og lejeregulering efter det lejedes værdi m.v.',NULL,4,0,'004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1792,1,1791,1791,'paragraph_group',NULL,'Lejeforhøjelse i private lejeboliger',NULL,1,1,'004.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1793,1,1792,1792,'paragraph','§ 42.',NULL,'Er lejen væsentlig lavere end det lejedes værdi, kan udlejeren forlange lejen forhøjet til det beløb, der er rimeligt under hensyn hertil. Ved vurderingen af lejen og det lejedes værdi ses der bort fra:',1,2,'004.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id39e00666-5e0a-4e46-8974-f42df6fbb538\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1794,1,1793,1793,'list_item','1)',NULL,'Lejeforhøjelser efter § 129, stk. 1 og 2, og § 137 og § 58 a i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, forbedringer efter § 129, stk. 1, og §§ 137 og 146 og forbedringer efter det tidligere gældende kapitel 6 a i lov om byfornyelse og udvikling af byer, jf. lovbekendtgørelse nr. 144 af 21. februar 2020.',1,3,'004.001.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1795,1,1793,1793,'list_item','2)',NULL,'Lejeforhøjelser efter § 63 b i tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010, og forbedringer, der er udført for beløb omfattet af § 63 a i tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010.',2,3,'004.001.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1796,1,1793,1793,'list_item','3)',NULL,'Lejeforhøjelser og forbedringer efter den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',3,3,'004.001.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1797,1,1793,1793,'list_item','4)',NULL,'Forbedringer, som lejeren har udført for egen regning med udlejerens tilladelse.',4,3,'004.001.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1798,1,1793,1793,'subsection','Stk. 2.',NULL,'Ved afgørelse efter stk. 1, 1. pkt., skal der foretages en sammenligning med den leje, som er almindeligt gældende i kvarteret eller området for tilsvarende beboelseslejlighed eller enkeltværelse til beboelse med hensyn til beliggenhed, art, størrelse, kvalitet, udstyr og vedligeholdelsestilstand.',5,3,'004.001.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1799,1,1793,1793,'subsection','Stk. 3.',NULL,'Ved sammenligningen af lejemål, jf. stk. 2, tillægges det vægt, når lejen i sammenligningslejemål har været genstand for særskilt prøvelse.',6,3,'004.001.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1800,1,1793,1793,'subsection','Stk. 4.',NULL,'Ved sammenligningen, jf. stk. 2, ses der bort fra:',7,3,'004.001.001.007','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1801,1,1793,1793,'list_item','1)',NULL,'Lejemål, der er forbedret efter § 129, stk. 1, og § 137.',8,3,'004.001.001.008','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1802,1,1793,1793,'list_item','2)',NULL,'Lejemål omfattet af §§ 49-51 og kapitel 5.',9,3,'004.001.001.009','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1803,1,1793,1793,'list_item','3)',NULL,'Lejemål omfattet af den tidligere gældende lov om sanering, jf. lovbekendtgørelse nr. 385 af 4. august 1983, den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 820 af 15. september 1994 med senere ændringer, den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003 med senere ændringer, og lov om byfornyelse og udvikling af byer.',10,3,'004.001.001.010','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1804,1,1793,1793,'subsection','Stk. 5.',NULL,'Krav om lejeforhøjelse kan tidligst få virkning 2 år efter lejeforholdets begyndelse, eller 2 år efter at der sidst er trådt en lejeforhøjelse i kraft, som følge af at lejen var væsentlig lavere end det lejedes værdi.',11,3,'004.001.001.011','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1805,1,1791,1791,'paragraph_group',NULL,'Lejeforhøjelse i ustøttede private plejeboliger',NULL,2,1,'004.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1806,1,1805,1805,'paragraph','§ 43.',NULL,'Lejen for ustøttede private plejeboliger, jf. § 1, stk. 5, skal til enhver tid være fastsat, således at den svarer til det lejedes værdi, som fastsættes ved en sammenligning med støttede ældre- eller plejeboliger i kommunen efter reglerne i § 42, stk. 2 og 4. Ved fastsættelse af lejen ses der bort fra forbedringer, som lejeren har udført for egen regning med udlejerens tilladelse.',1,2,'004.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2e275294-6350-4fc7-8195-e836b03a8f57\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1807,1,1806,1806,'subsection','Stk. 2.',NULL,'Krav om lejeforhøjelse, jf. stk. 1, kan varsles én gang årligt.',1,3,'004.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1808,1,1806,1806,'subsection','Stk. 3.',NULL,'Overstiger lejen det lejedes værdi efter stk. 1, kan lejeren forlange lejen nedsat hertil.',2,3,'004.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1809,1,1806,1806,'subsection','Stk. 4.',NULL,'Nedsættes lejen efter stk. 3, kan lejeren kræve det for meget betalte beløb tilbagebetalt.',3,3,'004.002.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1810,1,1806,1806,'subsection','Stk. 5.',NULL,'§ 45, stk. 4 og 5, finder tilsvarende anvendelse for ustøttede private plejeboliger.',4,3,'004.002.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1811,1,1791,1791,'paragraph_group',NULL,'Varsling',NULL,3,1,'004.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1812,1,1811,1811,'paragraph','§ 44.',NULL,'Lejeforhøjelse efter §§ 42 eller 43 kan gennemføres med 3 måneders varsel.',1,2,'004.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id0ef761e0-f72e-4c3a-afab-cb91964b186d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1813,1,1812,1812,'subsection','Stk. 2.',NULL,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde en angivelse af lejeforhøjelsens størrelse. Kravet skal tillige indeholde oplysning om grunden til lejeforhøjelsen og om lejerens adgang til at gøre indsigelse, jf. stk. 3. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',1,3,'004.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1814,1,1812,1812,'subsection','Stk. 3.',NULL,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren skriftligt fremsætte indsigelse, senest 6 uger efter at kravet om lejeforhøjelse er kommet frem. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',2,3,'004.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1815,1,1812,1812,'subsection','Stk. 4.',NULL,'Indtil huslejenævnets afgørelse foreligger, kan udlejeren oppebære den varslede lejeforhøjelse som en foreløbig lejeforhøjelse, der dog ikke må overstige 15 kr. pr. m² bruttoetageareal om året. Lejen skal reguleres i overensstemmelse med nævnets afgørelse. Regulering af depositum og forudbetalt leje kan ikke forlanges, før kravet om lejeforhøjelse er afgjort af nævnet. Tilbagebetaling til lejeren af for meget betalt leje forrentes fra betalingstidspunktet efter bestemmelsen i § 15, stk. 3.',3,3,'004.003.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1816,1,1812,1812,'subsection','Stk. 5.',NULL,'Lejeforhøjelse kan kræves uanset aftalt uopsigelighed, når udlejeren har forbeholdt sig at kunne regulere lejen.',4,3,'004.003.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1817,1,1791,1791,'paragraph_group',NULL,'Lejenedsættelse',NULL,4,1,'004.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1818,1,1817,1817,'paragraph','§ 45.',NULL,'Er lejen væsentlig højere end det lejedes værdi, kan lejeren forlange lejen nedsat til et beløb, der er rimeligt under hensyn hertil. Ved vurdering af lejen og det lejedes værdi finder reglen i § 42, stk. 1, tilsvarende anvendelse.',1,2,'004.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id4a358884-1df6-4dc4-942f-a15529dd3be4\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1819,1,1818,1818,'subsection','Stk. 2.',NULL,'Ved afgørelse efter stk. 1 skal der tages hensyn til de i § 42, stk. 2-4, nævnte omstændigheder.',1,3,'004.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1820,1,1818,1818,'subsection','Stk. 3.',NULL,'Nedsættes lejen efter stk. 1, kan lejeren kræve det for meget betalte beløb tilbagebetalt.',2,3,'004.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1821,1,1818,1818,'subsection','Stk. 4.',NULL,'Sag om nedsættelse af lejen skal indbringes inden 1 år efter det tidspunkt, lejen eller den forhøjede leje første gang skal betales.',3,3,'004.004.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1822,1,1818,1818,'subsection','Stk. 5.',NULL,'I ejendomme med beboerrepræsentation kan beboerrepræsentanterne kræve nedsættelse af lejen. Nedsættes lejen, anvendes tilbagebetalingsbeløbet forlods til dækning af beboerrepræsentanternes udgifter ved sagen.',4,3,'004.004.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1823,1,1791,1791,'paragraph_group',NULL,'Lejeforhøjelse som følge af øgede ejendomsskatter m.v.',NULL,5,1,'004.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1824,1,1823,1823,'paragraph','§ 46.',NULL,'Forøges de ejendomsskatter, der påhviler ejendommen, kan udlejeren forlange udgiften udlignet gennem en lejeforhøjelse for de beboelseslejligheder og beboelsesrum, som skatten vedrører. Lejeforhøjelse kan kræves uanset aftalt uopsigelighed.',1,2,'004.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf9017247-9034-4d0b-8e87-d73c0739f768\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1825,1,1824,1824,'subsection','Stk. 2.',NULL,'Lejeforhøjelsen fordeles i forhold til den gældende leje eller, hvor der ikke er fastsat nogen leje, lejeværdi. For lejeforhold i ejendomme, hvor reglerne i §§ 19-31 gælder, fordeles forhøjelsen dog efter reglerne i §§ 27 og 28.',1,3,'004.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1826,1,1824,1824,'subsection','Stk. 3.',NULL,'Lejeforhøjelsen kan gennemføres med 3 måneders varsel. Lejeforhøjelsen kan dog kræves med virkning fra det tidspunkt, udgiften er pålagt ejendommen, hvis kravet om lejeforhøjelse fremsættes senest 5 måneder efter dette tidspunkt.',2,3,'004.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1827,1,1824,1824,'subsection','Stk. 4.',NULL,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde en beregning af, hvorledes ændringen af lejen fremkommer, og oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 5. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',3,3,'004.005.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1828,1,1824,1824,'subsection','Stk. 5.',NULL,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren, senest 6 uger efter at kravet er kommet frem, fremsætte skriftlig indsigelse, der angiver, på hvilke punkter kravet ikke kan godkendes. I ejendomme med beboerrepræsentation kan beboerrepræsentanterne på samtlige lejeres vegne gøre indsigelse mod kravet om lejeforhøjelse, jf. 1. pkt. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',4,3,'004.005.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1829,1,1823,1823,'paragraph','§ 47.',NULL,'Reglerne i § 46 gælder også, hvis der pålægges ejendommen nye eller forøgede afgifter til vand, el, renovation, wc, skorstensfejning el.lign. efter takster, der er fastsat eller godkendt af det offentlige.',2,2,'004.005.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idb2d6b18f-eae1-47af-9184-973237a7d6b9\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1830,1,1829,1829,'subsection','Stk. 2.',NULL,'Reglerne i § 46 gælder også, hvis der pålægges ejendommen nye vej- eller kloakbidrag eller lignende bidrag til det offentlige. Er bidrag pålagt ejendommen som en engangsydelse, kan udlejeren, når ydelsen er betalt, opkræve bidraget hos lejerne gennem en lejeforhøjelse, der i løbet af 10 år har dækket udlejerens udlæg med tillæg af sædvanlige finansieringsudgifter. Lejeforhøjelsen bortfalder ved periodens udløb.',1,3,'004.005.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1831,1,1829,1829,'subsection','Stk. 3.',NULL,'Reglerne i § 46 gælder også udgifter til dækning af konsulentbistand i henhold til § 4 b, stk. 1, 2. pkt., i den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer. Udlejeren kan, når udgiften er betalt, udligne denne gennem en lejeforhøjelse, der i løbet af 12 måneder har dækket udlejerens udlæg med sædvanlige finansieringsudgifter. Lejeforhøjelsen kan dog alene opkræves med lige store beløb hos de lejere, som har antaget konsulentbistand, jf. 1. pkt., og lejeforhøjelsen bortfalder ved periodens udløb.',2,3,'004.005.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1832,1,1791,1791,'paragraph_group',NULL,'Lejenedsættelse ved faldende udgifter til ejendomsskatter m.v.',NULL,6,1,'004.006',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1833,1,1832,1832,'paragraph','§ 48.',NULL,'Bortfalder eller nedsættes de i §§ 46 og 47 nævnte skatter, afgifter, udgifter og bidrag, skal udlejeren med virkning fra nedsættelsestidspunktet foretage en tilsvarende lejenedsættelse for de beboelseslejligheder og beboelsesrum, i hvis leje udgiften har været indregnet. Udlejeren skal dog ikke foretage lejenedsættelse, hvis bortfald eller nedsættelse af skatter, afgifter, udgifter og bidrag samtidig udlignes eller overstiges af nye forøgede skatter, afgifter, udgifter eller bidrag. I fredede ejendomme, hvorpå der er tinglyst en særlig bevaringsdeklaration i henhold til lovgivningen om bygningsfredning, kan et beløb svarende til den ejendomsskat, der til enhver tid kunne have været opkrævet, dog opkræves som en del af lejen, uanset om en ejendom er fritaget for ejendomsbeskatning.',1,2,'004.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id93dbf2d6-fc5b-4c01-9460-cc461b3f8b7d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1834,1,1833,1833,'subsection','Stk. 2.',NULL,'Udlejeren skal give lejeren skriftlig meddelelse om nedsættelsen af lejen, senest 6 uger efter at meddelelsen om nedsættelsen af skatter, afgifter, udgifter eller bidrag er kommet frem.',1,3,'004.006.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1835,1,1791,1791,'paragraph_group',NULL,'Lejefastsættelse i indeksfinansierede ejendomme',NULL,7,1,'004.007',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1836,1,1835,1835,'paragraph','§ 49.',NULL,'For ejendomme, hvis opførelse er finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån, kan lejen fastsættes, således at den samlede lejeindtægt kan dække ejendommens nødvendige driftsudgifter på tidspunktet for ejendommens opførelse med tillæg af afkastet af ejendommens værdi.',1,2,'004.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id91525766-886e-4c9d-b6ec-5e588f6b4e02\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1837,1,1836,1836,'subsection','Stk. 2.',NULL,'Som afkast kan beregnes den rente, udlejeren løbende betaler på indekslån optaget til finansiering af ejendommens opførelse med tillæg af 4 pct. af den indekserede hovedstol. Udlejeren kan endvidere beregne en forrentning på 4 pct. af den resterende anskaffelsessum efter fradrag af lejerindskud.',1,3,'004.007.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1838,1,1836,1836,'subsection','Stk. 3.',NULL,'Driftsudgifterne efter stk. 1 og forrentningen efter stk. 2, 2. pkt., reguleres med samme procentsats, hvormed hovedstolen på indekslånet reguleres. Regulering kan dog ikke ske af driftsudgifter omfattet af §§ 46-48.',2,3,'004.007.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1839,1,1836,1836,'subsection','Stk. 4.',NULL,'Lejen fordeles på beboelseslejlighederne efter deres indbyrdes værdi. Ved bedømmelsen af beboelseslejlighedernes indbyrdes værdi ses der bort fra forbedringer, som lejeren har betalt.',3,3,'004.007.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1840,1,1836,1836,'subsection','Stk. 5.',NULL,'Lejeforhøjelse efter stk. 2 og 3 kan gennemføres med 3 måneders varsel.',4,3,'004.007.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1841,1,1836,1836,'subsection','Stk. 6.',NULL,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde en beregning af, hvorledes ændringen af lejen fremkommer, og oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 7. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',5,3,'004.007.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1842,1,1836,1836,'subsection','Stk. 7.',NULL,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren, senest 6 uger efter at kravet er kommet frem, fremsætte skriftlig indsigelse, der angiver, på hvilke punkter kravet ikke kan godkendes. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',6,3,'004.007.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1843,1,1791,1791,'paragraph_group',NULL,'Lejefastsættelse i realrenteafgiftsfritagede ejendomme',NULL,8,1,'004.008',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1844,1,1843,1843,'paragraph','§ 50.',NULL,'For ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af lov om realrenteafgift, kan lejen uanset ejendommens finansiering fastsættes til samme beløb, som lovligt kan opkræves efter § 49 for en tilsvarende ejendom finansieret med størst muligt indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån.',1,2,'004.008.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id8cffcac6-9dca-40da-a4d3-2d5b38b12cb5\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1845,1,1791,1791,'paragraph_group',NULL,'Undtagelse fra det lejedes værdi',NULL,9,1,'004.009',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1846,1,1845,1845,'paragraph','§ 51.',NULL,'§§ 42-45 finder ikke anvendelse for lejemål i ejendomme, hvis opførelse er finansieret med indekslån efter § 2, stk. 1, nr. 9, i den tidligere gældende lov om indeksregulerede realkreditlån. Det samme gælder for lejemål i ejendomme taget i brug efter den 1. januar 1989, der er opført af og udlejes af udlejere omfattet af lov om realrenteafgift, såfremt lejefastsættelsen sker efter § 50.',1,2,'004.009.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id9f71a522-1ac0-422f-ab7a-dc22112dffd6\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1847,1,1791,1791,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,10,1,'004.010',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1848,1,1847,1847,'paragraph','§ 52.',NULL,'Uenighed om lejeregulering og lejefastsættelse efter reglerne i dette kapitel afgøres af huslejenævnet.',1,2,'004.010.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf9900f9d-fabe-427f-b6a9-79bf02255a07\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1849,1,1791,1791,'paragraph_group',NULL,'Fravigelighed',NULL,11,1,'004.011',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1850,1,1849,1849,'paragraph','§ 53.',NULL,'§§ 42-48 kan ikke ved aftale fraviges til skade for lejeren, jf. dog kapitel 5 om fri leje.',1,2,'004.011.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb1f782ca-a4f1-44b9-ae7d-7649d8306f5b\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1851,1,1850,1850,'subsection','Stk. 2.',NULL,'Det kan dog aftales, at lejen én gang årligt reguleres efter udviklingen i Danmarks Statistiks nettoprisindeks. Lejeforhøjelse kan gennemføres alene ved udlejerens skriftlige meddelelse herom til lejeren.',1,3,'004.011.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1852,1,1850,1850,'subsection','Stk. 3.',NULL,'De øvrige bestemmelser i dette kapitel kan ikke fraviges.',2,3,'004.011.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1853,1,NULL,0,'chapter','Kapitel 5','Fri leje',NULL,5,0,'005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1854,1,1853,1853,'paragraph_group',NULL,'Aftalt fri leje',NULL,1,1,'005.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1855,1,1854,1854,'paragraph','§ 54.',NULL,'Lejen kan fastsættes frit efter parternes aftale i følgende lejeforhold:',1,2,'005.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id869885c7-7daf-48c5-9860-764119916395\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1856,1,1855,1855,'list_item','1)',NULL,'Lejeforhold om beboelseslejligheder i ejendomme, der er taget i brug efter den 31. december 1991.',1,3,'005.001.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1857,1,1855,1855,'list_item','2)',NULL,'Lejeforhold om beboelseslejligheder, der den 31. december 1991 eller inden denne dato lovligt udelukkende benyttedes til eller lovligt var indrettet udelukkende til erhvervsformål, jf. reglerne i kapitel VII i den tidligere gældende lov om midlertidig regulering af boligforholdene.',2,3,'005.001.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1858,1,1855,1855,'list_item','3)',NULL,'Lejeforhold om nyindrettede beboelseslejligheder eller nyindrettede enkeltværelser i en tagetage, som den 1. september 2002 ikke var benyttet til eller registreret som beboelse. Det samme gælder lejligheder og enkeltværelser i nypåbyggede etager, hvortil der er givet byggetilladelse efter den 1. juli 2004. I forbindelse med indretning af boliger i tagetagen kan udlejeren med 6 ugers varsel råde over loftsrum, hvis der anvises lejeren andre rum, der er anvendelige til det aftalte formål.',3,3,'005.001.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1859,1,1855,1855,'subsection','Stk. 2.',NULL,'For lejeforhold omfattet af stk. 1, nr. 2 og 3, er det en betingelse for, at lejen kan fastsættes frit, at det fremgår af lejeaftalen, at lejemålet er omfattet af disse bestemmelser.',4,3,'005.001.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1860,1,1855,1855,'subsection','Stk. 3.',NULL,'Lejeforhøjelse for lejeforhold, hvor lejen fastsættes frit efter parternes aftale, jf. stk. 1, kan kræves på grundlag af aftale om regulering af lejen efter nettoprisindeks og kan gennemføres alene ved udlejerens skriftlige meddelelse herom til lejeren.',5,3,'005.001.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1861,1,1853,1853,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,2,1,'005.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1862,1,1861,1861,'paragraph','§ 55.',NULL,'Uenighed om lejeaftaler indgået i henhold til § 54 og om, hvorvidt en aftale indgået i medfør af § 54 er rimelig, jf. aftalelovens § 36, afgøres af huslejenævnet. Huslejenævnet afgør endvidere uenighed om udlejerens ret til at råde over arealer i tagetager efter § 54, stk. 1, nr. 3.',1,2,'005.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id40b4167a-aac9-4533-9570-7b49d30f479e\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1863,1,1853,1853,'paragraph_group',NULL,'Fravigelighed',NULL,3,1,'005.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1864,1,1863,1863,'paragraph','§ 56.',NULL,'Dette kapitel kan ikke fraviges til skade for lejeren.',1,2,'005.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb69bb94b-f7b1-4fcb-9d7a-a5eadfc566e1\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1865,1,NULL,0,'chapter','Kapitel 6','Betaling af leje',NULL,6,0,'006',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1866,1,1865,1865,'paragraph_group',NULL,'Betalingssted',NULL,1,1,'006.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1867,1,1866,1866,'paragraph','§ 57.',NULL,'Udlejeren skal anvise et betalingssted her i landet i form af en konto i et pengeinstitut, jf. dog 2. pkt. Er der ikke anvist et betalingssted, skal lejen betales på udlejerens bopæl her i landet. Indbetaling til et pengeinstitut anses for betaling på det anviste betalingssted.',1,2,'006.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idecb24d76-b44d-46f3-9fa2-53ca9f1b77df\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1868,1,1865,1865,'paragraph_group',NULL,'Betalingstidspunkt',NULL,2,1,'006.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1869,1,1868,1868,'paragraph','§ 58.',NULL,'Lejen kan kræves betalt månedsvis forud.',1,2,'006.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id363a63de-aedf-40f9-a9dd-089543e38f5e\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1870,1,1869,1869,'subsection','Stk. 2.',NULL,'Er lejen beregnet for en kortere periode end 1 måned, kan den kræves betalt forud for den periode, den vedrører.',1,3,'006.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1871,1,1869,1869,'subsection','Stk. 3.',NULL,'Leje for beboelseslejligheder og enkeltværelser til beboelse kan ikke kræves betalt for mere end 3 måneder ad gangen. Leje for ustøttede private plejeboliger kan ikke kræves betalt for mere end 1 måned ad gangen.',2,3,'006.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1872,1,1869,1869,'subsection','Stk. 4.',NULL,'Rettidig betaling af husleje sker senest på forfaldsdagen. Forfalder lejen til betaling på en helligdag, en lørdag eller grundlovsdag, udskydes forfaldsdagen til den efterfølgende hverdag.',3,3,'006.002.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1873,1,1869,1869,'subsection','Stk. 5.',NULL,'I tilfælde af opsigelse eller ved det tidsbestemte lejeforholds udløb er lejeren kun pligtig at betale leje for tiden indtil lejeforholdets ophør.',4,3,'006.002.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1874,1,1865,1865,'paragraph_group',NULL,'Depositum og forudbetalt leje',NULL,3,1,'006.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1875,1,1874,1874,'paragraph','§ 59.',NULL,'Udlejeren kan i lejeforhold om beboelseslejligheder og enkeltværelser til beboelse ved lejemålets indgåelse som depositum kræve et beløb svarende til højst 3 måneders leje. Beløbet henstår til sikkerhed for lejerens forpligtelser ved fraflytning.',1,2,'006.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb4f34601-29c1-4597-a7ec-0e653d4d251e\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1876,1,1875,1875,'subsection','Stk. 2.',NULL,'I fremlejeforhold kan lejeren ved lejeaftalens indgåelse såvel som i lejeperioden i stedet for depositum vælge at stille sikkerhed i form af bankgaranti eller indestående på en særskilt deponeringskonto.',1,3,'006.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1877,1,1875,1875,'subsection','Stk. 3.',NULL,'Udlejeren kan ved lejemålets indgåelse desuden kræve lejen forudbetalt for et tidsrum op til 3 måneder, når den forudbetalte leje samtidig ikke overstiger den leje, som skal betales i perioden, fra lejemålet opsiges af lejeren, indtil lejeforholdet ophører. Ved forudbetalt leje forstås i denne forbindelse det beløb, der umiddelbart inden de aftalte betalingsterminer henstår som indbetalt hos udlejeren. Er lejeaftalen opsagt eller ophævet, kan lejeren modregne det beløb, der er forudbetalt efter 1. pkt. i den sidste del af lejeperioden.',2,3,'006.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1878,1,1875,1875,'subsection','Stk. 4.',NULL,'Depositum er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1. Hvis lejeren har valgt i stedet for depositum at stille sikkerhed i form af bankgaranti eller indestående på en deponeringskonto, finder reglerne for pligtig pengeydelse tilsvarende anvendelse, jf. § 182, stk. 1, nr. 1.',3,3,'006.003.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1879,1,1875,1875,'subsection','Stk. 5.',NULL,'Huslejenævnet kan tillade, at stk. 1-3 fraviges, såfremt der stilles behørig sikkerhed for lejerens tilbagebetalingskrav, jf. § 17, stk. 1, 2. pkt.',4,3,'006.003.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1880,1,1865,1865,'paragraph_group',NULL,'Regulering af depositum og forudbetalt leje',NULL,4,1,'006.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1881,1,1880,1880,'paragraph','§ 60.',NULL,'Gennemføres lejeforhøjelse, kan depositum og forudbetalt leje kræves reguleret. Reguleringen kan for de nævnte beløb opkræves med lige store månedlige beløb over samme antal måneder, som det pågældende beløb svarede til i forhold til lejen ved lejemålets indgåelse. 1. pkt. finder tilsvarende anvendelse, hvis lejeren har valgt i stedet for depositum at stille sikkerhed i form af bankgaranti eller indestående på en deponeringskonto. Nedsættes lejen, skal udlejeren med virkning fra nedsættelsestidspunktet foretage en tilsvarende tilbagebetaling af depositum og forudbetalt leje til lejeren.',1,2,'006.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id0c5db267-4183-4cd4-a0bc-1873a42590be\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1882,1,1881,1881,'subsection','Stk. 2.',NULL,'Regulering af depositum og forudbetalt leje efter stk. 1 er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1. Har lejeren valgt i stedet for depositum at stille sikkerhed i form af bankgaranti eller indestående på en deponeringskonto, finder reglerne for pligtig pengeydelse tilsvarende anvendelse, jf. § 182, stk. 1, nr. 1.',1,3,'006.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1883,1,1865,1865,'paragraph_group',NULL,'Ustøttede private plejeboliger',NULL,5,1,'006.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1884,1,1883,1883,'paragraph','§ 61.',NULL,'Udlejeren kan ikke i lejeforhold om ustøttede private plejeboliger kræve lejen forudbetalt efter § 59, stk. 3 og 4.',1,2,'006.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id3c9e1279-c578-4353-b215-ece101947015\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1885,1,1865,1865,'paragraph_group',NULL,'Straf',NULL,6,1,'006.006',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1886,1,1885,1885,'paragraph','§ 62.',NULL,'Med bøde eller fængsel indtil 4 måneder straffes den udlejer, som i ejendomme med lejefastsættelse efter §§ 19-31 forlanger depositum og forudbetalt leje i strid med § 59, stk. 1 og 3.',1,2,'006.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id73894e51-3596-477c-89a8-f58659738a4f\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1887,1,1886,1886,'subsection','Stk. 2.',NULL,'Medmindre højere straf er forskyldt efter anden lovgivning, straffes med bøde den lejer, der har foretaget fremleje, og som ikke inden 6 uger fra fremlejeforholdets ophør eller endelig huslejenævnsafgørelse, hvis sag herom er indbragt for huslejenævnet, har foretaget endelig afregning og tilbagebetaling af overskydende depositum og forudbetalt leje.',1,3,'006.006.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1888,1,1886,1886,'subsection','Stk. 3.',NULL,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',2,3,'006.006.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1889,1,1865,1865,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,7,1,'006.007',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1890,1,1889,1889,'paragraph','§ 63.',NULL,'Uenighed om depositum, forudbetalt leje og sikkerhedsstillelse efter §§ 59-61 afgøres af huslejenævnet. Huslejenævnet kan herunder tillade, at § 59, stk. 1-3, fraviges, jf. § 59, stk. 5.',1,2,'006.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id5b55fe5e-bafb-4f59-9cbf-ef5df61a4251\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1891,1,1865,1865,'paragraph_group',NULL,'Fravigelighed',NULL,8,1,'006.008',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1892,1,1891,1891,'paragraph','§ 64.',NULL,'§ 57, § 58, stk. 3-5, og §§ 59-61 kan ikke ved aftale fraviges til skade for lejeren.',1,2,'006.008.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id6da907fa-dc3b-4f69-b4fb-1ad99fb5dcc0\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1893,1,NULL,0,'chapter','Kapitel 7','Betaling for varme, vand, køling, gas og el m.v.',NULL,7,0,'007',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1894,1,1893,1893,'paragraph_group',NULL,'Udgifter til varme og opvarmning af vand',NULL,1,1,'007.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1895,1,1894,1894,'paragraph','§ 65.',NULL,'Leverer udlejeren varme og opvarmning af vand, kan udlejeren kræve sine udgifter til lejerens forbrug og andel i andre udgifter som nævnt i § 72, stk. 4 og 5, refunderet. De nævnte udgifter kan ikke indeholdes i lejen, jf. dog stk. 2.',1,2,'007.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id6681a0f2-2f72-44b1-a57b-59a85ff63574\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1896,1,1895,1895,'subsection','Stk. 2.',NULL,'Udgifter til leverancer efter stk. 1 kan indeholdes i lejen, medmindre pligt til måling af forbrug følger af anden lovgivning, ved følgende lejeaftaler:',1,3,'007.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1897,1,1895,1895,'list_item','1)',NULL,'Lejeaftaler om enkelte værelser til beboelse.',2,3,'007.001.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1898,1,1895,1895,'list_item','2)',NULL,'Lejeaftaler om lejligheder, der er forbeholdt uddannelsessøgende eller andre unge i ejendomme tilhørende selvejende institutioner, fonde el.lign., hvis vedtægter er godkendt af det offentlige.',3,3,'007.001.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1899,1,1894,1894,'paragraph','§ 66.',NULL,'Fordeling af udgiften imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. I ejendomme, som helt eller delvis er undtaget fra krav om individuel måling af varme i medfør af byggeloven, fordeles udgifterne efter udlejerens bestemmelse efter bruttoetagearealet eller efter rumfang.',2,2,'007.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"iddb23ed6c-0f05-4b87-821f-3a502cb3c641\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1900,1,1899,1899,'subsection','Stk. 2.',NULL,'I ejendomme, som helt eller delvis er undtaget fra krav om individuel måling af opvarmning af vand i medfør af byggeloven, fordeles udgifterne efter antallet og arten af varmtvandshaner og antallet af værelser.',1,3,'007.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1901,1,1893,1893,'paragraph_group',NULL,'Udgifter til køling',NULL,2,1,'007.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1902,1,1901,1901,'paragraph','§ 67.',NULL,'Leverer udlejeren køling, kan udlejeren kræve sine udgifter til lejerens forbrug og andel i andre udgifter som nævnt i § 72, stk. 4, refunderet. Fordeling af udgiften imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. Er ejendommen helt eller delvis undtaget fra krav om individuel måling af køling i medfør af byggeloven, indeholdes udgifterne hertil i lejen.',1,2,'007.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idaaab661a-a5ff-416d-a348-34f618387eae\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1903,1,1902,1902,'subsection','Stk. 2.',NULL,'Leverer udlejeren køling, og er udgiften hertil indeholdt i lejen, kan beboerrepræsentanterne eller et flertal af lejerne forlange, at fordelingen af udgiften fremover skal ske på grundlag af egnede forbrugsmålere. Udlejeren kan forlange, at fordelingen af udgiften i 1. pkt. fremtidig skal ske på grundlag af egnede forbrugsmålere, hvis installation af forbrugsmålere til måling af forbruget af køling er påbudt i henhold til lov. Beslutninger efter 1. og 2. pkt. er bindende for alle lejere uanset tidligere aftaler.',1,3,'007.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1904,1,1902,1902,'subsection','Stk. 3.',NULL,'Udlejeren kan modsætte sig gennemførelse af en beslutning efter stk. 2, 1. pkt., hvis udlejeren kan godtgøre, at gennemførelsen ikke kan anses for at være rimelig og hensigtsmæssig.',2,3,'007.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1905,1,1902,1902,'subsection','Stk. 4.',NULL,'Udgifter som følge af ændret fordeling betragtes som forbedring.',3,3,'007.002.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1906,1,1902,1902,'subsection','Stk. 5.',NULL,'Beslutninger efter stk. 2 kan gennemføres med 6 ugers varsel til en regnskabsperiodes begyndelse.',4,3,'007.002.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1907,1,1893,1893,'paragraph_group',NULL,'Udgifter til koldt vand',NULL,3,1,'007.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1908,1,1907,1907,'paragraph','§ 68.',NULL,'Leverer udlejeren koldt vand, kan udlejeren kræve sine udgifter til lejerens forbrug refunderet. Fordeling af udgifterne imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. Er ejendommen helt eller delvis undtaget fra krav om individuel måling af koldt vand i medfør af byggeloven, indeholdes udgifterne hertil i lejen.',1,2,'007.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ida047dbaa-06d7-4023-a17f-1ef23e7290e4\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1909,1,1908,1908,'subsection','Stk. 2.',NULL,'§ 67, stk. 2-5, finder tilsvarende anvendelse. Beslutninger efter § 67, stk. 2, vedrørende vand kan gennemføres med 6 ugers varsel og inden for en periode, der må anses for rimelig i forhold til omfanget af den samlede forbedring.',1,3,'007.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1910,1,1893,1893,'paragraph_group',NULL,'Udgifter til el og gas',NULL,4,1,'007.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1911,1,1910,1910,'paragraph','§ 69.',NULL,'Leverer udlejeren gas til opvarmning og el, kan udlejeren kræve sine udgifter til lejerens forbrug refunderet. Fordeling af udgiften imellem lejerne sker efter sædvanlige fordelingsregler efter forbrugsmålere. Er ejendommen helt eller delvis undtaget fra krav om individuel måling af el eller gas i medfør af byggeloven, kan fordeling af udgiften ske efter areal eller rumfang. Fordeling af udgiften til el til andet end opvarmning kan dog kun ske ved godkendte individuelle elektricitetsmålere.',1,2,'007.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idbbab0d8d-8e5c-4401-8f37-6bf4442c5895\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1912,1,1910,1910,'paragraph','§ 70.',NULL,'Måles forbruget af el og gas i den enkelte boligenhed ved fordelingsmålere, skal fordelingen imellem lejerne ske på grundlag af det målte forbrug. Udlejeren, beboerrepræsentanterne eller et flertal af lejerne kan forlange, at lejerne fremover betaler forbrug på grundlag af afregningsmålere direkte til forsyningsvirksomheden. Ændringen kan gennemføres med 6 ugers varsel. For leverancer af el til opvarmning kan ændringen gennemføres med 6 ugers varsel til et varmeregnskabsårs begyndelse.',2,2,'007.004.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idaac60c94-c042-4be2-b7dd-fe4b2d830652\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1913,1,1893,1893,'paragraph_group',NULL,'Acontobetaling af forbrugsudgifter',NULL,5,1,'007.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1914,1,1913,1913,'paragraph','§ 71.',NULL,'Udlejeren kan med 6 ugers varsel til en betalingstermin forlange, at lejeren skal betale acontobidrag til dækning af lejerens andel i ejendommens udgifter vedrørende varme, opvarmning af vand, køling, vand, el og gas, når udgifterne hertil ikke er indeholdt i lejen, jf. dog § 79, stk. 2. Udlejeren kan med samme varsel forlange forhøjelse af løbende acontobidrag.',1,2,'007.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ida0628a52-69b8-48c1-bb58-27ffaa949546\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1915,1,1914,1914,'subsection','Stk. 2.',NULL,'Bidragene betales med lige store beløb i forbindelse med de almindelige lejebetalinger.',1,3,'007.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1916,1,1914,1914,'subsection','Stk. 3.',NULL,'De samlede bidrag for 1 år for henholdsvis varme, opvarmning af vand, køling, vand, el og gas må højst opkræves med den udgift, som forventes at blive pålignet for regnskabsperioden for den pågældende leverance. Ved forhøjelse af det løbende acontobidrag kan det månedlige bidrag højst forøges til 1/12 af den samlede udgift, som forventes at blive pålignet for regnskabsperioden for den pågældende leverance.',2,3,'007.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1917,1,1893,1893,'paragraph_group',NULL,'Forbrugsregnskaber',NULL,6,1,'007.006',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1918,1,1917,1917,'paragraph','§ 72.',NULL,'Udgifterne i §§ 65-69 opgøres i særskilte forbrugsregnskaber for følgende:',1,2,'007.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idff8fb772-6dcf-4b39-a1f6-0f67ac59e438\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1919,1,1918,1918,'list_item','1)',NULL,'Varme og opvarmning af vand.',1,3,'007.006.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1920,1,1918,1918,'list_item','2)',NULL,'Køling.',2,3,'007.006.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1921,1,1918,1918,'list_item','3)',NULL,'Vand.',3,3,'007.006.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1922,1,1918,1918,'list_item','4)',NULL,'El.',4,3,'007.006.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1923,1,1918,1918,'list_item','5)',NULL,'Gas.',5,3,'007.006.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1924,1,1918,1918,'subsection','Stk. 2.',NULL,'Rabatydelser og lign. skal godskrives regnskabet.',6,3,'007.006.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1925,1,1918,1918,'subsection','Stk. 3.',NULL,'Lejerens bidrag efter §§ 65-69 er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1.',7,3,'007.006.001.007','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1926,1,1918,1918,'subsection','Stk. 4.',NULL,'I regnskabet for varme og opvarmning af vand og i kølingsregnskabet kan udlejeren kun medtage udgiften til energiforbruget i regnskabsperioden. Sker leverancen fra et kollektivt forsyningsanlæg eller fra et naturgasanlæg, skal udlejeren dog medtage den samlede udgift. Udgifter til kontrol, eftersyn og vedligeholdelse af henholdsvis varmeanlæg og kølingsanlæg, der er pålagt udlejeren i henhold til lov om fremme af energibesparelser i bygninger, skal medtages i regnskabet.',8,3,'007.006.001.008','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1927,1,1918,1918,'subsection','Stk. 5.',NULL,'Udgifterne til energimærkning medtages i regnskabet for varme og opvarmning af vand som en forholdsmæssig del med lige store beløb i hvert af årene i den periode, energimærkningen er gyldig. Endvidere kan medtages en passende forrentning af udgiften til energimærkning, der ikke er dækket ved lejernes betaling efter 1. pkt. Udlejeren har pligt til at orientere lejerne om, at der er udarbejdet energimærkning i henhold til lov om fremme af energibesparelser i bygninger og på en lejers forlangende give denne eller dennes befuldmægtigede adgang til at gennemgå dette materiale og eventuelle bilag hertil.',9,3,'007.006.001.009','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1928,1,1918,1918,'subsection','Stk. 6.',NULL,'I vandregnskabet kan udlejeren medtage samtlige udgifter vedrørende forsyning med vand, herunder vand- og vandafledningsafgift, i regnskabsperioden.',10,3,'007.006.001.010','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1929,1,1918,1918,'subsection','Stk. 7.',NULL,'Skal en udgift, der hidtil har været indeholdt i lejen, fremover indgå i et forbrugsregnskab, jf. stk. 1, nedsættes lejen samtidig med et beløb, der svarer til det, der var indeholdt i lejen.',11,3,'007.006.001.011','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1930,1,1917,1917,'paragraph','§ 73.',NULL,'Forbrugsregnskabet skal indeholde oplysning om lejerens andel af de samlede udgifter og om lejerens adgang til at gøre indsigelse, jf. § 77. Regnskabet skal endvidere indeholde oplysning om tidspunktet for udlejerens modtagelse af endelig afregning af leverancen fra et kollektivt forsyningsanlæg eller et naturgasanlæg, hvis regnskabet kommer frem til lejeren efter udløbet af fristen i § 75, 1. pkt. Indeholder regnskabet ikke disse oplysninger, er det ugyldigt.',2,2,'007.006.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idc11b3aff-c937-481e-a3d8-4b508f6afa3b\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1931,1,1917,1917,'paragraph','§ 74.',NULL,'Medmindre andet er aftalt, begynder regnskabsåret for de i § 72, stk. 1, nr. 1, 2, 4 og 5, anførte regnskaber den 1. juni, jf. dog stk. 2-4.',3,2,'007.006.003','{\"source_class\":\"Paragraf\",\"source_id\":\"ida1fb9acf-269f-452c-8862-a3a816039648\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1932,1,1931,1931,'subsection','Stk. 2.',NULL,'Udlejeren kan med 6 ugers varsel bestemme, at regnskabet fremover skal begynde på en anden dato, jf. dog stk. 3 og 4. Regnskabsperioden ved overgangen til det nye regnskabsår må højst være 18 måneder.',1,3,'007.006.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1933,1,1931,1931,'subsection','Stk. 3.',NULL,'For ejendomme, hvor leverancen af varme sker fra et kollektivt varmeforsyningsanlæg eller et naturgasanlæg, og for ejendomme, hvor leverancen af køling sker fra et kollektivt kølingsforsyningsanlæg, skal forbrugsregnskabet følge forsyningsanlæggets regnskabsår eller aflæsningsperiode.',2,3,'007.006.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1934,1,1931,1931,'subsection','Stk. 4.',NULL,'For ejendomme, hvor leverancen af vand sker fra en kommune eller et vandværk, skal regnskabsåret fastsættes, således at det svarer til det, som udlejeren afregner efter i forhold til kommunen eller vandværket. Udlejeren kan dog beslutte, at vandregnskabsåret skal følge varmeregnskabsåret, jf. stk. 1 og 3.',3,3,'007.006.003.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1935,1,1917,1917,'paragraph','§ 75.',NULL,'Forbrugsregnskabet, jf. § 72, stk. 1, skal være kommet frem til lejerne senest 4 måneder efter regnskabsårets udløb. Indeholder regnskabet udgifter vedrørende leverancer fra et kollektivt forsyningsanlæg eller et naturgasanlæg, jf. § 72, stk. 1, nr. 1-5, skal regnskabet være kommet frem til lejerne, senest 3 måneder efter at udlejeren har modtaget endelig afregning fra forsyningsanlægget, hvis dette tidspunkt er senere end fristen efter 1. pkt.',4,2,'007.006.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id7ed7dd33-eeaa-4042-8e7a-2a65883ecbee\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1936,1,1917,1917,'paragraph','§ 76.',NULL,'Når et forbrugsregnskab er udsendt, skal udlejeren på lejerens forlangende give lejeren eller dennes befuldmægtigede adgang til at gennemgå bilagene til regnskabet på ejendommen eller andetsteds i vedkommende byområde.',5,2,'007.006.005','{\"source_class\":\"Paragraf\",\"source_id\":\"id69e5c417-c180-46e0-ac46-554c7e19c97b\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1937,1,1917,1917,'paragraph','§ 77.',NULL,'Lejeren kan skriftligt gøre indsigelse mod de enkelte forbrugsregnskaber, senest 6 uger efter at regnskabet er kommet frem til lejeren. I ejendomme med beboerrepræsentation kan beboerrepræsentanterne på samtlige lejeres vegne gøre indsigelse mod de enkelte regnskaber, jf. 1. pkt. Indsigelsen skal indeholde oplysning om, på hvilke punkter regnskabet ikke kan godkendes. Udlejeren skal indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde sit krav om efterbetaling i henhold til regnskabet.',6,2,'007.006.006','{\"source_class\":\"Paragraf\",\"source_id\":\"id5d9b8877-bb27-45f3-888a-2531bae69cd6\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1938,1,1917,1917,'paragraph','§ 78.',NULL,'Har lejeren i henhold til et forbrugsregnskab betalt for lidt i acontobidrag, kan udlejeren kræve tillægsbetaling ved den første lejebetaling, der skal finde sted, når der er forløbet 1 måned, efter at forbrugsregnskabet er kommet frem til lejeren. Overstiger tillægsbetalingen 3 måneders leje, er lejeren dog berettiget til at betale i tre lige store månedlige rater, således at første rate forfalder til det fastsatte tidspunkt for tillægsbetalingen. Fraflytter lejeren, skal tillægsbetaling senest betales på fraflytningsdagen.',7,2,'007.006.007','{\"source_class\":\"Paragraf\",\"source_id\":\"idcb5ab917-9964-4ead-8943-303219e09506\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1939,1,1938,1938,'subsection','Stk. 2.',NULL,'Har lejeren i henhold til et forbrugsregnskab betalt for meget i acontobidrag, skal det for meget betalte beløb tilbagebetales lejeren eller fradrages i første lejebetaling, efter at forbrugsregnskabet er kommet frem til lejeren.',1,3,'007.006.007.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1940,1,1917,1917,'paragraph','§ 79.',NULL,'Er forbrugsregnskabet ikke kommet frem til lejeren ved udløbet af den i § 75 nævnte frist, mister udlejeren sin ret til at kræve tillægsbetaling af lejeren.',8,2,'007.006.008','{\"source_class\":\"Paragraf\",\"source_id\":\"id9da72ce0-9bd8-4650-a04f-f615352e7b27\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1941,1,1940,1940,'subsection','Stk. 2.',NULL,'Er forbrugsregnskabet ikke kommet frem til lejeren inden 2 måneder efter den i § 75 nævnte frist, kan lejeren undlade at indbetale acontobidrag, indtil regnskabet er kommet frem til lejeren og lejeren har modtaget et eventuelt for meget betalt bidrag for den afsluttede regnskabsperiode.',1,3,'007.006.008.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1942,1,1917,1917,'paragraph','§ 80.',NULL,'Har udlejeren som følge af en undskyldelig fejl ikke medtaget en udgiftspost på forbrugsregnskabet, kan udlejeren til det følgende forbrugsregnskab overføre den del af posten, som ikke overstiger 10 pct. af de samlede udgifter i det først afsluttede regnskab. Udlejeren skal orientere lejerne om størrelsen af det overførte beløb.',9,2,'007.006.009','{\"source_class\":\"Paragraf\",\"source_id\":\"id97de12be-6cc1-4e7d-b21c-2bce0c186e21\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1943,1,1942,1942,'subsection','Stk. 2.',NULL,'I tilfælde af fejlagtig udgiftsfordeling mellem lejerne skal udlejeren snarest rette fejlen ved skriftlig meddelelse til de berørte lejere. Med hensyn til tillægsbetaling og tilbagebetaling som følge af rettelsen finder § 78 og § 79, stk. 1, tilsvarende anvendelse.',1,3,'007.006.009.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1944,1,1893,1893,'paragraph_group',NULL,'Bemyndigelse m.v.',NULL,7,1,'007.007',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1945,1,1944,1944,'paragraph','§ 81.',NULL,'Indenrigs- og boligministeren kan fastsætte regler om, hvordan udgifter til kontrol, eftersyn og vedligeholdelse af tekniske anlæg til varme og opvarmning af vand samt køling, som er pålagt udlejeren i henhold til lov om fremme af energibesparelser i bygninger, fordeles mellem ejendommens lejligheder og lokaler.',1,2,'007.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ide95ad986-353d-4617-bc37-c5337eaede41\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1946,1,1945,1945,'subsection','Stk. 2.',NULL,'Indenrigs- og boligministeren kan fastsætte regler om, at engangsydelser eller udgifter, der ikke betales hvert år, skal fordeles over flere regnskabsår, og at udlejeren kan medtage en passende forrentning af den del af udgiften, der ikke er dækket ved lejernes løbende betaling.',1,3,'007.007.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1947,1,1893,1893,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,8,1,'007.008',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1948,1,1947,1947,'paragraph','§ 82.',NULL,'Uenighed om lejerens betaling for varme, opvarmning af vand, køling, vand, el og gas, herunder uenighed om acontobidrag, og hvor udlejeren modsætter sig at opsætte målere i henhold til § 67, stk. 2, § 68, stk. 2, og § 70, 2. pkt., afgøres af huslejenævnet.',1,2,'007.008.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id1d70b84d-2f9e-48c5-a695-53dd5ca41eaf\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1949,1,1893,1893,'paragraph_group',NULL,'Fravigelighed',NULL,9,1,'007.009',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1950,1,1949,1949,'paragraph','§ 83.',NULL,'§§ 65-69, § 72, stk. 3-5, og § 74, stk. 3, kan ikke fraviges.',1,2,'007.009.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2dd15156-3a43-4dba-a083-5c5700046b33\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1951,1,1950,1950,'subsection','Stk. 2.',NULL,'De øvrige bestemmelser i dette kapitel kan ikke fraviges til skade for lejeren.',1,3,'007.009.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1952,1,NULL,0,'chapter','Kapitel 8','Betaling for fælles programforsyning og adgang til elektroniske kommunikationstjenester m.v.',NULL,8,0,'008',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1953,1,1952,1952,'paragraph_group',NULL,'Lejerens betaling til fællesantenne m.v.',NULL,1,1,'008.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1954,1,1953,1953,'paragraph','§ 84.',NULL,'Leverer udlejeren fælles programforsyning, kan udlejeren forlange de nødvendige og rimelige udgifter til etablering og forbedring, jf. stk. 2, og drift heraf refunderet, herunder udgifter til administration. Det samme gælder forsyning med adgang til elektroniske kommunikationstjenester. Udgifterne fordeles ligeligt på de lejemål i ejendommen, hvor lejeren ifølge aftale med udlejeren er forpligtet til at bidrage til den fælles programforsyning eller til den fælles forsyning med adgang til elektroniske kommunikationstjenester, jf. dog § 85. Udgifterne kan ikke indeholdes i lejen.',1,2,'008.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id845bac4d-9bbc-491a-9bc5-2b68d8995c2e\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1955,1,1954,1954,'subsection','Stk. 2.',NULL,'Har udlejeren efter aftale med lejeren etableret eller forbedret ejendommens programforsyning eller forsyning med adgang til elektroniske kommunikationstjenester, kan udlejeren forlange, at lejeren godtgør udlejeren de etablerings- og forbedringsudgifter, der med rimelighed er afholdt. Uden aftale kan udlejeren dog forlange godtgørelse for udgifter, der med rimelighed er afholdt til forbedringer, det påhviler udlejeren at udføre efter anden lovgivning. Udlejeren kan forlange en passende forrentning og afskrivning af udgifterne. Udgifter til vedligeholdelse af fællesantenneanlæg eller fælles forsyning med adgang til elektroniske kommunikationstjenester kan ikke fradrages på ejendommens konti for udvendig vedligeholdelse, jf. §§ 119 og 120. Der kan ikke beregnes lejeforhøjelse efter §§ 128 og 129 for etablering og forbedring af fællesantenner.',1,3,'008.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1956,1,1954,1954,'subsection','Stk. 3.',NULL,'Lejerens bidrag til udgifter efter stk. 1 er pligtig pengeydelse i lejeforholdet, jf. § 182, stk. 1, nr. 1.',2,3,'008.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1957,1,1952,1952,'paragraph_group',NULL,'Betaling ved fravalg af programforsyning m.v.',NULL,2,1,'008.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1958,1,1957,1957,'paragraph','§ 85.',NULL,'For lejemål, hvor lejeren under iagttagelse af reglerne i § 6 a i lov om radio- og fjernsynsvirksomhed m.v. og de i medfør af § 6 a, stk. 6, i lov om radio- og fjernsynsvirksomhed m.v. udstedte regler har fravalgt tilslutning til og betaling for fælles programforsyning, eller hvor lejeren har individuelt valg af elektroniske kommunikationstjenester, skal den enkelte lejer kun betale for de programmer eller de elektroniske kommunikationstjenester, som lejeren har adgang til.',1,2,'008.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ida1293cc4-f084-4326-8df5-12bb8db2371c\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1959,1,1958,1958,'subsection','Stk. 2.',NULL,'Har lejeren fravalgt tilslutning til og betaling for programforsyning i et fællesantenneanlæg, som ejes af andre end udlejeren, kan lejeren ikke pålægges at betale til etablering, forbedring og drift af anlægget bortset fra rimelige udgifter til administration. Ejes fællesantenneanlægget af andre end udlejeren, og benyttes anlægget også til fremføring af andre elektroniske kommunikationstjenester, kan alle husstande uanset fravalg af fælles programforsyning pålægges at betale til etablering, forbedring og drift, herunder administration af anlægget.',1,3,'008.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1960,1,1952,1952,'paragraph_group',NULL,'Udlejerens og lejerens mulighed for at opsige leveringsaftale',NULL,3,1,'008.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1961,1,1960,1960,'paragraph','§ 86.',NULL,'Leverer udlejeren fælles programforsyning eller fælles forsyning med adgang til elektroniske kommunikationstjenester m.v. i ejendommen, kan udlejeren uanset modstående aftale med 6 måneders varsel meddele lejeren, at udlejeren bringer leveringen af fælles programforsyning eller fælles forsyning med adgang til elektroniske kommunikationstjenester m.v. i ejendommen til ophør.',1,2,'008.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2ffe9646-078a-48ca-a9ec-032496c98c96\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1962,1,1961,1961,'subsection','Stk. 2.',NULL,'Har udlejeren gjort sig skyldig i grov tilsidesættelse af sine forpligtelser vedrørende administration af den fælles programforsyning eller den fælles forsyning med adgang til elektroniske kommunikationstjenester m.v., kan lejeren med virkning for fremtiden frigøre sig fra forpligtelsen til at modtage den fælles programforsyning eller den fælles adgang til elektroniske kommunikationstjenester, som udlejeren foranstalter fordelt i ejendommen.',1,3,'008.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1963,1,1952,1952,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,4,1,'008.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1964,1,1963,1963,'paragraph','§ 87.',NULL,'Huslejenævnet afgør uenighed imellem lejeren og udlejeren vedrørende §§ 84-86.',1,2,'008.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf4de2424-02ec-4e2f-a11e-a9ea0d389808\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1965,1,1964,1964,'subsection','Stk. 2.',NULL,'Efter lejerens anmodning skal huslejenævnet afgøre, om udlejeren har opkrævet større beløb end tilladt efter §§ 84 og 85. Har udlejeren efter nævnets afgørelse opkrævet større beløb end tilladt, kan lejeren forlange det for meget betalte beløb tilbage. § 15, stk. 3, 2. og 3. pkt., finder tilsvarende anvendelse.',1,3,'008.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1966,1,1952,1952,'paragraph_group',NULL,'Fravigelighed',NULL,5,1,'008.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1967,1,1966,1966,'paragraph','§ 88.',NULL,'§§ 84 og 85 kan ikke fraviges til skade for lejeren. §§ 86 og 87 kan ikke fraviges.',1,2,'008.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id198a6202-6f97-424c-bf22-cec329073be5\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1968,1,NULL,0,'chapter','Kapitel 9','Lejerens indflytning',NULL,9,0,'009',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1969,1,1968,1968,'paragraph_group',NULL,'Det lejedes stand på overtagelsestidspunktet',NULL,1,1,'009.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1970,1,1969,1969,'paragraph','§ 89.',NULL,'Udlejeren skal stille det lejede til lejerens rådighed i god og forsvarlig stand fra tidspunktet for lejeforholdets begyndelse. På overtagelsestidspunktet skal det lejede være rengjort, ruderne skal være hele, og alle udvendige døre skal være forsynet med brugelige låse med tilhørende nøgler.',1,2,'009.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id76f8f702-2409-4448-8fce-cdc0a47e93b3\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1971,1,1968,1968,'paragraph_group',NULL,'Indflytningssyn og -rapport',NULL,2,1,'009.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1972,1,1971,1971,'paragraph','§ 90.',NULL,'Udlejeren, der udlejer mere end én beboelseslejlighed, skal syne beboelseslejligheden i forbindelse med indflytningen og udarbejde en indflytningsrapport. Den indflyttende lejer skal indkaldes til synet.',1,2,'009.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf545337d-e58e-489c-8a76-38eea0efd969\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1973,1,1972,1972,'subsection','Stk. 2.',NULL,'Indflytningsrapporten, jf. stk. 1, skal udleveres til lejeren ved synet, eventuelt i et digitalt dokument, jf. dog § 13, stk. 1. Er lejeren ikke til stede ved synet, eller vil lejeren ikke kvittere for modtagelsen af rapporten, skal rapporten sendes til lejeren senest 2 uger efter synet.',1,3,'009.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1974,1,1972,1972,'subsection','Stk. 3.',NULL,'Ved overtrædelse af stk. 1 og 2 bortfalder udlejerens krav på istandsættelse efter § 187, stk. 1, medmindre kravet skyldes skader, som lejeren er ansvarlig for.',2,3,'009.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1975,1,1968,1968,'paragraph_group',NULL,'Mangler på overtagelsestidspunktet',NULL,3,1,'009.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1976,1,1975,1975,'paragraph','§ 91.',NULL,'Er det lejede mangelfuldt ved lejeforholdets begyndelse, skal lejeren for ikke at miste retten til at påberåbe sig manglen, jf. §§ 95-97, senest 2 uger efter lejeforholdets begyndelse meddele udlejeren, at lejeren vil gøre den gældende. Dette gælder dog ikke, hvis manglen ikke kan erkendes ved anvendelse af sædvanlig agtpågivenhed eller udlejeren har handlet svigagtigt.',1,2,'009.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id1b80dfc9-93da-4f1f-bb5c-d475541fabfa\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1977,1,1968,1968,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,4,1,'009.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1978,1,1977,1977,'paragraph','§ 92.',NULL,'Uenighed om, hvorvidt det lejede er mangelfuldt ved lejeforholdets begyndelse, afgøres af huslejenævnet.',1,2,'009.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id5e10fd01-f92f-45ea-9605-9ff25a2c5c95\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1979,1,1978,1978,'subsection','Stk. 2.',NULL,'Huslejenævnet kan pålægge udlejeren at udbedre manglen.',1,3,'009.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1980,1,1968,1968,'paragraph_group',NULL,'Fravigelighed',NULL,5,1,'009.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1981,1,1980,1980,'paragraph','§ 93.',NULL,'§§ 90-92 kan ikke ved aftale fraviges til skade for lejeren.',1,2,'009.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ida0e021a0-65b2-4d54-ab78-f9674fd2d4fd\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1982,1,NULL,0,'chapter','Kapitel 10','Mangler ved boligen',NULL,10,0,'010',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1983,1,1982,1982,'paragraph_group',NULL,'Forsinkelse',NULL,1,1,'010.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1984,1,1983,1983,'paragraph','§ 94.',NULL,'Er det lejede ikke fuldført på det tidspunkt, hvor lejeren efter aftalen skal overtage lejemålet, eller er den tidligere lejer ikke fraflyttet på overtagelsestidspunktet, eller foreligger der en anden hindring for lejerens overtagelse af det lejede til den aftalte tid, uden at dette skyldes lejerens forhold, kan lejeren kræve et forholdsmæssigt afslag i lejen.',1,2,'010.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id84bd28d1-0831-4c2e-be7f-dad21c16db8b\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1985,1,1984,1984,'subsection','Stk. 2.',NULL,'Lejeren kan hæve lejeaftalen ved væsentlig forsinkelse i de tilfælde, som er omtalt i stk. 1, medmindre forsinkelsen af udlejeren måtte forudsættes ikke at være af væsentlig betydning for lejeren. Retten til at hæve lejeaftalen er betinget af, at lejeren, efter at forsinkelsen er indtrådt, har fremsat påkrav over for udlejeren, og at lejerens overtagelse ikke kan ske inden rimelig tid derefter. Er det lejede ikke fuldført ved lejeaftalens indgåelse, og er overtagelsestidspunktet ikke aftalt, kan lejeren til enhver tid inden overtagelsen hæve aftalen. Lejeaftalen kan dog altid hæves ved enhver forsinkelse, hvis lejeren udtrykkeligt har betinget sig overtagelse af lokalerne til et bestemt tidspunkt.',1,3,'010.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1986,1,1984,1984,'subsection','Stk. 3.',NULL,'Uanset om lejeren hæver lejeaftalen, kan lejeren i de tilfælde, hvor den tidligere lejer ikke er fraflyttet, kræve erstatning, medmindre udlejeren godtgør, at forsinkelsen ikke skyldes noget forhold, som udlejeren er ansvarlig for.',2,3,'010.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1987,1,1982,1982,'paragraph_group',NULL,'Fysiske mangler ved det lejede',NULL,2,1,'010.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1988,1,1987,1987,'paragraph','§ 95.',NULL,'Er det lejede ikke ved overtagelsen og under lejeforholdets bestående i den stand, som lejeren efter retsforholdet mellem lejeren og udlejeren kan kræve, og afhjælper udlejeren ikke straks manglen efter påkrav derom, kan lejeren selv afhjælpe den for udlejerens regning. Vedrører manglen det lejedes forsyning med lys, gas, varme, kulde el.lign., kan lejeren ved fogedens bistand skaffe sig adgang til ejendommens installationer for at afhjælpe manglen. 1. og 2. pkt. finder tilsvarende anvendelse, hvis udlejeren uberettiget har afbrudt det lejedes forsyning med lys, gas, varme, kulde el.lign. Hvis manglen vedrører det lejedes forsyning med varme, opvarmning af brugsvand, el eller vand, kan lejeren rette henvendelse til kommunen med henblik på at få genoptaget forsyningen efter reglerne i kapitel 3 om kommunal sikring af forsyning med vand, varme og el i lov om boligforhold.',1,2,'010.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idcfc22a8f-a039-432c-9852-464c7a803512\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1989,1,1988,1988,'subsection','Stk. 2.',NULL,'Lejeren kan kræve et forholdsmæssigt afslag i lejen, så længe en mangel forringer det lejedes værdi for lejeren.',1,3,'010.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1990,1,1987,1987,'paragraph','§ 96.',NULL,'Er det lejede mangelfuldt som nævnt i § 95, og afhjælper udlejeren ikke straks manglen, eller kan den ikke afhjælpes inden for en rimelig tid, kan lejeren hæve lejeaftalen, hvis manglen må anses for væsentlig eller udlejeren har handlet svigagtigt.',2,2,'010.002.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idfdf2246f-d540-4153-bac9-5db8300a35d4\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1991,1,1990,1990,'subsection','Stk. 2.',NULL,'Er manglen afhjulpet, inden lejeren har hævet lejeaftalen, kan lejeren ikke senere påberåbe sig manglen som grund for ophævelse.',1,3,'010.002.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1992,1,1987,1987,'paragraph','§ 97.',NULL,'Lejeren kan kræve erstatning, hvis det lejede ved aftalens indgåelse savnede egenskaber, som må anses for tilsikrede, eller udlejeren har handlet svigagtigt. Det samme gælder, hvis det lejede senere lider skade som følge af udlejerens forsømmelse eller der i øvrigt opstår hindringer eller ulemper for lejerens brugsret som følge af forhold, som udlejeren er ansvarlig for.',3,2,'010.002.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id19d1fd60-f866-4ab0-9e2c-41f51a77873d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1993,1,1987,1987,'paragraph','§ 98.',NULL,'Bliver det lejede ødelagt ved brand eller anden ulykke, bortfalder aftalen.',4,2,'010.002.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id091d02c7-522a-442f-bd55-069db9b0022f\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1994,1,1982,1982,'paragraph_group',NULL,'Retlige mangler',NULL,3,1,'010.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1995,1,1994,1994,'paragraph','§ 99.',NULL,'Er brugen af det lejede helt eller delvis i strid med lovgivning, andre offentlige forskrifter eller servitutter eller andre lignende rettigheder over ejendommen, som var gældende ved lejeaftalens indgåelse, kan lejeren kræve et forholdsmæssigt afslag i lejen og erstatning. Lejeren kan endvidere hæve lejeaftalen, såfremt brugen indskrænkes væsentligt eller udlejeren har handlet svigagtigt.',1,2,'010.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ida40708a0-9000-482b-80ab-914d42ff1fe3\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1996,1,1995,1995,'subsection','Stk. 2.',NULL,'Stk. 1 gælder ikke, hvis lejeren vidste, at brugen var retsstridig, og heller ikke, hvis lejerens ukendskab skyldes grov uagtsomhed. Endvidere finder stk. 1 ikke anvendelse, hvis det retsstridige forhold ikke har medført nogen indskrænkninger i lejerens brugsret og udlejeren efter opfordring straks bringer forholdet i orden.',1,3,'010.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1997,1,1995,1995,'subsection','Stk. 3.',NULL,'Er det lejede mangelfuldt efter stk. 1, skal lejeren for ikke at miste retten til at påberåbe sig manglen senest 2 uger efter lejeforholdets begyndelse meddele udlejeren, at lejeren vil gøre den gældende. Dette gælder dog ikke, hvis manglen ikke kan erkendes ved anvendelse af sædvanlig agtpågivenhed eller udlejeren har handlet svigagtigt.',2,3,'010.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1998,1,1994,1994,'paragraph','§ 100.',NULL,'Bringes et lejeforhold bortset fra de i § 99 nævnte tilfælde til ophør i utide på grund af andre rettigheder over ejendommen, kan lejeren kræve erstatning af udlejeren.',2,2,'010.003.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id51d01305-5635-46ce-9d53-f68e67536c06\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(1999,1,1998,1998,'subsection','Stk. 2.',NULL,'Bringes lejeforholdet til ophør i utide, fordi det offentlige af sundhedsmæssige eller andre grunde nedlægger forbud mod lejerens brug, er lejeren kun pligtig at betale leje indtil den dag, forbuddet træder i kraft. Hvis forbuddet kun begrænser brugen på mindre væsentlig måde, kan lejeren dog kun kræve et forholdsmæssigt afslag i lejen.',1,3,'010.003.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2000,1,1982,1982,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'010.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2001,1,2000,2000,'paragraph','§ 101.',NULL,'§§ 94-100 kan ikke ved aftale fraviges til skade for lejeren.',1,2,'010.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id46c08670-becf-4e70-8b8a-cf1d5de370f6\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2002,1,NULL,0,'chapter','Kapitel 11','Varsling af iværksættelse af arbejder',NULL,11,0,'011',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2003,1,2002,2002,'paragraph_group',NULL,'Udlejerens adgang til det lejede',NULL,1,1,'011.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2004,1,2003,2003,'paragraph','§ 102.',NULL,'Udlejeren eller dennes stedfortræder har ret til at få eller skaffe sig adgang til det lejede, når forholdene kræver det.',1,2,'011.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ida01858d2-1ad0-49c8-8723-daf37b51ad4f\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2005,1,2003,2003,'paragraph','§ 103.',NULL,'Udlejeren kan med 6 ugers varsel iværksætte arbejder i det lejede, når udførelsen ikke er til væsentlig ulempe for lejeren.',2,2,'011.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id83200b5c-79e3-44f1-a6ef-bcd2c76e6dd6\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2006,1,2005,2005,'subsection','Stk. 2.',NULL,'Inden iværksættelse af andre arbejder har lejeren krav på 3 måneders varsel.',1,3,'011.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2007,1,2005,2005,'subsection','Stk. 3.',NULL,'Udlejeren kan dog altid uden varsel foretage uopsættelige reparationer i det lejede.',2,3,'011.001.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2008,1,2002,2002,'paragraph_group',NULL,'Arbejdernes udførelse',NULL,2,1,'011.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2009,1,2008,2008,'paragraph','§ 104.',NULL,'Ethvert arbejde, der iværksættes af udlejeren, skal udføres uden afbrydelse og med den størst mulige hensyntagen til lejeren. Udlejeren skal straks foretage efterreparationer.',1,2,'011.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id3fbeb25f-57c5-4b21-a944-7e36adf6c594\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2010,1,2008,2008,'paragraph','§ 105.',NULL,'Inden udlejeren i ejendomme omfattet af § 6, stk. 1, og § 7, stk. 3, 3. pkt., iværksætter en forbedring, der vil medføre en lejeforhøjelse, der sammen med forbedringsforhøjelser gennemført i de sidste 3 år vil udgøre mere end 100 kr. pr. m² bruttoetageareal pr. år, skal udlejeren fremsætte skriftligt varsel herom over for de lejere, hvis lejeforhold ønskes forbedret. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',2,2,'011.002.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id38ef5665-ed95-4ea8-a291-8e46b63ab65a\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2011,1,2010,2010,'subsection','Stk. 2.',NULL,'I ejendomme med beboerrepræsentation skal udlejeren fremsætte tilsvarende varsel efter stk. 1 over for beboerrepræsentanterne.',1,3,'011.002.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2012,1,2010,2010,'subsection','Stk. 3.',NULL,'Varsling i henhold til stk. 1 og 2 skal indeholde en beskrivelse af arbejdet med overslag over udgifterne og den forventede størrelse af den lejeforhøjelse, der er en følge af forbedringens gennemførelse. Varslingen skal endvidere indeholde oplysning om beboerrepræsentationens eller i ejendomme uden beboerrepræsentation lejernes adgang til at gøre indsigelse, jf. stk. 4. I ejendomme med beboerrepræsentation skal lejerne tillige have oplysning om, at kravet samtidig er forelagt for beboerrepræsentanterne. Indeholder varslingen ikke disse oplysninger, er den ugyldig.',2,3,'011.002.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2013,1,2010,2010,'subsection','Stk. 4.',NULL,'Har beboerrepræsentationen, eller i ejendomme uden beboerrepræsentation mindst en fjerdedel af lejerne, senest 6 uger efter at varslingsskrivelsen er kommet frem til dem, skriftligt fremsat indsigelse mod iværksættelsen af en forbedring som nævnt i stk. 1, skal udlejeren inden yderligere 6 uger indbringe sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om forbedringen.',3,3,'011.002.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2014,1,2008,2008,'paragraph','§ 106.',NULL,'Vil en forbedring medføre en lejeforhøjelse, der sammen med lejeforhøjelser for forbedringer gennemført i de sidste 3 år vil udgøre mere end 199 kr. pr. m² bruttoetageareal pr. år, skal udlejeren i ejendomme omfattet af § 6, stk. 1, og § 7, stk. 3, 3. pkt., senest 3 måneder før forbedringens iværksættelse underrette lejeren om, at denne kan kræve at få tilbudt anden passende bolig inden udløbet af den i stk. 2 nævnte frist. Beløbet i 1. pkt. er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',3,2,'011.002.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id9eabd0c4-95a5-4744-a506-9e7c13564493\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2015,1,2014,2014,'subsection','Stk. 2.',NULL,'Fremsætter lejeren senest 6 uger efter varslingen efter stk. 1 krav om at få tilbudt anden passende bolig, skal udlejeren inden forbedringens iværksættelse tilbyde lejeren en bolig af passende størrelse, beliggenhed, kvalitet og udstyr og til en leje, der efter fradrag af eventuel boligstøtte ikke afviger væsentligt fra den hidtidige leje. Lejligheden har en passende størrelse, når den har samme værelsesantal som lejerens hidtidige lejlighed eller den har et værelse mere end antallet af husstandsmedlemmer.',1,3,'011.002.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2016,1,2014,2014,'subsection','Stk. 3.',NULL,'Såfremt lejeren gør indsigelse, fordi denne finder, at udlejerens tilbud om anden bolig ikke opfylder betingelserne i stk. 2, skal udlejeren indbringe spørgsmålet for huslejenævnet.',2,3,'011.002.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2017,1,2014,2014,'subsection','Stk. 4.',NULL,'Over for en lejer, der ikke har fået underretning efter stk. 1 om sin ret til at kræve anden bolig, kan lejeforhøjelse som følge af forbedringen ikke gennemføres ud over den i stk. 1 angivne grænse. Tilsvarende gælder, hvis udlejeren ikke overholder forpligtelserne efter stk. 2 og 3.',3,3,'011.002.003.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2018,1,2008,2008,'paragraph','§ 107.',NULL,'Når forbedringen alene omfatter foranstaltninger, der er påbudt i henhold til lov, arbejder, der er gennemført i medfør af § 146, eller foranstaltninger, der er omfattet af den tidligere gældende lov om byfornyelse og boligforbedring, jf. lovbekendtgørelse nr. 658 af 11. august 1993, af kapitel 5 i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003, eller af den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, finder reglerne i §§ 105 og 106 ikke anvendelse.',4,2,'011.002.004','{\"source_class\":\"Paragraf\",\"source_id\":\"ida1fdadce-e94a-436b-a808-fc7682f7244f\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2019,1,2002,2002,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,3,1,'011.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2020,1,2019,2019,'paragraph','§ 108.',NULL,'Huslejenævnet træffer afgørelse i tvister efter dette kapitel.',1,2,'011.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id66b1d8c9-aeaa-4936-8393-c5acdd188100\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2021,1,2020,2020,'subsection','Stk. 2.',NULL,'Udfører udlejeren ikke et påbegyndt forbedringsarbejde med den fornødne hurtighed, jf. § 104, kan huslejenævnet fastsætte en tidsfrist for arbejdets fuldførelse.',1,3,'011.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2022,1,2019,2019,'paragraph','§ 109.',NULL,'Indbringes sag om iværksættelse af forbedringer efter § 105, kan huslejenævnet modsætte sig iværksættelsen, hvis forbedringen må anses for uhensigtsmæssig under hensyn til ejendommens alder, beliggenhed og beskaffenhed. Det samme gælder, hvis forbedringen ikke skønnes at medføre en passende forøgelse af brugsværdien under hensyn til ejendommens og de pågældende rums karakter, tilstand, indretning og udstyr. Det kan herved tages i betragtning, om ændringer, som foranstaltningerne vil medføre i de enkelte udlejede rum, skønnes rimelige i forhold til disses hidtidige hensigtsmæssige anvendelse.',2,2,'011.003.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id932a4c89-7ca0-4fd2-9acc-30e240f6e71d\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2023,1,2022,2022,'subsection','Stk. 2.',NULL,'Såfremt udlejeren iværksætter en forbedring, som nævnet har modsat sig, kan udlejeren ikke kræve lejeforhøjelse for forbedringen.',1,3,'011.003.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2024,1,2022,2022,'subsection','Stk. 3.',NULL,'Indbringelse efter §§ 89 eller 90 i lov om boligforhold af en afgørelse, hvorved nævnet har tiltrådt iværksættelse af en forbedring, har opsættende virkning.',2,3,'011.003.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2025,1,2002,2002,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'011.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2026,1,2025,2025,'paragraph','§ 110.',NULL,'Dette kapitel kan ikke ved aftale fraviges til skade for lejeren.',1,2,'011.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id715b02f4-3c0a-4432-a589-389749b61d99\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2027,1,NULL,0,'chapter','Kapitel 12','Vedligeholdelse',NULL,12,0,'012',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2028,1,2027,2027,'paragraph_group',NULL,'Vedligeholdelsesbegreberne',NULL,1,1,'012.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2029,1,2028,2028,'paragraph','§ 111.',NULL,'Ved vedligeholdelse forstås de reparationer og udskiftninger, som udføres med henblik på at bevare og opretholde lejemålets og ejendommens stand, efterhånden som der sker forringelse ved slid og ælde.',1,2,'012.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf6078b0a-c045-4c6f-bf14-8cbf5cd72e96\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2030,1,2029,2029,'subsection','Stk. 2.',NULL,'Ved indvendig vedligeholdelse forstås vedligeholdelse af lejligheden med hvidtning, maling, tapetsering og behandling af gulve.',1,3,'012.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2031,1,2029,2029,'subsection','Stk. 3.',NULL,'Ved udvendig vedligeholdelse forstås vedligeholdelse af alle dele af ejendommen og det lejede, som ikke er omfattet af den indvendige vedligeholdelse.',2,3,'012.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2032,1,2027,2027,'paragraph_group',NULL,'Parternes vedligeholdelsespligt',NULL,2,1,'012.002',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2033,1,2032,2032,'paragraph','§ 112.',NULL,'Vedligeholdelse, herunder såvel indvendig som udvendig vedligeholdelse, jf. stk. 2, som følge af forringelse ved slid og ælde skal foretages, så ofte det er påkrævet under hensyn til ejendommens og det lejedes karakter, jf. dog § 117.',1,2,'012.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idaedf61d9-6e16-434c-b86f-ff9e25e2fc00\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2034,1,2033,2033,'subsection','Stk. 2.',NULL,'Udlejeren skal holde ejendommen og det lejede forsvarligt ved lige, herunder vedligeholde alle indretninger til afløb og til forsyning med el, gas, vand, varme og kulde, og sørge for renholdelse og sædvanlig belysning af ejendommen og adgangsvejene til det lejede, ligesom udlejeren skal renholde fortov, gård og andre fælles indretninger.',1,3,'012.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2035,1,2033,2033,'subsection','Stk. 3.',NULL,'Lejeren skal i lejeperioden foretage vedligeholdelse og fornøden fornyelse af låse og nøgler.',2,3,'012.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2036,1,2027,2027,'paragraph_group',NULL,'Vedligeholdelsesplan',NULL,3,1,'012.003',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2037,1,2036,2036,'paragraph','§ 113.',NULL,'Udlejeren skal hvert år inden den 1. juli udarbejde en plan for ejendommens vedligeholdelse i den kommende 10-årsperiode. Planen skal omfatte større vedligeholdelsesarbejder på ejendommen. I ejendomme med beboerrepræsentation skal udlejeren indkalde beboerrepræsentationen til møde med henblik på udarbejdelse og revision af vedligeholdelsesplanen.',1,2,'012.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id8543cbfe-6227-49df-ba9f-0a211791a3ba\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2038,1,2037,2037,'subsection','Stk. 2.',NULL,'Udlejeren mister retten til at opkræve beløb efter §§ 119 og 120, hvis udlejeren ikke har udarbejdet en vedligeholdelsesplan for ejendommen i overensstemmelse med stk. 1 og lejerne har indbragt sag herom for huslejenævnet. Udlejeren kan ikke opkræve de nævnte beløb fra lejernes indbringelse af sag for huslejenævnet, indtil en vedligeholdelsesplan er udarbejdet og udleveret til lejerne.',1,3,'012.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2039,1,2037,2037,'subsection','Stk. 3.',NULL,'Stk. 1 gælder ikke for ejendomme omfattet af § 3 b i lov om andelsboligforeninger og andre boligfællesskaber.',2,3,'012.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2040,1,2037,2037,'subsection','Stk. 4.',NULL,'Indenrigs- og boligministeren fastsætter nærmere regler om udarbejdelse af vedligeholdelsesplaner.',3,3,'012.003.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2041,1,2027,2027,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,4,1,'012.004',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2042,1,2041,2041,'paragraph','§ 114.',NULL,'Huslejenævnet træffer afgørelse i tvister om opfyldelse af henholdsvis lejerens og udlejerens pligt til renholdelse og vedligeholdelse, jf. § 112. Huslejenævnet træffer endvidere afgørelse i tvister om udarbejdelse og gennemførelse af vedligeholdelsesplaner, jf. § 113.',1,2,'012.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id4c62c19b-7aee-44ad-80f7-2a7c1df155bb\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2043,1,2042,2042,'subsection','Stk. 2.',NULL,'Huslejenævnet kan på lejerens begæring pålægge udlejeren at lade bestemte arbejder udføre og kan fastsætte nærmere retningslinjer herom. Huslejenævnet skal fastsætte en tidsfrist for det enkelte arbejdes fuldførelse. Huslejenævnet kan samtidig bestemme, at lejen skal nedsættes med et beløb, der svarer til forringelsen af det lejedes værdi, hvis udlejeren ikke overholder den frist, der er fastsat efter 2. pkt. Lejenedsættelsen gælder, indtil arbejderne er udført eller huslejenævnet beslutter, at ejendommen skal administreres på ejerens vegne, jf. kapitel 5 i lov om boligforhold. Grundejernes Investeringsfond kan træffe beslutning om at iværksætte arbejderne på udlejerens vegne, jf. § 70, stk. 1, i lov om boligforhold.',1,3,'012.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2044,1,2042,2042,'subsection','Stk. 3.',NULL,'Huslejenævnet kan give påbud efter stk. 2, uanset om udgifterne kan afholdes af indestående på konti efter §§ 119 og 120.',2,3,'012.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2045,1,2027,2027,'paragraph_group',NULL,'Fravigelighed',NULL,5,1,'012.005',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2046,1,2045,2045,'paragraph','§ 115.',NULL,'§§ 111, 113 og 114 kan ikke fraviges ved aftale. § 112 kan ikke ved aftale fraviges til skade for lejeren bortset fra aftale om, at lejeren overtager pligten til vedligeholdelse. Det kan ikke aftales, at lejeren ved fraflytning skal istandsætte andet end de dele af det lejede, som er omfattet af lejerens vedligeholdelsespligt.',1,2,'012.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd547aeb4-fc38-4199-8677-8d3fd41489c6\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2047,1,2046,2046,'subsection','Stk. 2.',NULL,'§ 112, stk. 2, kan ikke fraviges til skade for lejeren, for så vidt angår udvendig vedligeholdelse, i ejendomme omfattet af § 6, stk. 1. Det kan dog aftales, at lejeren skal vedligeholde den have, som indgår i det lejede.',1,3,'012.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2048,1,NULL,0,'chapter','Kapitel 13','Hensættelser til vedligeholdelse',NULL,13,0,'013',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2049,1,2048,2048,'paragraph_group',NULL,'Indvendig vedligeholdelseskonto',NULL,1,1,'013.001',NULL,'2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2050,1,2049,2049,'paragraph','§ 116.',NULL,'Når en lejlighed er udlejet helt eller delvis til beboelse, anses udlejerens pligt til indvendig vedligeholdelse for opfyldt, når udlejeren til dette formål løbende har afholdt de beløb, der skal anvendes hertil efter reglerne i §§ 117 og 118. Omfatter en lejeaftale såvel lokaler, der er udlejet til beboelse, som lokaler, der udelukkende er udlejet til andet end beboelse, og er lokalerne beliggende i hver sin fysiske enhed, finder 1. pkt. kun anvendelse, for så vidt angår den del af det lejede, der er udlejet til beboelse.',1,2,'013.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ide85f113c-d96b-4de0-8a29-67f8e69672fc\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2051,1,2049,2049,'paragraph','§ 117.',NULL,'Udlejeren skal i hvert regnskabsår afsætte 46 kr. pr. m² bruttoareal på en vedligeholdelseskonto for lejligheden til opfyldelse af den indvendige vedligeholdelsespligt. Beløbene afsættes med 1/12 månedsvis. Det i 1. pkt. nævnte beløb er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',2,2,'013.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id652f9e80-3ad6-4554-b5f1-491bacfcaea4\"}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2052,1,2051,2051,'subsection','Stk. 2.',NULL,'Har lejeren ved aftale delvis overtaget pligten til indvendig vedligeholdelse, nedsættes det beløb, der afsættes på vedligeholdelseskontoen, forholdsmæssigt.',1,3,'013.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:16','2026-03-30 23:41:16'),
(2053,1,2051,2051,'subsection','Stk. 3.',NULL,'Når udlejeren har afholdt udgift til indvendig vedligeholdelse og til anden vedligeholdelse efter § 118, stk. 2, kan udlejeren fradrage udgiften på vedligeholdelseskontoen. Udlejeren skal samtidig give lejeren en skriftlig opgørelse over de afholdte udgifter og oplysning om, hvilket beløb der herefter er til rådighed. Lejeren kan kræve dokumentation for de afholdte vedligeholdelsesudgifter.',2,3,'013.001.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2054,1,2051,2051,'subsection','Stk. 4.',NULL,'Inden 3 måneder efter hvert regnskabsårs afslutning skal udlejeren give lejeren skriftlig meddelelse om, hvilket beløb der ved regnskabsårets afslutning var til rådighed til lejlighedens vedligeholdelse. En negativ saldo skal ansættes til nul.',3,3,'013.001.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2055,1,2051,2051,'subsection','Stk. 5.',NULL,'Undlader udlejeren at efterkomme en anmodning fra huslejenævnet om inden et fastsat tidspunkt at fremlægge regnskaber med bilag for de sidste 5 år, kan lejeren kræve lagt til grund, at der på kontoen mindst henstår et beløb svarende til periodens hensættelse uden fradrag for afholdte udgifter til vedligeholdelse.',4,3,'013.001.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2056,1,2051,2051,'subsection','Stk. 6.',NULL,'Ved genudlejning skal vedligeholdelseskontoen videreføres, og udlejeren skal oplyse den nye lejer om, hvilket beløb der ved lejeforholdets begyndelse er til rådighed til vedligeholdelse.',5,3,'013.001.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2057,1,2051,2051,'subsection','Stk. 7.',NULL,'Ved ejerskifte overtager den nye udlejer vedligeholdelsespligten og viderefører vedligeholdelseskontoen.',6,3,'013.001.002.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2058,1,2049,2049,'paragraph','§ 118.',NULL,'Lejeren kan kræve, at udlejeren foretager indvendig vedligeholdelse, når det er nødvendigt, og udgiften kan afholdes af det beløb, der er til rådighed på vedligeholdelseskontoen.',3,2,'013.001.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id94db4ea5-d311-451e-98e5-ccb2f8b33171\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2059,1,2058,2058,'subsection','Stk. 2.',NULL,'Lejeren kan endvidere kræve, at det beløb, hvormed saldoen på vedligeholdelseskontoen overstiger et beløb svarende til de seneste 3 års samlede hensættelser, anvendes til andre rimelige og hensigtsmæssige vedligeholdelsesarbejder i lejligheden. Det er dog en betingelse, at lejligheden fremtræder i velvedligeholdt stand, for så vidt angår indvendig vedligeholdelse.',1,3,'013.001.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2060,1,2058,2058,'subsection','Stk. 3.',NULL,'Er lejeaftalen opsagt af en af parterne, kan lejeren ikke fremsætte krav efter stk. 1 og 2.',2,3,'013.001.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2061,1,2048,2048,'paragraph_group',NULL,'Udvendige vedligeholdelseskonti',NULL,2,1,'013.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2062,1,2061,2061,'paragraph','§ 119.',NULL,'Udlejeren skal som et led i opfyldelsen af sin pligt til at vedligeholde ejendommen afsætte det beløb, der blev afsat eller skulle være afsat efter den tidligere gældende § 18 i lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 962 af 11. august 2010, pr. 31. december 2014. Beløbet efter 1. pkt. reguleres én gang årligt, jf. § 204, stk. 2.',1,2,'013.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd2e1f209-c405-4106-9a5f-4d505e065ea1\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2063,1,2062,2062,'subsection','Stk. 2.',NULL,'Har ejendommen lejligheder og lokaler, der ikke er omfattet af reglerne om udvendige vedligeholdelseskonti i dette kapitel, skal der for sådanne lokaler afsættes samme beløb pr. kvadratmeter på vedligeholdelseskontoen, som afsættes af lejen for beboelseslejligheder. For private andelsboligforeninger skal der kun afsættes beløb på vedligeholdelseskontoen for lejligheder og lokaler, der er udlejet af andelsboligforeningen.',1,3,'013.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2064,1,2062,2062,'subsection','Stk. 3.',NULL,'Udlejeren af en ejendom, der ikke er omfattet af § 120, skal udarbejde et særskilt årsregnskab for vedligeholdelsesudgifterne fordelt på de enkelte arbejder eller kategorier af arbejder. En positiv eller negativ saldo overføres til det følgende regnskabsår. Udlejeren skal indsende årsregnskabet til Grundejernes Investeringsfond.',2,3,'013.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2065,1,2061,2061,'paragraph','§ 120.',NULL,'I ejendomme taget i brug før 1970, som har mere end to beboelseslejligheder, skal udlejeren ud over de beløb, der er nævnt i § 119, årligt afsætte det beløb, der blev afsat eller skulle være afsat efter den tidligere gældende § 18 b i lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 962 af 11. august 2010, pr. 31. december 2014. Beløbet efter 1. pkt. reguleres én gang årligt, jf. § 204, stk. 2. Beløbet indsættes på en konto for ejendommen i Grundejernes Investeringsfond, jf. § 60 i lov om boligforhold.',2,2,'013.002.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id8633b622-6475-4b5e-ba53-548322ef78a8\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2066,1,2065,2065,'subsection','Stk. 2.',NULL,'Stk. 1 finder tilsvarende anvendelse, hvor afsættelse sker efter § 211.',1,3,'013.002.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2067,1,2065,2065,'subsection','Stk. 3.',NULL,'Det indbetalte beløb kan ikke gøres til genstand for kreditorforfølgning og kan kun udbetales efter reglerne i § 122 og § 63 i lov om boligforhold.',2,3,'013.002.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2068,1,2065,2065,'subsection','Stk. 4.',NULL,'Bestemmelsen i stk. 1 finder ikke anvendelse på ejendomme, som af vurderingsmyndighederne er vurderet som landbrugs- eller skovejendom, jf. ejendomsvurderingslovens § 3, stk. 1, nr. 2 og 3.',3,3,'013.002.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2069,1,2048,2048,'paragraph_group',NULL,'Fradrag og udbetaling fra udvendige vedligeholdelseskonti',NULL,3,1,'013.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2070,1,2069,2069,'paragraph','§ 121.',NULL,'På kontoen efter §§ 119 og 120 kan fradrages beløb, der er anvendt til opfyldelsen af udlejerens pligt til udvendig vedligeholdelse, jf. § 111, stk. 3. Endvidere kan der med tilslutning fra beboerrepræsentanterne eller et flertal af lejerne fradrages beløb, der er anvendt til forbedring.',1,2,'013.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idbd4e9f54-938b-4f7f-a4d9-36fb18187ffa\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2071,1,2070,2070,'subsection','Stk. 2.',NULL,'Dækkes en udgift ved optagelse af lån, er udlejeren berettiget til i stedet for at fradrage udgiften at fradrage de årlige prioritetsydelser på kontoen, efterhånden som disse betales.',1,3,'013.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2072,1,2069,2069,'paragraph','§ 122.',NULL,'Beløb indbetalt på en konto efter § 120 kan udbetales, når udlejeren dokumenterer, at et tilsvarende beløb er anvendt til ejendommens udvendige vedligeholdelse, til forbedring eller til ydelser på lån til de nævnte formål, jf. § 121, stk. 2, jf. dog stk. 4. Der bortses fra den del af udgiften, hvortil tilskud er ydet efter anden lovgivning.',2,2,'013.003.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id88947fc8-e071-48df-9fb2-875d255d65a5\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2073,1,2072,2072,'subsection','Stk. 2.',NULL,'Senest samtidig med at udlejeren kræver beløb udbetalt efter stk. 1, skal beboerrepræsentanterne eller lejerne have underretning om, hvilke udgifter der er afholdt, og hvilket beløb der kræves udbetalt.',1,3,'013.003.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2074,1,2072,2072,'subsection','Stk. 3.',NULL,'Beløb indsat på en konto efter § 120 kan udbetales, medmindre beboerrepræsentanterne eller et flertal af lejerne protesterer mod udbetalingen inden 6 uger efter modtagelsen af underretningen efter stk. 2. Såfremt enighed ikke kan opnås mellem udlejeren og beboerrepræsentanterne eller et flertal af lejerne, skal udlejeren indbringe sagen for huslejenævnet, såfremt udlejeren ønsker at fastholde kravet om udbetaling efter stk. 1.',2,3,'013.003.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2075,1,2072,2072,'subsection','Stk. 4.',NULL,'Det er en betingelse for udbetaling efter stk. 1, at udlejeren dokumenterer, at indestående beløb på ejendommens konto efter § 119 er opbrugt.',3,3,'013.003.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2076,1,2048,2048,'paragraph_group',NULL,'Fritagelse for afsættelse efter § 120',NULL,4,1,'013.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2077,1,2076,2076,'paragraph','§ 123.',NULL,'Grundejernes Investeringsfond kan fritage ejeren af en ejendom for afsættelse efter § 120 for den del af ejendommen, der udelukkende anvendes til andet end beboelse.',1,2,'013.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id6041bc22-f684-4feb-a250-e089aa35b9f6\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2078,1,2077,2077,'subsection','Stk. 2.',NULL,'Grundejernes Investeringsfonds afgørelse efter stk. 1 kan indbringes for huslejenævnet.',1,3,'013.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2079,1,2077,2077,'subsection','Stk. 3.',NULL,'Indenrigs- og boligministeren kan fastsætte regler for, i hvilket omfang Grundejernes Investeringsfond kan fritage en ejer for afsættelse efter § 120.',2,3,'013.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2080,1,2048,2048,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,5,1,'013.005',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2081,1,2080,2080,'paragraph','§ 124.',NULL,'Tvister om opfyldelse af udlejerens pligt til at føre en indvendig vedligeholdelseskonto og om beløb, der fradrages på kontiene for indvendig og udvendig vedligeholdelse, afgøres af huslejenævnet.',1,2,'013.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id1d17f225-0ae8-4d7d-8ea8-218fe143aa26\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2082,1,2081,2081,'subsection','Stk. 2.',NULL,'Huslejenævnet kan beslutte, at afsættelsesbeløbet efter § 120, stk. 1, skal nedsættes i en periode op til 5 år, såfremt beboerrepræsentanterne eller et flertal af lejerne forlanger det. Beløbet kan bl.a. nedsættes, hvis der på kontoen efter § 120, stk. 1, i forvejen henstår beløb svarende til de seneste 5 års hensættelser, eller hvis ejendommens vedligeholdelsesstand tilsiger, at der i perioden ikke er behov for et større beløb. Beløbet kan ikke nedsættes til et beløb, der er lavere end 15 kr. pr. m² bruttoetageareal.',1,3,'013.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2083,1,2081,2081,'subsection','Stk. 3.',NULL,'Huslejenævnet indsender afgørelser, jf. stk. 2, til Grundejernes Investeringsfond, som lægger dem til grund ved beregningen af det bindingspligtige beløb efter § 120 for den enkelte ejendom.',2,3,'013.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2084,1,2048,2048,'paragraph_group',NULL,'Fravigelighed',NULL,6,1,'013.006',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2085,1,2084,2084,'paragraph','§ 125.',NULL,'§§ 116-118 kan ikke ved aftale fraviges til skade for lejeren. §§ 119-124 kan ikke fraviges.',1,2,'013.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idc7352286-aa3f-42a0-9292-340611231c93\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2086,1,NULL,0,'chapter','Kapitel 14','Udlejerens forbedringer',NULL,14,0,'014',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2087,1,2086,2086,'paragraph_group',NULL,'Udlejerens ændringer af ejendommen og det lejede',NULL,1,1,'014.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2088,1,2087,2087,'paragraph','§ 126.',NULL,'Udlejeren har ret til at foretage ændringer, herunder forbedringer af ejendommen og i det lejede, når ændringerne ikke væsentligt og varigt ændrer det lejedes identitet.',1,2,'014.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idde6f0316-160b-4ffb-9e2b-29f666c9b0a8\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2089,1,2088,2088,'subsection','Stk. 2.',NULL,'Ved installation af varmeanlæg i ejendommen har udlejeren ret til med 6 ugers varsel at råde over de kælder- og loftsrum, der er nødvendige til anlæggets drift, når der anvises lejeren andre rum, der er anvendelige til det aftalte brug. Lejeren kan dog ikke kræve anvist andet rum, hvis den forudsatte anvendelse af rummet må anses for overflødiggjort af installationen.',1,3,'014.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2090,1,2086,2086,'paragraph_group',NULL,'Forbedringer og lejeforhøjelser',NULL,2,1,'014.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2091,1,2090,2090,'paragraph','§ 127.',NULL,'Ved forbedringer forstås foranstaltninger eller installationer, der forøger det lejedes værdi, eller foranstaltninger, som er påbudt ved lov eller offentlige forskrifter, når disse ikke er omfattet af udlejerens vedligeholdelsespligt.',1,2,'014.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd238ed95-12e0-41a7-a06c-fe0e37f8a058\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2092,1,2091,2091,'subsection','Stk. 2.',NULL,'Inden udlejeren iværksætter forbedringer, skal udlejeren iagttage § 131 om inddragelse af beboerrepræsentationen.',1,3,'014.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2093,1,2091,2091,'subsection','Stk. 3.',NULL,'Inden udlejeren iværksætter forbedringer i ejendomme omfattet af § 6, stk. 1, og § 7, stk. 3, 3. pkt., skal udlejeren iagttage §§ 105 og 106 om varsling af iværksættelse.',2,3,'014.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2094,1,2090,2090,'paragraph','§ 128.',NULL,'Har udlejeren forbedret det lejede, kan udlejeren forlange lejen forhøjet med et beløb, der modsvarer forøgelsen af det lejedes værdi.',2,2,'014.002.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id8290bb4c-80c5-49ca-891a-adf607c01fc8\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2095,1,2094,2094,'subsection','Stk. 2.',NULL,'Lejeforhøjelsen skal som udgangspunkt kunne give en passende forrentning af den udgift, der med rimelighed er afholdt til forbedringen, og dække afskrivning og sædvanlige udgifter til vedligeholdelse, administration, forsikring og lign.',1,3,'014.002.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2096,1,2090,2090,'paragraph','§ 129.',NULL,'For arbejder, der medfører energibesparelser for lejerne i ejendommen, kan udlejeren forlange en lejeforhøjelse på grundlag af de samlede udgifter, der med rimelighed er afholdt hertil, dog højst svarende til den besparelse, som arbejderne medfører for lejerne.',3,2,'014.002.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id5ea2e409-f222-41c8-8aff-80a11fb06ce6\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2097,1,2096,2096,'subsection','Stk. 2.',NULL,'Har udlejeren gennemført arbejder efter reglen i § 146, kan udlejeren forlange en lejeforhøjelse, der giver en passende forrentning af den udgift, der med rimelighed er afholdt, og dækker afskrivning og sædvanlige udgifter til vedligeholdelse, administration, forsikring og lign.',1,3,'014.002.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2098,1,2096,2096,'subsection','Stk. 3.',NULL,'Har udlejeren udført foranstaltninger efter den tidligere gældende lov om privat byfornyelse, jf. lovbekendtgørelse nr. 49 af 1. februar 1996 med senere ændringer, eller efter kapitel 5 i den tidligere gældende lov om byfornyelse, jf. lovbekendtgørelse nr. 260 af 7. april 2003, kan udlejeren i stedet for lejeforhøjelse for forbedringerne efter § 128 kræve lejeforhøjelse beregnet og gennemført efter reglerne i den tidligere gældende lov om privat byfornyelse eller i kapitel 5 i den tidligere gældende lov om byfornyelse.',2,3,'014.002.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2099,1,2096,2096,'subsection','Stk. 4.',NULL,'Har en ejendom centralvarme eller varmtvandsinstallation, og tilslutter udlejeren denne til et kollektivt varmeforsyningsanlæg, kan udlejeren forlange, at lejeren over 10 år godtgør udlejeren ejendommens udgifter ved omlægningen med fradrag af besparelsen.',3,3,'014.002.003.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2100,1,2096,2096,'subsection','Stk. 5.',NULL,'Indenrigs- og boligministeren fastsætter nærmere regler til stk. 1 om krav til dokumentation, om betingelserne for at kræve lejeforhøjelse og om forhøjelsens beregning.',4,3,'014.002.003.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2101,1,2086,2086,'paragraph_group',NULL,'Varsling m.v.',NULL,3,1,'014.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2102,1,2101,2101,'paragraph','§ 130.',NULL,'Lejeforhøjelse efter §§ 128 og 129 kan gennemføres med 3 måneders varsel. Lejeforhøjelsen kan dog tidligst få virkning fra det tidspunkt, hvor forbedringen er fuldført.',1,2,'014.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id88f2740e-3c18-44ee-881e-7521fe516503\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2103,1,2102,2102,'subsection','Stk. 2.',NULL,'Kravet om lejeforhøjelse skal fremsættes skriftligt og indeholde oplysning om grunden til lejeforhøjelsen og en beregning af lejeforhøjelsen med oplysning om de afholdte udgifter samt oplysning om lejerens adgang til at gøre indsigelse, jf. stk. 5. Indeholder kravet ikke disse oplysninger, er det ugyldigt.',1,3,'014.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2104,1,2102,2102,'subsection','Stk. 3.',NULL,'Udlejeren kan kræve en foreløbig lejeforhøjelse på grundlag af et overslag over udgifterne og forbeholde sig at fremsætte nyt krav, når byggeregnskabet er afsluttet. Lejen skal reguleres efter byggeregnskabet, når det foreligger.',2,3,'014.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2105,1,2102,2102,'subsection','Stk. 4.',NULL,'Hvis byggeregnskabet ikke er aflagt inden 6 måneder fra det tidspunkt, hvor den foreløbige lejeforhøjelse trådte i kraft, kan huslejenævnet på begæring af en lejer fastsætte en frist, inden for hvilken byggeregnskabet skal aflægges. Er byggeregnskab ikke aflagt inden fristens udløb, bortfalder den foreløbige lejeforhøjelse, medmindre overskridelsen af fristen beror på forhold, som ikke kan lægges udlejeren til last.',3,3,'014.003.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2106,1,2102,2102,'subsection','Stk. 5.',NULL,'Vil lejeren ikke godkende kravet om lejeforhøjelse, skal lejeren fremsætte skriftlig indsigelse, senest 6 uger efter at kravet er kommet frem til lejeren. I ejendomme med beboerrepræsentation kan beboerrepræsentanterne på samtlige lejeres vegne gøre indsigelse mod kravet om lejeforhøjelse, jf. 1. pkt. Udlejeren skal da indbringe sagen for huslejenævnet senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at fastholde kravet om lejeforhøjelse.',4,3,'014.003.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2107,1,2102,2102,'subsection','Stk. 6.',NULL,'For ejendomme omfattet af § 6, stk. 1, finder §§ 38 og 40 også anvendelse for varslede forbedringsforhøjelser.',5,3,'014.003.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2108,1,2102,2102,'subsection','Stk. 7.',NULL,'Er en sag indbragt for huslejenævnet, kan udlejeren, indtil nævnets afgørelse foreligger, oppebære den varslede lejeforhøjelse som en foreløbig lejeforhøjelse. Lejen skal reguleres i overensstemmelse med nævnets afgørelse. Huslejenævnet kan dog bestemme, at udlejeren kun kan oppebære et mindre beløb, indtil nævnet har truffet sin afgørelse.',6,3,'014.003.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2109,1,2101,2101,'paragraph','§ 131.',NULL,'Inden udlejeren i en ejendom med beboerrepræsentation varsler iværksættelse af arbejder, der vil medføre en lejeforhøjelse, som sammen med forbedringsforhøjelser gennemført i de sidste 3 år vil udgøre mere end 63 kr. pr. m² bruttoetageareal pr. år, skal udlejeren med rimeligt varsel skriftligt indkalde beboerrepræsentanterne til et møde med henblik på at orientere om og drøfte de påtænkte forbedringsarbejder, udbudsmateriale og overslag over forbedringsforhøjelsen. Mødet skal afholdes, inden iværksættelse varsles. Forud for mødet skal udlejeren fremsende skriftligt materiale vedrørende forbedringsarbejderne. Det i 1. pkt. nævnte beløb er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',2,2,'014.003.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id1fad526a-bdcf-43c4-ad2e-27ba4ead3ec3\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2110,1,2109,2109,'subsection','Stk. 2.',NULL,'Skal udlejeren ikke varsle iværksættelse af de arbejder, der vil medføre en lejeforhøjelse, men er de øvrige betingelser i stk. 1 opfyldt, skal møde efter stk. 1 afholdes senest 2 uger før forbedringsforhøjelsens varsling.',1,3,'014.003.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2111,1,2109,2109,'subsection','Stk. 3.',NULL,'Hvis arbejderne udbydes i begrænset licitation uden forudgående prækvalifikation, skal udlejeren senest på det i stk. 1 nævnte møde opfordre beboerrepræsentanterne til at pege på mindst én bydende i licitationen. Udlejeren skal skriftligt og med rimeligt varsel indkalde beboerrepræsentanterne til deltagelse i licitationsforretningen.',2,3,'014.003.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2112,1,2109,2109,'subsection','Stk. 4.',NULL,'Overholder udlejeren ikke forpligtelserne efter stk. 1-3, kan lejeforhøjelse ikke opkræves ud over beløbsgrænsen nævnt i stk. 1.',3,3,'014.003.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2113,1,2086,2086,'paragraph_group',NULL,'Forhåndsgodkendelse',NULL,4,1,'014.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2114,1,2113,2113,'paragraph','§ 132.',NULL,'Inden der iværksættes forbedringer, herunder gennemgribende forbedringer efter § 19, stk. 2, og ombygningsarbejder vedrørende sammenlægning af lejligheder, kan huslejenævnet på udlejerens anmodning træffe afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves, hvis ombygningsarbejdet udføres i overensstemmelse med det projektmateriale vedrørende det påtænkte arbejde, som udlejeren skal forelægge huslejenævnet, jf. stk. 4.',1,2,'014.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id9358ec7a-5a5b-4959-a279-3d085279e01c\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2115,1,2114,2114,'subsection','Stk. 2.',NULL,'Inden ejeren af en ejerbolig eller andelshaveren med brugsret til en bestemt beboelseslejlighed træffer beslutning om at udleje boligen, kan huslejenævnet tillige træffe afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves. Denne adgang gælder dog kun for ejere, der ikke ejer andre udlejede ejerboliger, og for andelshavere, der ikke har brugsret til andre udlejede andelsboliger.',1,3,'014.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2116,1,2114,2114,'subsection','Stk. 3.',NULL,'Inden udlejeren iværksætter ombygningsarbejder efter bestemmelsen i § 2, stk. 1, nr. 1-4, i den tidligere gældende lov om privat byfornyelse, og hvis der er foretaget reservation af investeringsramme efter den tidligere gældende lov om privat byfornyelse, kan huslejenævnet på udlejerens anmodning træffe afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves. Huslejenævnet kan forlange dokumentation for, at der er reserveret investeringsramme efter den tidligere gældende lov om privat byfornyelse.',2,3,'014.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2117,1,2114,2114,'subsection','Stk. 4.',NULL,'Samtidig med indbringelse for nævnet efter stk. 1 skal udlejeren fremsende projektmateriale indeholdende arbejdernes art, en angivelse af lejen eller lejeforhøjelsens forventede størrelse og de anslåede udgifter ved arbejdernes gennemførelse til huslejenævnet og de lejere, der berøres af forbedringsarbejdet.',3,3,'014.004.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2118,1,2114,2114,'subsection','Stk. 5.',NULL,'Huslejenævnets afgørelse om forhåndsgodkendelse skal træffes, senest 2 måneder efter at huslejenævnet har modtaget bemærkninger efter § 83, stk. 3, i lov om boligforhold eller svar efter § 84, stk. 4, i lov om boligforhold, eller når fristen for svar efter bestemmelserne er udløbet.',4,3,'014.004.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2119,1,2114,2114,'subsection','Stk. 6.',NULL,'Huslejenævnet kan kun ændre den ved forhåndsgodkendelsen fastsatte leje, hvis der er tale om ændrede forhold.',5,3,'014.004.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2120,1,2113,2113,'paragraph','§ 133.',NULL,'For de enkelte lejemål omfattet af § 2, stk. 1, nr. 1-4, i den tidligere gældende lov om privat byfornyelse, hvor huslejenævnet inden arbejdernes iværksættelse har truffet afgørelse om størrelsen af den leje, der lovligt vil kunne opkræves, afgør nævnet på udlejerens anmodning, når ombygningen er udført, om ombygningsudgifterne står i rimeligt forhold til den opnåede kvalitet. Nævnet afgør ligeledes, om de udførte ombygningsarbejder er omfattet af den i medfør af § 2, stk. 3, i den tidligere gældende lov om privat byfornyelse fastsatte positivliste, og om den af udlejeren beregnede lejeforhøjelse er i overensstemmelse med bestemmelsen i § 5 a i den tidligere gældende lov om privat byfornyelse. Udlejerens anmodning til huslejenævnet skal vedlægges et ombygningsregnskab med oplysning om de afholdte og dokumenterede udgifter og lejestigninger fordelt på de enkelte lejemål attesteret af en registreret eller statsautoriseret revisor.',2,2,'014.004.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id2c975315-a17e-4f71-b321-9efbd2546ca1\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2121,1,2086,2086,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,5,1,'014.005',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2122,1,2121,2121,'paragraph','§ 134.',NULL,'Huslejenævnet træffer afgørelse i tvister om lejeforhøjelse efter reglerne om forbedringer i §§ 128-131.',1,2,'014.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id3ef76efa-42f8-4bdf-834a-4a938d2f2121\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2123,1,2086,2086,'paragraph_group',NULL,'Straf',NULL,6,1,'014.006',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2124,1,2123,2123,'paragraph','§ 135.',NULL,'Med bøde eller fængsel indtil 4 måneder straffes den, som gennemfører forbedringer i en ejendom omfattet af § 6, stk. 1, i strid med reglerne i § 127, stk. 3, § 128, § 129, stk. 1-3, eller § 130 eller med kendskab til det lovstridige forhold finansierer sådanne forbedringer.',1,2,'014.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id06fd3128-3534-4d61-8990-e427cf939650\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2125,1,2124,2124,'subsection','Stk. 2.',NULL,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',1,3,'014.006.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2126,1,2086,2086,'paragraph_group',NULL,'Fravigelighed',NULL,7,1,'014.007',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2127,1,2126,2126,'paragraph','§ 136.',NULL,'Dette kapitel kan ikke fraviges til skade for lejeren, jf. dog stk. 2-4.',1,2,'014.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id362ccfbc-7db1-4f36-b194-b32ee482d6d7\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2128,1,2127,2127,'subsection','Stk. 2.',NULL,'§ 126 og § 130, stk. 1, 1. pkt., kan fraviges ved aftale. § 129, stk. 4, kan ligeledes fraviges ved aftale, for så vidt angår perioden for godtgørelse.',1,3,'014.007.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2129,1,2127,2127,'subsection','Stk. 3.',NULL,'§ 128 i ejendomme, som ikke er omfattet af § 6, stk. 1, kan fraviges ved aftale, for så vidt angår lejeforhøjelsens størrelse.',2,3,'014.007.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2130,1,2127,2127,'subsection','Stk. 4.',NULL,'Kapitlets bestemmelser finder ikke anvendelse ved aftalte forbedringer i henhold til § 137. Varslingsreglerne i § 130 finder ikke anvendelse ved beboerrepræsentanternes tiltrædelse af forbedringer i henhold til § 138.',3,3,'014.007.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2131,1,NULL,0,'chapter','Kapitel 15','Aftalte forbedringer',NULL,15,0,'015',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2132,1,2131,2131,'paragraph_group',NULL,'Individuelt aftalte forbedringer',NULL,1,1,'015.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2133,1,2132,2132,'paragraph','§ 137.',NULL,'Udlejeren og lejeren af en beboelseslejlighed kan, efter at lejeaftale er indgået, indgå aftale om gennemførelse af forbedringsarbejder i lejligheden med en i aftalen nærmere fastsat lejeforhøjelse.',1,2,'015.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id7275bff4-5678-4481-841a-47faaeee7662\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2134,1,2133,2133,'subsection','Stk. 2.',NULL,'Lejeren kan forlange, at udlejeren, forinden aftale indgås, indhenter en forhåndsgodkendelse efter bestemmelserne i § 132, stk. 1. Lejeren kan endvidere anmode Udbetaling Danmark om en udtalelse vedrørende eventuelle boligstøttemæssige konsekvenser af en aftale om lejeforhøjelse efter stk. 1.',1,3,'015.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2135,1,2133,2133,'subsection','Stk. 3.',NULL,'En aftale, jf. stk. 1, er kun gyldig, hvis følgende betingelser er opfyldt:',2,3,'015.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2136,1,2133,2133,'list_item','1)',NULL,'Aftalen skal være skriftlig.',3,3,'015.001.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2137,1,2133,2133,'list_item','2)',NULL,'Det skal udtrykkeligt fremgå af aftalen, at lejeforhøjelsen er aftalt efter nærværende bestemmelse.',4,3,'015.001.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2138,1,2133,2133,'list_item','3)',NULL,'Udlejeren skal, forinden aftale indgås, have orienteret lejeren om muligheden for at indhente forhåndsgodkendelse, jf. stk. 2, 1. pkt., og beregning vedrørende boligstøttemæssige konsekvenser, jf. stk. 2, 2. pkt.',5,3,'015.001.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2139,1,2133,2133,'subsection','Stk. 4.',NULL,'Aftalen bortfalder, når det pågældende lejeforhold ophører.',6,3,'015.001.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2140,1,2131,2131,'paragraph_group',NULL,'Beboerrepræsentanters tiltrædelse af forbedringer',NULL,2,1,'015.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2141,1,2140,2140,'paragraph','§ 138.',NULL,'Beboerrepræsentanterne kan på samtlige lejeres vegne tiltræde forbedringsarbejder, der sammen med forbedringsarbejder, som beboerrepræsentanterne inden for de sidste 3 år har tiltrådt efter denne bestemmelse, medfører lejeforhøjelser, som ikke overstiger 100 kr. pr. m² bruttoetageareal. Det i stk. 1 nævnte beløb er opgjort i 2021-niveau og reguleres én gang årligt, jf. reglerne i § 204, stk. 1.',1,2,'015.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id826d42d1-eea2-498d-a13e-68c39166b348\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2142,1,2141,2141,'subsection','Stk. 2.',NULL,'Beboerrepræsentanterne skal, forinden de tiltræder forbedringsarbejderne, afholde beboermøde til drøftelse af de pågældende forbedringsarbejder, og der skal på beboermødet være flertal blandt de fremmødte beboere for forbedringsarbejdernes gennemførelse. Efter beboermødet skal beboerrepræsentanterne snarest skriftligt meddele samtlige beboere beslutningen og oplyse, at såfremt en fjerdedel af beboerne inden 2 uger efter meddelelsen forlanger det, skal beboerrepræsentanterne foranstalte urafstemning blandt ejendommens beboere, jf. bekendtgørelsen om beboerrepræsentation.',1,3,'015.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2143,1,2131,2131,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,3,1,'015.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2144,1,2143,2143,'paragraph','§ 139.',NULL,'Huslejenævnet træffer afgørelse i tvister om, hvorvidt en aftale i henhold til § 138 om forbedringsarbejder er åbenbart urimelig.',1,2,'015.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id0b039039-5595-4087-b53d-4fd65c99b334\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2145,1,2131,2131,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'015.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2146,1,2145,2145,'paragraph','§ 140.',NULL,'Dette kapitel kan ikke fraviges til skade for lejeren.',1,2,'015.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ide0868548-119a-443e-a7b2-00cb1afa1ed0\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2147,1,NULL,0,'chapter','Kapitel 16','Lejerens ret til at foretage installationer i og forbedringer af det lejede',NULL,16,0,'016',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2148,1,2147,2147,'paragraph_group',NULL,'Lejerens installationsret',NULL,1,1,'016.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2149,1,2148,2148,'paragraph','§ 141.',NULL,'Lejeren må ikke uden udlejerens samtykke foretage ændringer af det lejede eller anbringe andre indretninger eller genstande end de i §§ 142-145 nævnte.',1,2,'016.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idfbf78869-02d9-4e58-9752-fa34ab8237e5\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2150,1,2148,2148,'paragraph','§ 142.',NULL,'Lejeren har ret til at foretage sædvanlige installationer i det lejede, medmindre udlejeren kan godtgøre, at ejendommens el- og afløbskapacitet ikke er tilstrækkelig til installationen. Lejeren skal give meddelelse til udlejeren, inden lejeren foretager installationen.',2,2,'016.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id3a71d55f-d2dc-4c18-a664-42d5ffcfa51d\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2151,1,2150,2150,'subsection','Stk. 2.',NULL,'Lejeren af en beboelseslejlighed eller et værelse til helårsbeboelse har ret til at installere hjælpemidler m.v. i det lejede og efter udlejerens anvisning på ejendommens fællesarealer efter bestemmelserne i lov om social service, hvis kommunalbestyrelsen garanterer for betaling af retableringsudgifter ved lejerens fraflytning. Lejeren skal forudgående skriftligt anmelde de påtænkte installationer m.v. til udlejeren. Lejeren har ret til at lade installationerne udføre, hvis udlejeren ikke har gjort skriftlig begrundet indsigelse senest 6 uger efter lejerens anmeldelse af arbejderne. Udlejeren kan nægte lejeren at lade installationerne på fællesarealerne udføre, hvis de er til væsentlig ulempe for ejendommen eller de øvrige lejere.',1,3,'016.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2152,1,2150,2150,'subsection','Stk. 3.',NULL,'Lejeren er erstatningsansvarlig for skade, der er forårsaget af de installationer, lejeren har foretaget. Udlejeren kan kræve, at lejeren ved forsikring eller på anden måde stiller fornøden sikkerhed for opfyldelsen af erstatningsansvaret.',2,3,'016.001.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2153,1,2148,2148,'paragraph','§ 143.',NULL,'Lejeren har efter udlejerens anvisning ret til at anbringe radio- og fjernsynsantenne på ejendommen til modtagelse af radio- og tv-programmer, jf. dog stk. 2. Lejeren har tilsvarende ret til at lade etablere kabelforbindelse til fremføring af radio- og tv-programmer eller adgang til elektroniske kommunikationstjenester i ejendommen, hvis der er mulighed for tilslutning til kabel-tv eller lignende fælles net i området. Ønsker flere lejere at etablere samme programforsyning eller forsyning med adgang til elektroniske kommunikationstjenester, kan disse beslutte, at opsætning af antenne eller forsyning med adgang til elektroniske kommunikationstjenester skal ske i form af et fællesanlæg.',3,2,'016.001.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id878c26fa-369a-4ee7-b8b8-5fda1ba7f6fc\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2154,1,2153,2153,'subsection','Stk. 2.',NULL,'Lejerens ret efter stk. 1 gælder ikke, hvis udlejeren godtgør, at anbringelsen vil være til ulempe for ejendommen eller dens lejere. Retten gælder endvidere ikke, hvis lejeren kan få adgang til et ønsket program enten gennem udlejerens fælles tv-forsyning eller gennem et af lejerne etableret fællesantenneanlæg.',1,3,'016.001.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2155,1,2153,2153,'subsection','Stk. 3.',NULL,'Lejeren er erstatningsansvarlig for skade, der er forårsaget af antennen eller kabelforbindelsen. Udlejeren kan forlange, at lejeren indbetaler et rimeligt depositum til sikkerhed for krav mod lejeren, som opstår som følge af antennen, herunder udgifter til nedtagning af antennen og retablering ved lejerens fraflytning, jf. stk. 7.',2,3,'016.001.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2156,1,2153,2153,'subsection','Stk. 4.',NULL,'Ønsker flere lejere at etablere en fællesantenne i ejendommen efter stk. 1, 3. pkt., kan udlejeren forlange, at de pågældende lejere stifter en antenneforening, som skal stå for etablering og drift af fællesantenneanlægget. Der skal vælges en bestyrelse for antenneforeningen. Det påhviler bestyrelsen at meddele udlejeren, hvem der sidder i bestyrelsen, således at udlejeren med frigørende virkning kan henvende sig til disse angående spørgsmål vedrørende antenneanlægget. Bestyrelsen skal samtidig sende et eksemplar af foreningens vedtægter til udlejeren. Antenneforeningen er erstatningsansvarlig for skade, der er forårsaget af fællesantenneanlægget. Vedtægterne skal indeholde bestemmelser om, at foreningen skal tegne en ansvarsforsikring og en kaskoforsikring vedrørende antenneanlægget, og at foreningen i tilfælde af ophør skal bære udgifterne til nedtagning af antenneanlægget og retablering. Udlejeren kan forlange, at foreningen indbetaler et rimeligt depositum til sikkerhed for udlejerens krav mod foreningen, herunder udgifter til nedtagning af antenneanlægget og retablering.',3,3,'016.001.003.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2157,1,2153,2153,'subsection','Stk. 5.',NULL,'Ved væsentlig tilsidesættelse af de pligter, som er angivet i stk. 4, kan udlejeren kræve fællesantenneanlægget nedtaget og retablering.',4,3,'016.001.003.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2158,1,2153,2153,'subsection','Stk. 6.',NULL,'Stk. 4 og 5 gælder tilsvarende for lejernes etablering af fælles forsyning med adgang til elektroniske kommunikationstjenester.',5,3,'016.001.003.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2159,1,2153,2153,'subsection','Stk. 7.',NULL,'Har lejeren opsat egen antenne efter stk. 1 eller været tilsluttet fællesantenneanlæg efter stk. 4, kan udlejeren kræve lejerens antenne nedtaget og retablering, når lejeren fraflytter lejemålet.',6,3,'016.001.003.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2160,1,2148,2148,'paragraph','§ 144.',NULL,'Lejeren har ret til at foretage skiltning på mure, døre og vinduer, der hører til det lejede, i det omfang det er sædvanligt efter arten af lejerens forretning og ejendommen. Lejeren har endvidere ret til at anbringe markiser, udhængsskabe, automater, varer og lign. i sædvanligt omfang.',4,2,'016.001.004','{\"source_class\":\"Paragraf\",\"source_id\":\"idd47d640d-20c8-4bad-99e4-c2503ddb8e11\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2161,1,2160,2160,'subsection','Stk. 2.',NULL,'Lejeren af en butik eller en beværtning skal holde forretningen åben og i forsvarlig drift i sædvanligt omfang. Det kan ikke uanset modstående aftale pålægges lejere af forretninger i butiksfællesskaber at holde åbent mandag til fredag efter kl. 20.00 og fra lørdag kl. 17.00 til mandag kl. 6.00.',1,3,'016.001.004.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2162,1,2147,2147,'paragraph_group',NULL,'Lejerens råderet',NULL,2,1,'016.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2163,1,2162,2162,'paragraph','§ 145.',NULL,'Lejeren af en beboelseslejlighed har ret til at udføre nærmere fastsatte forbedringsarbejder m.v. i lejligheden og ved fraflytning få godtgørelse for de afholdte udgifter efter reglerne i stk. 4-8. Bestemmelsen i 1. pkt. gælder ikke for lejere i fremlejeforhold efter § 158 og lejere i tidsbegrænsede lejeforhold efter § 173.',1,2,'016.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id9a5db06d-8eaf-4d8b-91c2-23e497f35d39\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2164,1,2163,2163,'subsection','Stk. 2.',NULL,'Lejeren skal forudgående anmelde de påtænkte forbedringsarbejder m.v. til udlejeren. Nødvendig byggesagsbehandling forestås og betales af lejeren. § 142, stk. 3, finder tilsvarende anvendelse.',1,3,'016.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2165,1,2163,2163,'subsection','Stk. 3.',NULL,'Forbedringer m.v. efter stk. 1 skal være rimelige og hensigtsmæssige. Udlejeren kan nægte lejeren at forbedre det lejede, når særlig vægtige grunde taler herfor, herunder når der er tale om uhensigtsmæssige arbejder, f.eks. særlig luksusprægede eller særlig energiforbrugende arbejder. Lejeren kan lade arbejderne udføre, såfremt udlejeren ikke har gjort indsigelse senest 6 uger efter lejerens anmeldelse af arbejderne efter stk. 2. Indsigelsen skal være skriftlig og angive, hvilke arbejder der gøres indsigelse mod, og begrundelsen herfor.',2,3,'016.002.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2166,1,2163,2163,'subsection','Stk. 4.',NULL,'Godtgørelsen beregnes på grundlag af afholdte udgifter, som skal dokumenteres efter arbejdernes afslutning og påtegnes lejekontrakten. Udlejeren kan reducere beregningsgrundlaget for godtgørelse med værdien af eksisterende installationer og bygningsdele m.v., som er omfattet af forbedringsarbejderne. Udlejeren kan endvidere reducere beregningsgrundlaget for godtgørelse, hvis udgifterne skønnes at være uforholdsmæssigt høje.',3,3,'016.002.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2167,1,2163,2163,'subsection','Stk. 5.',NULL,'Godtgørelsen udgør den del af de afholdte udgifter beregnet efter stk. 4, som efter fradrag af eventuel støtte efter anden lovgivning overstiger 16.015 kr. Godtgørelsen kan højst udgøre 126.684 kr. Godtgørelse på mindre end 3.204 kr. udbetales ikke. Som afholdte udgifter kan alene medregnes dokumenterede udgifter til virksomheder, der er registreret efter momsloven, og som driver bygge- og anlægsvirksomhed. De i 1.-3. pkt. nævnte beløb er opgjort i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1.',4,3,'016.002.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2168,1,2163,2163,'subsection','Stk. 6.',NULL,'Der kan ydes godtgørelse for flere forbedringer m.v. i samme lejlighed, selv om arbejderne ikke udføres samtidig. Under hensyntagen til nedskrivningen efter stk. 7 kan den samlede godtgørelse til en lejer dog aldrig overstige beløbsgrænsen i stk. 5.',5,3,'016.002.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2169,1,2163,2163,'subsection','Stk. 7.',NULL,'Den oprindelig beregnede godtgørelse nedskrives med 10 pct. for hvert år, forbedringen m.v. har været i brug, første gang dog først 2 år efter at forbedringen er taget i brug, medmindre anden nedskrivning aftales imellem lejeren og udlejeren under hensyn til arbejdernes karakter. Ibrugtagningsdatoen for forbedringen m.v. skal sammen med en eventuel særlig aftale om nedskrivning af godtgørelsen påtegnes lejekontrakten.',6,3,'016.002.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2170,1,2163,2163,'subsection','Stk. 8.',NULL,'Godtgørelsen udbetales af udlejeren ved lejerens fraflytning, hvis udførelsen af arbejderne er tilendebragt, jf. § 188, stk. 3. Udlejeren kan foretage modregning i godtgørelsen for lejerens forpligtelser over for udlejeren.',7,3,'016.002.001.007','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2171,1,2163,2163,'subsection','Stk. 9.',NULL,'I nedskrivningsperioden, jf. stk. 7, kan en ny lejer ved genudlejning enten vælge at betale den nedskrevne godtgørelse til udlejeren eller vælge at betale en lejeforhøjelse, der modsvarer forøgelsen af det lejedes værdi, jf. § 128. Ved genudlejningen efter nedskrivningsperiodens udløb, jf. stk. 7, kan udlejeren kræve en lejeforhøjelse, der modsvarer forøgelsen af det lejedes værdi, jf. § 128.',8,3,'016.002.001.008','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2172,1,2163,2163,'subsection','Stk. 10.',NULL,'Flytter en lejer, der har betalt den nedskrevne godtgørelse til udlejeren efter stk. 9, i nedskrivningsperioden, har lejeren ret til godtgørelse svarende til den nedskrevne godtgørelse beregnet efter stk. 7 modregnet eventuelle forpligtelser over for udlejeren, jf. stk. 8.',9,3,'016.002.001.009','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2173,1,2163,2163,'subsection','Stk. 11.',NULL,'Indenrigs- og boligministeren fastsætter nærmere regler om afgrænsningen af forbedringsarbejder m.v. efter § 145.',10,3,'016.002.001.010','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2174,1,2147,2147,'paragraph_group',NULL,'Lejernes adgang til at forlange energibesparende foranstaltninger gennemført',NULL,3,1,'016.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2175,1,2174,2174,'paragraph','§ 146.',NULL,'Leverer udlejeren varme og opvarmning af brugsvand, og overstiger udgifterne hertil ifølge det senest udsendte varmeregnskab for 1 år halvdelen af lejen for den pågældende periode, kan beboerrepræsentanterne eller et flertal af lejerne forlange, at der udføres alle eller en del af de arbejder vedrørende varme og opvarmning af brugsvand, der er angivet i en energiplan, jf. lov om fremme af energibesparelser i bygninger. Foreligger der ikke energimærkning med tilhørende energiplan, jf. lov om fremme af energibesparelser i bygninger, kan lejerne, såfremt forholdet er omfattet af 1. pkt., kræve, at udlejeren gennemfører en sådan energimærkning. Det er en betingelse, at beboerrepræsentanterne eller et flertal af lejerne samtidig giver tilslutning til en lejeforhøjelse til dækning af samtlige udgifter, der følger af arbejdernes gennemførelse, jf. § 129, stk. 2.',1,2,'016.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id804db93e-ee87-4fed-a607-e9fccec29ffc\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2176,1,2147,2147,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,4,1,'016.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2177,1,2176,2176,'paragraph','§ 147.',NULL,'Tvister om lejerens rettigheder og forpligtelser efter dette kapitel afgøres af huslejenævnet.',1,2,'016.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id4ee1bc1b-1a75-4938-9c82-9f656bde474c\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2178,1,2177,2177,'subsection','Stk. 2.',NULL,'På begæring af beboerrepræsentanterne eller et flertal af lejerne afgør huslejenævnet, om betingelserne er opfyldt for at kræve udførelse af arbejder omfattet af lovens § 146.',1,3,'016.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2179,1,2177,2177,'subsection','Stk. 3.',NULL,'Nævnet kan pålægge udlejeren at udføre de i stk. 2 nævnte arbejder og fastsætte en tidsfrist for det enkelte arbejdes udførelse.',2,3,'016.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2180,1,2147,2147,'paragraph_group',NULL,'Fravigelighed',NULL,5,1,'016.005',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2181,1,2180,2180,'paragraph','§ 148.',NULL,'§§ 142 og 143, § 144 stk. 2, 2. pkt., og §§ 145 og 146 kan ikke fraviges til skade for lejeren.',1,2,'016.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ideb081ac2-2a5a-48c8-9c4f-fdf2555884a7\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2182,1,NULL,0,'chapter','Kapitel 17','Lejerens brug af det lejede',NULL,17,0,'017',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2183,1,2182,2182,'paragraph_group',NULL,'Lejerens forsvarlige brug af det lejede',NULL,1,1,'017.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2184,1,2183,2183,'paragraph','§ 149.',NULL,'Lejeren skal behandle det lejede forsvarligt.',1,2,'017.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id562ce567-f12f-4534-b1a2-2e61af79de73\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2185,1,2184,2184,'subsection','Stk. 2.',NULL,'Lejeren er erstatningsansvarlig for skade, som forvoldes ved uforsvarlig adfærd af lejeren selv, lejerens husstand eller andre, som lejeren har givet adgang til det lejede.',1,3,'017.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2186,1,2184,2184,'subsection','Stk. 3.',NULL,'Skader, hvis udbedring er uopsættelig, skal lejeren straks anmelde til udlejeren. Andre skader skal lejeren anmelde uden ugrundet ophold.',2,3,'017.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2187,1,2183,2183,'paragraph','§ 150.',NULL,'Lejeren må ikke uden udlejerens samtykke bruge det lejede til andet formål end aftalt.',2,2,'017.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id2c7465dc-ab1a-4e99-b2ca-3c9f965fdeb4\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2188,1,2187,2187,'subsection','Stk. 2.',NULL,'Lejeren må ikke uden udlejerens samtykke overlade brugen af det lejede eller nogen del deraf til andre end medlemmer af sin husstand, jf. dog §§ 157 og 158.',1,3,'017.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2189,1,2182,2182,'paragraph_group',NULL,'Fravigelighed',NULL,2,1,'017.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2190,1,2189,2189,'paragraph','§ 151.',NULL,'Dette kapitel kan ikke fraviges til skade for lejeren.',1,2,'017.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb365e27f-73b3-4724-bbbd-0fb99060889d\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2191,1,NULL,0,'chapter','Kapitel 18','God skik og orden i ejendommen',NULL,18,0,'018',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2192,1,2191,2191,'paragraph_group',NULL,'Tilsidesættelse af god skik og orden',NULL,1,1,'018.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2193,1,2192,2192,'paragraph','§ 152.',NULL,'Udlejeren skal sørge for, at der hersker god orden i ejendommen og om fornødent ophæve lejeforhold i de i § 182, stk. 1, nr. 7-10 og 13, nævnte tilfælde. Bestemmelserne i § 95, stk. 2, og §§ 96 og 97 finder tilsvarende anvendelse på udlejerens overtrædelse af denne pligt.',1,2,'018.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id257b2a6a-2910-4a97-9742-dabb9d57bde4\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2194,1,2193,2193,'subsection','Stk. 2.',NULL,'Lejeren skal overholde de almindelige ordensregler, der gælder for ejendommen, og skal efterkomme andre rimelige påbud, der skal sikre god husorden og forsvarlig brug af det lejede, jf. § 153.',1,3,'018.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2195,1,2193,2193,'subsection','Stk. 3.',NULL,'Lejeren skal sørge for, at de pligter, der påhviler lejeren efter stk. 2, også iagttages af de personer, for hvis handlinger lejeren er ansvarlig efter § 149, stk. 2.',2,3,'018.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2196,1,2192,2192,'paragraph','§ 153.',NULL,'En lejer kan pålægges retsfølger efter § 154, når lejeren i følgende tilfælde udøver adfærd, som er til gene for ejendommen, udlejeren, dennes ansatte eller lejere i ejendommen eller andre, der lovligt færdes i ejendommen:',2,2,'018.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id41a02a60-ade1-4f52-8112-82f22238165b\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2197,1,2196,2196,'list_item','1)',NULL,'Når lejeren udøver eller truer med fysisk vold mod de pågældende personer.',1,3,'018.001.002.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2198,1,2196,2196,'list_item','2)',NULL,'Når lejerens adfærd kan være til fare for ejendommen eller de pågældende personer, herunder på grund af anvendelse af våben eller opbevaring af farefremkaldende materialer i det lejede.',2,3,'018.001.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2199,1,2196,2196,'list_item','3)',NULL,'Når lejerens adfærd medfører gener for de pågældende personer som generel utryghed, forråelse af ejendommens miljø eller sundhedsmæssig risiko.',3,3,'018.001.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2200,1,2196,2196,'list_item','4)',NULL,'Når lejeren, uden at der er tale om fysisk vold, udøver chikane over for de pågældende personer.',4,3,'018.001.002.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2201,1,2196,2196,'list_item','5)',NULL,'Når lejeren udøver uacceptabel støj til væsentlig gene for de pågældende personer i form af uacceptabelt støjende menneskelig adfærd, stærk musikstøj eller stærk maskinstøj.',5,3,'018.001.002.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2202,1,2196,2196,'list_item','6)',NULL,'Når lejeren ødelægger ejendommen eller løsøre på ejendommen eller på fællesarealer.',6,3,'018.001.002.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2203,1,2196,2196,'list_item','7)',NULL,'Når lejeren vanrøgter det lejede.',7,3,'018.001.002.007','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2204,1,2196,2196,'list_item','8)',NULL,'Når lejerens husdyr er til væsentlig gene for de pågældende personer på grund af støj, lugt, uhumskhed eller fare- eller frygtfremkaldelse.',8,3,'018.001.002.008','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2205,1,2196,2196,'list_item','9)',NULL,'Når lejeren, uden at der er tale om de i nr. 5 nævnte tilfælde, udøver støjende adfærd til gene for de pågældende personer.',9,3,'018.001.002.009','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2206,1,2196,2196,'list_item','10)',NULL,'Når lejerens husdyrhold, uden at der er tale om de i nr. 8 nævnte tilfælde, er til gene for de pågældende personer.',10,3,'018.001.002.010','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2207,1,2196,2196,'list_item','11)',NULL,'Når lejeren i øvrigt udøver adfærd, som er til gene for ejendommen eller de pågældende personer.',11,3,'018.001.002.011','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2208,1,2196,2196,'subsection','Stk. 2.',NULL,'En lejer kan desuden pålægges retsfølger efter § 154, når lejeren holder husdyr i strid med lejeaftale eller husorden, uanset om husdyrholdet er til gene for ejendommen eller de i stk. 1 nævnte personer.',12,3,'018.001.002.012','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2209,1,2196,2196,'subsection','Stk. 3.',NULL,'Lejeren kan pålægges retsfølger, uanset om den i stk. 1 og 2 beskrevne adfærd udøves af lejeren selv, lejerens husstand eller andre, som lejeren har givet adgang til det lejede.',13,3,'018.001.002.013','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2210,1,2191,2191,'paragraph_group',NULL,'Retsfølger ved tilsidesættelse af god skik og orden',NULL,2,1,'018.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2211,1,2210,2210,'paragraph','§ 154.',NULL,'Har lejeren tilsidesat god skik og orden, jf. § 153, kan lejeren af huslejenævnet pålægges en af følgende retsfølger:',1,2,'018.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id4bce144b-5c17-442c-a1fd-89cc3138a4c4\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2212,1,2211,2211,'list_item','1)',NULL,'Lejeforholdet kan gøres betinget, således at der, hvis lejeren inden for 1 år efter afgørelsen overtræder nærmere fastsatte betingelser vedrørende adfærd i ejendommen, er grundlag for, at lejemålet kan opsiges eller ophæves efter reglerne i kapitel 20 og 21.',1,3,'018.002.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2213,1,2211,2211,'list_item','2)',NULL,'Lejeren kan meddeles en advarsel om, at fornyet overtrædelse af god skik og orden, jf. § 153, kan føre til, at lejeforholdet gøres betinget efter nr. 1, eller til, at lejemålet opsiges eller ophæves efter reglerne i kapitel 20 og 21.',2,3,'018.002.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2214,1,2211,2211,'subsection','Stk. 2.',NULL,'Det er en betingelse for, at en lejer kan pålægges retsfølger for tilsidesættelse af god skik og orden efter stk. 1, at tilsidesættelsen sker trods udlejerens påmindelse.',3,3,'018.002.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2215,1,2191,2191,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,3,1,'018.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2216,1,2215,2215,'paragraph','§ 155.',NULL,'Sag om pålæg af retsfølger efter § 154 indbringes for huslejenævnet af udlejeren. Er der fremsat krav om, at lejeren pålægges en advarsel, kan nævnet ikke pålægge lejeren en strengere retsfølge.',1,2,'018.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idcf7e4e00-1865-4292-aa78-977242871001\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2217,1,2191,2191,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'018.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2218,1,2217,2217,'paragraph','§ 156.',NULL,'Dette kapitel kan ikke fraviges.',1,2,'018.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd4ff787e-04ea-457e-81a4-45efff86e3d7\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2219,1,NULL,0,'chapter','Kapitel 19','Brugsrettens overgang til andre',NULL,19,0,'019',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2220,1,2219,2219,'paragraph_group',NULL,'Fremleje',NULL,1,1,'019.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2221,1,2220,2220,'paragraph','§ 157.',NULL,'Lejeren af en beboelseslejlighed har ret til at fremleje op til halvdelen af lejlighedens beboelsesrum til beboelse. Det samlede antal personer, der bor i lejligheden, må ikke overstige antallet af beboelsesrum.',1,2,'019.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id30272f1b-6b9d-473d-8f7b-912311c7f9af\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2222,1,2221,2221,'subsection','Stk. 2.',NULL,'Udlejeren skal modsætte sig fremlejeforholdet, hvis lejligheden er omfattet af reglerne om beboermaksimum og vil blive beboet af flere end to personer pr. beboelsesrum, jf. § 14, stk. 1, i lov om boligforhold.',1,3,'019.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2223,1,2221,2221,'subsection','Stk. 3.',NULL,'Fremlejeaftaler skal indgås skriftligt, og lejeren skal inden fremlejeperiodens begyndelse tilstille udlejeren kopi af fremlejeaftalen.',2,3,'019.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2224,1,2220,2220,'paragraph','§ 158.',NULL,'En lejlighed, der udelukkende er udlejet til beboelse, har lejeren ret til at fremleje i indtil 2 år, når lejerens fravær er midlertidigt og skyldes sygdom, forretningsrejse, studieophold, midlertidig forflyttelse el.lign.',2,2,'019.001.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id7de3fc3a-ed6f-4c0c-994a-0adff4d65b53\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2225,1,2224,2224,'subsection','Stk. 2.',NULL,'Udlejeren kan modsætte sig fremlejeforholdet, når en af følgende betingelser er opfyldt:',1,3,'019.001.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2226,1,2224,2224,'list_item','1)',NULL,'Ejendommen omfatter færre end 13 beboelseslejligheder.',2,3,'019.001.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2227,1,2224,2224,'list_item','2)',NULL,'Det samlede antal personer i lejligheden vil overstige antallet af beboelsesrum.',3,3,'019.001.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2228,1,2224,2224,'list_item','3)',NULL,'Udlejeren har i øvrigt rimelig grund til at modsætte sig fremlejeforholdet.',4,3,'019.001.002.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2229,1,2224,2224,'subsection','Stk. 3.',NULL,'§ 157, stk. 2 og 3, finder tilsvarende anvendelse.',5,3,'019.001.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2230,1,2224,2224,'subsection','Stk. 4.',NULL,'Hvis det skønnes rimeligt af hensyn til efterspørgslen, kan udlejer ved fremleje af ældreboliger eller ustøttede private plejeboliger stille krav om, at den pågældende bolig skal bebos af personer, som opfylder betingelserne for at komme i betragtning til en bolig af den pågældende karakter.',6,3,'019.001.002.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2231,1,2220,2220,'paragraph','§ 159.',NULL,'Lejeren er erstatningsansvarlig for skade, som ved uforsvarlig adfærd forvoldes af personer, der i kraft af reglerne i § 157 og § 158 benytter det lejede.',3,2,'019.001.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id066ea371-62be-41ff-b664-9e1e1a9b92f9\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2232,1,2231,2231,'subsection','Stk. 2.',NULL,'Lejeren er over for udlejeren ansvarlig for, at de i stk. 1 nævnte personer overholder de regler, der skal sikre en god husorden og forsvarlig brug af det lejede.',1,3,'019.001.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2233,1,2231,2231,'subsection','Stk. 3.',NULL,'Lejeren er endvidere erstatningsansvarlig efter § 142, stk. 3, for skade forårsaget af installationer, som de i stk. 1 nævnte personer har foretaget i det lejede.',2,3,'019.001.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2234,1,2220,2220,'paragraph','§ 160.',NULL,'Lejeren må ikke uden ægtefællens samtykke foretage fremleje, såfremt dette vil medføre, at det lejede ikke længere kan tjene til fælles bolig eller som grundlag for ægtefællernes eller den anden ægtefælles virksomhed. Er den anden ægtefælle umyndig, meddeler værgen samtykket.',4,2,'019.001.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id80aa7b06-78eb-4de7-b9aa-8cacf9030ad6\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2235,1,2234,2234,'subsection','Stk. 2.',NULL,'Nægter den anden ægtefælle at give samtykke efter stk. 1, eller kan samtykke ikke indhentes inden for rimelig tid, kan fremleje efter anmodning fra den ægtefælle, der lejer boligen, eller fra den anden part i aftalen tillades, hvis der ikke er rimelig grund til at nægte at gennemføre aftalen. Tilladelse efter 1. pkt. gives af Familieretshuset.',1,3,'019.001.004.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2236,1,2234,2234,'subsection','Stk. 3.',NULL,'Har en ægtefælle indgået en aftale, der er omfattet af stk. 1, uden samtykke fra den anden ægtefælle og uden tilladelse efter stk. 2, kan aftalen efter anmodning fra den anden ægtefælle omstødes ved dom. Dette gælder dog ikke, hvis den anden part i fremlejeaftalen godtgør, at parten ikke vidste eller burde have vidst, at ægtefællen ikke var berettiget til at indgå fremlejeaftalen.',2,3,'019.001.004.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2237,1,2234,2234,'subsection','Stk. 4.',NULL,'Retssag om omstødelse efter stk. 3 skal anlægges, inden 3 måneder efter at den anden ægtefælle fik kendskab til aftalen, dog senest 1 år efter at aftalen blev gennemført.',3,3,'019.001.004.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2238,1,2219,2219,'paragraph_group',NULL,'Bytteret',NULL,2,1,'019.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2239,1,2238,2238,'paragraph','§ 161.',NULL,'Lejeren af en lejlighed, der udelukkende er udlejet til beboelse, har ret til at bytte med en lejer af en anden beboelseslejlighed, således at denne overtager lejligheden.',1,2,'019.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idc44a01eb-181e-4823-aed3-f7061e991a91\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2240,1,2239,2239,'subsection','Stk. 2.',NULL,'Udlejeren kan modsætte sig bytte, hvis en af følgende betingelser er opfyldt:',1,3,'019.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2241,1,2239,2239,'list_item','1)',NULL,'Udlejer har sin bopæl i ejendommen, og denne omfatter færre end syv lejligheder.',2,3,'019.002.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2242,1,2239,2239,'list_item','2)',NULL,'Den fraflyttede lejer har ikke beboet lejligheden i 3 år.',3,3,'019.002.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2243,1,2239,2239,'list_item','3)',NULL,'Lejligheden vil ved bytning blive beboet af flere end én person pr. beboelsesrum.',4,3,'019.002.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2244,1,2239,2239,'list_item','4)',NULL,'Udlejeren har i øvrigt rimelig grund til at modsætte sig det pågældende bytte.',5,3,'019.002.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2245,1,2239,2239,'subsection','Stk. 3.',NULL,'Såfremt der er tale om et lejemål, som udlejeren agter at forbedre i forbindelse med byttet og herefter fastsætte lejen efter § 19, stk. 2, skal udlejeren straks meddele lejeren dette og senest 1 måned efter lejerens meddelelse om bytte anmode huslejenævnet om en forhåndsgodkendelse, jf. § 132, stk. 1. Udlejeren skal fremsende kopi af anmodningen om forhåndsgodkendelse og oplysning om størrelsen af den forventede husleje efter forbedringen til lejeren. Når huslejenævnets forhåndsgodkendelse foreligger, skal udlejeren straks give lejeren kopi heraf. Undlader udlejeren at give de i 1. og 3. pkt. nævnte oplysninger, kan lejen ikke fastsættes efter § 19, stk. 2, hvis genudlejning sker som led i det pågældende bytte. Ved forhåndsgodkendelsen ses bort fra § 21, stk. 1.',6,3,'019.002.001.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2246,1,2239,2239,'subsection','Stk. 4.',NULL,'Lejeren skal, senest 14 dage efter at kopi af huslejenævnets forhåndsgodkendelse efter stk. 3 er kommet frem til lejeren, meddele udlejeren, at byttet ønskes gennemført. Sker det ikke, fortsætter lejeforholdet på uændrede vilkår. En indhentet forhåndsgodkendelse efter stk. 3 har gyldighed i indtil 2 år efter godkendelsens datering.',7,3,'019.002.001.007','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2247,1,2239,2239,'subsection','Stk. 5.',NULL,'Udlejeren skal modsætte sig bytte, hvis lejligheden er omfattet af reglerne om beboermaksimum og efter bytning vil blive beboet af flere end to personer pr. beboelsesrum, jf. § 14, stk. 1, i lov om boligforhold.',8,3,'019.002.001.008','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2248,1,2239,2239,'subsection','Stk. 6.',NULL,'Hvis det skønnes rimeligt af hensyn til efterspørgslen, kan udlejer ved bytte af ældreboliger eller ustøttede private plejeboliger stille krav om, at den pågældende bolig skal bebos af personer, som opfylder betingelserne for at komme i betragtning til en bolig af den pågældende karakter.',9,3,'019.002.001.009','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2249,1,2238,2238,'paragraph','§ 162.',NULL,'Den lejer, der ved bytning ønsker at overtage en lejlighed, der tilhører en kommune, en almen boligorganisation, et kollegieselskab eller en stiftelse, skal opfylde de særlige vilkår, der gælder for overtagelse af sådanne lejligheder. Med stiftelse ligestilles en pensionskasse el.lign., der kun genudlejer lejlighederne til sine medlemmer ved overgang til pension.',2,2,'019.002.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idf05ad050-f6c5-4feb-9bf6-06dc54fc6891\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2250,1,2249,2249,'subsection','Stk. 2.',NULL,'Det kan betinges, at den, der ved bytning opnår en lejlighed i en andelsboligforening, skal indtræde som medlem af foreningen.',1,3,'019.002.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2251,1,2249,2249,'subsection','Stk. 3.',NULL,'Bytteretten gælder uanset vedtægtsmæssige begrænsninger i beboernes bytteadgang.',2,3,'019.002.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2252,1,2219,2219,'paragraph_group',NULL,'Brugsrettens overgang til ægtefællen m.v.',NULL,3,1,'019.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2253,1,2252,2252,'paragraph','§ 163.',NULL,'Dør lejeren, har ægtefællen ret til at fortsætte lejeforholdet.',1,2,'019.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id3b45624b-30f5-49d2-a4e5-e7b354b5309e\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2254,1,2253,2253,'subsection','Stk. 2.',NULL,'Dør lejeren af en beboelseslejlighed uden at efterlade sig en ægtefælle, har en anden person, der i en periode på mindst 2 år umiddelbart forud for dødsfaldet har haft fælles husstand med lejeren, ret til at fortsætte lejeforholdet.',1,3,'019.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2255,1,2253,2253,'subsection','Stk. 3.',NULL,'Dør en lejer af en lejlighed, der delvis er udlejet til andet end beboelse, og har lejeren drevet en erhvervsvirksomhed, hvis stedlige forbliven i ejendommen er af væsentlig betydning og værdi for virksomheden, uden at efterlade sig en ægtefælle, har enhver af lejerens livsarvinger eller svigerbørn ret til at overtage lejeforholdet, medmindre udlejeren har vægtige grunde til at modsætte sig det. Det er dog en betingelse, at den pågældende har fornødent kendskab til den branche, hvori forretningen hidtil har været drevet, og ønsker selv eller sammen med sin ægtefælle at føre forretningen videre. Indtræder den pågældende ikke som lejer, kan udlejeren ikke udleje til anden side på lempeligere vilkår, end udlejeren har foreslået den pågældende.',2,3,'019.003.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2256,1,2253,2253,'subsection','Stk. 4.',NULL,'I øvrigt kan i tilfælde af lejerens død såvel udlejeren som dødsboet opsige lejeforholdet med sædvanligt varsel, selv om lejeforholdet måtte være indgået for en bestemt længere tid eller med længere opsigelsesfrist.',3,3,'019.003.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2257,1,2253,2253,'subsection','Stk. 5.',NULL,'Er det lejede en plejebolig, jf. § 1, stk. 1, 2. pkt., i den tidligere lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996, eller § 5, stk. 2, i lov om almene boliger m.v., eller en ustøttet privat plejebolig, jf. § 1, stk. 5, og dør lejeren uden at efterlade sig ægtefælle eller andre, som lejeren har haft fælles husstand med som anført i stk. 2, kan opsigelsen uanset stk. 4 ske med 1 måneds varsel. Indbo m.v. efter den afdøde beboer kan opmagasineres under iagttagelse af § 8 i lov om skifte af dødsboer.',4,3,'019.003.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2258,1,2252,2252,'paragraph','§ 164.',NULL,'Hvis lejeren af en beboelseslejlighed på grund af alder eller sygdom flytter på plejehjem, i beskyttet bolig el.lign. eller i plejebolig efter § 1, stk. 1, 2. pkt., i den tidligere lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996, eller § 5, stk. 2, i lov om almene boliger m.v., i en ustøttet privat plejebolig, jf. § 1, stk. 5, eller i en friplejebolig, finder § 163, stk. 1 og 2, tilsvarende anvendelse.',2,2,'019.003.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idd1482701-ec91-40ee-8aee-c32c951f9a48\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2259,1,2252,2252,'paragraph','§ 165.',NULL,'I tilfælde af lejerens separation eller skilsmisse eller ved omstødelse af lejerens ægteskab afgøres det om nødvendigt ved separationen, skilsmissen eller omstødelsen, hvilken af ægtefællerne der har ret til at fortsætte lejeforholdet. Den ægtefælle, hvis erhvervsvirksomhed er knyttet til et forretningslokale, har fortrinsret til dette og den dertil hørende beboelse.',3,2,'019.003.003','{\"source_class\":\"Paragraf\",\"source_id\":\"iddce73acb-c13e-4e88-b257-a214c7be9d34\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2260,1,2252,2252,'paragraph','§ 166.',NULL,'Såfremt parter, der i mindst 2 år har haft fælles husstand, ophæver samlivet, kan de aftale, hvem af parterne der skal have ret til at fortsætte lejeforholdet til en lejlighed, der har tjent som fælles bolig. Kan parterne ikke blive enige om en aftale, jf. 1. pkt., kan der, når særlige grunde, herunder navnlig hensynet til parternes mindreårige børn, taler derfor, ved dom træffes bestemmelse om, hvem af parterne der skal have ret til at fortsætte lejeforholdet. § 165, 2. pkt., finder tilsvarende anvendelse.',4,2,'019.003.004','{\"source_class\":\"Paragraf\",\"source_id\":\"idd5d06953-ec5e-4e5c-a031-a286465dca75\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2261,1,2252,2252,'paragraph','§ 167.',NULL,'Har lejeren forladt sin ægtefælle, har denne ret til at fortsætte lejeforholdet efter reglen i § 163, stk. 1.',5,2,'019.003.005','{\"source_class\":\"Paragraf\",\"source_id\":\"ida2109f38-7f02-4983-907d-89f8c4d5c361\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2262,1,2219,2219,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'019.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2263,1,2262,2262,'paragraph','§ 168.',NULL,'Lejeren kan ikke give afkald på de rettigheder, der tilkommer lejeren eller andre efter §§ 157, 158, 160, 161 og 163-167. § 162 kan ikke fraviges ved aftale.',1,2,'019.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id215fad2b-63a9-48d6-9597-158d3a91f5a2\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2264,1,NULL,0,'chapter','Kapitel 20','Opsigelse',NULL,20,0,'020',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2265,1,2264,2264,'paragraph_group',NULL,'Lejerens opsigelse',NULL,1,1,'020.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2266,1,2265,2265,'paragraph','§ 169.',NULL,'Lejeren kan frit opsige lejeaftalen, medmindre andet er aftalt.',1,2,'020.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb2fe12d2-4df7-431e-acd5-b9cfcaf6afc0\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2267,1,2266,2266,'subsection','Stk. 2.',NULL,'Lejeren må dog ikke uden sin ægtefælles samtykke opsige lejemål om familiens bolig eller om lokaler, hvortil ægtefællernes eller den anden ægtefælles virksomhed er knyttet. § 160, stk. 2-4, finder tilsvarende anvendelse.',1,3,'020.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2268,1,2264,2264,'paragraph_group',NULL,'Udlejerens opsigelse',NULL,2,1,'020.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2269,1,2268,2268,'paragraph','§ 170.',NULL,'Udlejeren kan opsige følgende lejeforhold om:',1,2,'020.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idd93bb095-6a67-4c20-a690-6f9cf1346ab1\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2270,1,2269,2269,'list_item','1)',NULL,'Enkelte værelser til beboelse, når værelset er en del af udlejerens beboelseslejlighed eller er en del af et en- eller tofamilieshus, som udlejeren bebor.',1,3,'020.002.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2271,1,2269,2269,'list_item','2)',NULL,'En beboelseslejlighed i et hus, hvori der på tidspunktet for aftalens indgåelse kun findes to beboelseslejligheder, hvoraf ejeren bebor den ene. Reglen gælder, selv om ejeren anvender et eller flere lokaler i huset til andet end beboelse, og selv om der i ejendommen er udlejet et eller flere enkeltværelser til beboelse.',2,3,'020.002.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2272,1,2269,2269,'list_item','3)',NULL,'En ejerbolig eller en andelsbolig, hvis ejeren eller andelshaveren selv agter at bebo lejligheden, idet reglen dog kun gælder for ejere af ejerboliger eller ejere af andele i andelsboligforeninger, der ejede den pågældende lejlighed eller andel på tidspunktet for lejeaftalens indgåelse, og som på tidspunktet for opsigelsen ikke ejer andre udlejede ejerboliger eller andelsboliger.',3,3,'020.002.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2273,1,2269,2269,'list_item','4)',NULL,'En beboelseslejlighed, hvortil er knyttet lokaler til restauration, butik, kiosk eller tilsvarende brug på banegårde og i teatre, foreningsbygninger, forlystelsesanlæg, skove og parker og lign., hvor forretningen må antages hovedsagelig at blive søgt af det publikum, der benytter de nævnte virksomheder, skove og parker, og hvor forretningen står i direkte tilknytning til disse.',4,3,'020.002.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2274,1,2268,2268,'paragraph','§ 171.',NULL,'Andre lejeforhold end de i § 170 nævnte kan udlejeren kun opsige i følgende tilfælde, jf. dog §§ 172 og 177:',2,2,'020.002.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id2779409b-1a50-4359-ac2f-d2368c1fa19c\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2275,1,2274,2274,'list_item','1)',NULL,'Når udlejeren ønsker selv at benytte det lejede.',1,3,'020.002.002.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2276,1,2274,2274,'list_item','2)',NULL,'Når udlejeren dokumenterer, at ejendommen skal nedrives. Det samme gælder, når udlejeren dokumenterer, at ombygning af ejendommen medfører, at det lejede må fraflyttes, og ejendommen efter ombygningen er omfattet af lov om almene boliger m.v., eller ombygningen sker som følge af ekspropriation eller ombygning til fyldestgørelse af et formål, til hvis gennemførelse der kan foretages ekspropriation.',2,3,'020.002.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2277,1,2274,2274,'list_item','3)',NULL,'Når lejeren af en beboelseslejlighed siden lejeaftalens indgåelse har været antaget som funktionær ved ejendommens drift til arbejde, for hvis udførelse det er af væsentlig betydning, at funktionæren bor i ejendommen, og udlejeren godtgør, at arbejdet ikke har været udført på tilfredsstillende måde. Opsigelse kan kun ske, når lejligheden ved genudlejning skal benyttes af den efterfølgende funktionær.',3,3,'020.002.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2278,1,2274,2274,'list_item','4)',NULL,'Når lejeren af en beboelseslejlighed, som er lejet som arbejder- eller funktionærbolig af den virksomhed, hvori lejeren er ansat, udtræder eller er udtrådt af sit arbejdsforhold til virksomheden, og lejligheden skal benyttes af en anden ansat i virksomheden.',4,3,'020.002.002.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2279,1,2274,2274,'list_item','5)',NULL,'Når udlejeren to eller flere gange i henhold til § 86, stk. 8, i lov om boligforhold har fået meddelelse om lejerens manglende efterlevelse af endelige huslejenævnsafgørelser.',5,3,'020.002.002.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2280,1,2274,2274,'list_item','6)',NULL,'Når lejeren har tilsidesat god skik og orden, jf. § 153, stk. 1, nr. 1-8 eller 11, jf. § 154, stk. 2, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',6,3,'020.002.002.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2281,1,2274,2274,'list_item','7)',NULL,'Når lejeren har tilsidesat betingelserne i et betinget lejeforhold, jf. § 154, stk. 1, nr. 1, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',7,3,'020.002.002.007','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2282,1,2274,2274,'list_item','8)',NULL,'Når vægtige grunde i øvrigt gør det særlig magtpåliggende for udlejeren at blive løst fra lejeforholdet.',8,3,'020.002.002.008','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2283,1,2274,2274,'subsection','Stk. 2.',NULL,'Vedrører lejeforholdet en plejebolig efter § 1, stk. 1, 2. pkt., i den tidligere gældende lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996, eller § 5, stk. 2, i lov om almene boliger m.v. eller en ustøttet privat plejebolig, jf. § 1, stk. 5, anvist af kommunen eller amtskommunen, kan opsigelse efter stk. 1 kun ske, når lejeren samtidig anvises en anden og passende bolig.',9,3,'020.002.002.009','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2284,1,2264,2264,'paragraph_group',NULL,'Begrænsninger i udlejerens opsigelsesadgang',NULL,3,1,'020.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2285,1,2284,2284,'paragraph','§ 172.',NULL,'Hvad angår opsigelsesretten efter § 171, stk. 1, nr. 1, gælder følgende begrænsninger:',1,2,'020.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id560ec63c-fca8-4bee-8c16-c452529e7228\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2286,1,2285,2285,'list_item','1)',NULL,'Vedrører lejeforholdet en beboelseslejlighed, er det en betingelse, at udlejeren selv agter at bebo lejligheden.',1,3,'020.003.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2287,1,2285,2285,'list_item','2)',NULL,'Opsigelsen skal være rimelig ud fra en vurdering af begge parters forhold. Ved afgørelsen skal der bl.a. tages hensyn til, hvor længe udlejeren har ejet ejendommen, og, ved opsigelse af en lejer af en beboelseslejlighed, lejerens muligheder for at finde anden passende bolig.',2,3,'020.003.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2288,1,2285,2285,'list_item','3)',NULL,'Lejeforhold om lokaler, der er udlejet til erhvervsformål, kan udlejeren ikke opsige med henblik på at drive erhverv i samme branche som lejerens.',3,3,'020.003.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2289,1,2285,2285,'list_item','4)',NULL,'Er det lejede en ejerlejlighed, omfattes lejeforholdet kun af opsigelsesretten, hvis lejemålet er indgået efter ejendommens opdeling i ejerlejligheder. Er lejeaftalen indgået den 1. januar 1980 eller senere, er det herudover et krav, at lejeren ved lejeforholdets begyndelse var gjort bekendt med, at det lejede er en ejerlejlighed, og at opsigelse kan ske efter § 171, stk. 1, nr. 1. Er lejeaftalen indgået den 1. juli 1986 eller senere, er det tillige et krav, at udlejeren tidligere har beboet lejligheden.',4,3,'020.003.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2290,1,2285,2285,'list_item','5)',NULL,'En lejer kan ikke opsiges, så længe lejeren er beboerrepræsentant.',5,3,'020.003.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2291,1,2285,2285,'list_item','6)',NULL,'Bebor udlejeren ved opsigelsens afgivelse en lejlighed i ejendommen, skal udlejeren samtidig med opsigelsen tilbyde lejeren at overtage denne lejlighed.',6,3,'020.003.001.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2292,1,2285,2285,'list_item','7)',NULL,'Såfremt ejendommen ejes af flere personer i fællesskab, kan ejerne kun opsige lejeren af én beboelseslejlighed.',7,3,'020.003.001.007','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2293,1,2264,2264,'paragraph_group',NULL,'Tidsbegrænsede lejeaftaler',NULL,4,1,'020.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2294,1,2293,2293,'paragraph','§ 173.',NULL,'Er lejeaftalen tidsbestemt, ophører lejeforholdet uden opsigelse ved den aftalte lejetids udløb. Den tidsbestemte lejeaftale kan ikke ved opsigelse bringes til ophør i lejeperioden, medmindre dette er aftalt eller den anden part i lejeforholdet misligholder aftalen.',1,2,'020.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id82aa1f96-5872-4964-933c-4772776023fd\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2295,1,2294,2294,'subsection','Stk. 2.',NULL,'Benytter lejeren med udlejerens vidende det lejede i mere end 1 måned efter den aftalte lejetids udløb, uden at udlejeren har opfordret lejeren til at flytte, fortsætter lejeforholdet uden tidsbegrænsning.',1,3,'020.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2296,1,2294,2294,'subsection','Stk. 3.',NULL,'Boligretten kan tilsidesætte tidsbegrænsningen, hvis den ikke må anses for tilstrækkeligt begrundet i udlejerens forhold.',2,3,'020.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2297,1,2264,2264,'paragraph_group',NULL,'Tilbud om en anden bolig',NULL,5,1,'020.005',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2298,1,2297,2297,'paragraph','§ 174.',NULL,'Opsiges en lejer af en beboelseslejlighed efter § 171, stk. 1, nr. 1, 2, 3 eller 8, skal udlejeren uden unødigt ophold tilbyde lejeren at leje en anden lejlighed i ejendommen, hvis der bliver en lejlighed ledig til overtagelse senest 3 måneder efter den flyttedag, hvortil lejeren er opsagt, og lejligheden skal udlejes.',1,2,'020.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idecdf3c2f-dddd-4ca0-8bd3-b079bb05883d\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2299,1,2298,2298,'subsection','Stk. 2.',NULL,'Opsiges en lejer efter § 171, stk. 1, nr. 2, skal udlejeren samtidig med opsigelsen tilbyde lejeren at leje en lejlighed eller lokaler af samme art som det opsagte, hvis der efter genopførelsen eller ombygningen sker udleje af lejligheder eller lokaler.',1,3,'020.005.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2300,1,2298,2298,'subsection','Stk. 3.',NULL,'Opsiges en lejer af en beboelseslejlighed efter § 171, stk. 1, nr. 2, som følge af at en ejendom ombygges til almene ældreboliger eller almene ungdomsboliger efter lov om almene boliger m.v., finder stk. 1 og 2 alene anvendelse, hvis lejeren tilhører den personkreds, som er berettiget efter den nævnte lov.',2,3,'020.005.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2301,1,2298,2298,'subsection','Stk. 4.',NULL,'Hvis en lejer af en beboelseslejlighed, jf. stk. 3, ikke tilhører den personkreds, som er berettiget efter den i stk. 3 nævnte lov, skal udlejeren samtidig med opsigelsen tilbyde lejeren at leje en passende bolig. En bolig anses for passende, når denne opfylder betingelserne i § 44, stk. 2, 2. og 3. pkt., i lov om boligforhold.',3,3,'020.005.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2302,1,2264,2264,'paragraph_group',NULL,'Opsigelsesvarsler',NULL,6,1,'020.006',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2303,1,2302,2302,'paragraph','§ 175.',NULL,'Opsigelsesvarslet er 3 måneder til den første hverdag i en måned, der ikke er dagen før en helligdag. Dog er opsigelsesvarslet 1 måned for de i § 170, nr. 1, nævnte lejeforhold.',1,2,'020.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id170a7384-dce0-475b-a3b7-67594124b736\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2304,1,2303,2303,'subsection','Stk. 2.',NULL,'Ved opsigelse efter § 170, nr. 2 og 3, og § 171, stk. 1, nr. 1, har lejeren krav på et opsigelsesvarsel på mindst 1 år til den første hverdag i en måned, der ikke er dagen før en helligdag.',1,3,'020.006.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2305,1,2303,2303,'subsection','Stk. 3.',NULL,'Fraflytter lejeren inden opsigelsesvarslets udløb, skal udlejeren bestræbe sig på at genudleje det lejede. Hvad udlejeren indvinder eller burde have indvundet ved genudlejning, skal fragå i udlejerens krav over for lejeren.',2,3,'020.006.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2306,1,2264,2264,'paragraph_group',NULL,'Formelle krav til udlejerens opsigelse',NULL,7,1,'020.007',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2307,1,2306,2306,'paragraph','§ 176.',NULL,'Udlejerens opsigelse efter § 170, nr. 2 og 3, og § 171 skal være skriftlig og indeholde oplysning om lejerens adgang til at gøre indsigelse efter stk. 2. Udlejerens opsigelse efter § 171 skal endvidere indeholde oplysning om opsigelsesgrunden. Er det lejede udlejet til andet end beboelse, skal opsigelsen tillige indeholde oplysning om lejerens rettigheder efter §§ 177-179. Indeholder opsigelsen ikke disse oplysninger, er den ugyldig.',1,2,'020.007.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id121ffd5c-1d88-4245-8306-cee2c6300483\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2308,1,2307,2307,'subsection','Stk. 2.',NULL,'Vil lejeren ikke godkende opsigelsen, skal lejeren, senest 6 uger efter at opsigelsen er kommet frem til denne, fremsætte skriftlig indsigelse. Udlejeren må da anlægge sag ved boligretten senest 6 uger efter lejerfristens udløb, hvis udlejeren ønsker at opretholde opsigelsen.',1,3,'020.007.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2309,1,2264,2264,'paragraph_group',NULL,'Erhvervsbeskyttelse',NULL,8,1,'020.008',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2310,1,2309,2309,'paragraph','§ 177.',NULL,'En lejer, der driver en erhvervsvirksomhed, hvis stedlige forbliven i ejendommen er af væsentlig betydning og værdi for virksomheden, kan kun opsiges efter § 171, hvis opsigelsen er rimelig ud fra en vurdering af begge parters forhold.',1,2,'020.008.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id3ed83f7a-ff75-4753-99c1-ff235380d1f2\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2311,1,2310,2310,'subsection','Stk. 2.',NULL,'Ved afgørelsen efter stk. 1 skal der bl.a. tages hensyn til længden af det tidsrum, hvori forretningen har været drevet i de lejede lokaler, værdien af kundekredsen, forretningens nettooverskud, vægtige indvendinger mod lejerens person eller forretningsførelse, lejerens behandling af de lejede lokaler og lejerens forbedringer af disse.',1,3,'020.008.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2312,1,2309,2309,'paragraph','§ 178.',NULL,'Opsiges en lejer, der driver en erhvervsvirksomhed, hvis stedlige forbliven i ejendommen er af væsentlig betydning og værdi for virksomheden, kan der gives lejeren erstatning for opsigelsen.',2,2,'020.008.002','{\"source_class\":\"Paragraf\",\"source_id\":\"id915cf5e1-cf7b-433f-baa5-4a2c05528c03\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2313,1,2312,2312,'subsection','Stk. 2.',NULL,'Ved fastsættelse af en eventuel erstatning efter stk. 1 skal boligretten ud over de i § 177, stk. 2, nævnte forhold navnlig tage hensyn til følgende:',1,3,'020.008.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2314,1,2312,2312,'list_item','1)',NULL,'Værdiforringelsen af lejerens inventar og lign. ved flytning.',2,3,'020.008.002.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2315,1,2312,2312,'list_item','2)',NULL,'Lejerens flytteudgifter.',3,3,'020.008.002.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2316,1,2312,2312,'list_item','3)',NULL,'Det forhold, at ejendommen skal nedrives eller ombygges, og at lejeren er gjort bekendt hermed ved lejeaftalens indgåelse.',4,3,'020.008.002.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2317,1,2312,2312,'subsection','Stk. 3.',NULL,'Lejeren skal ikke fraflytte, før lejeren har modtaget den erstatning, der er tilkendt denne, eller udlejeren ved bankgaranti eller på anden måde har stillet betryggende sikkerhed for erstatningsbeløbets betaling.',5,3,'020.008.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2318,1,2309,2309,'paragraph','§ 179.',NULL,'Vil lejeren godkende opsigelsen, men kræve erstatning efter § 178, skal lejeren meddele udlejeren dette, senest 6 uger efter at opsigelsen er kommet frem til lejeren.',3,2,'020.008.003','{\"source_class\":\"Paragraf\",\"source_id\":\"idc420cd49-1006-4faf-8c1a-cd612e516120\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2319,1,2318,2318,'subsection','Stk. 2.',NULL,'Lejeren må endvidere anlægge sag ved boligretten senest 6 uger efter udløbet af den i stk. 1 nævnte frist.',1,3,'020.008.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2320,1,2309,2309,'paragraph','§ 180.',NULL,'Boligretten kan fastsætte, at hele erstatningen eller en del af denne skal tilbagebetales til udlejeren, hvis lejeren på ny åbner forretning i samme branche inden for en af retten fastsat tidsfrist på højst 3 år og inden for en af retten fastsat afstand fra det tidligere forretningslokale.',4,2,'020.008.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id0c81125e-154c-4423-b81c-acb87602e7bc\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2321,1,2320,2320,'subsection','Stk. 2.',NULL,'Lejeren må ikke åbne forretning i samme branche inden for den af retten fastsatte afstand i tid og sted, før lejeren har tilbagebetalt erstatning i overensstemmelse med reglerne i stk. 1.',1,3,'020.008.004.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2322,1,2264,2264,'paragraph_group',NULL,'Fravigelighed',NULL,9,1,'020.009',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2323,1,2322,2322,'paragraph','§ 181.',NULL,'§§ 171-179 kan, for så vidt angår opsigelse fra udlejerens side, ikke ved aftale fraviges til skade for lejeren, så længe udlejeren ikke har opsagt lejeren.',1,2,'020.009.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id90a9a07e-99a9-47f9-a953-6891cc654a27\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2324,1,2323,2323,'subsection','Stk. 2.',NULL,'Lejeren kan ikke give afkald på sin ægtefælles ret efter § 169, stk. 2.',1,3,'020.009.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2325,1,NULL,0,'chapter','Kapitel 21','Udlejerens ret til at hæve lejeaftalen',NULL,21,0,'021',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2326,1,2325,2325,'paragraph_group',NULL,'Hvornår kan udlejeren hæve lejeaftalen',NULL,1,1,'021.001',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2327,1,2326,2326,'paragraph','§ 182.',NULL,'Udlejeren kan hæve lejeaftalen i følgende tilfælde, jf. dog § 183:',1,2,'021.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idce0340c2-5555-4618-bc2a-34c416674098\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2328,1,2327,2327,'list_item','1)',NULL,'Når leje eller anden pligtig pengeydelse ikke er betalt rettidigt, jf. stk. 2.',1,3,'021.001.001.001','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2329,1,2327,2327,'list_item','2)',NULL,'Når det lejede benyttes til andet end aftalt og lejeren ikke trods udlejerens indsigelse er ophørt hermed.',2,3,'021.001.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2330,1,2327,2327,'list_item','3)',NULL,'Når lejeren modsætter sig, at udlejeren eller andre får adgang til det lejede, hvor de har ret hertil efter § 54, stk. 1, nr. 3, § 102, § 126, stk. 2, og § 186.',3,3,'021.001.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2331,1,2327,2327,'list_item','4)',NULL,'Når lejeren fraflytter det lejede i utide uden aftale med udlejeren.',4,3,'021.001.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2332,1,2327,2327,'list_item','5)',NULL,'Når lejeren vanrøgter det lejede og ikke uden ophold efter udlejerens indsigelse bringer det lejede i stand.',5,3,'021.001.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2333,1,2327,2327,'list_item','6)',NULL,'Når lejeren helt eller delvis overlader brugen af det lejede til en anden i tilfælde, hvor lejeren ikke er berettiget hertil og trods udlejerens indsigelse ikke bringer forholdet til ophør.',6,3,'021.001.001.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2334,1,2327,2327,'list_item','7)',NULL,'Når lejeren har tilsidesat god skik og orden, jf. § 153, stk. 1, nr. 1-8 eller 11, jf. § 154, stk. 2, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',7,3,'021.001.001.007','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2335,1,2327,2327,'list_item','8)',NULL,'Når lejeren har tilsidesat betingelserne i et betinget lejeforhold, jf. § 154, stk. 1, nr. 1, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',8,3,'021.001.001.008','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2336,1,2327,2327,'list_item','9)',NULL,'Når nogen er straffet i medfør af § 4 i lov om forbud mod besøgende i bestemte lokaler for at have modtaget besøgende i eller ved det lejede i strid med et forbud nedlagt i medfør af loven, eller når lejeren er straffet i medfør af § 8, stk. 1, i lov om forbud mod anvendelse af bestemte ejendomme som samlingssted for en gruppe for at have anvendt det lejede som samlingssted i strid med et forbud nedlagt i medfør af loven.',9,3,'021.001.001.009','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2337,1,2327,2327,'list_item','10)',NULL,'Når lejeren eller medlemmer af lejerens husstand er idømt en ubetinget fængselsstraf eller anden strafferetlig retsfølge af frihedsberøvende karakter for overtrædelse af §§ 119, 119 b, 134 a, 180, 181, 192 a, 216, 237 eller 244-246, § 252, stk. 1, §§ 260, 266, 276 a, 281 eller 288 eller § 291, stk. 2, i straffeloven eller i medfør af § 3 i lov om euforiserende stoffer for at have besiddet euforiserende stoffer med henblik på videreoverdragelse, og når overtrædelsen er begået inden for 1 km fra den ejendom, hvor lejemålet er beliggende.',10,3,'021.001.001.010','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2338,1,2327,2327,'list_item','11)',NULL,'Når lejeren af en butik eller beværtning trods udlejerens indsigelse ikke opfylder pligten til at holde forretningen åben og i forsvarlig drift.',11,3,'021.001.001.011','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2339,1,2327,2327,'list_item','12)',NULL,'Når en lejer, der helt eller delvis skal betale lejen ved at udføre arbejde, groft forsømmer sine pligter ved arbejdets udførelse og arbejdsforholdet som følge heraf bringes til ophør.',12,3,'021.001.001.012','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2340,1,2327,2327,'list_item','13)',NULL,'Når lejeren i øvrigt misligholder sine forpligtelser på en sådan måde, at lejerens fjernelse er påkrævet.',13,3,'021.001.001.013','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2341,1,2327,2327,'subsection','Stk. 2.',NULL,'Udlejeren kan kun hæve lejeaftalen som følge af for sen betaling, hvis lejeren ikke har berigtiget restancen, senest 14 dage efter at skriftligt påkrav herom er kommet frem til lejeren. Udlejerens påkrav kan tidligst afgives efter 3. hverdag efter sidste rettidige betalingsdag og skal udtrykkeligt angive, at lejeforholdet kan ophæves, hvis lejerestancen ikke betales inden fristens udløb. Er den i 2. pkt. nævnte hverdag en lørdag eller grundlovsdag, kan påkrav tidligst afgives den følgende hverdag. Udløber den i 2. pkt. nævnte frist på en helligdag, en lørdag eller grundlovsdag, udskydes udløbet af fristen til den efterfølgende hverdag. Som gebyr for påkravet kan udlejeren kræve 287 kr. Det i 5. pkt. nævnte beløb er fastsat i 2021-niveau og reguleres én gang årligt, jf. § 204, stk. 1. Gebyret er pligtig pengeydelse i lejeforholdet.',14,3,'021.001.001.014','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2342,1,2327,2327,'subsection','Stk. 3.',NULL,'Vedrører lejeaftalen en plejebolig efter § 1, stk. 1, 2. pkt., i den tidligere gældende lov om boliger for ældre og personer med handicap, jf. lovbekendtgørelse nr. 316 af 24. april 1996 med senere ændringer, eller § 5, stk. 2, i lov om almene boliger m.v. eller en ustøttet privat plejebolig, jf. § 1, stk. 5, anvist af kommunen eller amtskommunen, kan aftalen kun hæves efter stk. 1, når lejeren samtidig anvises en anden og passende bolig.',15,3,'021.001.001.015','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2343,1,2325,2325,'paragraph_group',NULL,'Yderligere betingelser for at kunne hæve lejeaftalen',NULL,2,1,'021.002',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2344,1,2343,2343,'paragraph','§ 183.',NULL,'Skønnes det forhold, der lægges lejeren til last, at være af uvæsentlig betydning, kan udlejeren ikke hæve lejeaftalen.',1,2,'021.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2fcb77bb-4a33-4d36-b536-65d83f850421\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2345,1,2344,2344,'subsection','Stk. 2.',NULL,'Udlejeren kan ikke påberåbe sig de i § 182, nr. 1-6, nævnte forhold, hvis de er rettet, inden udlejeren hæver lejeaftalen.',1,3,'021.002.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2346,1,2325,2325,'paragraph_group',NULL,'Lejerens og udlejerens pligter efter ophævelsen',NULL,3,1,'021.003',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2347,1,2346,2346,'paragraph','§ 184.',NULL,'Når udlejeren hæver lejeaftalen, skal lejeren straks fraflytte og betale leje m.v. for tiden, indtil lejeren kunne fraflytte med sædvanligt varsel. Lejeren skal endvidere erstatte udlejeren ethvert tab, derunder omkostningerne ved lejerens udsættelse af det lejede.',1,2,'021.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idb2ab71ad-b939-4619-bc67-ab96d252d014\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2348,1,2347,2347,'subsection','Stk. 2.',NULL,'Udlejeren skal bestræbe sig for at genudleje det lejede. Hvad udlejeren indvinder eller burde have indvundet ved genudlejning i det i stk. 1 nævnte tidsrum, skal fragå i udlejerens krav over for lejeren.',1,3,'021.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2349,1,2325,2325,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'021.004',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2350,1,2349,2349,'paragraph','§ 185.',NULL,'Dette kapitel kan ikke fraviges, således at udlejeren skal kunne ophæve aftalen af andre grunde end de i § 182, jf. § 183, nævnte, eller at disse skal have videregående følger for lejeren end fastsat i § 184.',1,2,'021.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idbbdbedf0-4522-4451-9867-de6e02ccd68b\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2351,1,NULL,0,'chapter','Kapitel 22','Lejerens fraflytning',NULL,22,0,'022',NULL,'2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2352,1,2351,2351,'paragraph','§ 186.',NULL,'Er der afgivet opsigelse, eller skal det lejede af anden grund fraflyttes, skal lejeren give adgang til at bese det lejede. Lejeren fastsætter tiden herfor. Den skal være mindst 2 timer hveranden hverdag på et tidspunkt, der er bekvemt for en besigtigelse. Denne kan kun finde sted med deltagelse af udlejeren eller dennes stedfortræder, når lejeren ikke er repræsenteret.',1,1,'022.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id838c20d4-73dd-4b06-a7bd-00fd41e6d06e\"}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2353,1,2352,2352,'subsection','Stk. 2.',NULL,'Lejeren skal senest 8 dage før fraflytning opgive den adresse, som meddelelser, herunder krav efter § 187, kan sendes til.',1,2,'022.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:17','2026-03-30 23:41:17'),
(2354,1,2351,2351,'paragraph','§ 187.',NULL,'Det lejede skal være fraflyttet senest kl. 12.00 på fraflytningsdagen. Lejeren skal aflevere det lejede i samme stand som ved overleveringen med undtagelse af den forringelse, som skyldes slid og ælde, og som ikke er omfattet af lejerens vedligeholdelsespligt, og mangler, som det påhviler udlejeren at udbedre. Det kan ikke pålægges lejeren at bringe det lejede i bedre stand end den, hvori lejeren overtog det lejede.',2,1,'022.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idb8f2d6bc-2e2e-44bc-9a7d-93ba60408189\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2355,1,2354,2354,'subsection','Stk. 2.',NULL,'Udlejeren kan ikke gøre krav i medfør af stk. 1 gældende, når der er forløbet mere end 2 uger fra flyttesynet, jf. stk. 3, eller fra fraflytningsdagen for lejemål, der ikke er omfattet af pligten i stk. 3. Udgifter til istandsættelse, der ikke er medtaget i fraflytningsrapporten, jf. stk. 4, er lejeren uvedkommende. 1. og 2. pkt. gælder dog ikke, hvis manglen ikke kan erkendes ved anvendelse af sædvanlig agtpågivenhed eller lejeren har handlet svigagtigt.',1,2,'022.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2356,1,2354,2354,'subsection','Stk. 3.',NULL,'Udlejere, der udlejer mere end én beboelseslejlighed, skal syne beboelseslejligheden, senest 2 uger efter at udlejeren er blevet bekendt med, at fraflytning har fundet sted. Den fraflyttende lejer skal indkaldes skriftligt til synet med mindst 1 uges varsel. Udlejeren og lejeren kan dog aftale et kortere varsel, når lejeforholdet er ophævet eller opsagt.',2,2,'022.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2357,1,2354,2354,'subsection','Stk. 4.',NULL,'Udlejeren skal i forbindelse med synet, jf. stk. 3, udarbejde en fraflytningsrapport. Rapporten skal udleveres til lejeren ved synet eller sendes til lejeren senest 2 uger efter synet, såfremt lejeren ikke er til stede ved synet eller ikke vil kvittere for modtagelsen af rapporten.',3,2,'022.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2358,1,2354,2354,'subsection','Stk. 5.',NULL,'Ved overtrædelse af stk. 3 og 4 bortfalder udlejerens krav på istandsættelse efter stk. 1.',4,2,'022.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2359,1,2351,2351,'paragraph','§ 188.',NULL,'Forbedringer, som lejeren har foretaget, må kun fjernes, når lejeren bringer det lejede i den stand, hvori lejeren overtog det.',3,1,'022.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id597f619f-ec13-4e4e-862e-cdc213ec769a\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2360,1,2359,2359,'subsection','Stk. 2.',NULL,'Har lejeren med udlejerens samtykke efter § 141 foretaget ændringer af det lejede, kan udlejeren kun kræve retablering, når udlejeren har taget forbehold herfor, da udlejeren meddelte samtykket.',1,2,'022.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2361,1,2359,2359,'subsection','Stk. 3.',NULL,'Har lejeren iværksat forbedringsarbejder m.v. mod godtgørelse ved fraflytning, jf. § 145, stk. 1, og § 63 i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010, og er disse ikke tilendebragt, kan udlejeren enten kræve arbejderne færdiggjort eller eventuelt kræve retablering.',2,2,'022.003.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2362,1,2351,2351,'paragraph_group',NULL,'Fravigelighed',NULL,4,1,'022.004',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2363,1,2362,2362,'paragraph','§ 189.',NULL,'§ 187, stk. 1, 3. pkt., stk. 2, 1. pkt., hvor der i henhold til § 187, stk. 3, er pligt til at afholde flyttesyn, og stk. 3-5, kan ikke ved aftale fraviges til skade for lejeren.',1,2,'022.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id272b149b-dd98-41e6-bc90-b41a098ec54f\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2364,1,2351,2351,'paragraph_group',NULL,'Huslejenævnets kompetence',NULL,5,1,'022.005',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2365,1,2364,2364,'paragraph','§ 190.',NULL,'Huslejenævnet træffer afgørelser i tvister om reglerne i §§ 187-189.',1,2,'022.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id0b51896e-cd34-480a-993c-44d9c8404f78\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2366,1,NULL,0,'chapter','Kapitel 23','Beboerrepræsentation',NULL,23,0,'023',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2367,1,2366,2366,'paragraph','§ 191.',NULL,'Formålet med ordningen med beboerrepræsentation er at give lejerne mulighed for at vælge repræsentanter, som kan varetage lejernes interesser i forholdet til udlejeren og være forhandlingspart over for udlejeren. Som et led heri er det et væsentligt formål med ordningen, at den medvirker til at sikre det bedst mulige grundlag for samarbejdet imellem lejerne og udlejeren i den enkelte ejendom. Med henblik på at sikre et godt og konstruktivt samarbejde om forhold af fælles interesse i ejendommen skal udlejeren og beboerrepræsentanterne derfor bestræbe sig på at sikre et højt gensidigt informationsniveau om dispositioner vedrørende ejendommen. Udlejeren bør for at fremme samarbejdet inddrage beboerrepræsentanterne i alle spørgsmål, der er af væsentlig betydning for lejerne i ejendommen.',1,1,'023.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id2443e192-1eb0-40bf-b3c0-a422c209aa34\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2368,1,2367,2367,'subsection','Stk. 2.',NULL,'Beboerrepræsentanterne kan følgende:',1,2,'023.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2369,1,2367,2367,'list_item','1)',NULL,'Få oplysning om, hvem der ejer ejendommen, og hvem der administrerer den.',2,2,'023.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2370,1,2367,2367,'list_item','2)',NULL,'Drøfte ethvert spørgsmål af betydning for ejendommens drift med udlejeren.',3,2,'023.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2371,1,2367,2367,'list_item','3)',NULL,'Blive holdt orienteret, når der foretages genudlejning af lejligheder i ejendommen.',4,2,'023.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2372,1,2367,2367,'list_item','4)',NULL,'Blive holdt orienteret om udlejerens ansættelse og afskedigelse af ejendomsfunktionærer.',5,2,'023.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2373,1,2366,2366,'paragraph','§ 192.',NULL,'I ejendomme med mindst seks beboelseslejligheder har lejerne ret til at vælge beboerrepræsentanter.',2,1,'023.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idfbda8c9d-a686-4390-b583-7e5572467b82\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2374,1,2373,2373,'subsection','Stk. 2.',NULL,'Ved oprettelsen af en beboerrepræsentation i en ejendom skal mindst 50 pct. af de på et beboermøde fremmødte lejere vælge beboerrepræsentanter. Er der ikke 50 pct. af lejerne til stede på beboermødet, skal en beslutning om at oprette en beboerrepræsentation bekræftes ved en efterfølgende urafstemning blandt samtlige lejere. Der skal vælges tre beboerrepræsentanter. I ejendomme med mindre end 13 lejligheder nedsættes antallet til en.',1,2,'023.002.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2375,1,2373,2373,'subsection','Stk. 3.',NULL,'I ejendomme med mindre end seks og mere end to udlejede beboelseslejligheder har et flertal af lejerne samme beføjelser som beboerrepræsentationen i andre ejendomme. Der skal vælges en talsmand til at repræsentere lejerne over for udlejerne. Talsmanden skal handle i overensstemmelse med lejerflertallets beslutninger.',2,2,'023.002.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2376,1,2373,2373,'subsection','Stk. 4.',NULL,'Er der oprettet en beboerrepræsentation i en ejendom, fortsætter den, indtil den besluttes ophævet, jf. dog stk. 5 og 6. En beslutning om at ophæve beboerrepræsentationen skal drøftes efter reglerne i stk. 2.',3,2,'023.002.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2377,1,2373,2373,'subsection','Stk. 5.',NULL,'Såfremt det ikke med sikkerhed kan konstateres, hvorvidt der stadig er en beboerrepræsentation i ejendommen, herunder om de valgte beboerrepræsentanter stadig bebor ejendommen, kan udlejeren anmode samtlige beboelseslejere om inden en vis frist skriftligt at oplyse, hvem der er beboerrepræsentanter. Svarfristen skal være mindst 6 uger, dog således at der ved beregning af fristen ses bort fra juli måned. Hvis udlejeren ved svarfristens udløb ikke har modtaget den udbedte oplysning, anses beboerrepræsentationen for bortfaldet.',4,2,'023.002.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2378,1,2373,2373,'subsection','Stk. 6.',NULL,'Beboerrepræsentationen bortfalder, såfremt der ikke har været afholdt beboermøde med valg af beboerrepræsentanter i 2 år.',5,2,'023.002.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2379,1,2373,2373,'subsection','Stk. 7.',NULL,'Er flere ejendomme, der ejes af samme ejer, opført kontinuerligt som en samlet bebyggelse, og har disse ejendomme fælles friarealer eller nogen form for driftsfællesskab, kan der oprettes en beboerrepræsentation, når ejendommene i alt har mindst seks beboelseslejligheder. Det samme gælder, hvor flere ejendomme er samvurderet eller samnoteret i tingbogen. I sådanne ejendomme skal beboerrepræsentationen omfatte samtlige ejendomme.',6,2,'023.002.006','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2380,1,2373,2373,'subsection','Stk. 8.',NULL,'I en ejendom, der er opdelt i ejerlejligheder, gælder reglerne om beboerrepræsentation for lejere, hvis udlejeren ejer mindst seks beboelseslejligheder i ejerforeningen.',7,2,'023.002.007','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2381,1,2373,2373,'subsection','Stk. 9.',NULL,'I en ejendom, der ejes af en andelsboligforening, gælder reglerne om beboerrepræsentation, hvis mindst seks beboelseslejligheder ikke bebos af andelshavere.',8,2,'023.002.008','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2382,1,2373,2373,'subsection','Stk. 10.',NULL,'Indenrigs- og boligministeren fastsætter nærmere regler om afholdelse af beboermøde og valg af beboerrepræsentanter og om afholdelse af udgifter i forbindelse med beboerrepræsentation.',9,2,'023.002.009','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2383,1,2366,2366,'paragraph','§ 193.',NULL,'Er der valgt beboerrepræsentanter, kan et beboermøde vedtage en husorden. Den skal være gældende, medmindre udlejeren har vægtige grunde til at modsætte sig dette.',3,1,'023.003','{\"source_class\":\"Paragraf\",\"source_id\":\"id42cdc7c1-a72d-46a6-a973-5c4ea5e4e6dd\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2384,1,2383,2383,'subsection','Stk. 2.',NULL,'I ejendomme, der er opdelt i ejerlejligheder, og i ejendomme, der ejes af andelsboligforeninger, skal samtlige beboere indkaldes til det beboermøde, der træffer afgørelse om husordenen. For hver beboelseslejlighed kan afgives én stemme.',1,2,'023.003.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2385,1,2366,2366,'paragraph','§ 194.',NULL,'Udlejeren skal inden for 2 uger fra den endelige afgørelse meddele det til beboerrepræsentationen, når der træffes afgørelser om boliglejeforhold, som giver en lejer helt eller delvist medhold og ikke angår husordenssager i den eller de ejendomme, som beboerrepræsentationen vedrører. I ejendomme, hvor der ikke findes en beboerrepræsentation, skal udlejeren inden for 2 uger fra den endelige afgørelse meddele det til samtlige lejere, når der træffes afgørelser om lejeforhold, som giver en lejer helt eller delvist medhold og ikke angår husordenssager i ejendommen.',4,1,'023.004','{\"source_class\":\"Paragraf\",\"source_id\":\"id93c7a19d-569d-443c-a223-b1f22c9eb43e\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2386,1,2385,2385,'subsection','Stk. 2.',NULL,'Meddelelsen skal gives skriftligt og indeholde oplysning om tvistens emne og afgørelsens resultat. Meddelelsen skal tillige indeholde kopi af den trufne afgørelse. Indeholder meddelelsen ikke disse oplysninger, er den ugyldig. De oplysninger, der er nævnt i 1. pkt., kan gives digitalt, herunder ved at gøre oplysningerne tilgængelige på en digital platform, når udlejeren har givet lejeren meddelelse herom.',1,2,'023.004.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2387,1,2385,2385,'subsection','Stk. 3.',NULL,'Overtrædelse af stk. 1 straffes med bøde eller fængsel indtil 4 måneder, medmindre højere straf er forskyldt efter anden lovgivning.',2,2,'023.004.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2388,1,2385,2385,'subsection','Stk. 4.',NULL,'Der kan pålægges selskaber m.v. (juridiske personer) strafansvar efter reglerne i straffelovens 5. kapitel.',3,2,'023.004.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2389,1,2366,2366,'paragraph_group',NULL,'Fravigelighed',NULL,5,1,'023.005',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2390,1,2389,2389,'paragraph','§ 195.',NULL,'Dette kapitel kan ikke ved aftale fraviges til skade for lejeren. § 194 kan ikke fraviges.',1,2,'023.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id4b90af01-a9e8-4142-a51c-b6f2f2751401\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2391,1,NULL,0,'chapter','Kapitel 24','Tilbudspligt',NULL,24,0,'024',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2392,1,2391,2391,'paragraph_group',NULL,'Anvendelsesområde',NULL,1,1,'024.001',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2393,1,2392,2392,'paragraph','§ 196.',NULL,'I ejendomme, der helt eller delvis anvendes til beboelse, skal udlejeren tilbyde lejerne ejendommen til overtagelse på andelsbasis, inden ejendommen overdrages til anden side.',1,2,'024.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf0c4f603-4248-4687-95e8-0d728c5ddedc\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2394,1,2393,2393,'subsection','Stk. 2.',NULL,'Reglerne om tilbudspligt finder anvendelse på ejendomme, der udelukkende anvendes til beboelse, og som indeholder mindst seks beboelseslejligheder. Reglerne finder endvidere anvendelse på andre ejendomme med mindst 13 beboelseslejligheder.',1,3,'024.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2395,1,2393,2393,'subsection','Stk. 3.',NULL,'Reglerne om tilbudspligt finder ikke anvendelse på ejendomme, der er opdelt i ejerlejligheder. Dette gælder dog ikke den ejerlejlighed, som efter § 16, stk. 3, i lov om ejerlejligheder indeholder boligerne i den oprindelige ejendom, og den ejerlejlighed, som efter § 20, stk. 1, 3. pkt., i lov om ejerlejligheder indeholder boligerne og eventuelle lokaler til andet end beboelse i den oprindelige ejendom.',2,3,'024.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2396,1,2393,2393,'subsection','Stk. 4.',NULL,'Reglerne om tilbudspligt anvendes ved overdragelse af ejendomme omfattet af lov om leje af almene boliger, hvis ejendommen efter overdragelsen ikke er omfattet af samme lov. Dette gælder dog ikke for ejendomme, som er beliggende i et udsat boligområde, jf. § 61 a, stk. 1, i lov om almene boliger m.v., eller et boligområde, som ikke opfylder betingelserne i § 61 a, stk. 1, i lov om almene boliger m.v., men er omfattet af en fælles udviklingsplan eller en kommunal udviklingsplan, jf. § 168 a, stk. 1, eller § 168 b, stk. 1, i lov om almene boliger m.v.',3,3,'024.001.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2397,1,2393,2393,'subsection','Stk. 5.',NULL,'Tilbudspligten efter stk. 1 og 2 opretholdes, selv om ejeren foretager udstykning, matrikulering eller arealoverførsel efter lov om udstykning og anden registrering i matriklen.',4,3,'024.001.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2398,1,2391,2391,'paragraph_group',NULL,'Øvrige rettigheder',NULL,2,1,'024.002',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2399,1,2398,2398,'paragraph','§ 197.',NULL,'Tilbudspligten respekterer private forkøbsrettigheder og køberettigheder, der er tinglyst før den 3. maj 1979, men går i øvrigt forud for andre rettigheder over ejendommen, uanset hvornår de er stiftet.',1,2,'024.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ide1cf9662-e19a-493b-af1e-0928b1a5540a\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2400,1,2391,2391,'paragraph_group',NULL,'Aktivering af tilbudspligt',NULL,3,1,'024.003',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2401,1,2400,2400,'paragraph','§ 198.',NULL,'Tilbudspligten gælder, når ejendommen eller en del heraf overdrages ved salg, gave, fusion, spaltning eller mageskifte. Tilbudspligten gælder endvidere ved overdragelse af aktier og anparter i aktie- og anpartsselskaber, som ejer ejendomme, når erhververen herved opnår majoriteten af stemmerne i selskabet.',1,2,'024.003.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id57309297-0e26-4ee6-a43b-3c824c3c1883\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2402,1,2401,2401,'subsection','Stk. 2.',NULL,'Tilbudspligten kommer dog ikke til anvendelse i følgende tilfælde:',1,3,'024.003.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2403,1,2401,2401,'list_item','1)',NULL,'Når erhververen er staten eller en kommune.',2,3,'024.003.001.002','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2404,1,2401,2401,'list_item','2)',NULL,'Når erhververen er den hidtidige ejers ægtefælle eller er beslægtet eller besvogret med ejeren i op- eller nedadstigende linje eller i dennes sidelinje så nær som søskende eller disses børn.',3,3,'024.003.001.003','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2405,1,2401,2401,'list_item','3)',NULL,'Når erhververen er en hidtidig medejer.',4,3,'024.003.001.004','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2406,1,2401,2401,'list_item','4)',NULL,'Når erhvervelsen sker ved arv, medmindre erhververen er en juridisk person.',5,3,'024.003.001.005','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2407,1,2401,2401,'list_item','5)',NULL,'Når ejendommen inden for de seneste 5 år har været ejet af en andelsboligforening, et boligaktieselskab eller et boliganpartsselskab.',6,3,'024.003.001.006','{\"source_class\":\"Liste1\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2408,1,2391,2391,'paragraph_group',NULL,'Opfyldelse af tilbudspligt',NULL,4,1,'024.004',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2409,1,2408,2408,'paragraph','§ 199.',NULL,'Tilbudspligten opfyldes, ved at ejeren over for samtlige lejere af beboelseslejligheder fremsætter tilbud om, at en af beboerne dannet andelsboligforening kan erhverve ejendommen til samme købesum, kontante udbetaling og øvrige vilkår, som ejeren kan opnå ved salg til anden side. Vilkårene skal være af et sådant indhold, at de kan opfyldes af en andelsboligforening. Acceptfristen skal være mindst 10 uger, dog således at der ved beregning af fristen ses bort fra juli måned.',1,2,'024.004.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idc8873190-99b2-44a3-a28d-a096c39d08b4\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2410,1,2409,2409,'subsection','Stk. 2.',NULL,'I tilfælde af påtænkt salg skal tilbuddet ledsages af dokumentation for, at ejeren ved salget kan opnå de tilbudte vilkår. I tilfælde af påtænkt overdragelse ved gave, fusion, spaltning eller mageskifte eller af påtænkt arveudlæg skal der til afgørelse af, om købesummen og de øvrige tilbudte vilkår svarer til ejendommens værdi i handel og vandel som udlejningsejendom, optages syn og skøn efter reglerne herom i retsplejelovens § 343.',1,3,'024.004.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2411,1,2409,2409,'subsection','Stk. 3.',NULL,'Ved overdragelse af aktier og anparter, hvor tilbudspligten efter § 198, stk. 1, 2. pkt., gælder, skal der ligeledes optages syn og skøn, jf. stk. 2. Dette gælder dog ikke ved overdragelse af aktier og anparter i selskaber, som ikke ejer andre aktiver end den tilbudspligtige ejendom.',2,3,'024.004.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2412,1,2409,2409,'subsection','Stk. 4.',NULL,'Senest samtidig med tilbuddet skal ejeren give sædvanlige oplysninger om ejendommen, herunder ejendommens driftsudgifter, lejeforhold og saldi på de forskellige konti, som ejeren skal føre i henhold til denne lov. Den i stk. 1 nævnte acceptfrist løber fra det tidspunkt, hvor lejerne har modtaget oplysningerne. De oplysninger, der er nævnt i 1. pkt., kan gives digitalt, herunder ved at gøre oplysningerne tilgængelige på en digital platform, når udlejeren har givet lejeren meddelelse herom.',3,3,'024.004.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2413,1,2409,2409,'subsection','Stk. 5.',NULL,'Ejeren kan afvise andelsboligforeningens accept, hvis foreningen ikke på anfordring dokumenterer, at den kan betale den krævede kontante udbetaling.',4,3,'024.004.001.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2414,1,2409,2409,'subsection','Stk. 6.',NULL,'Bliver ejerens tilbud ikke accepteret, kan ejendommen videreoverdrages til andre ved salg på de tilbudte vilkår eller ved gave, mageskifte eller arveudlæg, hvis skøde anmeldes til tinglysning senest 1 år efter tilbuddet til lejerne.',5,3,'024.004.001.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2415,1,2391,2391,'paragraph_group',NULL,'Tinglysning',NULL,5,1,'024.005',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2416,1,2415,2415,'paragraph','§ 200.',NULL,'Justitsministeren fastsætter regler om tinglysning af dokumenter om overdragelse af en ejendom, hvorpå der er tilbudspligt.',1,2,'024.005.001','{\"source_class\":\"Paragraf\",\"source_id\":\"iddc8b2c55-5064-4658-8979-fd04a10b74bf\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2417,1,2391,2391,'paragraph_group',NULL,'Fravigelighed',NULL,6,1,'024.006',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2418,1,2417,2417,'paragraph','§ 201.',NULL,'§§ 196-200 kan ikke ved aftale fraviges til skade for lejeren.',1,2,'024.006.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id1f52d37e-5a5b-4e16-b36e-091c124cd84d\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2419,1,NULL,0,'chapter','Kapitel 25','Boligretten',NULL,25,0,'025',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2420,1,2419,2419,'paragraph_group',NULL,'Saglig kompetence',NULL,1,1,'025.001',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2421,1,2420,2420,'paragraph','§ 202.',NULL,'Tvister om lejeforhold, der er omfattet af denne lov, kan i 1. instans indbringes for byretten, hvis spørgsmålet ikke efter denne lov kan indbringes for huslejenævnet eller i Københavns Kommune ankenævnet. Retten benævnes boligretten.',1,2,'025.001.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id3abff2e2-191c-438f-a595-112f3cf0e000\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2422,1,2421,2421,'subsection','Stk. 2.',NULL,'Parterne kan dog, når der er opstået en tvist, aftale, at tvisten kan indbringes for boligretten, uden at huslejenævnet og i Københavns Kommune ankenævnet har behandlet sagen.',1,3,'025.001.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2423,1,2421,2421,'subsection','Stk. 3.',NULL,'Stk. 1 og 2 begrænser ikke fogedrettens adgang til at gennemføre en umiddelbar fogedforretning, jf. retsplejelovens kapitel 55, om udsættelse af et lejemål, der er ophævet som følge af lejerens tilsidesættelse af god skik og orden.',2,3,'025.001.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2424,1,2419,2419,'paragraph_group',NULL,'Fravigelighed',NULL,2,1,'025.002',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2425,1,2424,2424,'paragraph','§ 203.',NULL,'Dette kapitel kan ikke fraviges.',1,2,'025.002.001','{\"source_class\":\"Paragraf\",\"source_id\":\"ideab4a648-4e65-4c23-bbb3-0d1aaf19ca63\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2426,1,NULL,0,'chapter','Kapitel 26','Regulering af beløb og beløbsgrænser',NULL,26,0,'026',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2427,1,2426,2426,'paragraph','§ 204.',NULL,'De i § 19, stk. 2 og 5, § 23, stk. 4, § 105, stk. 1, § 106, stk. 1, § 117, stk. 1, § 131, stk. 1, § 138, § 145, stk. 5, og § 182, stk. 2, nævnte beløb er opgjort i 2021-niveau og reguleres én gang årligt efter udviklingen i Danmarks Statistiks nettoprisindeks i en 12-månedersperiode sluttende i juni måned året før det finansår, reguleringen vedrører. Beløbene afrundes til nærmeste hele kronebeløb.',1,1,'026.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id8f3e8097-17c1-4a27-9342-68cd26a03943\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2428,1,2427,2427,'subsection','Stk. 2.',NULL,'De i § 119, stk. 1, og § 120, stk. 1 og 2, nævnte beløb reguleres én gang årligt efter udviklingen i Danmarks Statistiks nettoprisindeks i en 12-månedersperiode sluttende i juni måned året før det finansår, reguleringen vedrører. Beløbene afrundes til nærmeste hele kronebeløb.',1,2,'026.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2429,1,NULL,0,'chapter','Kapitel 27','Delegation',NULL,27,0,'027',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2430,1,2429,2429,'paragraph','§ 205.',NULL,'Indenrigs- og boligministeren kan bemyndige en under ministeriet oprettet styrelse til at udøve de beføjelser, der i denne lov er tillagt ministeren.',1,1,'027.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id0d899f78-8de4-4f9f-88f5-305a61eca346\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2431,1,2430,2430,'subsection','Stk. 2.',NULL,'Indenrigs- og boligministeren kan fastsætte regler om adgangen til at påklage afgørelser, der er truffet i henhold til bemyndigelse efter stk. 1, herunder at afgørelsen ikke skal kunne indbringes for ministeren.',1,2,'027.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2432,1,NULL,0,'chapter','Kapitel 28','Beregning af bruttoetageareal',NULL,28,0,'028',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2433,1,2432,2432,'paragraph','§ 206.',NULL,'Indenrigs- og boligministeren fastsætter nærmere regler om beregning af boligers og erhvervslokalers bruttoetageareal i henhold til denne lov.',1,1,'028.001','{\"source_class\":\"Paragraf\",\"source_id\":\"idf79cf87b-e8ce-482a-9c6b-58be554ec962\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2434,1,NULL,0,'chapter','Kapitel 29','Ikrafttræden m.v.',NULL,29,0,'029',NULL,'2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2435,1,2434,2434,'paragraph','§ 207.',NULL,'Loven træder i kraft den 1. juli 2022.',1,1,'029.001','{\"source_class\":\"Paragraf\",\"source_id\":\"id5891329d-a232-464d-9574-04d3addb7e8c\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2436,1,2435,2435,'subsection','Stk. 2.',NULL,'Lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, ophæves.',1,2,'029.001.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2437,1,2435,2435,'subsection','Stk. 3.',NULL,'Lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, ophæves.',2,2,'029.001.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2438,1,2435,2435,'subsection','Stk. 4.',NULL,'Reglerne i § 3, stk. 2, i lov nr. 609 af 21. december 1983, § 4, stk. 6, i lov nr. 419 af 1. juni 1994, § 2, stk. 2, i lov nr. 461 af 12. juni 1996, § 11, stk. 3, 5, 7 og 8, i lov nr. 406 af 31. maj 2000, § 5, stk. 3, i lov nr. 1090 af 17. december 2002, § 6, stk. 2, i lov nr. 1219 af 27. december 2003, § 9, stk. 2, i lov nr. 1235 af 27. december 2003, § 7, stk. 3, i lov nr. 488 af 9. juni 2004, § 3, stk. 2, i lov nr. 632 af 11. juni 2010, § 4, stk. 3, i lov nr. 517 af 5. juni 2012, § 6, stk. 3 og 4, i lov nr. 439 af 6. maj 2014, § 5, stk. 3, 6 og 10, i lov nr. 310 af 30. marts 2015, § 4, stk. 2, i lov nr. 643 af 8. juni 2016, § 7, stk. 8, i lov nr. 550 af 30. maj 2017, § 3, stk. 2, i lov nr. 1561 af 19. december 2017, § 58, stk. 6, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, § 3, stk. 2 og 3, i lov nr. 817 af 9. juni 2020, § 3, stk. 2 og 3, i lov nr. 818 af 9. juni 2020 og § 3, stk. 2, i lov nr. 819 af 9. juni 2020 finder fortsat anvendelse.',3,2,'029.001.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2439,1,2434,2434,'paragraph','§ 208.',NULL,'Regler fastsat i medfør af lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, forbliver i kraft, indtil de ophæves eller afløses af forskrifter udstedt i medfør af denne lov eller lov om boligforhold.',2,1,'029.002','{\"source_class\":\"Paragraf\",\"source_id\":\"idab87d750-8f69-49d0-8c99-c70b0fafa2b6\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2440,1,2434,2434,'paragraph','§ 209.',NULL,'Reglerne i kapitel 23 og §§ 131, 138 og 161 finder ikke anvendelse i ejendomme, der inden den 1. marts 1975 er erhvervet af en kommune eller et godkendt saneringsselskab, og som er omfattet af en godkendt saneringsplan.',3,1,'029.003','{\"source_class\":\"Paragraf\",\"source_id\":\"ide5b5bb20-bbc3-45f6-a4e5-8ee2ad00a6d2\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2441,1,2434,2434,'paragraph','§ 210.',NULL,'Ved vurderingen af, om lejemålet opfylder beløbskravene i § 19, stk. 2, 2. pkt., medregnes ligeledes ikke forbedringer foretaget efter § 58, stk. 3, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019.',4,1,'029.004','{\"source_class\":\"Paragraf\",\"source_id\":\"idf6b2c983-d1ff-4f48-975b-9cbb798f490e\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2442,1,2441,2441,'subsection','Stk. 2.',NULL,'Ved sammenligningen efter §§ 20 og 42 ses der tillige bort fra lejemål, som er forbedret efter § 58, stk. 3, og § 62 b i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019.',1,2,'029.004.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2443,1,2441,2441,'subsection','Stk. 3.',NULL,'Ved vurderingen af lejen og det lejedes værdi efter §§ 20 og 42 ses der tillige bort fra lejeforhøjelse efter § 58, stk. 3 og 4, og § 62 b i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og forbedringer efter § 46 a, stk. 3, § 58, stk. 3, og § 62 b i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019. Der ses tillige bort fra lejeforhøjelser til afsættelse efter § 18 b i den tidligere gældende lov om midlertidig regulering af boligforholdene, jf. lovbekendtgørelse nr. 929 af 4. september 2019, og forbedringer gennemført for beløb, der er afsat efter denne bestemmelse.',2,2,'029.004.002','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2444,1,2441,2441,'subsection','Stk. 4.',NULL,'Udlejeren kan ud over de i § 171 nævnte tilfælde opsige lejeren, når denne tilsidesætter betingelserne i et betinget lejeforhold i henhold til § 79 b, stk. 1, nr. 1, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og forholdet er af en sådan karakter, at lejerens flytning er påkrævet.',3,2,'029.004.003','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2445,1,2441,2441,'subsection','Stk. 5.',NULL,'Har lejeren med udlejerens samtykke efter § 28 i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, foretaget ændringer af det lejede, kan udlejeren uanset § 188, stk. 2, kun kræve retablering, når udlejeren har taget forbehold herfor, da udlejeren meddelte samtykket.',4,2,'029.004.004','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2446,1,2441,2441,'subsection','Stk. 6.',NULL,'Har lejeren iværksat forbedringsarbejder m.v. mod godtgørelse ved fraflytning, jf. § 62 a, stk. 1, i den tidligere gældende lov om leje, jf. lovbekendtgørelse nr. 927 af 4. september 2019, og er disse ikke tilendebragt, kan udlejeren enten kræve arbejderne færdiggjort eller eventuelt kræve retablering.',5,2,'029.004.005','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2447,1,2434,2434,'paragraph','§ 211.',NULL,'Såfremt den andel af lejen, der efter tidligere gældende regler afsættes til vedligeholdelse og opretning, er større end de beløb, der er fastsat i §§ 117 og 119, opretholdes den højere afsættelse, indtil de lejeforhøjelser, der måtte gennemføres i medfør af §§ 23 og 127-130, overstiger de hidtidige hensættelsesbeløb.',5,1,'029.005','{\"source_class\":\"Paragraf\",\"source_id\":\"ida1c890c3-7726-475c-9c5d-93287fb75eeb\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2448,1,2447,2447,'subsection','Stk. 2.',NULL,'Såfremt den andel af lejen, der efter tidligere gældende regler afsættes til vedligeholdelse og opretning, er mindre end de beløb, der er fastsat i §§ 117 og 119, bibeholdes den lavere afsættelse, indtil der gennemføres lejeforhøjelse i medfør af §§ 23 og 127-130.',1,2,'029.005.001','{\"source_class\":\"Stk2\",\"source_id\":null}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2449,1,2434,2434,'paragraph','§ 212.',NULL,'For ejendomme, der pr. 1. juli 2015 ikke længere er omfattet af reglerne i kapitel X A i lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010 med senere ændringer, udbetales det på kontoen efter § 63 a i samme lov indestående beløb efter reglerne i kapitel X A i samme lov. Der kan ikke varsles forbedringsforhøjelse for ejendomme omfattet af 1. pkt., før indestående beløb på kontoen efter § 63 a i lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010 med senere ændringer, er udbetalt. Huslejenævnet træffer afgørelse om tilsidesættelse af forbedringsforhøjelse opkrævet i strid med 2. pkt. For konti med negativ saldo fortsætter udlejeren med at opkræve og afsætte beløb efter §§ 63 a og 63 b i lov om leje, jf. lovbekendtgørelse nr. 963 af 11. august 2010 med senere ændringer, indtil kontoen er udlignet. Når saldoen på kontoen er udbetalt eller udlignet, skal lejen nedsættes tilsvarende. Huslejenævnet træffer afgørelse om nedsættelse af lejen efter 4. pkt.',6,1,'029.006','{\"source_class\":\"Paragraf\",\"source_id\":\"id60d49a1b-ff33-4743-8028-c02e7eb0a75d\"}','2026-03-30 23:41:18','2026-03-30 23:41:18'),
(2450,1,2434,2434,'paragraph','§ 213.',NULL,'Loven gælder ikke for Færøerne og Grønland.',7,1,'029.007','{\"source_class\":\"Paragraf\",\"source_id\":\"id65477949-0dcc-4ad6-ac87-df44bd6f1580\"}','2026-03-30 23:41:18','2026-03-30 23:41:18');
